INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('shredded-beef-tacos','Shredded Beef Tacos','Slow-cooked shredded beef with smoky chipotle flavors','mexican','easy',480,15,495,6,350,1,0,0,1,0,'beef',3,0.645,8,1,'[{"name":"Beef chuck roast","quantity":3,"unit":"lbs","unit_norm":"lb","category":"meat"},{"name":"Yellow onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Chipotle peppers in adobo","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Beef broth","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Corn tortillas","quantity":12,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"Avocado","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Fresh cilantro","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Season beef roast with salt and pepper","Place in slow cooker with onion, garlic, and chipotles","Add broth and cook on low for 8 hours","Shred beef with two forks","Serve in tortillas or lettuce wraps","Top with fresh salsa, avocado, and cilantro"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-carnitas-bowl','Pork Carnitas Bowl','Crispy slow-cooked pork with rice, beans, and fresh toppings','mexican','easy',480,15,495,6,420,1,0,0,1,0,'pork',2,0.645,8,1,'[{"name":"Pork shoulder","quantity":4,"unit":"lbs","unit_norm":"lb","category":"meat"},{"name":"Orange juice","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Garlic","quantity":6,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Cumin","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"White rice","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"Black beans","quantity":15,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Fresh salsa","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Lime","quantity":2,"unit":"unit","unit_norm":"","category":"produce"}]','["Season pork shoulder with cumin, oregano, and salt","Place in slow cooker with orange juice and garlic","Cook on low for 8 hours until very tender","Shred pork and broil to crisp","Serve over rice with black beans","Top with fresh salsa, cheese, and lime"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-sausage-and-vegetable-bake','Chicken Sausage and Vegetable Bake','Easy sheet pan dinner with chicken sausage and roasted vegetables','mediterranean','easy',30,10,40,4,320,1,0,0,1,0,'chicken',2,0.757,7,1,'[{"name":"Chicken sausages","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Bell peppers","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Zucchini","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Red onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Cherry tomatoes","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Italian seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat oven to 400°F","Cut sausages and vegetables into chunks","Toss everything with olive oil and seasonings","Spread on a sheet pan in a single layer","Roast for 25-30 minutes until vegetables are tender","Stir halfway through cooking"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('asian-beef-lettuce-wraps','Asian Beef Lettuce Wraps','Savory ground beef with Asian flavors in crispy lettuce cups','asian','easy',15,10,25,4,310,1,0,0,1,0,'beef',2,0.892,8,1,'[{"name":"Ground beef","quantity":1.5,"unit":"lbs","unit_norm":"lb","category":"meat"},{"name":"Garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Water chestnuts","quantity":8,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Coconut aminos","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Sesame oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Butter lettuce","quantity":1,"unit":"head","unit_norm":"head","category":"produce"},{"name":"Green onions","quantity":4,"unit":"unit","unit_norm":"","category":"produce"}]','["Heat oil in a large skillet over high heat","Add ground beef and cook until browned","Add garlic, ginger, and water chestnuts","Stir in coconut aminos and sesame oil","Cook until sauce thickens","Serve in butter lettuce cups","Top with green onions and sesame seeds"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemon-herb-salmon','Lemon Herb Salmon','Baked salmon with fresh herbs and lemon','mediterranean','easy',15,5,20,4,320,1,0,1,1,0,'fish',3,1,6,1,'[{"name":"Salmon fillets","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"Lemon","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Fresh dill","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":2,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Capers","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat oven to 400°F","Place salmon fillets on a baking sheet","Drizzle with olive oil and lemon juice","Season with herbs, salt, and pepper","Bake for 12-15 minutes until flaky","Garnish with fresh dill and lemon slices"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tuscan-chicken-skillet','Tuscan Chicken Skillet','Creamy sun-dried tomato chicken with spinach','mediterranean','medium',25,10,35,4,380,1,0,0,0,1,'chicken',4,0.773,8,1,'[{"name":"Chicken breasts","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Sun-dried tomatoes","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Fresh spinach","quantity":4,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"Heavy cream","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Chicken broth","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Garlic","quantity":4,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Parmesan cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Italian seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Season chicken with Italian herbs","Sear chicken in a hot skillet, set aside","Sauté garlic and sun-dried tomatoes","Add broth and cream, simmer","Add spinach and return chicken to pan","Cook until chicken is done and spinach wilted","Garnish with parmesan"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bacon-burgers-with-broccoli-and-twice-baked-fries','Bacon Burgers with Broccoli and Twice-Baked Fries','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',15,20,35,4,NULL,1,0,0,0,1,'pork',3,0.71,8,1,'[{"name":"roasted broccoli","quantity":3,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"extra-virgin olive oil","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"premade burger patties","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"slices white cheddar cheese or other cheese of choice","quantity":4,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"bacon","quantity":4,"unit":"strips","unit_norm":"strips","category":"meat"},{"name":"tomato, or 4 cherry tomatoes","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"avocado (optional)","quantity":1,"unit":"small","unit_norm":"","category":"produce"},{"name":"butter lettuce leaves (optional)","quantity":8,"unit":"unit","unit_norm":"","category":"dairy"}]','["Preheat the oven to 400°F.","Line a rimmed baking sheet with parchment paper.","Spread out the fries on one half of the lined baking sheet and toss with the olive oil.","On the other half of the baking sheet, spread out the broccoli.","Bake for 15 minutes, until both the fries and the broccoli are warmed through and slightly crisp.","For the burgers:","While the fries and broccoli are baking, preheat a grill to high heat.","Once the grill is at temperature, sear the burger patties for 4 to 5 minutes on each side, until they develop char marks and are medium to medium-well done. (Alternatively, you can cook the burgers in a skillet over medium-high heat for 4 to 5 minutes per side.) After ͆ipping, top the burgers with cheese and bacon.","Once cooked, transfer to a plate to rest.","While the burgers are resting, slice the tomato(es) and avocado, if using.","Plate the burgers, top with the tomato and avocado slices, and serve alongside the fries and broccoli!","If desired, use butter lettuce leaves as “buns.”"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cajun-chicken-and-rice-skillet','Cajun Chicken and Rice Skillet','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',15,5,20,5,NULL,1,0,0,0,1,'chicken',2,0.943,16,1,'[{"name":"salted butter or avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"green bell pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"red bell pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"yellow onion","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"lemon","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"cubed cooked chicken breast","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"salted butter or avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"cooked white rice or cauli-rice","quantity":2.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"fresh lemon juice (about ½ small lemon)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"chicken broth","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"ͅne sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"dried oregano leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"paprika","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"chopped fresh ͆at-leaf parsley (optional)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["To make the Cajun chicken, melt the butter in a large sauté pan over medium heat.","Once melted, add the peppers, onion, and garlic and cook for 5 to 6 minutes, until browned, then transfer the vegetables to a large bowl and set aside.","Cut the lemon in half and place the halves cut side down in the pan for 1 to 2 minutes, until browned, then set aside.","Add the sausage and chicken to the pan and cook until slightly browned, 3 to 5 minutes, then transfer to the bowl with the vegetables.","To make the rice, melt the butter in the same pan.","Once melted, add the rest of the ingredients for the rice and stir to combine.","Cook until warmed through, scraping the bottom of the pan with a wooden spoon to release the charred bits.","Top the rice with the veggies, sausage, and chicken and garnish with the parsley and charred lemon halves, then serve.","I know that at ͅrst glance, ground chicken, bell peppers, and rice don’t sound like the most inspiring ingredients, but hang in there."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('curried-chicken-lettuce-cups','Curried Chicken Lettuce Cups','From Cook Once, Eat All Week cookbook - 4 servings',NULL,'easy',12,5,17,4,NULL,1,0,0,1,0,'chicken',2,0.863,13,0,'[{"name":"ghee or avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"red bell peppers","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"lime","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic","quantity":2,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"cooked ground chicken","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"sliced green onions","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"curry powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ginger powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"chicken broth","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"coconut aminos","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"lime","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"}]','["To make the chicken ͅlling, heat the ghee in a large sauté pan over medium-high heat.","Once hot, add the bell peppers and cook, stirring occasionally, for 3 to 4 minutes, until slightly browned.","Meanwhile, juice the lime and set aside.","Add the garlic to the pan with the bell peppers and cook for 30 seconds, or until fragrant.","Add the chicken, green onions, curry powder, ginger powder, and salt to the pan and stir to combine.","Add the broth, coconut aminos, and lime juice and cook for 5 to 6 minutes, until the chicken is warmed through and the broth has evaporated.","Meanwhile, cut ½ lime into wedges for serving.","Stir the cilantro into the chicken mixture, then remove from the heat.","Spoon the chicken into the lettuce leaves and serve with lime wedges!","Firecracker Meatballs Precooked meatballs Sriracha-lime sauce","Place the meatballs and sauce in a large saucepan over medium heat and toss to coat.","Cover and cook for 5 minutes, or until the meatballs are warmed through.","Meanwhile, reheat the rice either by placing it in a medium-sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","Serve the meatballs alongside the rice and garnish with the sliced green onions."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-burrito-bowls','Chicken Burrito Bowls','From Cook Once, Eat All Week cookbook - 5 servings','mexican','easy',20,5,25,5,NULL,1,0,0,1,0,'chicken',2,0.83,18,1,'[{"name":"avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"red bell peppers","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"yellow onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"cooked ground chicken","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"chicken broth","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"fresh lime juice (about ½ lime)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"chili powder","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"dried oregano leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"cooked white rice or cauli-rice","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"fresh lime juice (about ½ lime)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"avocado","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"red onion","quantity":0.5,"unit":"small","unit_norm":"","category":"produce"},{"name":"lime","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["To make the pepper and onion topping, heat the oil in a large sauté pan over medium heat.","Once hot, add the peppers and onion and season with ½ teaspoon of the salt.","Cook, stirring occasionally, for 7 to 8 minutes, until the peppers and onion are limp and slightly browned.","Meanwhile, prepare the ingredients for serving: Slice the avocado, dice the red onion, and cut the lime into ͅve wedges.","When the peppers and onion are done, remove them from the pan and set aside.","To make the chicken topping, add the chicken to the sauté pan along with the broth, lime juice, spices, and remaining ½ teaspoon of salt.","Cook for 5 to 6 minutes, until the broth has evaporated, then remove from the heat.","Meanwhile, reheat the rice either by placing it in a medium-sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","Stir the salt, lime juice, and cilantro into the rice.","To assemble the burrito bowls, divide the rice among ͅve bowls, then add the pepper/onion and chicken toppings.","Garnish with the avocado slices and diced red onion and serve with lime wedges!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('roasted-tomato-soup-and-grilled-turkey-and-cheese-sandwiches','Roasted Tomato Soup and Grilled Turkey and Cheese Sandwiches','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',15,5,20,4,NULL,1,0,0,0,1,'turkey',2,0.943,11,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"white onion","quantity":0.5,"unit":"medium","unit_norm":"","category":"produce"},{"name":"garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"fresh basil leaves","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"chicken broth","quantity":1,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"heavy cream","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"slices white cheddar cheese or other cheese of choice","quantity":8,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"slices gluten-free bread","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"salted butter","quantity":8,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"}]','["Heat the olive oil in a medium-sized saucepan over medium-high heat.","Once hot, add the onion and garlic.","Sauté for 3 to 4 minutes, until the onion starts to brown and the garlic is fragrant.","Measure out ¼ cup of the basil leaves and tear each leaf in half, setting the rest aside for garnish.","Add the torn basil leaves to the pan along with the remaining soup ingredients and stir to combine.","Simmer for 1 to 2 minutes, then either blend in the pan with an immersion blender or transfer the soup to a blender and carefully blend until smooth.","Return the soup to the pan, then taste for seasoning and add more salt, if needed.","Reduce the heat to low to keep the soup warm while you make the sandwiches.","To make the grilled cheese sandwiches:","Place a skillet large enough to ͅt at least two sandwiches over medium-low heat.","For each sandwich, layer a slice of cheese, one-quarter of the turkey, and another slice of cheese between two slices of bread.","Spread 1 tablespoon of butter on the outside of each slice of bread.","Place two sandwiches in the skillet and cook for about 2 minutes, until the cheese is starting to melt and the bread is golden brown.","Carefully ͆ip the sandwiches and cook for an additional 2 minutes, until the cheese is fully melted and the bread is golden brown.","Repeat with the remaining bread, butter, cheese, and turkey to make two more sandwiches.","While the second set of sandwiches is toasting, cut the remaining basil into ribbons: Stack the leaves, then roll them up and thinly slice them.","Cut the sandwiches in half and serve alongside the hot tomato soup garnished with the sliced basil.","Enjoy!","Buﬀalo"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('turkey-casserole','Turkey Casserole','From Cook Once, Eat All Week cookbook - 6 servings','american','medium',30,10,40,6,NULL,1,0,0,0,1,'turkey',2,0.637,7,1,'[{"name":"roasted potatoes","quantity":4,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"medium-hot hot sauce","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"salted butter","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"cubed roasted turkey breast","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"bacon, cooked and chopped or crumbled","quantity":6,"unit":"strips","unit_norm":"strips","category":"meat"},{"name":"green onions","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"ranch dressing","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Preheat the oven to 350°F.","Spread the potatoes in a 3-quart casserole dish or 2½-quart Dutch oven.","In a large bowl, whisk together the hot sauce and melted butter.","Add the turkey and toss to coat.","Layer the turkey and sauce on top of the potatoes in the casserole dish, then top with the bacon.","Bake the casserole for 30 minutes, until completely warmed through.","While the casserole is in the oven, thinly slice the green onions and chop the parsley.","Remove the casserole from the oven and allow to cool slightly.","Drizzle with the ranch dressing, then garnish with the sliced green onions and chopped parsley and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('turkey-pizza-sheet-pan-dinner','Turkey Pizza Sheet Pan Dinner','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',20,8,28,4,NULL,1,0,0,0,1,'turkey',2,0.83,10,1,'[{"name":"cubed roasted turkey breast","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"ranch dressing","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"cherry tomatoes","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"roasted potatoes","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"shredded mozzarella cheese","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"sliced pepperoni","quantity":2,"unit":"ounces","unit_norm":"oz","category":"produce"},{"name":"sliced mushrooms","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"sliced black olives","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"green bell pepper","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"red pepper ͆akes","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"}]','["Preheat the oven to 375°F.","Line a rimmed baking sheet with parchment paper.","Toss the turkey with the ranch dressing, then spread the turkey on the lined baking sheet.","Cut the tomatoes in half and sprinkle them on top of the turkey.","Follow with the potatoes and then the cheese.","Layer the pepperoni, mushrooms, black olives, and bell pepper on top of the cheese.","Bake for 20 minutes, until the toppings are browned and the cheese is bubbly.","Garnish with the red pepper ͆akes and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('taco-casserole','Taco Casserole','From Cook Once, Eat All Week cookbook - 6 servings','mexican','easy',20,5,25,6,NULL,1,0,0,1,0,'beef',2,0.892,17,1,'[{"name":"cooked white rice or cauli-rice","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"can mild diced tomatoes and green chilis","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"fresh lime juice (about ½ lime)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"cooked ground beef","quantity":3.75,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"chili powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"garlic powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"onion powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"dried oregano leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"sliced romaine lettuce","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"avocado","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"tomato","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"jalapeño pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"red onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["Preheat the oven to 350°F.","Put all of the ingredients for the rice layer in a large bowl and mix to combine, then spread the mixture in an 8 by 11-inch or similar-sized baking dish.","Mix together the ingredients for the beef layer, then layer the beef mixture on top of the rice.","Bake for 20 minutes, until the casserole is hot and the beef is browned on top.","While the casserole is baking, dice the avocado.","Remove the casserole from the oven, top it with the lettuce, avocado, tomato, jalapeño, and red onion, and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('korean-beef-bowls','Korean Beef Bowls','From Cook Once, Eat All Week cookbook - 5 servings','asian','easy',15,5,20,5,NULL,1,0,0,0,1,'beef',2,0.943,7,1,'[{"name":"ghee or avocado oil","quantity":1.5,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"cooked ground beef","quantity":3.75,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"thinly sliced green onions","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"eggs","quantity":5,"unit":"large","unit_norm":"","category":"dairy"},{"name":"cooked white rice or cauli-rice","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"green onions","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sesame seeds","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Heat 1 tablespoon of the ghee in a large skillet over medium heat.","Once hot, add the ground beef and green onions.","Cook for 3 to 4 minutes, until the onions have wilted, then pour the Korean sauce over the beef mixture.","Cook for an additional 4 to 5 minutes, until warmed through.","Meanwhile, fry the eggs: Heat the remaining ½ tablespoon of ghee in a large skillet over medium heat.","Crack the eggs into the skillet and fry for about 4 minutes, or until done to your liking.","Reheat the rice either by placing it in a medium-sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","To serve, divide the warmed rice, beef mixture, and pickled carrots evenly among ͅve bowls.","Top each bowl with a fried egg, some green onions, Sriracha mayo, sesame seeds, and a sprinkle of red pepper ͆akes, if using, and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('confetti-chicken-casserole','Confetti Chicken Casserole','From Cook Once, Eat All Week cookbook - 6 servings','american','medium',30,5,35,6,NULL,1,0,0,0,1,'chicken',3,0.773,9,1,'[{"name":"cooked fresh corn kernels","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"sliced kale","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"cubed baked chicken breast","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"avocado oil mayonnaise","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"shredded cheddar cheese","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"bacon, cooked and sliced or crumbled","quantity":6,"unit":"strips","unit_norm":"strips","category":"meat"},{"name":"green onion","quantity":1,"unit":"large","unit_norm":"","category":"produce"}]','["Preheat the oven to 350°F.","In a large bowl, stir together the onion and bell pepper mixture, corn, kale, chicken, mayonnaise, salt, and pepper until combined.","Transfer the chicken mixture to a 3-quart rectangular casserole dish, then top with the cheese and bacon.","Bake for 30 minutes, until the cheese is browned and bubbling.","Meanwhile, slice the green onion and set aside.","Let the casserole cool slightly, then garnish with green onion and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mexican-chicken-and-corn-street-tacos','Mexican Chicken and Corn Street Tacos','From Cook Once, Eat All Week cookbook - 4 servings','mexican','easy',14,5,19,4,NULL,1,0,0,0,1,'chicken',2,0.943,12,1,'[{"name":"sliced kale","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"salted butter or avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"cubed baked chicken breast","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"cooked fresh corn kernels","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"fresh lime juice (about 1 lime)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"chili powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"paprika","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"miniature corn tortillas, or 8 regular-size corn tortillas","quantity":12,"unit":"unit","unit_norm":"","category":"produce"},{"name":"crumbled Cotija cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"lime wedges","quantity":4,"unit":"unit","unit_norm":"","category":"produce"}]','["Make the slaw: In a small bowl, toss the kale with the chipotle-lime dressing until it is fully coated.","Set aside.","Make the chicken ͅlling: Melt the butter in a large skillet over medium-high heat.","Once melted, add the chicken and corn and cook for 2 minutes to warm through.","Add the lime juice, salt, chili powder, garlic powder, and paprika and toss to coat the chicken and corn.","Sauté for 3 to 4 minutes, until the chicken is slightly browned.","Place a small skillet over medium-high heat.","Once hot, put one tortilla in the pan at a time and warm for about 30 seconds per side, until the tortilla is pliable and begins to brown slightly.","Repeat with the remaining tortillas.","To keep the tortillas warm while you are heating the remaining ones, you can wrap them in a kitchen towel.","To assemble the tacos, top the warmed tortillas with the kale slaw and chicken ͅlling and garnish with the Cotija cheese.","Serve with lime wedges.","Green Goddess Salad Green goddess dressing, divided or frozen corn kernels, thawed","Toss the kale with 1/3 cup of the dressing until well coated.","Cube the avocado.","Divide the dressed kale among four plates.","Top each serving evenly with the corn, chicken, avocado, and bacon.","Serve with the remaining dressing on the side."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('philly-cheesesteak-loaded-fries','Philly Cheesesteak Loaded Fries','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',15,5,20,5,NULL,1,0,0,0,1,'beef',3,1,6,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"slices provolone cheese","quantity":8,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"dried parsley","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Preheat the oven to 400°F.","Place the potato wedges and 1½ teaspoons of the olive oil in a medium-sized bowl and toss to coat.","Spread the potato wedges on a rimmed baking sheet.","In another medium-sized bowl, toss the brisket with the remaining oil, salt, pepper, and garlic powder.","Arrange the seasoned beef on top of the fries.","Spread the peppers and onions on top of the beef, then top with the cheese.","Bake for 15 minutes, until the cheese is browned and bubbling.","Sprinkle with the dried parsley and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('gyro-salad-with-garlic-potato-wedges','Gyro Salad with Garlic Potato Wedges','From Cook Once, Eat All Week cookbook - 4 servings','mediterranean','easy',10,10,20,4,NULL,1,0,0,0,1,'none',4,0.943,11,1,'[{"name":"extra-virgin olive oil","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"head romaine lettuce","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"diced cucumbers","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"halved Kalamata olives","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"red onion","quantity":0.25,"unit":"unit","unit_norm":"","category":"produce"},{"name":"crumbled feta cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"grape tomatoes (optional)","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"cucumber","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"plain full-fat Greek yogurt or dairy-free Greek-style yogurt","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"garlic","quantity":1,"unit":"clove","unit_norm":"clove","category":"produce"}]','["Preheat the oven to 400°F.","Toss the potato wedges with the olive oil and garlic powder and lay on one-half of a rimmed baking sheet.","Toss the brisket with one-third of the Greek dressing, then lay the beef on the other half of the baking sheet.","Bake the potatoes and brisket for 10 minutes, until warmed through and slightly browned.","While the potatoes and beef are baking, make the salad: Put the lettuce, diced cucumbers, olives, red onion, and feta in a large serving bowl.","If using grape tomatoes, slice them in half and add them to the bowl.","Toss the salad and set aside.","To make the tzatziki, peel and shred the cucumber, then roll it up in a dish towel or cheesecloth and squeeze until all of the moisture is released.","Place the drained cucumber in a small bowl along with the yogurt, garlic, and salt.","Stir to combine and set aside.","When the potatoes and beef are ͅnished baking, place them on top of the salad, then drizzle with the remaining dressing.","Serve with the tzatziki for dipping!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemon-ginger-chicken-stir-fry','Lemon Ginger Chicken Stir-Fry','From Cook Once, Eat All Week cookbook - 4 servings','asian','easy',12,2,14,4,NULL,1,0,0,1,0,'chicken',3,0.925,4,0,'[{"name":"avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"green beans","quantity":8,"unit":"ounces","unit_norm":"oz","category":"pantry"},{"name":"sesame seeds","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"lemon","quantity":0.5,"unit":"small","unit_norm":"","category":"produce"}]','["Heat the oil in a large sauté pan or wok over medium-high heat.","Once hot, add the green beans and stir-fry for 3 to 4 minutes, until bright green and crisp-tender.","Remove the beans from the pan and set aside.","Add the chicken to the pan and cook, stirring occasionally, for 4 to 5 minutes, until warmed through and slightly browned.","Return the green beans to the pan with the chicken, then pour the sauce over the beans and chicken and stir to combine.","Cook for 1 to 2 minutes, until the sauce is warmed, then remove from the heat.","Garnish with the sesame seeds and serve with lemon wedges."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-vesuvio','Chicken Vesuvio','From Cook Once, Eat All Week cookbook - 4 servings','italian','easy',20,8,28,4,NULL,1,0,0,0,1,'chicken',2,0.83,15,1,'[{"name":"avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"garlic","quantity":6,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"white wine","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"chicken broth","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"roasted chicken leg quarters","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"roasted chicken wings","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"yellow onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"green beans, cut into 1-inch pieces","quantity":8,"unit":"ounces","unit_norm":"oz","category":"pantry"},{"name":"frozen peas","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"frozen"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"salted butter","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"fresh lemon juice (about 1 small lemon)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"lemon","quantity":0.5,"unit":"small","unit_norm":"","category":"produce"},{"name":"chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Heat 1 teaspoon of the oil in a medium-sized saucepan over medium heat.","Once hot, add the garlic and cook for 30 seconds to 1 minute, until browned.","Add the white wine and broth and bring to a simmer.","Continue to simmer for 5 minutes, until reduced slightly, then remove the pan from the heat.","Meanwhile, recrisp the chicken and cook/reheat the vegetables.","Heat the remaining 1 tablespoon plus 2 teaspoons of oil in a large cast-iron skillet or heavy sauté pan over medium-high heat.","Sear the chicken pieces, skin side down, for 5 to 7 minutes, or until crisp.","If the chicken skin sticks to the pan, add more oil as needed to prevent sticking.","Remove the chicken from the pan and set aside.","Add the onion to the cast-iron skillet and cook for 3 minutes, or until translucent.","Then add the green beans, potatoes, peas, salt, and pepper and toss to combine.","Whisk the butter and lemon juice into the thickened wine and garlic sauce, then pour it over the green bean and potato mixture.","Nestle the chicken into the pan, skin side up, and reduce the heat to medium.","Cook for 5 minutes, until everything is fully reheated and the sauce is bubbling.","Garnish with the lemon slices and parsley, then serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('italian-beef-rolls-with-vodka-sauce','Italian Beef Rolls with Vodka Sauce','From Cook Once, Eat All Week cookbook - 4 servings','italian','medium',20,20,40,4,NULL,1,0,0,1,0,'beef',2,0.637,7,1,'[{"name":"shredded beef","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Italian seasoning","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"collard leaves, stems shaved","quantity":12,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"chopped fresh basil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"}]','["Preheat the oven to 350°F.","Put the beef in a bowl and toss with the Italian seasoning, garlic powder, salt, and pepper.","Place about ¼ cup of the seasoned beef on the bottom third of a collard leaf, then fold the sides of the leaf over the beef ͅlling and roll.","Place the collard roll, folded side down, in a 3-quart rectangular casserole dish.","Repeat with the remaining collard leaves and beef.","Pour the vodka sauce over the collard rolls, then bake for 20 minutes, until the sauce has browned slightly on top.","Garnish with the chopped basil and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('red-curry-acorn-squash-soup-with-crispy-beef','Red Curry Acorn Squash Soup with Crispy Beef','From Cook Once, Eat All Week cookbook - 4 servings',NULL,'easy',10,10,20,4,NULL,1,0,0,0,1,'beef',2,0.943,13,1,'[{"name":"full-fat coconut milk","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"chicken broth","quantity":1,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"jar red curry paste","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"fresh lime juice (about 2 limes)","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"ghee, avocado oil, or other fat of choice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"shredded beef","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"garlic powder","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"ginger powder","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"coconut aminos","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"}]','["Put all of the soup ingredients in a blender and blend until smooth, then pour the soup into a large pot.","Cook over medium heat for 5 minutes or until fully warmed through.","While the soup is heating, prepare the beef: Place the ghee in a large skillet over medium-high heat.","Put the beef, spices, salt, and coconut aminos in a medium- sized bowl and toss to combine.","Once the ghee is hot, add the seasoned beef to the pan, spreading it across the surface of the pan.","Cook for 3 to 4 minutes, until crisp, then ͆ip and cook for an additional 3 to 4 minutes, until browned and crisp on the other side.","Serve the soup in bowls topped with the shredded beef and garnished with the cilantro."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-and-sour-chicken-chow-mein','Sweet-and-Sour Chicken Chow Mein','From Cook Once, Eat All Week cookbook - 4 servings','asian','easy',15,5,20,4,NULL,1,0,0,1,0,'chicken',2,0.943,9,1,'[{"name":"ghee or avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"red bell peppers","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"-sized white onion","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"cubed baked chicken breast","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"pineapple chunks, fresh or frozen","quantity":1,"unit":"cup","unit_norm":"cup","category":"frozen"},{"name":"ghee or avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"shredded green cabbage","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"sliced green onions","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"sesame seeds","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Put the ghee in a large skillet or wok over medium-high heat.","Once hot, add the bell peppers and onion.","Cook, stirring occasionally, for 4 to 5 minutes, until the onion is translucent and the peppers are slightly browned and wilted.","Add the chicken and pineapple, then pour in the sauce and cook for an additional chow mein.","For the chow mein:","Place the ghee in a large skillet over medium-high heat.","Once hot, add the cabbage and cook for 2 to 3 minutes, until wilted, then add the squash and teriyaki sauce and toss to coat.","Cook for an additional 2 to 3 minutes, until warmed through.","Add the green onions and stir to combine, then garnish with the sesame seeds.","Serve the sweet-and-sour chicken alongside the chow mein."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-souvlaki-bowls','Chicken Souvlaki Bowls','From Cook Once, Eat All Week cookbook - 5 servings','mediterranean','easy',8,10,18,5,NULL,1,0,0,0,1,'chicken',2,0.943,9,1,'[{"name":"cucumber","quantity":0.33,"unit":"unit","unit_norm":"","category":"produce"},{"name":"plain full-fat Greek yogurt or dairy-free Greek-style yogurt","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"garlic","quantity":1,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"cubed baked chicken breast","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"cooked white rice","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"tomato","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"head romaine lettuce","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"cucumber","quantity":0.67,"unit":"unit","unit_norm":"","category":"produce"},{"name":"pitted Kalamata olives","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["To make the tzatziki, peel and shred the cucumber, or until you have about 3 tablespoons, then roll it up in a dish towel or cheesecloth and squeeze until all of the excess moisture is released from the cucumber.","Place the drained cucumber in a small bowl along with the yogurt, garlic, and salt.","Stir to combine, then store in the refrigerator until ready to serve.","Put the chicken in a large skillet over medium heat, then pour in half of the dressing; reserve the other half for serving.","Toss to coat the chicken with the dressing.","Cook for 2 to 3 minutes, then ͆ip the chicken.","Add the roasted peppers to the skillet and cook for an additional 2 to 3 minutes, until the peppers are warmed and the chicken is browned, then remove from the heat.","While the peppers are warming, reheat the rice either by placing it in a medium- sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","Meanwhile, chop the parsley leaves and cut the tomato into four wedges.","When the rice is warmed, stir in the chopped parsley.","To assemble the bowls, divide the lettuce evenly among ͅve bowls, then top the lettuce evenly with the rice, chicken and peppers, cucumber slices, tomato wedges, and olives.","Serve with the tzatziki and the remaining Greek dressing on the side."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-tetrazzini','Chicken Tetrazzini','From Cook Once, Eat All Week cookbook - 6 servings','italian','medium',35,8,43,6,NULL,1,0,0,0,1,'chicken',2,0.575,9,1,'[{"name":"salted butter or ghee","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"gluten-free ͆our blend, or 1 tablespoon arrowroot powder","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"chicken broth","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"heavy cream or full-fat coconut milk","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"cubed baked chicken breast","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"frozen peas","quantity":1,"unit":"cup","unit_norm":"cup","category":"frozen"},{"name":"chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 350°F.","Place the butter in a medium-sized saucepan over medium heat.","Once melted, add the ͆our and whisk until smooth.","Slowly pour in the broth, whisking constantly to smooth out any lumps, then whisk in the heavy cream, salt, and pepper.","Bring the mixture to a boil, then stir in the chicken, peas, and cooked mushroom mixture.","Simmer for 2 minutes to thicken the sauce.","Layer the squash strands in a 9 by 13-inch baking dish, then spoon the chicken mixture over the squash.","Bake for 30 minutes, until the top is slightly bubbly, then remove from the oven.","Let cool slightly, then garnish with the parsley and serve! note: If using arrowroot powder, omit the butter and skip Steps 2 and 3.","Instead, combine the broth, cream, salt, and pepper in a medium-sized saucepan and bring to a boil over medium-high heat.","In a small bowl, mix together 1 tablespoon arrowroot powder and 2 tablespoons water.","Once the broth mixture is boiling, pour in the arrowroot slurry and bring back up to a boil.","Reduce the heat and simmer until thickened, 1 to 2 minutes, then proceed with Step 4.","I know I’m not supposed to play favorites, but if I had to choose just one week’s worth of meals to make over and over again, it would undoubtedly be this one."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-ragu','Beef Ragu','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',13,2,15,5,NULL,1,0,0,0,1,'beef',4,0.943,4,1,'[{"name":"shredded beef","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"bunch Lacinato (aka dinosaur) kale","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"extra-virgin olive oil","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"shaved Parmesan cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Make the ragu: Bring the tomato sauce to a simmer in a large pot over medium heat, 3 to 4 minutes.","Add the shredded beef to the sauce and stir to combine, then reduce the heat to medium-low and cook for 5 to 7 minutes, until the meat is warmed through.","Taste the sauce and season with salt, if needed.","While the ragu is cooking, make the noodles: Heat the oil in a large skillet over medium heat.","Once hot, add the zucchini noodles and sauté for 4 to 5 minutes, until the zucchini is reduced in volume and cooked through.","Drain oﬀ any excess water.","Stir the sliced kale into the ragu and cook for 1 to 2 minutes, until the kale is wilted and turns bright green.","Serve the ragu with the zucchini noodles, garnished with the shaved Parmesan and some freshly ground pepper.","This is one of those weeks that just makes a lot of sense!","These recipes transform ground beef, spinach, and spaghetti squash into classic comfort foods, but with a twist."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bolognese-casserole','Bolognese Casserole','From Cook Once, Eat All Week cookbook - 5 servings','italian','medium',20,10,30,5,NULL,1,0,0,0,1,'none',4,0.848,6,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"dried parsley","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"sprigs fresh ͆at-leaf parsley","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"shaved or shredded Parmesan cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Preheat the oven to 350°F.","Toss the squash strands with the olive oil, parsley, garlic powder, and salt, then place in a 3-quart baking dish.","Top the squash mixture with the Bolognese sauce, then bake for 20 minutes, until the top is slightly browned and bubbling.","Meanwhile, chop the parsley and set aside.","Garnish the casserole with the parsley and Parmesan cheese and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mediterranean-skillet','Mediterranean Skillet','From Cook Once, Eat All Week cookbook - 5 servings','mediterranean','easy',12,10,22,5,NULL,1,0,0,0,1,'beef',3,0.83,15,1,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"white onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic","quantity":2,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"frozen quartered artichoke hearts, thawed","quantity":1,"unit":"pound","unit_norm":"lb","category":"frozen"},{"name":"grape tomatoes","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"lemons","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"fresh spinach","quantity":6,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"cooked ground beef","quantity":3.75,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"dried basil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"dried oregano leaves","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"dried dill weed","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"crumbled feta cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"sprigs fresh ͆at-leaf parsley","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"}]','["Heat 1 tablespoon of the oil in a large cast-iron skillet or sauté pan over medium heat.","Add the onion and garlic and cook for 3 to 4 minutes, until the onion is translucent.","Add the artichoke hearts and tomatoes and cook, stirring occasionally, for an additional 3 to 4 minutes, until slightly browned.","Meanwhile, juice the lemons until you have about ¼ cup of juice.","Set aside.","Add the remaining tablespoon of oil to the pan with the tomatoes and artichokes, then stir in the spinach and cook for about 1 minute, until the spinach is wilted.","Mix in the beef.","Add the lemon juice, salt, and seasonings and toss to combine.","Cook for 1 to 2 minutes to let the ͆avors combine.","Meanwhile, chop the parsley.","Garnish the mixture in the skillet with the olives, feta, and chopped parsley and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spinach-pesto-spaghetti-squash-boats','Spinach Pesto Spaghetti Squash Boats','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',15,10,25,4,NULL,1,1,0,0,1,'none',4,0.83,3,1,'[{"name":"baked spaghetti squash halves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"shredded Parmesan cheese","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"}]','["Preheat the oven to 350°F.","Use a fork to scrape the squash strands from the shells, reserving the shells.","In a large bowl, toss the squash strands with the spinach pesto and salt.","Stuﬀ the mixture back into the shells and top with the meatballs.","Bake for 15 minutes or until fully warmed through, then garnish with the Parmesan cheese and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('al-pastor-pizzas','Al Pastor Pizzas','From Cook Once, Eat All Week cookbook - 4 servings','mexican','medium',50,10,60,4,NULL,1,0,0,1,0,'pork',1,0.713,5,1,'[{"name":"shredded pork","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"pineapple tidbits","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"par-baked pizza crusts","quantity":2,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"red onion","quantity":0.25,"unit":"unit","unit_norm":"","category":"produce"}]','["Place an oven rack in the lower position.","Preheat the oven to 375°F.","Spread the shredded pork and pineapple over the pizza crusts, then top with the adobo sauce.","Place the pizzas directly on the lower oven rack and bake for 15 minutes, until the pork is browned and the sauce is bubbling.","Garnish with the cilantro and red onion, then slice and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('green-pork-chili','Green Pork Chili','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',15,5,20,5,NULL,1,0,0,0,1,'pork',2,0.943,12,1,'[{"name":"chicken broth","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"jar salsa verde","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"sour cream or cream scooped from the top of 1 (13½-ounce) can chilled full-fat coconut milk","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"fresh lime juice (about 1 lime)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"dried oregano leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"shredded pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"bunch Lacinato (aka dinosaur) kale, destemmed and chopped","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sprigs fresh cilantro","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sour cream","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["In a large pot over medium heat, whisk together the chicken broth, salsa, sour cream, lime juice, and seasonings, then stir in the shredded pork and kale.","Let the chili come to a slight simmer, then reduce the heat to medium-low and cook for 15 minutes.","Serve in bowls and garnish with the fresh cilantro and sour cream.","Caribbean Plantain Bowls Pan-fried plantains Wilted kale Garlic sauce","Heat 1 tablespoon of the oil in a large skillet over medium-high heat.","Once hot, add the plantains and cook for 1 to 2 minutes per side, until warmed through.","Remove from the pan and set aside.","Add the wilted kale to the skillet and cook for 1 to 2 minutes, until warmed through.","Remove from the pan and set aside.","Add the remaining tablespoon of oil to the skillet and evenly spread the shredded pork over the pan.","Cook for 3 to 4 minutes, until crisp on the bottom, then ͆ip and cook for an additional 3 to 4 minutes, until crisp on the other side.","Assemble the bowls with the crispy pork, plantains, and kale.","Drizzle with the garlic sauce and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crusted-chicken-pot-pie','Crusted Chicken Pot Pie','From Cook Once, Eat All Week cookbook - 6 servings','american','medium',30,15,45,6,NULL,1,0,0,0,1,'chicken',1,0.575,12,1,'[{"name":"salted butter, ghee, or oil of choice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"yellow onion","quantity":1,"unit":"small","unit_norm":"","category":"produce"},{"name":"minced garlic","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"gluten-free ͆our blend","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"chicken broth","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"heavy cream or coconut cream","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"dried rubbed sage","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"dried thyme leaves","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"frozen peas and carrots","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"chopped fresh ͆at-leaf parsley","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 350°F.","Melt the butter in a Dutch oven or other heavy-bottomed pot over medium heat, then add the onion and garlic.","Sauté for 4 to 5 minutes, until the onion is translucent.","Sprinkle the ͆our over the onion mixture and whisk to combine.","Pour in the broth 1 cup at a time, whisking constantly, then add the cream, sage, thyme, salt, and pepper, continuing to whisk until the mixture is smooth.","Stir in the chicken and the peas and carrots.","Simmer for 5 minutes.","While the chicken mixture is simmering, rewarm the potato-parsnip mash in the microwave for 3 minutes or in a covered saucepan on the stovetop over medium heat for 3 to 5 minutes.","It should have a spreadable consistency.","Transfer the chicken mixture to a 4-quart casserole dish or deep-sided ovenproof sauté pan, then top with the potato-parsnip mash.","Bake for 30 minutes, until browned and bubbly on top.","Remove from the oven and let cool slightly, then garnish with the parsley and serve! note: If using arrowroot powder instead of the gluten-free ͆our blend, skip Step 3 and pick up with Step 4.","When the broth begins to bubble in Step 5, whisk 2 teaspoons arrowroot powder with 2 tablespoons water to make a slurry, then pour the slurry into the chicken mixture, whisking constantly, and return it to a simmer.","Continue to cook for 1 minute, until thickened.","Buﬀalo"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cashew-chicken','Cashew Chicken','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',12,5,17,4,NULL,1,0,0,1,0,'chicken',2,0.943,6,1,'[{"name":"avocado oil or ghee","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"red bell peppers","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"snow peas","quantity":6,"unit":"ounces","unit_norm":"oz","category":"pantry"},{"name":"green onions","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"cooked white rice or cauli-rice","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"sesame seeds","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat a large wok or skillet over medium-high heat.","Once hot, add 1 tablespoon of the avocado oil and swirl it around the pan.","Add the bell pepper strips and cook for 2 to 3 minutes, stirring occasionally, until slightly browned.","Add the broccoli ͆orets and snow peas to the pan.","Cook for 2 to 3 minutes, stirring occasionally, until the vegetables begin to soften.","Add the remaining tablespoon of oil to the pan, then add the chicken, green onions, and toasted cashews.","Cook for 1 to 2 minutes, until the chicken is warmed through, then pour the stir-fry sauce over the chicken mixture and toss to coat.","To reheat the rice, place it in a medium-sized saucepan over low heat, covered, for 5 minutes or microwave for 2 minutes, or until hot.","Garnish with the sesame seeds and serve with the rice."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('twice-baked-loaded-butternut-squash','Twice-Baked Loaded Butternut Squash','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',25,10,35,4,NULL,1,0,0,0,1,'pork',2,0.773,8,1,'[{"name":"roasted butternut squash halves","quantity":2,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"plain full-fat Greek yogurt or dairy-free Greek-style yogurt","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"dried thyme leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"dried rosemary leaves","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"bacon, cooked and sliced or crumbled","quantity":5,"unit":"strips","unit_norm":"strips","category":"meat"},{"name":"fresh chives","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 375°F.","Place the squash halves on a rimmed baking sheet, then scoop the pulp out of the shells into a medium-sized bowl, leaving a ½-inch-thick wall of squash in the shells.","To the squash pulp, add the yogurt, salt, garlic powder, thyme, and rosemary.","Mash with a potato masher or blend with an immersion blender until fully incorporated, then stir in the bacon.","Taste for seasoning and add more salt, if needed.","Spoon the squash mixture back into the shells and top with the cubed turkey.","Bake for 25 minutes, until warmed through and slightly browned on top.","To serve, cut the squash halves in half to create four portions.","Divide among four plates and snip the chives over the top, if using."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tuscan-turkey-kale-soup','Tuscan Turkey Kale Soup','From Cook Once, Eat All Week cookbook - 4 servings','italian','medium',20,15,35,4,NULL,1,0,0,1,0,'turkey',2,0.693,9,0,'[{"name":"carrots, peeled and sliced into ¼-inch-thick coins","quantity":4,"unit":"medium","unit_norm":"","category":"produce"},{"name":"can diced tomatoes","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"Italian seasoning","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"chicken broth","quantity":6,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"bunch Lacinato (aka dinosaur) kale, destemmed and chopped","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"fresh lemon juice (about 1 small lemon)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"}]','["Place the shredded turkey, carrots, tomatoes, Italian seasoning, garlic powder, ½ teaspoon of salt, and pepper in a large soup pot with a lid.","Pour in the broth and stir to combine.","Bring to a low boil over medium-high heat, then reduce the heat to medium-low and cover.","Simmer for 15 minutes, until the carrots are soft.","Stir the kale into the soup, then cover and cook for another 2 to 3 minutes, until the kale is bright green and wilted.","Remove from the heat and stir in the lemon juice.","Taste for seasoning, add up to"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('harvest-casserole','Harvest Casserole','From Cook Once, Eat All Week cookbook - 5 servings','american','medium',20,15,35,5,NULL,1,0,0,0,1,'none',2,0.71,9,1,'[{"name":"salted butter or ghee","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"chopped fresh sage, or 1 teaspoon dried rubbed sage","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"salted butter or ghee","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"honey","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ground cinnamon","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"coarsely chopped raw pecans","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"pomegranate seeds","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Preheat the oven to 375°F.","Place the butternut squash pulp, butter, sage, ½ teaspoon of salt, and pepper in a large bowl and mash with a potato masher or blend with an immersion blender.","Taste for seasoning and add up to ½ teaspoon more salt, if needed.","Spread the squash mixture in an 8-inch baking dish or similar-sized enameled cast-iron pan, then top with the wilted kale.","Next, layer on the cubed turkey.","To make the topping, whisk together the butter, honey, cinnamon, and salt in a small bowl, then add the pecans and toss to coat.","Sprinkle the pecans on top of the casserole.","Bake for 20 minutes, until the casserole is warmed through and the pecans are toasted.","Top with the pomegranate seeds and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('smashed-sweet-potato-and-pork-bowls','Smashed Sweet Potato and Pork Bowls','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',15,5,20,5,NULL,1,0,0,0,1,'pork',2,0.943,6,1,'[{"name":"salted butter, ghee, or other fat of choice","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"coarse sea salt","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"shredded pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"dried oregano leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Preheat the oven to 425°F.","Line a rimmed baking sheet with parchment paper.","Cut the sweet potatoes crosswise into 1-inch-thick rounds and place on the lined baking sheet, then smash the potatoes with a metal spatula to a ¼-inch thickness.","Brush the sweet potatoes with the melted butter and sprinkle with 1 teaspoon of the salt.","Bake for 15 minutes, until slightly browned and crisp on top.","While the potatoes are cooking, place the oil in a large sauté pan over medium- high heat.","Once hot, add the shredded pork, oregano, pepper, and remaining teaspoon of salt to the pan.","Cook for 3 to 4 minutes, until the pork is crisp, then ͆ip and cook for an additional 2 to 3 minutes, until it is browned and crisp on the other side.","Remove the pork from the pan and set aside.","Add the Brussels sprouts and cook, stirring occasionally, for 4 to 5 minutes, until heated through, then remove the pan from the heat.","Assemble the bowls: Place two or three sweet potato rounds in each bowl and divide the pork and Brussels sprouts evenly among the bowls.","Drizzle with the aioli before serving."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('harvest-sheet-pan-dinner','Harvest Sheet Pan Dinner','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',30,10,40,4,NULL,1,1,0,1,0,'none',2,0.637,8,1,'[{"name":"red apple","quantity":1,"unit":"large","unit_norm":"","category":"pantry"},{"name":"white onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"extra-virgin olive oil","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"dried thyme leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"balsamic vinegar","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"sprigs fresh thyme","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 400°F.","Cut the apple into ½-inch wedges, discarding the core.","In a medium-sized bowl, toss the apple and onion wedges in 1 tablespoon of the olive oil and the thyme, then spread out on the lined baking sheet and bake for 15 minutes, until softened.","While the apple and onion are cooking, cut the pork shoulder into 1-inch slices.","Then whisk together the remaining 2 tablespoons of oil, the balsamic vinegar, and garlic powder in a large bowl and toss the pork and Brussels sprouts in this mixture.","Lay the pork and Brussels sprouts on the baking sheet with the apple and onion, sprinkle the remaining 2 tablespoons of salt over the pork, lay the thyme sprigs on top, and bake for an additional 15 minutes, until the pork is browned.","Let cool slightly, then serve!","Southwestern Stuﬀed"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chipotle-chicken-casserole','Chipotle Chicken Casserole','From Cook Once, Eat All Week cookbook - 5 servings','mexican','medium',30,10,40,5,NULL,1,0,0,1,0,'chicken',2,0.637,8,1,'[{"name":"paprika","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"chipotle chili powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"onion powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"ͅne sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"avocado oil mayonnaise","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"cubed baked chicken breast","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"}]','["Preheat the oven to 350°F.","Place the paprika, chili powder, garlic powder, onion powder, salt, and mayonnaise in a medium-sized bowl and whisk until smooth.","Add the chicken and toss to coat.","Place the cubed sweet potatoes in a deep 8-inch square casserole dish, then layer the collard greens on top and cover with the chicken mixture.","Bake for 30 minutes, until the top is slightly browned and the casserole is warmed through.","Remove from the oven, drizzle with the cilantro-lime sauce, garnish with the chopped cilantro, if using, and serve! note: To make this dish egg-free, omit the mayo and whisk together the paprika, chili powder, garlic powder, onion powder, and salt with 2 tablespoons extra-virgin olive oil and 1 tablespoon fresh lime juice.","Buﬀalo Chicken–Stuﬀed"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-florentine-lasagna','Chicken Florentine Lasagna','From Cook Once, Eat All Week cookbook - 6 servings','italian','medium',40,25,65,6,NULL,1,0,0,0,1,'chicken',4,0.463,12,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"white onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"sliced baby bella (aka cremini) mushrooms","quantity":8,"unit":"ounces","unit_norm":"oz","category":"produce"},{"name":"white wine","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"chicken broth","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"heavy cream or full-fat coconut milk","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"fresh lemon juice (about ½ small lemon)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"no-boil gluten-free lasagna noodles","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"cubed baked chicken breast","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"shredded Parmesan cheese (about 3 ounces)","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Preheat the oven to 350°F.","Heat the olive oil in a large sauté pan over medium-high heat.","Once hot, add the onion, garlic, and mushrooms.","Cook for 5 to 6 minutes, until the onion and mushrooms are beginning to brown and the garlic is fragrant.","Add the collard greens and sun-dried tomatoes, then pour in the wine, broth, heavy cream, and lemon juice.","Season with the salt.","Stir to combine, then simmer for 3 to 5 minutes, until the liquid has reduced slightly.","Place ½ cup of the collard green mixture in a 2-quart rectangular casserole dish, then layer half of the lasagna noodles on top.","Layer half of the remaining collard green mixture on top of the noodles, followed by half of the chicken, then repeat the layers.","Bake for 15 minutes, then top with the Parmesan cheese and return the casserole to the oven to bake for another 15 minutes, until the sauce is bubbly around the edges and the cheese is browned.","Remove from the oven and let cool slightly, then cut and serve!","What a fun week this is!","You are going to transform the wonderfully aﬀordable ground beef, cabbage, and carrots into three fantastic dinners that your family will love."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('italian-wedding-soup','Italian Wedding Soup','From Cook Once, Eat All Week cookbook - 6 servings','italian','easy',10,12,22,6,NULL,1,0,0,0,1,'chicken',3,0.812,13,0,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"white onion","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"minced garlic","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"carrots, sliced into ¼-inch-thick coins","quantity":6,"unit":"unit","unit_norm":"","category":"produce"},{"name":"quarts chicken broth","quantity":2,"unit":"unit","unit_norm":"","category":"meat"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"coarsely chopped escarole leaves","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"shredded napa cabbage","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"chopped fresh parsley","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"eggs","quantity":2,"unit":"large","unit_norm":"","category":"dairy"},{"name":"shredded Parmesan cheese","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"fresh lemon juice (about 1 small lemon)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"}]','["Heat the olive oil in a soup pot that has a lid over medium-high heat.","Once hot, add the onion, garlic, and carrots.","Sauté for 3 to 4 minutes, until the onion is translucent and the carrots are slightly browned.","Add the broth, meatballs, salt, pepper, escarole, cabbage, and parsley to the pot.","Cover with the lid and cook for 5 minutes, until the escarole and cabbage are tender.","Place the eggs and Parmesan cheese in a small bowl and whisk together.","While stirring the simmering soup, slowly pour in the egg mixture until thin strands of eggs form, about 1 minute.","Stir in the lemon juice, then taste for seasoning and add more salt, if needed.","Remove from the heat and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('texas-beef-chili','Texas Beef Chili','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',20,5,25,4,NULL,1,0,0,0,1,'beef',2,0.812,10,0,'[{"name":"salted butter, ghee, or oil of choice","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"white onion","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"minced garlic","quantity":4,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"scant cups cooked ground beef","quantity":4.5,"unit":"unit","unit_norm":"","category":"meat"},{"name":"plus 2 tablespoons Texas Chili Spice Blend","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"strained tomatoes or tomato puree","quantity":24,"unit":"ounces","unit_norm":"oz","category":"produce"},{"name":"chicken broth","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"cooked white rice or cauli-rice","quantity":3.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"full-fat sour cream","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"jalapeño pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["Melt the butter in a soup pot over medium-high heat.","Once melted, add the onion and sauté for 3 to 4 minutes, until the onion is translucent.","Then add the garlic and continue cooking for 2 to 3 minutes, until the onion starts to develop a light brown color and the garlic is fragrant.","Add the ground beef and stir to combine.","Then add the spice blend and cook for an additional 2 minutes, or until the spices become fragrant.","Add the strained tomatoes and broth, stir to combine, and simmer over medium heat for 10 minutes, or until some of the liquid has evaporated.","While the chili is simmering, reheat the rice either by placing it in a medium- sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","Serve the chili over the warmed rice and garnish with the sour cream and jalapeño slices."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('asian-beef-lettuce-cups','Asian Beef Lettuce Cups','From Cook Once, Eat All Week cookbook - 4 servings','asian','easy',12,15,27,4,NULL,1,0,0,1,0,'beef',2,0.83,11,1,'[{"name":"ghee or avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"shredded napa cabbage","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"shredded carrots","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"scant cups cooked ground beef","quantity":4.5,"unit":"unit","unit_norm":"","category":"meat"},{"name":"can water chestnuts","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"sliced green onions","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"ginger powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"cooked white rice or cauli-rice","quantity":4,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"sesame seeds","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Melt the ghee in a large skillet or wok over medium-high heat.","Once melted, add the cabbage and carrots.","Cook for 4 to 5 minutes, until the vegetables are reduced in size and slightly browned.","Add the ground beef, water chestnuts, green onions, ginger, salt, and pepper to the pan and cook for 3 to 4 minutes, until the beef is warmed through.","Pour the sauce over the beef mixture and cook for an additional 1 to 2 minutes to let the ͆avors meld, then remove from the heat.","Meanwhile, reheat the rice either by placing it in a medium-sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","Serve the beef mixture in the lettuce leaves, garnished with sesame seeds, with the rice on the side."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-potatoes-with-mango-kale-slaw','Sweet Potatoes with Mango Kale Slaw','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',10,10,20,4,NULL,1,0,0,1,0,'pork',2,0.943,10,1,'[{"name":"baked sweet potatoes","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"extra-virgin olive oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lime juice (about 1 lime)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"bunch kale, thinly sliced into ¼-inch strips","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"mango","quantity":1,"unit":"medium","unit_norm":"","category":"pantry"},{"name":"jalapeño pepper, seeded and ͅnely chopped","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"coarsely chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"shredded pork","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"Jerk Seasoning","quantity":1.5,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 350°F.","Line a rimmed baking sheet with parchment paper.","Place the sweet potatoes on the lined baking sheet and bake for 10 minutes, until warmed through.","Meanwhile, make the slaw: Put the olive oil, lime juice, and salt in a medium- sized bowl and whisk together until combined and thickened.","Add the kale to the dressing and massage the dressing into the kale with your hands.","Add the mango, jalapeño, and cilantro to the bowl and toss to coat, then set aside.","To make the jerk pork, place the shredded pork and Jerk Seasoning in a medium- sized bowl and mix to evenly coat the meat in the seasoning.","Pour the olive oil into a large heavy skillet over medium-high heat.","Once hot, add the seasoned pork.","Cook, undisturbed, for 2 to 3 minutes, then ͆ip and cook for an additional 2 to 3 minutes, until golden brown.","Remove from the heat.","Cut a slit in each sweet potato, then stuﬀ with the pork and top with the slaw.","Serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('honey-garlic-pork-skillet','Honey Garlic Pork Skillet','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',10,2,12,5,NULL,1,0,0,0,1,'pork',2,0.943,5,1,'[{"name":"salted butter or ghee","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"cloves garlic","quantity":4,"unit":"large","unit_norm":"","category":"produce"},{"name":"shredded pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"cooked white rice or cauli-rice","quantity":4.5,"unit":"cups","unit_norm":"cup","category":"pantry"}]','["Place the butter in a large skillet over medium-high heat.","Once hot, add the garlic and cook for 30 seconds or until fragrant.","Remove the garlic from the pan and set aside.","Spread the pork evenly across the pan and sprinkle with the salt.","Cook for 2 to 3 minutes, until the pork starts to brown, then ͆ip and cook for an additional 1 to 2 minutes, until browned on the other side.","Pour the honey sauce and cooked garlic over the browned pork and stir to combine.","Cook for 2 to 3 minutes, until the sauce bubbles and begins to reduce.","Reheat the rice either by placing it in a medium-sized saucepan, covered, over low heat for 5 minutes or by microwaving it for about 2 minutes, until hot.","Serve the pork mixture over the rice.","Enjoy!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-potato-tamale-pie','Sweet Potato Tamale Pie','From Cook Once, Eat All Week cookbook - 5 servings','american','medium',30,8,38,5,NULL,1,0,0,0,1,'pork',2,0.575,10,1,'[{"name":"shredded pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"can tomato paste","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"fresh lime juice (about 1 lime)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"plus 1 teaspoon chili powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"plus 1 teaspoon ground cumin","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"meat"},{"name":"dried oregano leaves","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"avocado","quantity":1,"unit":"small","unit_norm":"","category":"produce"},{"name":"full-fat sour cream","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"or 2 sprigs fresh cilantro","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["Preheat the oven to 350°F.","To make the ͅlling, place the pork, tomato paste, lime juice, chili powder, cumin, oregano, and salt in a large bowl and stir until fully combined.","Spread the ͅlling in a 3-quart casserole dish or a 10-inch cast-iron skillet, then layer the sweet potato mash over the top.","Bake for 30 minutes, until the pie is warmed through and the sweet potato topping is slightly browned.","Just before the pie is done, thinly slice the avocado and set it aside.","Garnish the pie with the sour cream, sliced avocado, and cilantro and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chorizo-and-potato-tacos-with-cilantro-lime-slaw','Chorizo and Potato Tacos with Cilantro-Lime Slaw','From Cook Once, Eat All Week cookbook - 5 servings','mexican','easy',20,5,25,5,NULL,1,0,0,0,1,'pork',2,0.83,15,1,'[{"name":"avocado oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"baked and cubed red potatoes","quantity":1,"unit":"pound","unit_norm":"lb","category":"pantry"},{"name":"cooked ground pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"chili powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"paprika","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"dried oregano leaves","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"apple cider vinegar","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"shredded green and purple cabbage","quantity":4,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"corn or grain-free tortillas","quantity":10,"unit":"unit","unit_norm":"","category":"produce"},{"name":"chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"Cotija cheese, crumbled","quantity":3,"unit":"ounces","unit_norm":"oz","category":"dairy"},{"name":"lime","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["To make the ͅlling, heat the oil in a large skillet over medium-high heat.","Once hot, add the potatoes.","Fry for 3 to 4 minutes, then ͆ip and cook for an additional 3 minutes, until browned and crispy.","Remove the potatoes from the pan and set aside.","Drain all but 1 tablespoon of oil from the pan, then add the pork, salt, spices, and vinegar.","Cook, stirring occasionally, for 4 to 5 minutes, until the pork is crispy.","Return the potatoes to the pan and stir them into the pork, then remove the pan from the heat.","To make the slaw, toss the shredded cabbage with the cilantro-lime dressing.","Season to taste with salt.","Place a small skillet over medium-high heat.","Once hot, put a tortilla in the pan and warm for 30 seconds per side, until the tortilla is pliable and begins to brown slightly.","Repeat with the remaining tortillas.","To keep them warm while you heat the remaining tortillas, you can wrap them in a kitchen towel.","To assemble the tacos, ͅll each warmed tortilla with the chorizo-potato ͅlling, top with the slaw, and then garnish with the cilantro and cheese.","Serve with lime wedges."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('egg-roll-in-a-bowl','Egg Roll in a Bowl','From Cook Once, Eat All Week cookbook - 4 servings','asian','easy',10,5,15,4,NULL,1,0,0,1,0,'pork',2,1,14,1,'[{"name":"avocado oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"yellow onion","quantity":1,"unit":"small","unit_norm":"","category":"produce"},{"name":"garlic","quantity":4,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"grated fresh ginger","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"cooked ground pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"coconut aminos","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"unseasoned rice wine vinegar","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"toasted sesame oil","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"red pepper ͆akes","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"chopped green and purple cabbage","quantity":6,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"shredded carrots","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"sliced green onions","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"sesame seeds","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Heat the avocado oil in a large skillet over medium-high heat.","Once hot, add the onion and garlic and sauté for 2 to 3 minutes, until the onion is translucent.","Stir in the ginger, then add the pork, coconut aminos, vinegar, sesame oil, red pepper ͆akes, and salt.","Stir to combine and cook for 2 minutes, until the sauce begins to bubble.","Add the cabbage, carrots, and green onions to the pan and toss to coat in the sauce.","Cook for 3 to 4 minutes, stirring occasionally, until the cabbage and carrots are wilted, then serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('swedish-meatballs-over-mashed-potatoes','Swedish Meatballs Over Mashed Potatoes','From Cook Once, Eat All Week cookbook - 4 servings',NULL,'easy',15,5,20,4,NULL,1,0,0,0,1,'beef',2,0.943,7,1,'[{"name":"salted butter, ghee, or oil of choice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"gluten-free ͆our blend, or 1 tablespoon arrowroot powder","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"chicken broth","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"heavy cream or full-fat coconut milk","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"coarse sea salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"chopped fresh ͆at-leaf parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Melt the butter in a large skillet over medium heat.","Once melted, sprinkle in the ͆our and whisk until smooth.","Pour in the chicken broth ½ cup at a time, whisking constantly to smooth out any lumps.","Bring the mixture to a low boil, then reduce the heat to medium-low and whisk in the cream, salt, and pepper.","Add the meatballs to the pan and stir to coat, then cover and cook for 5 minutes, until heated through.","Before serving, taste the sauce for seasoning and add more salt, if desired.","While the meatballs are warming, reheat the mashed potatoes either by microwaving for 3 minutes, stirring halfway through, or by placing in a small saucepan over medium heat and cooking, covered, for 5 minutes, stirring occasionally.","Serve the meatballs and sauce over the mashed potatoes and garnish with the parsley. note: If using arrowroot powder, bring the broth to a boil in a large skillet.","Meanwhile, stir the arrowroot powder and 2 tablespoons of water together in a small bowl to form a slurry.","Once the broth is boiling, whisk in the slurry.","Boil for 1 minute, until the broth begins to thicken.","Reduce the heat to medium-low and whisk in the cream, salt, and pepper, then proceed to Step 3."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-marsala-casserole','Chicken Marsala Casserole','From Cook Once, Eat All Week cookbook - 6 servings','italian','medium',25,10,35,6,NULL,1,0,0,0,1,'chicken',4,0.773,13,1,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"Marsala wine","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"chicken broth","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"heavy cream or coconut milk","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"salted butter, ghee, or oil of choice","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"dried parsley","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"thin slices prosciutto, crisped","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"strands scraped from 1 roasted spaghetti squash","quantity":5,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"cubed cooked chicken breast","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"chopped fresh ͆at-leaf parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 350°F.","Heat 1 tablespoon of the olive oil in a saucepan over medium heat.","Once hot, add the cooked onion, garlic, and mushroom mixture and sauté for 1 to 2 minutes, until warmed through.","Pour in the wine and broth and boil for 1 minute to cook oﬀ the alcohol, then whisk in the cream, butter, dried parsley, ½ teaspoon of the salt, and ¼ teaspoon of the pepper.","Stir in the prosciutto, then slide the pan oﬀ the heat.","Place the squash strands in an 8-inch round casserole dish and toss with the remaining tablespoon of oil, the garlic powder, remaining ½ teaspoon of salt, and remaining ¼ teaspoon of pepper.","Spread the chicken on top of the squash, then pour the mushroom sauce over the chicken.","Bake for 20 minutes to warm the casserole through.","Garnish with the fresh parsley and serve."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spaghetti-squash-chicken-chow-mein','Spaghetti Squash Chicken Chow Mein','From Cook Once, Eat All Week cookbook - 4 servings','asian','easy',15,2,17,4,NULL,1,0,0,1,0,'chicken',1,1,9,0,'[{"name":"avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"yellow onion","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"head purple cabbage, cut into 2-inch strips","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sliced celery","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"minced garlic","quantity":4,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"strands scraped from 1 roasted spaghetti squash","quantity":5,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"cooked shredded chicken","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"green onions, cut into 1-inch pieces","quantity":6,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sesame seeds","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Heat the oil in a large sauté pan over medium heat.","Add the onion and sauté for and cook for an additional 4 to 5 minutes, until the vegetables are slightly browned.","Stir in the squash strands, chicken, sauce, and green onions.","Toss to combine, then cook for an additional 3 to 4 minutes, until the squash is warmed through and the sauce has started to bubble.","Garnish with the sesame seeds and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('creamy-chicken-and-mushroom-soup','Creamy Chicken and Mushroom Soup','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',12,10,22,4,NULL,1,0,0,0,1,'chicken',2,0.83,13,1,'[{"name":"salted butter, ghee, or oil of choice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"yellow onion","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"mushrooms","quantity":8,"unit":"ounces","unit_norm":"oz","category":"produce"},{"name":"minced garlic","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"gluten-free ͆our blend or arrowroot powder","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"chicken broth","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"heavy cream or coconut cream","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"spicy brown mustard","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"fresh lemon juice (about ½ small lemon)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"chopped fresh thyme","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"shredded, cooked chicken","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"}]','["Melt the butter in a soup pot over medium heat, then add the onion, mushrooms, and garlic.","Cook, stirring occasionally, for 4 to 5 minutes, until the onion and mushrooms are slightly browned.","Sprinkle the ͆our blend into the pot and whisk until it has been absorbed into the mushroom mixture.","Pour in the broth 1 cup at a time, whisking constantly to smooth out any lumps.","To the pot, add the cream, mustard, lemon juice, thyme, salt, pepper, and chicken.","Give the soup a stir and cook for about 5 minutes, until the chicken is warmed through, then serve. note: If using arrowroot powder, complete Step 1, then add all of the chicken broth to the pot, cover, and bring to a boil over medium-high heat.","Meanwhile, whisk together the arrowroot powder and ¼ cup water, then stir the slurry into the boiling broth.","Simmer for 1 to 2 minutes, until thickened, then reduce the heat to medium and proceed to Step 3."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bbq-brisket-bowls','BBQ Brisket Bowls','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',6,10,16,5,NULL,1,0,0,1,0,'beef',2,1,7,1,'[{"name":"BBQ Spice Rub","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"cooked white rice or cauli-rice","quantity":3.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"dill pickle spears","quantity":10,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"red onion","quantity":0.5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"BBQ sauce","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"}]','["Thinly slice the brisket, then put it in a medium-sized bowl along with the spice rub.","Toss to coat the meat in the seasonings.","Heat the olive oil in a large skillet over medium-high heat.","Once hot, add the seasoned brisket.","Cook for 2 to 3 minutes, then ͆ip each piece and cook for an additional 2 to 3 minutes, until browned on both sides.","Meanwhile, reheat the rice either by placing it in a medium-sized saucepan, covered, over low heat for 5 minutes or by microwaving for about 2 minutes, until hot.","Spoon the warmed rice into bowls and top with the brisket, pickles, onion slices, a drizzle of BBQ sauce, and a sprinkle of chopped cilantro.","Enjoy!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chipotle-brisket-tacos-with-green-apple-slaw','Chipotle Brisket Tacos with Green Apple Slaw','From Cook Once, Eat All Week cookbook - 4 servings','mexican','medium',15,15,30,4,NULL,1,0,0,1,0,'beef',2,0.71,16,1,'[{"name":"chipotle chili powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"paprika","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"green apple","quantity":1,"unit":"small","unit_norm":"","category":"pantry"},{"name":"avocado oil mayonnaise or vegan mayo","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"fresh lemon juice (about 1 small lemon)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"honey","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"shredded Brussels sprouts","quantity":4,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"corn tortillas or grain-free tortillas","quantity":8,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sprigs fresh cilantro","quantity":8,"unit":"unit","unit_norm":"","category":"produce"}]','["Place the chili powder, cumin, garlic powder, paprika, salt, and pepper in a medium-sized bowl and whisk to combine.","Thinly slice the brisket and add it to the bowl with the seasonings.","Toss the meat in the seasoning mixture until well coated.","Heat the olive oil in a large skillet over medium-high heat.","Once hot, add the seasoned brisket and cook for 2 to 3 minutes, then ͆ip and cook for an additional 2 to 3 minutes, until browned on both sides.","Remove from the heat and set aside.","While the brisket is cooking, make the slaw: Cut the apple into ¼-inch-thick matchsticks, to equal 1 cup.","Place the mayonnaise, lemon juice, honey, salt, and pepper in a large bowl and whisk until smooth.","Stir in the apple, Brussels sprouts, and chopped cilantro.","To warm the tortillas, preheat a small skillet over medium-high heat.","Once hot, put a tortilla in the pan and warm for 30 seconds per side, until the tortilla is pliable and begins to brown slightly.","Repeat with the remaining tortillas.","To keep them warm while you heat the remaining tortillas, you can wrap them in a kitchen towel.","Fill each tortilla with brisket and slaw, garnish with a cilantro sprig, and serve!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('brisket-fried-rice','Brisket Fried Rice','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',18,5,23,5,NULL,1,0,0,0,1,'beef',2,0.83,14,1,'[{"name":"eggs","quantity":2,"unit":"large","unit_norm":"","category":"dairy"},{"name":"plus 1 teaspoon ghee or avocado oil","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"grated ginger","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"minced garlic","quantity":4,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"shredded Brussels sprouts","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"carrots","quantity":2,"unit":"medium","unit_norm":"","category":"produce"},{"name":"plus 2 tablespoons thinly sliced green onions","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"cooked white rice or cauli-rice","quantity":4,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"coconut aminos","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lime juice (about ½ lime)","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"toasted sesame oil","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"red pepper ͆akes","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"sprigs fresh cilantro, or 1 tablespoon chopped fresh cilantro","quantity":5,"unit":"unit","unit_norm":"","category":"produce"}]','["In a small bowl, whisk the eggs.","Place 1 teaspoon of the ghee in a small skillet over medium-high heat.","Once melted, add the eggs and spread evenly across the pan.","Cook for 2 minutes, then ͆ip and cook for an additional minute, until fully heated through.","Transfer the eggs to a cutting board and cut into ½-inch squares, then set aside.","Cut the brisket into ½-inch cubes.","Heat 1½ tablespoons of the ghee in a large sauté pan or wok over medium-high heat.","Once hot, add the brisket.","Cook for 3 to 4 minutes, until browned.","Add the ginger and garlic to the pan with the brisket and cook for 30 seconds, until fragrant.","Add the Brussels sprouts and carrots to the pan with the brisket.","Cook for 3 to 4 minutes, until the carrots and Brussels sprouts are slightly browned, then stir in ¼ cup of the green onions.","Add the remaining 1½ tablespoons of ghee to the pan and stir it into the meat and vegetable mixture.","Add the rice and toss to combine it with the rest of the ingredients.","Add the eggs, coconut aminos, lime juice, sesame oil, and red pepper ͆akes to the rice mixture and stir to combine.","Add the salt, then taste for seasoning and add more salt, if needed.","Let the rice cook, untouched, for 2 minutes.","Then stir the rice, scraping any browned bits oﬀ of the bottom of the pan.","Cook for an additional 1 to 2 minutes, until the rice is slightly browned and crisp.","Remove from the heat.","Garnish with the remaining 2 tablespoons of green onions and the cilantro and enjoy!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('honey-mustard-sheet-pan-dinner','Honey Mustard Sheet Pan Dinner','From Cook Once, Eat All Week cookbook - 5 servings','american','easy',15,5,20,5,NULL,1,0,0,1,0,'pork',2,1,7,1,'[{"name":"shredded pork","quantity":3,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"coarse sea salt","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"roasted green cabbage wedges","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"roasted purple cabbage wedges","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"sprigs ͆at-leaf parsley","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 350°F.","Place the shredded pork, half of the honey mustard dressing, and ½ teaspoon of the salt in a medium-sized bowl and toss to coat.","Place the cabbage wedges and potatoes on a rimmed baking sheet.","Drizzle with the olive oil, sprinkle with the pepper and remaining teaspoon of salt, and toss to coat.","Place clumps of the shredded pork mixture on the baking sheet in between the cabbage and potatoes.","Bake for 15 minutes, until the pork is browned and the potatoes and cabbage are warmed through.","Meanwhile, wash, dry, and chop the parsley.","Drizzle the remaining dressing over the potatoes and cabbage, garnish with the parsley, and serve."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('enchilada-verde-casserole-with-avocado-slaw','Enchilada Verde Casserole with Avocado Slaw','From Cook Once, Eat All Week cookbook - 6 servings','mexican','medium',30,15,45,6,NULL,1,0,0,0,1,'pork',2,0.575,16,1,'[{"name":"shredded pork","quantity":4,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"chili powder","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"meat"},{"name":"dried oregano leaves","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"salsa verde","quantity":4,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"corn or grain-free tortillas","quantity":6,"unit":"unit","unit_norm":"","category":"produce"},{"name":"shredded white cheddar or Monterey Jack cheese","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"fresh lime juice (about 1 lime)","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"avocado oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"diced red onions","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"jalapeño pepper, ͅnely chopped","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"avocado, cut into ½-inch cubes","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"fresh cilantro leaves","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Preheat the oven to 350°F.","Make the casserole: In a medium-sized bowl, toss the pork with the chili powder, cumin, oregano, garlic powder, salt, and pepper.","Spread 1 cup of the salsa in an 8-inch square baking dish, then cover with 2 tortillas: place a tortilla in one corner of the dish, then cut the second tortilla in half and use the halves to ͅll in the empty spaces along the side and bottom of the whole tortilla.","Spread one-third of the seasoned pork over the tortillas, then top with 1 cup of the salsa and ¼ cup of the cheese.","Repeat for two more layers.","Bake the casserole, uncovered, for 30 minutes, until the cheese is bubbling.","Meanwhile, make the avocado slaw: In a medium-sized bowl, whisk together the lime juice and avocado oil.","Add the onions, jalapeño, avocado, cilantro, and cabbage and toss to coat.","Place the slaw on top of the casserole and serve!","Mini Sloppy Joe–Stuﬀed"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemon-pepper-chicken-breasts','Lemon Pepper Chicken Breasts','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',18,5,23,4,NULL,1,0,0,1,0,'chicken',3,0.892,4,1,'[{"name":"boneless, skinless chicken breast halves","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Preheat the oven to 350°F.","Line a rimmed baking sheet with parchment paper.","In a medium-sized bowl, whisk together the lime juice and olive oil.","Place the chicken in the bowl and toss to coat evenly.","Place the chicken on the lined baking sheet, then sprinkle both sides with the paprika, salt, and pepper.","Bake for 15 to 18 minutes, until the juices run clear.","Let the chicken rest for 5 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('paprika-lime-chicken-breasts','Paprika Lime Chicken Breasts','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',18,5,23,4,NULL,1,0,0,1,0,'chicken',3,0.892,5,1,'[{"name":"boneless, skinless chicken breast halves","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"paprika","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Preheat the oven to 350°F.","Line a rimmed baking sheet with parchment paper.","In a medium-sized bowl, whisk together the lemon juice and olive oil.","Place the chicken in the bowl and toss to coat evenly.","Place the chicken on the lined baking sheet, then sprinkle both sides with the salt and pepper.","Bake for 15 to 18 minutes, until the juices run clear.","Let the chicken rest for 5 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-curried-chicken-thighs','Crispy Curried Chicken Thighs','From Cook Once, Eat All Week cookbook - 4 servings',NULL,'medium',45,5,50,4,NULL,1,0,0,1,0,'chicken',1,0.637,4,1,'[{"name":"bone-in, skin-on chicken thighs","quantity":2,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"curry powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Preheat the oven to 375°F.","Line a rimmed baking sheet with parchment paper.","Pour the balsamic vinegar into a medium-sized bowl.","Place the chicken in the bowl and toss to coat evenly.","Place the thighs on the lined baking sheet, then sprinkle with the salt and pepper.","Bake for 25 minutes, or until the juices run clear and the tops are browned.","Let the chicken rest for 5 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('balsamic-chicken-thighs','Balsamic Chicken Thighs','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',25,5,30,4,NULL,1,0,0,1,0,'chicken',1,0.773,4,1,'[{"name":"boneless, skinless chicken thighs","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"balsamic vinegar","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Preheat the oven to 400°F.","Line a rimmed baking sheet with parchment paper.","In a medium-sized bowl, whisk together the lime juice and curry powder.","Place the chicken in the bowl and toss to coat evenly.","Place the thighs, skin side up, on the lined baking sheet, then sprinkle both sides with the salt and pepper.","Bake for 45 minutes, or until the juices run clear and the tops are browned.","Let the chicken rest for 5 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('ranch-chicken-thighs','Ranch Chicken Thighs','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',25,5,30,4,NULL,1,0,0,1,0,'chicken',1,0.773,4,1,'[{"name":"boneless, skinless chicken thighs","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"ranch dressing, store-bought or homemade","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Preheat the oven to 350°F.","Sprinkle both sides of the pork chops with the rub.","Place a medium-sized ovenproof skillet over medium heat and pour in the olive oil.","Once the oil thins from the heat, after about 30 seconds, add the pork chops.","Sear the chops for about 3 minutes, or until slightly golden on one side.","Flip the chops over and transfer to the oven to bake for 12 minutes, or until the juices run clear.","Let the chops rest for 5 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('simple-seared-pork-chops','Simple Seared Pork Chops','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',15,5,20,4,NULL,1,0,0,1,0,'pork',3,1,3,1,'[{"name":"boneless pork chops","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"Texas Grill Rub","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 375°F.","Line a rimmed baking sheet with parchment paper.","Pour the ranch dressing into a medium-sized bowl.","Place the chicken in the bowl and toss to coat evenly.","Place the thighs on the lined baking sheet, then sprinkle both sides with the salt and pepper.","Bake for 25 minutes, or until the juices run clear and the tops are browned.","Let the chicken rest for 5 minutes before cutting. pro tip: If you want these pork chops to be extra juicy, let them sit in a refrigerated brine of 2 cups water plus 2 tablespoons sea salt and 2 tablespoons maple syrup for a minimum of 4 hours or a maximum of 24 hours.","Pat dry and proceed with the cooking instructions above."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('southwestern-pork-chops','Southwestern Pork Chops','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',15,5,20,4,NULL,1,0,0,1,0,'pork',3,1,3,1,'[{"name":"boneless pork chops","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"Texas Chili Spice Blend","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 375°F.","Heat the olive oil in a large cast-iron or other ovenproof skillet over high heat.","While the oil heats, sprinkle all sides of the tenderloin with the rub.","Once the oil has thinned from the heat, sear the tenderloin on all sides for about and bake for 25 minutes, or until the internal temperature of the pork reads 160°F.","Let the pork rest for 10 minutes before cutting. pro tip: If you want these pork chops to be extra juicy, let them sit in a refrigerated brine of 2 cups water plus 2 tablespoons sea salt and 2 tablespoons maple syrup for a minimum of 4 hours or a maximum of 24 hours.","Pat dry and proceed with the cooking instructions above."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('basic-pork-tenderloin','Basic Pork Tenderloin','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',35,5,40,4,NULL,1,0,0,1,0,'pork',4,0.637,3,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"pork tenderloin","quantity":1,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Texas Grill Rub","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 350°F.","Sprinkle both sides of the pork chops with the spice blend.","Place a medium-sized ovenproof skillet over medium heat and pour in the olive oil.","Once the oil thins from the heat, after about 30 seconds, add the pork chops.","Sear the chops for about 3 minutes, or until slightly golden on one side.","Flip the chops over and transfer to the oven to bake for 12 minutes, or until the juices run clear.","Let the chops rest for 5 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('honey-mustard-pork-tenderloin','Honey Mustard Pork Tenderloin','From Cook Once, Eat All Week cookbook - 4 servings','american','medium',35,5,40,4,NULL,1,0,0,1,0,'pork',4,0.713,6,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"Dijon mustard","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"},{"name":"pork tenderloin","quantity":1,"unit":"unit","unit_norm":"","category":"meat"}]','["Preheat the oven to 375°F.","Heat the olive oil in a large cast-iron or other ovenproof skillet over high heat.","While the oil heats, sprinkle all sides of the tenderloin with the seasoning.","Once the oil has thinned from the heat, sear the tenderloin on all sides for about and bake for 25 minutes, or until the internal temperature of the pork reads 160°F.","Let the pork rest for 10 minutes before cutting."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('jerk-pork-tenderloin','Jerk Pork Tenderloin','From Cook Once, Eat All Week cookbook - 4 servings',NULL,'medium',35,5,40,4,NULL,1,0,0,1,0,'pork',4,0.575,3,1,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"pork tenderloin","quantity":1,"unit":"unit","unit_norm":"","category":"meat"},{"name":"Jerk Seasoning","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 375°F.","Heat the olive oil in a large cast-iron or other ovenproof skillet over high heat.","While the oil heats, whisk the mustard, honey, salt, and pepper together in a bowl.","Spread the honey mustard evenly over the pork tenderloin.","Once the oil has thinned from the heat, sear the tenderloin on all sides for about and bake for 25 minutes, or until the internal temperature of the pork reads 160°F.","Let the pork rest for 10 minutes before cutting.","Pan-Seared Steak","Heat the olive oil in a large cast-iron or other ovenproof skillet over medium- high heat.","Mix the salt and spices together in a small bowl and sprinkle over both sides of the steaks.","Sear the steaks on each side for 2 minutes for rare, 3 minutes for medium-rare, or Mocha Coﬀee Steak","Heat the olive oil in a large cast-iron or other ovenproof skillet over medium- high heat.","Sprinkle both sides of the steaks with the rub.","Sear the steaks on each side for 2 minutes for rare, 3 minutes for medium-rare, or"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('easy-tuna-steak','Easy Tuna Steak','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',5,5,10,4,NULL,1,0,0,1,0,'fish',4,1,4,1,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"tuna steaks","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Heat the olive oil in a large skillet over medium-high heat.","Sprinkle both sides of the ͅsh with the salt and pepper.","Once the oil has thinned from the heat, sear the ͅsh for 2 minutes per side, or until a light brown crust develops.","Sprinkle the cooked ͅsh with the lemon juice.","Let rest for 5 minutes before serving."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pan-seared-white-fish','Pan-Seared White Fish','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',5,5,10,4,NULL,1,0,0,1,0,'fish',3,1,4,1,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"white ͅsh ͅllets (such as snapper)","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Heat the olive oil in a large skillet over medium-high heat.","Sprinkle both sides of the tuna with the salt and pepper.","Once the oil has thinned from the heat, sear the tuna for 2 minutes per side, or until a light brown crust develops on the outside and the inside is still pink. (This cook time results in medium-done tuna; if you like your tuna slightly more or less well-done, adjust the time accordingly.)","Let the tuna rest for 5 to 10 minutes before serving.","Enjoy warm or chilled and sliced over a salad."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemon-garlic-shrimp','Lemon-Garlic Shrimp','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',8,20,28,4,NULL,1,0,1,1,0,'fish',4,0.892,4,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"large shrimp, peeled and deveined","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"seafood"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"coarse sea salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Heat the oil in a large skillet over high heat.","Sprinkle the shrimp with the garlic powder and salt.","Add the shrimp to the skillet and reduce the heat to medium.","Cook for 3 minutes per side, or until pink.","Once cooked, add the lemon juice and stir to combine.","Serve immediately."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pan-seared-salmon','Pan-Seared Salmon','From Cook Once, Eat All Week cookbook - 4 servings','american','easy',6,5,11,4,NULL,1,0,0,1,0,'fish',3,1,4,1,'[{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"salmon ͅllets","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"coarse sea salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"meat"}]','["Heat the olive oil in a large skillet over medium heat.","Sprinkle the salmon ͅllets with the salt and pepper.","Sear the salmon on each side for 3 minutes, or until the ͅsh ͆akes at the thickest part.","Let rest for 5 minutes before serving."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('slow-cooker-mediterranean-beef-with-tzatziki','Slow Cooker Mediterranean Beef with Tzatziki','From Stress-Free Family Meal Planning - 6 servings','mediterranean','easy',10,5,15,6,NULL,0,0,0,1,0,'beef',3,0.943,5,1,'[{"name":"beef chuck roast","quantity":2,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"dried oregano","quantity":1.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"fresh lemon juice","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Add the oil to a large, heavy skillet over medium-high heat.","Add the beef and sear it for 3 to 4 minutes, until it is brown.","Flip the beef and cook it for 3 to 4 minutes, until it is brown.","Transfer the beef to a large slow cooker.","You can skip this step, but it adds flavor and color.","If you choose to skip this step, omit the oil from the recipe.In a small bowl, mix together the oregano, salt, cumin, coriander, black pepper, and allspice.","Sprinkle this mixture over the beef in the slow cooker and stir to coat the beef.","Stir in the onion and garlic.","Cook the beef on low for 8 hours.To make the tzatziki, finely grate the cucumber.","Use a paper towel or kitchen towel to squeeze out as much of the cucumber’s moisture as possible.","Transfer the cucumber to a medium bowl.","Add the yogurt, garlic, lemon juice, lemon zest, oil, dill, black pepper, and salt to taste.","Stir to combine the ingredients.","Place the tzatziki in the fridge to chill for at least 2 hours before serving.Serve the beef drizzled with the tzatziki in a pita, over rice, or on a bed of greens."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cashew-chicken-and-pineapple-fried-rice','Cashew Chicken and Pineapple Fried Rice','From Stress-Free Family Meal Planning - 4 servings','american','easy',17,8,25,4,NULL,0,0,0,1,0,'chicken',3,0.83,8,1,'[{"name":"coconut oil or","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Asian garlic chili paste","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"coarsely chopped pineapple½ red bell pepper","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"frozen peas and carrots","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"cooked and cooled brown rice","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"coarsely chopped cooked boneless, skinless chicken","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"raw cashews","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"low-sodium soy sauce","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Add the eggs.","Scramble the eggs for 1 to 2 minutes, until they are just cooked through.","Remove the eggs from the skillet and set them aside.Add the remaining 1 tablespoon (15 g) of oil to the skillet.","Add the green onions, garlic, Asian garlic chili paste (if using), and ginger.","Cook the mixture for 30 seconds.","Add the pineapple, bell pepper, and peas and carrots.","Cook the mixture for 3 to 4 minutes, until the pineapple begins to caramelize.","Add the rice, chicken, and cashews.","Stir to combine the ingredients.Press the rice into the bottom of the skillet with the back of a spoon.","Cook the rice for 2 to 3 minutes, until it begins to turn brown and crispy.","Repeat this step if desired for more crispy rice.Stir in the scrambled eggs and soy sauce.","Taste and add more soy sauce as needed.Kitchen Hack: Don’t have time to prep the rice or chicken?","Let the grocery store do the heavy lifting.","Grab some frozen brown rice and cook it for two-thirds of the suggested cooking time.","Then grab a rotisserie chicken or some cooked chicken breast.","You can even grab the green onions, red bell pepper, and pineapple from the salad bar."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('baked-pizza-pork-chops-with-cauliflower','Baked Pizza Pork Chops with Cauliflower','From Stress-Free Family Meal Planning - 2 servings','american','medium',24,11,35,2,NULL,0,0,0,0,1,'pork',3,0.71,6,1,'[{"name":"cauliflower florets","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"lean boneless pork chops","quantity":2,"unit":"unit","unit_norm":"","category":"meat"},{"name":"spaghetti sauce","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"shredded part-skim mozzarella cheese","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"coarsely chopped turkey pepperoni","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"meat"}]','["Add some sauce and cheese, and I can get them to eat just about anything.","We usually do this with veggies, although lately I have been trying it with proteins—it works like a charm.Serves: 2Total Time: 35 minutes2 cups (460 g) cauliflower florets1 tbsp (15 ml) olive oil, divided1 tsp Italian seasoning, dividedSalt, as neededBlack pepper, as needed2 (5-oz [140-g]) lean boneless pork chops½ tsp garlic powder⅔ cup (160 ml) spaghetti sauce⅓ cup (37 g) shredded part-skim mozzarella cheese2 tbsp (20 g) coarsely chopped turkey pepperoniPreheat the oven to 400°F (204°C).In a large glass baking dish, toss the cauliflower with ½ tablespoon (8 ml) of the oil, ½ teaspoon of the Italian seasoning, salt, and black pepper.","Spread the cauliflower out in a single layer and roast it for 10 minutes, until it is beginning to brown and soften.Meanwhile, brush the pork chops on both sides with the remaining ½ tablespoon (7 ml) of oil.","Sprinkle them with the remaining ½ teaspoon of Italian seasoning, garlic powder, and salt.Carefully remove the baking dish from the oven.","Nestle the pork chops into the dish among the cauliflower.","Cook the pork chops and cauliflower for 12 minutes.Carefully remove the baking dish from the oven and cover the pork chops and cauliflower with the spaghetti sauce.","Sprinkle the mozzarella cheese and pepperoni over top.","Return the baking dish to the oven and cook for 8 to 10 minutes, until the pork’s internal temperature reaches 145°F (63°C).Know Your Ingredients: There are so many different options for jarred pasta sauce, it can be hard to know what to choose.","Always look for a sauce with little or, better yet, no added sugar.","Make sure the ingredient list includes only things you recognize, and avoid sauces with high-fructose corn syrup and added preservatives."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-herb-polenta-fries','Crispy Herb Polenta Fries','From Stress-Free Family Meal Planning - 2 servings','american','medium',24,11,35,2,NULL,0,1,0,1,0,'none',3,0.773,3,1,'[{"name":"tube polenta","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"spaghetti sauce","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Preheat the oven to 400°F (204°C).","Spray a large baking sheet with cooking spray.Cut the polenta into slices that are about ¾ inch (2 cm) thick.","Then cut those slices into fries that are about ¾ inch (2 cm) wide.","Transfer the fries to the prepared baking sheet.Gently toss the polenta fries with the oil, garlic powder, Italian seasoning, salt, and black pepper.Spread out the polenta fries in a single layer, so that they aren’t touching.","Bake the polenta fries for 30 minutes, flipping them halfway through the cooking time, until they are brown and crispy.","Serve the polenta fries with the spaghetti sauce for dipping.Kitchen Tip: Tubed polenta is one of my favorite pantry staples to grab when I need a quick side dish.","Although fries are our family favorite, you can cut the polenta into cubes for croutons, rounds for an easy appetizer, or “soldiers” for dipping into soup."]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('skillet-turkey-enchiladas','Skillet Turkey Enchiladas','From Stress-Free Family Meal Planning - 4 servings','mexican','medium',21,9,30,4,NULL,0,0,0,0,1,'turkey',3,0.71,3,1,'[{"name":"salsa verde","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"reduced-fat sour cream or cream cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"shredded Cheddar cheese","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Add the onion and bell pepper.","Cook the vegetables for 4 to 5 minutes, until they are tender.","Add the garlic and cook it for 30 seconds, until it is fragrant.","Add the turkey, cumin, oregano, and salt.","Cook the mixture for 7 to 10 minutes, breaking up the turkey as it cooks, until the turkey is brown and cooked through.","Taste the mixture and season it with additional salt if needed.Stir in the pinto beans, tortillas, and salsa verde.","Cook the mixture for 4 to 5 minutes, until it is heated through and the tortillas are soft.","Stir in the sour cream, if using, until it is fully incorporated.","Add the Cheddar cheese and cover.","Cook the mixture for 2 to 3 minutes, until the cheese is melted.Top the enchiladas with cilantro, avocado, jalapeños, diced tomatoes, or any other toppings you enjoy.Reheating Tip: If you are using the leftovers for lunch, add some extra salsa before reheating to keep everything moist and delicious.Know Your Ingredients: In this recipe, I opt for salsa verde instead of standard enchilada sauce.","Although enchilada sauce would work, I find the ingredients in salsa to be much cleaner—more veggies, fewer fillers and artificial flavors.","And in case you’re wondering, salsa definitely counts as a serving of veggies."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cheddar-apple-chicken-burgers','Cheddar-Apple Chicken Burgers','From Stress-Free Family Meal Planning - 2 servings','american','easy',10,5,15,2,NULL,0,0,0,0,1,'chicken',3,1,3,1,'[{"name":"lean ground chicken½ apple","quantity":8,"unit":"oz","unit_norm":"oz","category":"meat"},{"name":"shredded Cheddar cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"olive oil","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["In a medium bowl, combine the chicken, apple, Cheddar cheese, poultry seasoning, garlic powder, salt, and black pepper.","Gently combine the ingredients using your hands, and try not to compress the meat.Divide the meat into portions and shape them into patties.","Make a small indent in the center of each patty with your thumb to help it cook more evenly.Heat the oil in a medium skillet over medium-high heat.","Add the burgers and cook them for 4 to 5 minutes on each side, until the burgers’ internal temperature reaches at least 165°F (74°C)."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('slow-cooker-honey-soy-chicken','Slow Cooker Honey-Soy Chicken','From Stress-Free Family Meal Planning - 6 servings','american','easy',10,5,15,6,NULL,0,0,0,1,0,'chicken',1,0.943,8,1,'[{"name":"boneless, skinless chicken thighs","quantity":2,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"low-sodium soy sauce","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"honey","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"rice vinegar½ red onion","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"minced fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Asian garlic chili paste","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"cornstarch","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"sliced green onions","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Add the chicken thighs to the slow cooker.In a medium bowl, mix together the soy sauce, honey, vinegar, red onion, garlic, ginger, and Asian garlic chili paste (if using).","Pour the sauce over the chicken.","Cook the chicken on low for 4 hours.Remove the chicken and set it aside.","Whisk the cornstarch into the liquid in the slow cooker.","Cover the slow cooker with its lid and increase the heat to high.","Cook the sauce for 15 to 30 minutes, until it thickens to your liking.Meanwhile, slice or shred the chicken.","Transfer it back to the sauce.","Top the chicken with the green onions.Kitchen Hack: If you forget to throw this in your slow cooker, you can always speed things up with a rotisserie chicken.","Simply add the ingredients for the sauce to a small pot over medium heat and simmer it until it thickens.","Then toss the sauce with the sliced rotisserie chicken and serve."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('coconut-quinoa','Coconut Quinoa','From Stress-Free Family Meal Planning - 4 servings','american','easy',18,9,27,4,NULL,0,1,0,0,1,'none',2,0.75,5,0,'[{"name":"coconut oil","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"quinoa","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"unsweetened shredded coconut","quantity":2.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"canned coconut milk","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"water","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Add the quinoa and coconut.","Toast them for 4 to 5 minutes, stirring often, until they are light brown.","Add the coconut milk, water, brown sugar, and salt.Bring the quinoa to a boil and stir.","Reduce the heat to low.","Cover the quinoa and cook it for 15 minutes.Without uncovering the pot, turn off the heat and let the quinoa sit for 5 minutes, or until it is fluffy and the liquid is absorbed.","Fluff the quinoa with a fork.Make It Your Own: We love adding some fresh lime juice to this dish, along with either chopped fresh cilantro or green onions.","If you prefer something sweeter, use sweetened shredded coconut in place of the unsweetened.","Trying to sneak in veggies?","Throw in some cauliflower rice.","It blends right in with the quinoa."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spicy-asian-brussels-sprouts','Spicy Asian Brussels Sprouts','From Stress-Free Family Meal Planning - 2 servings','asian','easy',18,9,27,2,NULL,0,1,0,1,0,'none',2,0.812,6,0,'[{"name":"fresh Brussels sprouts","quantity":8,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"sesame oil","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Salt","quantity":null,"unit":"","category":"produce"},{"name":"Black pepper","quantity":null,"unit":"","category":"produce"},{"name":"low-sodium soy sauce","quantity":1.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 450°F (232°C).","Spray a large baking sheet with cooking spray.In a large bowl, toss the Brussels sprouts with the oil.","Lightly season them with the salt and black pepper.","Place the Brussels sprouts in a single layer on the baking sheet, leaving some space between the Brussels sprouts.","They shouldn’t overlap.","Roast the Brussels sprouts for 20 to 25 minutes, or until they are brown and crispy.Meanwhile, in a small saucepan over medium heat, combine the soy sauce, honey, rice vinegar, Asian garlic chili paste, and garlic powder.","Bring the mixture to a simmer and cook it for 3 to 4 minutes, until it thickens and coats the back of a spoon.","Remove the sauce from the heat.Toss the hot Brussels sprouts with the sauce and serve."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('creamy-spinach-and-artichoke-pasta','Creamy Spinach and Artichoke Pasta','From Stress-Free Family Meal Planning - 2 servings','italian','medium',21,9,30,2,NULL,0,0,0,0,1,'chicken',4,0.693,10,0,'[{"name":"olive oil","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"boneless, skinless chicken breast","quantity":8,"unit":"oz","unit_norm":"oz","category":"meat"},{"name":"canned or jarred artichoke hearts","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"low-sodium chicken broth","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"pasta","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"baby spinach","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"shredded Parmesan cheese","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"reduced-fat cream cheese","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"Salt","quantity":null,"unit":"","category":"dairy"},{"name":"Black pepper","quantity":null,"unit":"","category":"dairy"}]','["Add the shallot, garlic, and artichoke hearts to the pot.","Cook for 3 to 4 minutes, stirring often.Add the broth and bring the mixture to a boil.","Add the pasta.","Bring the mixture back to a boil, and then reduce the heat to medium-low.","Cover the pot and cook the pasta for 12 to 15 minutes, stirring halfway through the cooking time, until the pasta is al dente and has absorbed most of the liquid.Stir in the spinach and cook until it wilts.","Stir in the Parmesan cheese, cream cheese, and cooked chicken.","Remove the pot from the heat and let the mixture rest for 5 minutes to allow the sauce to thicken.","Season the pasta with the salt and black pepper."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('broiled-barbecue-flank-steak-with-mango-salsa','Broiled Barbecue Flank Steak with Mango Salsa','From Stress-Free Family Meal Planning - 4 servings','american','easy',17,8,25,4,NULL,0,0,0,1,0,'beef',2,0.75,6,0,'[{"name":"lean flank steak","quantity":1.33,"unit":"lb","unit_norm":"lb","category":"pantry"},{"name":"olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"brown sugar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"paprika","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"diced red onion","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"}]','["In a small bowl, mix together the brown sugar, paprika, garlic powder, onion powder, salt, chili powder, and black pepper.","Set the spice rub aside.Place the steak on the foil-lined baking sheet.","Broil the steak for 4 to 5 minutes.","Carefully flip the steak over and cover the top with the spice rub.","Broil the steak for 4 to 5 minutes, until it is brown and its internal temperature reaches 140°F (60°C) for medium doneness.","Adjust the cooking time depending on your desired level of doneness.","Remove the steak from the oven and tent it with foil.","Let the steak rest for 10 minutes.Meanwhile, make the mango salsa.","In a medium bowl, mix together the mango, jalapeño (if using), onion, cilantro, lime juice, salt, and black pepper.Slice the steak very thinly against the grain and serve it with the mango salsa.Kitchen Tip: During spring and summer, we make this dish on the grill.","It will take the same amount of time on a medium-hot grill.","For something extra special, toss your mango on the grill for a couple of minutes to add some smoky flavors.Steak Cooking TimesRare— 4–6 minutes totalMedium Rare— 6–8 minutes totalMedium— 8–11 minutes totalMedium Well— 10–12 minutes totalWell— 12–15 minutes total"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('skillet-pork-tenderloin-with-apples-and-snap-peas','Skillet Pork Tenderloin with Apples and Snap Peas','From Stress-Free Family Meal Planning - 4 servings','american','medium',24,11,35,4,NULL,0,0,0,1,0,'pork',4,0.71,5,1,'[{"name":"lean pork tenderloin","quantity":1.33,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"honey","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"snap peas","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"olive oil","quantity":4,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Black pepper","quantity":null,"unit":"","category":"produce"}]','["Preheat the oven to 400°F (204°C).Coat all sides of the pork with the grill seasoning.","In a medium bowl, toss the apples with the honey, cinnamon, and a pinch of salt.","In another medium bowl, toss the snap peas with 2 teaspoons (10 ml) of the oil, salt, and black pepper.In a large, heavy, oven-safe skillet, heat the remaining 2 teaspoons (10 ml) of oil over medium-high heat.","Add the pork tenderloin and sear the pork for 3 to 4 minutes on each side, turning the pork once it is brown.","Push the pork to the center of the skillet.","Add the snap peas on one side and the apples on the other side.Place the skillet in the oven and roast the pork, apples, and snap peas for 13 to 17 minutes, or until the pork’s internal temperature reaches 145°F (63°C).","Stir the apples and snap peas halfway through the cooking time.Tent the entire skillet with foil and let the pork rest for 10 minutes before serving.Make It Yours: This is one of those recipes that allows you to play with flavors.","Use peaches, plums, or pears instead of apples.","Swap out the spice blend for herbs like rosemary or thyme.","Try different veggies like asparagus or green beans."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tomato-basil-fish','Tomato-Basil Fish','From Stress-Free Family Meal Planning - 2 servings','american','easy',14,6,20,2,NULL,0,0,1,0,1,'fish',3,0.925,5,0,'[{"name":"olive oil","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"canned San Marzano tomatoes","quantity":10,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"butter","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"coarsely chopped fresh basil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"white fish","quantity":10,"unit":"oz","unit_norm":"oz","category":"seafood"}]','["Add the garlic and cook it for 30 seconds, until it is fragrant.","Add the tomatoes, breaking them up with a wooden spoon.","Add the butter and basil.","Cook the mixture for 5 minutes, until the tomatoes begin to break down.Meanwhile, season the fish with the oregano, salt, and black pepper.Add the fish to the pan and cover it with the tomato sauce.","Cover the pan and cook the fish for 10 to 12 minutes, until the fish is cooked through and flakes easily with a fork.Know Your Ingredients: San Marzano tomatoes are a type of tomato from Italy that tend to be sweeter and less acidic than standard tomatoes.","They can make a big difference in the flavor of tomato sauces and in my opinion are worth the extra money.","With that said, regular canned tomatoes will also work just fine in this dish."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-baked-sweet-potato-taquitos','Crispy Baked Sweet Potato Taquitos','From Stress-Free Family Meal Planning - 2 servings','american','medium',21,9,30,2,NULL,0,1,0,1,0,'none',1,0.71,6,1,'[{"name":"diced sweet potatoes","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"canned black beans","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"canned diced tomatoes with green chiles, undrained¼ to","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"salsa verde½ avocado","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"finely chopped fresh cilantro","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Salt","quantity":null,"unit":"","category":"pantry"}]','["Preheat the oven to 425°F (218°C).","Spray a large baking sheet with cooking spray.To make the taquitos, heat the oil in a large skillet over medium-high heat.","Add the onion and cook it for 4 to 5 minutes, until it is soft.","Add the garlic and cook the mixture for 30 seconds, until the garlic is fragrant.","Add the sweet potatoes, black beans, tomatoes with green chiles, chili powder, cumin, and paprika.","Stir the mixture and add the water.","Reduce the heat to medium-low and cover the skillet.","Cook the filling for 10 minutes.","Uncover the skillet and stir the mixture.","Cook the filling for 2 to 3 minutes, if needed, until the sweet potatoes are tender and beginning to break down.","Add the lime juice and cilantro.","Season the filling with salt and black pepper.To assemble the taquitos, wrap 3 tortillas in a moist paper towel.","Microwave them for 30 to 45 seconds to soften the tortillas.","Add 1 rounded tablespoon (15 g) of the filling to each of the tortillas.","Roll the tortillas and place them on the prepared baking sheet, seam side down.","Repeat this process with the remaining tortillas.","Spray the taquitos with cooking spray.Bake the taquitos for 22 to 25 minutes, until their tops are crispy.","If needed, increase the oven’s temperature to broil and broil the taquitos for 1 to 2 minutes to brown the edges.While the taquitos are baking, make the creamy salsa verde.","In a blender, combine the salsa verde, avocado, and cilantro.","Blend until the ingredients are smooth.","Season the creamy salsa verde with salt.","Serve it with the taquitos.Kitchen Hack: The most time-consuming part of this recipe is making the taquitos.","For a quicker option, simply bake your own crispy taco shells in an oven preheated to 400°F (204°C) for 8 to 10 minutes while you make the filling."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('creamy-ranch-chicken-bites','Creamy Ranch Chicken Bites','From Stress-Free Family Meal Planning - 2 servings','american','medium',21,9,30,2,NULL,0,0,0,0,1,'chicken',4,0.773,4,1,'[{"name":"boneless, skinless chicken breast, cut into bite-size pieces","quantity":10,"unit":"oz","unit_norm":"oz","category":"meat"},{"name":"Greek yogurt","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"shredded Parmesan cheese","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"homemade or store-bought ranch seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 400°F (204°C).","Line a medium baking sheet with foil and spray the foil with cooking spray.In a large bowl, stir together the chicken, yogurt, Parmesan cheese, ranch seasoning, and lemon zest.","Marinate the chicken for at least 15 minutes (or up to 60 minutes) at room temperature.Spread the chicken out in a single layer on the prepared baking sheet.","Bake the chicken for 10 to 15 minutes, until the chicken’s internal temperature reaches at least 165°F (74°C).","Optionally, during the last 2 minutes of cooking time, increase the oven’s temperature to broil to brown the top of the chicken.Season the chicken with the salt and black pepper and serve.Know Your Ingredients: It’s important to pay attention to the ingredients in store-bought ranch seasoning mixes, since some have lots of artificial and unnecessary ingredients.","Look for a seasoning blend that contains dried buttermilk, dried herbs, and dried spices only.","For the healthiest option, make your own by mixing the following: ¼ cup (60 g) dried buttermilk, 1½ tablespoons (9 g) onion powder, 1 tablespoon (6 g) garlic powder, ½ tablespoon (3 g) dried chives, ½ tablespoon (3 g) dried dill, ½ tablespoon (3 g) dried parsley, 2 teaspoons (5 g) kosher salt and ½ teaspoon black pepper."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mini-meatloaves-and-green-beans','Mini Meatloaves and Green Beans','From Stress-Free Family Meal Planning - 4 servings','american','medium',28,12,40,4,NULL,0,1,0,1,0,'none',2,0.575,7,1,'[{"name":"seasoned whole-wheat breadcrumbs","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"grated onion","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"finely shredded carrots","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"ketchup","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"green beans","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"ketchup","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 400°F (204°C).","Line a large baking sheet with foil and spray the foil with cooking spray.To make the meatloaves and green beans, combine the turkey, breadcrumbs, onion, carrots, garlic, ketchup, grill seasoning, egg, egg white, and Worcestershire sauce in a large bowl.","Season the mixture with salt and black pepper as needed, depending on the grill seasoning used.","Use your hands to gently combine the meatloaf mixture, being sure not to compress the meat.","Divide the mixture into four portions.","Use your hands to shape each portion into a mini meatloaf, not more than 1 inch (2.5 cm) thick.","Place the meatloaves on the prepared baking sheet.","Bake the meatloaves for 15 minutes.Meanwhile, trim the green beans.","Place them in another large bowl and toss them with the oil.","Season them with salt, black pepper, and additional grill seasoning (if desired).To make the glaze, mix together the ketchup, brown sugar, and mustard in a small bowl.Remove the baking sheet from the oven.","Brush the meatloaves with the glaze.","Add the green beans to the baking sheet.Return the baking sheet to the oven and cook the meatloaves and green beans for 10 to 12 minutes, until the meatloaves’ internal temperature reaches 165°F (74°C) and the green beans are crisp-tender.Recipe Blueprint: Use this meatloaf recipe as a base and try out different flavor combinations.","Add cheese and taco seasoning for a Mexican spin.","Use Italian seasoning and spaghetti sauce for the glaze for an Italian option.","Use different veggies to switch things up."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sesame-orange-chicken-and-broccoli','Sesame-Orange Chicken and Broccoli','From Stress-Free Family Meal Planning - 4 servings','american','medium',24,11,35,4,NULL,0,0,0,1,0,'chicken',2,0.71,11,1,'[{"name":"chicken","quantity":1.33,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"cornstarch","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Salt","quantity":null,"unit":"","category":"produce"},{"name":"Black pepper","quantity":null,"unit":"","category":"produce"},{"name":"orange juice","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"low-sodium soy sauce","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"rice vinegar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"sesame oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"broccoli florets","quantity":4,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"sesame seeds","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 400°F (204°C).In a large bowl, toss the chicken with 1 tablespoon (9 g) of the cornstarch, salt, and black pepper.In a small bowl, whisk together the orange juice, soy sauce, honey, remaining 1 tablespoon (9 g) of cornstarch, vinegar, ginger, garlic, and orange zest.","Set the mixture aside.In a large oven-safe skillet, heat the oil over medium heat.","Add the chicken in a single layer.","Cook it for 2 to 3 minutes on one side, until it is brown.","Flip the chicken and cook it for 2 to 3 minutes on the other side.","Turn off the heat and pour the sauce mixture over the chicken, stirring to combine.","Place the skillet in the oven and cook the chicken for 10 minutes.Carefully remove the skillet and stir in the broccoli.","Return the skillet to the oven and cook for 5 minutes.","Sprinkle the chicken and broccoli with the sesame seeds and serve.Kitchen Hack: Miss the crunch?","My friend makes this recipe for her kids all the time with store-bought baked chicken nuggets.","She gets the nuggets and broccoli started on a baking sheet while she reduces the sauce on the stove until it’s thick.","Toss the sauce with the nuggets and broccoli for a healthier version that still has crispy chicken."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('blackened-fish-tacos-with-mexican-corn-slaw','Blackened Fish Tacos with Mexican Corn Slaw','From Stress-Free Family Meal Planning - 4 servings','mexican','easy',17,8,25,4,NULL,0,0,1,0,1,'fish',3,0.83,7,1,'[{"name":"olive oil","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"fresh, canned, or frozen corn","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"light mayonnaise","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"coleslaw mix","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"crumbled queso fresco cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"blackening seasoning","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"cod","quantity":1,"unit":"lb","unit_norm":"lb","category":"pantry"}]','["Add the corn and cook it, stirring occasionally, for 4 to 5 minutes, until the corn is brown and beginning to char.","Remove the corn from the heat and set it aside.","Let the corn cool.In a large bowl, combine the mayonnaise, yogurt, and lime juice and zest.","Season the mixture with the salt and black pepper.","Add the corn, avocado, coleslaw mix, cilantro, jalapeño, and green onion.","Stir to combine.","Taste the slaw and season it with salt and black pepper as needed.","Top the slaw with the queso fresco cheese.","Set the slaw aside while you make the tacos.To make the tacos, press the blackening seasoning into the cod.","Heat the oil in a medium heavy-bottomed skillet over medium-high heat.","Add the cod and cook it for 3 to 4 minutes, until the blackening seasoning darkens and becomes almost black.","Flip the fish and cook it 3 to 4 minutes, until it is cooked through and easily flakes with a fork.Serve the fish in the tortillas topped with the Mexican corn slaw."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('shortcut-refried-beans','Shortcut Refried Beans','From Stress-Free Family Meal Planning - 2 servings','american','easy',14,6,20,2,NULL,0,0,0,0,1,'chicken',2,1,7,1,'[{"name":"diced onion","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"canned pinto beans","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"chicken broth","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"Salt","quantity":null,"unit":"","category":"meat"},{"name":"Black pepper","quantity":null,"unit":"","category":"meat"},{"name":"pico de gallo","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"shredded Cheddar cheese","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Add the onion and garlic.","Cook them for 4 to 5 minutes, until the onion begins to soften.","Add the pinto beans and broth.","Cook the beans for about 5 minutes, until they are warm.","Turn off the heat and season the beans with the salt and black pepper.Mash the beans using a potato masher or wooden spoon.Top the beans with the pico de gallo and Cheddar cheese.","Cover the skillet for 2 to 3 minutes, until the Cheddar cheese melts.Recipe Ideas: There are so many ways to customize refried beans.","Make them spicy by adding a diced jalapeño with the onion.","Add smokiness with a pinch of cumin or canned chipotle pepper in adobo.","Use black beans instead of pinto for a different twist."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chickpea-pizza','Chickpea Pizza','From Stress-Free Family Meal Planning - 2 servings','american','medium',35,15,50,2,NULL,0,1,0,0,1,'none',3,0.575,5,1,'[{"name":"chickpea flour","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"warm water","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"spaghetti sauce","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"shredded part-skim mozzarella cheese½ to","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Add all of your favorite toppings for a healthier spin on family pizza night.Serves: 2Total Time: 50 minutes1 cup (130 g) chickpea flour1 cup (240 ml) warm water2 tbsp (30 ml) olive oil, divided½ tsp garlic powder½ tsp Italian seasoningSalt, as neededBlack pepper, as needed½ cup (120 ml) spaghetti sauce⅔ cup (75 g) shredded part-skim mozzarella cheese½ to 1 cup pizza toppings of choiceIn a medium bowl, mix together the chickpea flour, warm water, 1 tablespoon (15 ml) of the oil, garlic powder, Italian seasoning, salt, and black pepper until the ingredients are well combined.","Let the mixture rest for at least 30 minutes.Preheat the oven to 450°F (232°C).Heat a 10- to 12-inch (25- to 30-cm) cast-iron skillet over medium-high heat.","After 2 to 3 minutes, once the skillet is very hot, add the remaining 1 tablespoon (15 ml) of oil and swirl the skillet around to coat the skillet with the oil.","You may also want to spray the skillet with cooking spray if things tend to stick to it.","Add the chickpea mixture and swirl it around the skillet.","It will bubble on the edges.","Place the skillet in the oven and cook the pizza crust for 15 minutes, until it is firm.Remove the skillet from the oven and spread the pizza crust with the spaghetti sauce.","Add the mozzarella cheese and pizza toppings.","Return the pizza to the oven for 5 minutes, until the cheese is melted.","Remove the pizza from the oven and let it rest for 5 minutes before serving."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cheesy-broccoli-and-cauliflower-chowder','Cheesy Broccoli and Cauliflower Chowder','From Stress-Free Family Meal Planning - 4 servings','american','medium',28,12,40,4,NULL,0,0,0,1,0,'chicken',1,0.575,5,1,'[{"name":"white whole-wheat flour","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"low-sodium chicken broth","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"frozen cauliflower","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"frozen broccoli","quantity":3,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"canned cannellini beans","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Add the onion, carrot, celery, and garlic.","Cook the vegetables for 6 to 8 minutes, stirring often, until the onion is translucent and the other vegetables have softened.","Add the flour and stir to coat the vegetables.","Add the broth, milk, cauliflower, broccoli, cannellini beans, salt, black pepper, and nutmeg (if using).Bring the soup to a simmer and cook it for 20 minutes, until the broccoli and cauliflower are very tender.Add the Cheddar cheese, about ¼ cup (30 g) at a time, stirring it into the soup until the soup is smooth.Add half of the soup to a blender.","Blend until the soup is smooth.","Return the blended soup to the pot.","Season the soup with salt and black pepper if needed.","Serve with extra Cheddar cheese if desired.If You’re Craving Crunch: Make some easy croutons.","Preheat the oven to 375°F (191°C).","Slice or tear 6 slices of whole-grain bread into bite-size pieces.","Toss them with 2 tablespoons (30 ml) of olive oil, ¾ teaspoon of garlic powder, ½ teaspoon of kosher salt, and black pepper as needed.","Spread out the bread in a single layer on a medium baking sheet.","Bake the croutons for 15 to 20 minutes, shaking the baking sheet halfway through the cooking time.Know Your Ingredients: In a soup like this, cheese really matters.","Since we are using about a third of the cheese used in a standard cheesy soup, make sure to choose a strong, pungent, delicious Cheddar.","My favorite is extra-sharp aged Cheddar.","Shred it yourself for a smoother soup."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('slow-cooker-citrus-carnitas-with-pineapple-salsa','Slow Cooker Citrus Carnitas with Pineapple Salsa','From Stress-Free Family Meal Planning - 6 servings','american','easy',10,5,15,6,NULL,0,0,0,1,0,'pork',1,0.943,6,1,'[{"name":"lean pork shoulder","quantity":2,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"orange juice","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lime juice","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"finely chopped fresh cilantro","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"diced red onion","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"fresh lime juice","quantity":1.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Add the pork and sear it for 3 to 4 minutes on each side.","If you don’t have time, skip this step.","Add the pork to a large slow cooker.In a small bowl, mix together the orange juice, lime juice, cumin, oregano, salt, black pepper, and garlic.","Pour this mixture over the pork.","Add the bay leaf.","Cook the pork on low for 8 hours.Shred the pork with two forks and let it marinate in the cooking juices for 30 minutes to soak up the flavors.Meanwhile, make the pineapple salsa.","In a medium bowl, combine the pineapple, bell pepper, jalapeño, cilantro, onion, lime juice, orange juice, salt, and black pepper.Serve the pork carnitas with the pineapple salsa.Optional Step: For crispy carnitas, remove the pork from the slow cooker with a slotted spoon and place it on a large baking sheet covered with foil.","Broil the carnitas for 3 to 5 minutes, until they are brown and crispy.Recipe Ideas: If you are missing spice in this dish, consider two quick options for kicking things up.","Try adding 1 to 2 canned chipotle peppers to the pork while it cooks.","This adds heat and some smokiness.","Alternatively, add an extra jalapeño or swap it for a spicier pepper, like a serrano or habanero, in the pineapple salsa."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('one-pot-american-chop-suey','One-Pot American Chop Suey','From Stress-Free Family Meal Planning - 2 servings','american','medium',35,15,50,2,NULL,0,0,0,1,0,'beef',2,0.575,6,1,'[{"name":"Italian seasoning⅛ tsp red pepper flakes","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"low-sodium beef broth","quantity":1,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"canned fire-roasted diced tomatoes, undrained","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"tomato sauce","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"tomato paste","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"cellentani pasta or elbow macaroni","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"}]','["Add the onion, green bell pepper, and red bell pepper.","Cook the vegetables for about 5 minutes, stirring frequently, until they have softened but not browned.","Add the garlic, Italian seasoning, and red pepper flakes (if using).","Cook the mixture for about 1 minute, stirring often, until the garlic is fragrant.","Add the beef and cook the mixture for 5 to 7 minutes, until the beef is brown.Season the beef with the salt and black pepper.","Add the broth, tomatoes, tomato sauce, tomato paste, Worcestershire sauce, and bay leaf.","Reduce the heat to medium-low and simmer the beef mixture for 20 minutes.Add the cellentani pasta and cook it for 12 to 15 minutes, until the pasta is cooked to your liking.","Discard the bay leaf, then taste and season the American chop suey as needed before serving.Kitchen Hack: Don’t have time to make homemade sauce?","Try this instead: Get the pasta started.","Meanwhile, brown the ground beef with ½ onion, 1 diced bell pepper, and a few cloves of minced garlic.","Add a jar of your favorite spaghetti sauce, a splash of Worcestershire sauce, and a sprinkling of Italian seasoning.","Season the mixture with salt and black pepper, and dinner is done."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-coconut-chicken-strips','Crispy Coconut Chicken Strips','From Stress-Free Family Meal Planning - 4 servings','american','medium',21,9,30,4,NULL,0,0,0,1,0,'chicken',2,0.773,3,1,'[{"name":"panko breadcrumbs","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"unsweetened shredded coconut","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"brown sugar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 400°F (204°C).","Spray a large baking sheet with cooking spray.Season the chicken strips with the salt and black pepper.","On a plate, mix together the panko breadcrumbs, coconut, brown sugar, and garlic powder.","Place the eggs in a shallow dish next to the plate of breadcrumbs.","Dip each chicken strip into the eggs and let the excess drip off.","Then dredge the chicken strip in the coconut breadcrumbs.","Place each chicken strip on the prepared baking sheet.Spray the top of the chicken strips with cooking spray.","Bake the chicken strips for 7 to 8 minutes per side, until they are light brown and their internal temperature reaches 165°F (74°C)."]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sesame-mandarin-green-beans','Sesame-Mandarin Green Beans','From Stress-Free Family Meal Planning - 2 servings','american','easy',10,5,15,2,NULL,0,1,0,1,0,'none',2,1,3,1,'[{"name":"green beans","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"water","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"sesame seeds","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Heat a medium skillet over medium-high heat.","Add the green beans and water to the skillet.","Bring the water to a boil and cook the green beans for 3 to 4 minutes, until they are bright green.","Drain any excess water.Add the oil, garlic, mandarin orange zest, salt, and black pepper.","Stir and cook the green beans for 2 to 3 minutes, until the green beans are crisp-tender.Drizzle the mandarin orange juice over the green beans, then sprinkle them with the sesame seeds.Optional Addition: Add mandarin orange slices to the green beans.Know Your Ingredients: Green beans need a little prep work before they get cooked.","Start by washing and drying the beans, then trim the stem end.","Normally you don’t need to remove the opposite end as well, but you can if it seems tough or fibrous."]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('asian-peanut-lettuce-wraps','Asian Peanut Lettuce Wraps','From Stress-Free Family Meal Planning - 4 servings','asian','easy',14,6,20,4,NULL,0,1,0,0,1,'none',1,1,11,1,'[{"name":"sesame oil","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"minced fresh ginger","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"diced mushrooms","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"low-sodium soy sauce","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"peanut butter","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"hot water","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"fresh lime juice","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"shredded carrots","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"finely chopped green onions","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"finely chopped fresh cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Add the garlic and ginger and cook it for 30 seconds, until it is fragrant.","Add the turkey and mushrooms and cook them for 6 to 8 minutes, breaking the turkey up as it cooks.Meanwhile, in a small bowl, mix together the soy sauce, peanut butter, water, lime juice, honey, and Asian garlic chili paste (if using).Once the turkey is no longer pink, add the peanut sauce to the skillet.","Stir to coat the turkey in the sauce.","Cook the turkey for 2 to 3 minutes, until the sauce thickens and coats the turkey.Serve the turkey wrapped in the butter lettuce leaves and topped with the carrots, green onions, cilantro, peanuts, and lime wedges.Recipe Ideas: If you love this peanut sauce as much as we do, you’ll want to use it for other meals.","Toss it with shredded chicken, use it for Asian pasta dishes or stir-fries, drizzle it on salads, and use it as a dipping sauce for everything from baked chicken strips to spring rolls."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-and-spicy-pepper-jelly-chicken-and-cauliflower','Sweet and Spicy Pepper Jelly Chicken and Cauliflower','From Stress-Free Family Meal Planning - 2 servings','american','easy',14,6,20,2,NULL,0,0,0,1,0,'chicken',2,0.943,5,1,'[{"name":"cauliflower florets½ red onion","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"olive oil","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"meat"},{"name":"Salt","quantity":null,"unit":"","category":"meat"},{"name":"Black pepper","quantity":null,"unit":"","category":"meat"},{"name":"hot pepper jelly","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"}]','["Preheat the oven to 400°F (204°C).To make the cauliflower, toss the cauliflower and onion with the oil in a medium bowl.","Season the cauliflower and onion liberally with salt and black pepper.","Spread out the vegetables in a single layer on a large baking sheet.","Roast them for 15 minutes.Meanwhile, make the chicken.","In a large bowl, combine the hot pepper jelly, apricot preserves, garlic, salt, and black pepper.","Add the chicken thighs to this mixture and let them marinate while the cauliflower cooks.Remove the baking sheet from the oven.","Nestle the chicken thighs among the cauliflower and onion.","Top the chicken with any remaining marinade.","Roast the mixture for 15 minutes, or until the chicken is cooked through and its juices run clear.","Sprinkle the cilantro on top (if using) and serve.Serving Suggestion: If you are serving this meal with couscous, rice, or another grain, pour the pan juices over the grains for tons of extra flavor.Make It Yours: This simple sauce works with many combinations of proteins and vegetables.","Try making it with pork chops and green beans.","Use it as a marinade for chicken drumsticks.","It even tastes great spread on some salmon and baked in the oven.","If spice doesn’t work in your home, use all apricot preserves and add 1 to 2 tablespoons (15 to 30 ml) of soy sauce to cut the sweetness."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('shrimp-scampi-cakes','Shrimp Scampi Cakes','From Stress-Free Family Meal Planning - 4 servings','american','easy',17,8,25,4,NULL,0,0,1,0,1,'fish',4,0.892,4,1,'[{"name":"raw frozen shrimp, peeled and deveined","quantity":1,"unit":"lb","unit_norm":"lb","category":"seafood"},{"name":"fresh parsley","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"butter","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"olive oil","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Add 8 ounces (224 g) of the shrimp, the garlic, and the parsley to a food processor.","Pulse to create a chunky paste.","Coarsely chop the remaining 8 ounces (224 g) of shrimp.","Transfer the chopped and pulsed shrimp to a large bowl.","Add the breadcrumbs, egg, lemon zest, juice of ½ lemon, salt, and black pepper.","Mix until the ingredients are just combined.","Using a ¼-cup (60-g) measuring cup, form the mixture into round patties.Heat the butter in a medium skillet over medium-high heat.","Working in batches if necessary, add the shrimp patties to the skillet and cook them for 3 to 4 minutes per side, until they are cooked through and brown.In a medium bowl, toss together the arugula, tomato, oil, remaining lemon juice, additional salt, and additional black pepper.","Serve the arugula alongside the shrimp patties."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('baked-cilantro-lime-salmon-packets','Baked Cilantro-Lime Salmon Packets','From Stress-Free Family Meal Planning - 4 servings','american','medium',21,9,30,4,NULL,0,0,1,0,1,'fish',2,0.71,10,1,'[{"name":"salmon fillets","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"Salt","quantity":null,"unit":"","category":"seafood"},{"name":"Black pepper","quantity":null,"unit":"","category":"seafood"},{"name":"butter","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"canned corn","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"canned black beans","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"cherry tomatoes","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"diced green bell pepper","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"diced red onion","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"finely chopped fresh cilantro","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Preheat the oven to 400°F (204°C).","Cut eight squares of foil measuring about 12 x 12 inches (30 x 30 cm).","Layer two pieces of foil together to create 4 packets.Season the salmon on both sides with the salt and black pepper.In a small bowl, mix together the butter, honey, lime juice, and garlic.","In a medium bowl, mix together the corn, black beans, cherry tomatoes, bell pepper, and onion.Add about 1 cup (240 g) of the bean and corn mixture to each of the foil packets.","Place a salmon fillet on top of each portion of the bean mixture.","Pour the sauce over the salmon.Close the packets and place them on a large baking sheet.","Cook the packets for 10 minutes.","Carefully open the packets.","Increase the oven to broil and cook the salmon for 2 to 3 minutes to brown the top.","Sprinkle the cilantro on top of each fillet and serve.Kitchen Tip: For best results, always let your salmon come to room temperature before cooking.","Normally this takes between 15 and 20 minutes, but the extra time will ensure your salmon cooks evenly and correctly."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sheet-pan-chicken-and-vegetable-stir-fry','Sheet-Pan Chicken and Vegetable Stir-Fry','From Stress-Free Family Meal Planning - 4 servings','asian','medium',21,9,30,4,NULL,0,0,0,1,0,'chicken',1,0.71,11,1,'[{"name":"boneless, skinless chicken thighs","quantity":1.33,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"sesame oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"low-sodium soy sauce","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"water","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"hoisin sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"cornstarch","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"small broccoli florets","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"small cauliflower florets","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"thinly sliced carrots","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"snow peas","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Preheat the oven to 400°F (204°C).","Line a large baking sheet with foil and spray the foil with cooking spray.Toss the chicken with the oil and black pepper on the prepared baking sheet.","Spread out the chicken in a single layer on the prepared baking sheet.","Bake the chicken for 10 minutes.Meanwhile, combine the soy sauce, water, hoisin sauce, honey, garlic, and cornstarch in a small saucepan over medium-high heat.","Bring the mixture to a boil, and then reduce the heat to low.","Cook the sauce for 4 to 6 minutes, until it thickens and coats the back of a spoon, being careful not to burn it.Remove the chicken from the oven.","Add the broccoli, cauliflower, carrots, and snow peas to the baking sheet.","Drizzle the mixture with the sauce and toss to coat.","Cook the chicken and vegetables for 8 to 10 minutes, until the vegetables are crisp-tender.Recipe Ideas: Play around with the flavors in the stir-fry sauce to create different spins on this easy sheet-pan dinner.","Add Sriracha for a spicy sauce, add ginger and lemongrass for extra punch, swap oyster or sweet chili sauce for the hoisin sauce, add some curry paste—you get the idea."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mango-curry-chicken-salad','Mango Curry Chicken Salad','From Downshiftology Healthy Meal Prep cookbook',NULL,'medium',20,15,35,6,NULL,1,0,0,1,0,'chicken',3,0.63,12,0,'[{"name":"boneless","quantity":2,"unit":"pounds","unit_norm":"lb","category":"pantry"},{"name":"mangoes","quantity":2,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"celery ribs","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"green onions","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"raw cashews","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"roughly chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"roughly chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"mayonnaise","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lemon juice","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"curry powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Place the chicken in a wide pot and cover by about 1 inch of cold water.","Set over medium heat, add a generous pinch of salt, and bring the water to a gentle boil.","Reduce the heat to a low simmer and cover.","Let the chicken simmer for 8 to 12 minutes, or until an instant-read thermometer reads 160°F (71°C).","Use tongs to transfer the chicken to a plate and let it rest for a couple of minutes, then place it in the fridge until it’s completely cooled, about 15 minutes.","Set the cooled chicken on a cutting board and dice into ½-inch (1.3cm) pieces.","Place it in a large mixing bowl and add the diced mango, celery, green onions, cashews, parsley, cilantro, salt, and pepper.","In a separate small bowl, whisk together the mayonnaise, lemon juice, and curry powder.","Stir this mixture into the chicken until combined.","Cover the bowl with plastic wrap and refrigerate until chilled, about 30 minutes, then serve as you like (see Ways to Serve).","Store in an airtight container in the fridge for 4 to 5 days. ways to serve In addition to enjoying this salad by itself (which is what I usually do), you can pile it on gluten- free bread to make a sandwich, or roll it up in lettuce leaves or a grain-free tortilla to make a wrap. helpful tip When shopping for a ripe mango at the market, look for a slightly soft texture (similar to a ripe avocado).","If your mango is a bit hard or completely green, you can speed up the ripening process by placing it in a paper bag at room temperature for a couple of days."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('three-bean-salad-with-pine-nuts','Three-Bean Salad with Pine Nuts','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,1,0,1,0,'none',3,0.693,13,0,'[{"name":"olive oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"apple cider vinegar","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"garlic clove","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"honey","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"raw pine nuts","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"can cannellini beans","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"can kidney beans","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"can chickpeas","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"celery ribs","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"red onion","quantity":0.5,"unit":"medium","unit_norm":"","category":"produce"},{"name":"loosely packed fresh parsley","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["To make the dressing: In a small bowl, whisk together the oil, vinegar, garlic, honey, salt, and pepper.","To make the salad: Heat a small pan over medium-low heat and add the pine nuts.","Toast for 3 to 4 minutes, stirring frequently, until lightly golden.","In a large bowl, combine the cannellini beans, kidney beans, chickpeas, celery, red onion, pine nuts, and parsley.","Add the dressing and toss all the ingredients together until well combined.","Store in an airtight container in the fridge for 4 to 5 days."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('melon-and-shrimp-salad','Melon and Shrimp Salad','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,1,0,'fish',4,0.693,10,0,'[{"name":"fresh lime juice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ﬁnely chopped shallot","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"honey","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"roughly chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"extra-large shrimp","quantity":1,"unit":"pound","unit_norm":"lb","category":"seafood"},{"name":"cantaloupe","quantity":0.5,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"honeydew melon","quantity":0.5,"unit":"unit","unit_norm":"","category":"pantry"}]','["To make the dressing: In a small bowl, whisk together the lime juice, oil, shallot, honey, cilantro, and salt.","To make the salad: Heat the oil in a medium sauté pan over medium heat.","Add the shrimp and cook for 2 to 3 minutes on each side, or until the shrimp is pink and opaque.","Remove the shrimp to plate and place in the fridge to cool.","Place the shrimp in a large bowl with the cantaloupe and honeydew and toss with the dressing.","Store in an airtight container in the fridge for 3 to 4 days."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('turkey-spinach-patties','Turkey Spinach Patties','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,0,1,0,'turkey',2,0.773,8,1,'[{"name":"ground turkey","quantity":1,"unit":"pound","unit_norm":"lb","category":"meat"},{"name":"loosely packed baby spinach","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"green onions","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"ﬁnely chopped fresh oregano","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"olive oil","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["In a medium bowl, combine the turkey, spinach, green onions, garlic, oregano, salt, and pepper.","Use your hands to mix everything together.","Divide the mixture evenly and form 4 large patties.","In a large skillet over medium heat, heat the oil.","Cook the patties for approximately 5 minutes per side, or until golden brown and cooked through.","Preheat the oven to 350°F (180°C) and reheat for 4 to 5 minutes, until warmed through.","You can also reheat the patties in the microwave for 1 to 2 minutes. helpful tip If you don’t have fresh oregano, use dill or thyme.","If you want to substitute with dried herbs, use just 1 teaspoon."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemon-oregano-roasted-chicken-legs-and-potatoes','Lemon Oregano Roasted Chicken Legs and Potatoes','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,0,1,0,'chicken',2,0.71,8,1,'[{"name":"whole chicken legs","quantity":4,"unit":"unit","unit_norm":"","category":"meat"},{"name":"lemons","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"extra-virgin olive oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"garlic cloves","quantity":5,"unit":"unit","unit_norm":"","category":"produce"},{"name":"dried oregano","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"new potatoes","quantity":2,"unit":"pounds","unit_norm":"lb","category":"pantry"}]','["Preheat the oven to 400°F (200°C).","Pat the chicken dry with a paper towel and set aside.","In a small bowl, zest and juice 1 of the lemons.","You should have about 1 tablespoon of zest and 3 tablespoons of juice.","Add the oil, garlic, oregano, salt, and pepper and stir together.","Place the diced potatoes in a 13 × 9-inch (33 × 23cm) casserole dish and drizzle with half the lemon oil mixture, then toss to combine.","Arrange the chicken on top, drizzle with the remaining lemon oil mixture, and use your ﬁngers or a brush to make sure the chicken is well coated.","Thinly slice the remaining lemon and place the slices on top.","Roast the chicken for 50 to 60 minutes, basting every 15 minutes with the pan drippings, until golden brown and an instant-read thermometer inserted into the thigh reads 170°F to 175°F (76°C to 80°C) and the potatoes are tender.","If the top of the chicken is browning too quickly, cover the pan loosely with aluminum foil.","Store both the chicken and potatoes together in an airtight container in the fridge for 3 to 4 days, or in the freezer for up to 3 months.","If frozen, thaw in the fridge overnight.","Reheat in a 350°F (180°C) oven for about 10 minutes, or in the microwave for 2 to 3 minutes, until warmed through. helpful tip While chicken is safe to eat at 165°F (74°C), chicken legs (which contain more connective tissue) are most tender when they’re cooked to a slightly higher internal temperature.","But that’s perfect as it gives the potatoes enough time to cook!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pepper-steak-stir-fry','Pepper Steak Stir-Fry','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,0,0,1,0,'beef',2,0.71,14,1,'[{"name":"low-sodium tamari soy sauce or coconut aminos","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"sesame oil","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"coconut sugar","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"arrowroot powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ﬂank steak","quantity":1,"unit":"pound","unit_norm":"lb","category":"pantry"},{"name":"freshly ground black pepper","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"green bell peppers","quantity":2,"unit":"large","unit_norm":"","category":"produce"},{"name":"red bell pepper","quantity":1,"unit":"large","unit_norm":"","category":"produce"},{"name":"yellow onion","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"minced peeled fresh ginger","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"green onion","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["To make the sauce: In a small bowl, whisk together the tamari, sesame oil, coconut sugar, and arrowroot powder.","Set aside.","To make the stir-fry: In a medium bowl, toss the sliced steak with the pepper and salt until coated.","Heat a medium skillet or wok on medium- high heat and add 1 tablespoon of the avocado oil.","Add the ﬂank steak and sear for 1 to 2 minutes, until mostly browned but with a little bit of pink inside.","Remove to a plate.","Leave any juices in the pan and add the remaining 1 tablespoon avocado oil along with the bell peppers and onion and sauté 2 to 3 minutes, until tender.","Add the garlic and ginger to the skillet, stir for 30 seconds, then add the steak back to the skillet along with the sauce.","Stir- fry for 1 to 2 minutes, until the sauce thickens.","Serve over rice if you’d like and sprinkle the green onion on top.","Once thawed, reheat in a pan on the stove or in the microwave for 1 to 2 minutes, until warmed through. helpful tip You can also use skirt steak or top sirloin steak in this recipe.","Just make sure to cut against the grain (the opposite direction of the ﬁbers or striations) for the most tender pieces of meat."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('gingered-cashew-chicken-and-sugar-snap-peas','Gingered Cashew Chicken and Sugar Snap Peas','From Downshiftology Healthy Meal Prep cookbook','asian','medium',20,15,35,4,NULL,1,0,0,1,0,'chicken',3,0.71,17,1,'[{"name":"low-sodium chicken broth","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"low-sodium tamari soy sauce or coconut aminos","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"dry sherry","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"sesame oil","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"rice vinegar or apple cider vinegar","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"arrowroot powder","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"raw cashews","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"boneless","quantity":1,"unit":"pound","unit_norm":"lb","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"sugar snap peas","quantity":8,"unit":"ounces","unit_norm":"oz","category":"pantry"},{"name":"yellow bell pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"green onions","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"ﬁnely grated peeled fresh ginger","quantity":1.5,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["To make the sauce: In a small bowl, whisk together the broth, tamari, sherry, honey, sesame oil, vinegar, and arrowroot powder.","Set aside.","To make the stir fry: In a small pan on medium-low heat, toast the cashews for 4 to 5 minutes, until lightly golden, ﬂipping and tossing a few times.","Set aside.","In a large skillet or wok on medium-high heat, add 1 tablespoon of the avocado oil and swirl the pan to coat the bottom.","Add the chicken in a single ﬂat layer.","Season the chicken with the salt and pepper and cook until lightly browned, 4 to 5 minutes, stirring as needed.","Remove the chicken to a plate.","Leave any juices in the pan, then add the remaining 1 tablespoon avocado oil along with the sugar snap peas, bell pepper, and white parts of the green onion.","Cook the vegetables until tender, 3 to 4 minutes.","Add the chicken back to the pan with the minced garlic and grated ginger.","Stir for 30 seconds.","Pour in the sauce (it may need to be quickly stirred again ﬁrst) and stir-fry for another 1 to 2 minutes, until the sauce thickens.","Remove from the heat, stir in the cashews and green parts of the green onion, garnish with sesame seeds, and serve.","Once thawed, reheat in a pan on the stove or in the microwave for 1 to 2 minutes, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('golden-chicken-zoodle-soup','Golden Chicken Zoodle Soup','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,0,0,1,0,'chicken',2,0.63,14,0,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"yellow onion","quantity":0.5,"unit":"medium","unit_norm":"","category":"produce"},{"name":"celery ribs","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"carrots","quantity":3,"unit":"medium","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"low-sodium chicken broth","quantity":6,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"boneless","quantity":2,"unit":"large","unit_norm":"","category":"pantry"},{"name":"grated peeled fresh ginger","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"grated fresh turmeric","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"ground coriander","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"zucchini","quantity":1,"unit":"large","unit_norm":"","category":"produce"},{"name":"ﬁnely chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["In a large stockpot or Dutch oven, heat the oil over medium heat.","Add the onion, celery, and carrots and sauté for 4 to 5 minutes, until the onion becomes translucent.","Add the garlic and sauté 1 minute more.","Add the broth to the pot, along with the chicken, ginger, turmeric, coriander, salt, and pepper.","Bring to a boil, then reduce the heat to low and cover the pot.","Simmer the soup for 15 minutes, or until the chicken is cooked through.","With tongs, remove the chicken to a cutting board and shred with two forks, then return to the pot.","Stir in the spiralized zucchini and parsley and simmer for an additional minute.","Divide among bowls and serve.","Reheat from frozen or chilled.","Reheat a portion in a bowl in the microwave for 1 to 2 minutes if thawed, or 3 to 4 minutes if frozen, or in a pot on the stove until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('honey-citrus-chicken-breasts','Honey Citrus Chicken Breasts','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,0,1,0,'chicken',2,0.71,13,1,'[{"name":"olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"boneless","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"ﬁnely chopped shallot","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"orange zest","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"fresh orange juice","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lemon juice","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"honey","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"arrowroot powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"water","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"orange","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"}]','["In a large skillet, heat the oil over medium heat.","Season both sides of the chicken breasts with the salt and pepper.","Place in the skillet and cook for 5 to 7 minutes on each side, until lightly golden and the chicken has reached an internal temperature of 160°F (71°C).","Remove the chicken to a plate.","Place the shallot and garlic in the skillet and sauté for about 1 minute, until the shallot has softened.","Stir in the orange zest, orange juice, lemon juice, and honey, simmering until it reduces slightly, about 2 minutes.","Meanwhile, in a small bowl, stir together the arrowroot powder and water to create a slurry.","Pour the slurry into the pan and immediately whisk into the pan juices.","Add the diced orange to the pan and stir with the sauce.","Make room in the pan by pushing the orange slices to the side and return the chicken to the pan.","Turn the chicken to coat in the sauce and warm through, plate the chicken, and pour extra sauce on top.","Once thawed, reheat in a pan on the stove or in the microwave for 1 to 2 minutes, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mediterranean-lamb-meatballs','Mediterranean Lamb Meatballs','From Downshiftology Healthy Meal Prep cookbook','mediterranean','medium',20,15,35,6,NULL,1,0,0,0,1,'lamb',4,0.773,14,1,'[{"name":"ground lamb","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"egg","quantity":1,"unit":"large","unit_norm":"","category":"dairy"},{"name":"ﬁnely chopped red onion","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"almond ﬂour","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"ﬁnely chopped fresh parsley","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"ﬁnely chopped fresh mint","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"dried oregano","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"lemon zest","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"to 30 minutes","quantity":25,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"°F oven for 10 to 15 minutes","quantity":300,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 400°F (200°C).","Line a rimmed baking sheet with parchment paper.","In a medium bowl, combine the lamb, egg, onion, ﬂour, garlic, parsley, mint, oregano, cumin, lemon zest, salt, and pepper.","Using your hands, mix the ingredients together until well combined.","Measure out 1½ tablespoons (27g) of the mixture (or use a medium cookie scoop) and roll the mixture between your hands, forming about 30 meatballs.","Place the meatballs on the prepared baking sheet and bake for If frozen, thaw in the fridge overnight.","Place them in a single layer on a rimmed baking sheet in a through. dietary swaps If you’re not a fan of lamb, you can swap in ground pork or beef as well (or a use a mix of ground meats)."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('greek-sheet-pan-chicken','Greek Sheet Pan Chicken','From Downshiftology Healthy Meal Prep cookbook','mediterranean','medium',20,15,35,6,NULL,1,0,0,0,1,'chicken',3,0.71,15,1,'[{"name":"extra-virgin olive oil","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"dried oregano","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"dried thyme","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"Dijon mustard","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"bone-in chicken thighs","quantity":6,"unit":"unit","unit_norm":"","category":"meat"},{"name":"zucchini","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"yellow bell pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"red onion","quantity":0.5,"unit":"large","unit_norm":"","category":"produce"},{"name":"cherry or grape tomatoes","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"kalamata olives","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"feta cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"ﬁnely chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 425°F (220°C).","In a small bowl, whisk together the oil, lemon juice, garlic, oregano, thyme, mustard, salt, and pepper.","In a large bowl, use your hands to thoroughly coat the chicken thighs with two-thirds of the marinade.","Marinate the chicken for 10 to 15 minutes on the counter.","While the chicken is marinating, spread the zucchini, bell pepper, red onion, and cherry tomatoes in an even layer on a rimmed baking sheet.","Drizzle the remaining marinade on top and toss together to coat the vegetables.","Add the chicken thighs to the baking sheet, nestling them around the veggies, and bake for 30 minutes.","Remove the baking sheet from the oven and add the olives and feta.","Return the baking sheet to the oven for another 10 to 15 minutes, or until the vegetables are softened and the chicken is cooked through.","Sprinkle with chopped parsley before serving.","If frozen, thaw in the fridge overnight.","Reheat in a 350°F (180°C) oven for about 10 minutes, or in the microwave for 2 to 3 minutes, until warmed through. helpful tip If you’d like to use boneless, skinless chicken breasts rather than chicken thighs, cook the vegetables by themselves on the sheet pan ﬁrst for about 20 minutes.","Then add the chicken breasts on top and cook for another 20 to 25 minutes."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('slow-cooker-maple-mustard-pulled-pork','Slow-Cooker Maple Mustard Pulled Pork','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,12,NULL,1,0,0,1,0,'pork',2,0.71,11,1,'[{"name":"dried oregano","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ground mustard","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"pork shoulder or pork butt","quantity":4.5,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"yellow onion","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"pure maple syrup","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"whole grain mustard","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"dried oregano","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["To make the pork shoulder: In a small bowl, stir together the oregano, ground mustard, salt, and pepper.","Trim any excess fat from the pork shoulder (but remember that some fat is good), then rub the spice mixture generously over the entire pork.","Place the pork in the slow cooker and add the onion and garlic around it.","To make the sauce: In a medium bowl, stir together the maple syrup, whole grain mustard, oregano, salt, and pepper.","Pour half the sauce all over the pork.","Use your hands to make sure the meat is coated on all sides except the bottom.","Reserve the other half of the sauce.","Secure the lid on the slow cooker and cook on the low setting for 8 to 10 hours, or on the high setting for 5 to 6 hours, until the meat is fall-apart tender.","Remove the pork from the slow cooker to a large cutting board and use two forks to shred the meat.","Using a slotted spoon or small ﬁne-mesh sieve, scoop up some of the onions from the slow cooker, letting the liquid drain, and add to the shredded meat.","Pour the remaining sauce over the meat and stir it together.","Thaw in the fridge overnight, then reheat in the oven at 250°F (120°C) in a covered pan for about 30 minutes, or in the microwave for 1 to 2 minutes, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('apple-cider-beef-stew','Apple Cider Beef Stew','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,0,1,0,'beef',2,0.63,14,0,'[{"name":"beef stew meat","quantity":2,"unit":"pounds","unit_norm":"lb","category":"meat"},{"name":"kosher salt","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"yellow onion","quantity":1,"unit":"large","unit_norm":"","category":"produce"},{"name":"apple cider vinegar","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"arrowroot powder","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"apple cider juice","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"low-sodium beef broth","quantity":2,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"dried thyme","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"bay leaf","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"or 2 small-to-medium turnips","quantity":1,"unit":"large","unit_norm":"","category":"pantry"},{"name":"carrots","quantity":4,"unit":"medium","unit_norm":"","category":"produce"},{"name":"celery ribs","quantity":3,"unit":"unit","unit_norm":"","category":"produce"}]','["Pat the beef dry with paper towels.","Season with salt and pepper.","In a large stockpot or Dutch oven, heat the oil over medium-high heat.","Working in batches, place the beef in the pot and sear on all sides until golden, 2 to 3 minutes per side, then remove to a plate.","Place the onion in the pot and pour in the vinegar (which will help loosen the browned bits from the bottom of the pan) and cook for 3 to 4 minutes, until the onion is softened.","Return the beef to the pot and stir in the arrowroot powder, coating the beef and vegetables, until fully dissolved.","Add the cider, broth, thyme, and bay leaf.","Use a large spoon or spatula to stir everything together.","Bring the broth to a boil, then reduce the heat to low and simmer partially covered for 1 hour.","Add the turnips, carrots, and celery.","Cook for an additional 20 to 30 minutes, or until the vegetables are fork-tender.","Remove the bay leaf and, if you’d like, garnish with fresh thyme.","If frozen, thaw in the fridge overnight, then microwave for 1 to 2 minutes or heat on the stove over medium heat, until hot."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('two-whole-roasted-chickens-with-fennel-pear-and-onion','Two Whole Roasted Chickens with Fennel, Pear, and Onion','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,12,NULL,1,0,0,1,0,'chicken',2,0.63,11,0,'[{"name":"Anjou or Bosc pears","quantity":2,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"yellow onion","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"fennel bulb","quantity":1,"unit":"large","unit_norm":"","category":"produce"},{"name":"lemons","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"thyme sprigs","quantity":8,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"extra-virgin olive oil","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":3.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":1.75,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"whole chickens","quantity":2,"unit":"unit","unit_norm":"","category":"meat"},{"name":"head garlic","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"minutes","quantity":15,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 425°F (220°C) and place a rack in the lower third of the oven.","Place the pears, onion, fennel, 8 of the lemon quarters, and 4 of the thyme sprigs in a large roasting pan.","Drizzle with 1 tablespoon of the oil, season with ½ teaspoon of the salt and ¼ teaspoon of the pepper, then toss together.","Pat the chickens dry with paper towels.","Rub 1 tablespoon oil each on the outside of the chickens.","Season each chicken with 1 teaspoon of salt and ½ teaspoon of pepper, and the inside with ½ teaspoon of salt and ¼ teaspoon of pepper.","Then stuff each chicken with 2 lemon quarters, the garlic, and 2 sprigs of thyme.","Place the chicken on top of the pears and vegetables, breast side up, and tuck the wings under.","Tie the legs together with kitchen twine (you can also leave them untied if you wish).","Roast the chicken for 1¾ to 2 hours, or until an instant-read thermometer reads 160°F (71°C) at the thickest part of the breast (the juices should run clear when you cut between a leg and thigh).","Let rest for Break down the chicken, then store in an airtight container in the fridge for 3 to 4 days, or in the freezer for up to 3 months.","If frozen, thaw in the fridge overnight.","Then place in a baking dish with a splash of broth, cover tightly with aluminum foil, and reheat in a 400°F (200°C) oven for 15 to 20 minutes.","You can also microwave for 1 to 2 minutes, until warmed through. ways to serve My favorite way to eat this dish is to plate a chicken leg or breast with a dollop of mashed potatoes or Garlicky Root Vegetable Mash (this page) next to it.","Then use tongs to place some of the juicy, caramelized veggies and pears on top.","The juices absorb into whatever mash you’re eating, and it’s oh so good!","Of course, you can also shred chicken leftovers to top on salads and bowls throughout the week."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('paprika-rubbed-pork-tenderloin-with-shallot-pan-sauce','Paprika Rubbed Pork Tenderloin with Shallot Pan Sauce','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,0,0,0,1,'pork',4,0.71,14,1,'[{"name":"sweet paprika","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"smoked paprika","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"onion powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"dried thyme","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"pork tenderloins","quantity":2,"unit":"unit","unit_norm":"","category":"meat"},{"name":"shallot","quantity":1,"unit":"small","unit_norm":"","category":"pantry"},{"name":"low-sodium chicken broth","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"meat"},{"name":"honey","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"butter","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"roughly chopped fresh thyme","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Preheat the oven to 375°F (190°C).","To make the tenderloin: In a small bowl, stir together the sweet paprika, smoked paprika, garlic powder, onion powder, dried thyme, salt, and pepper.","Sprinkle the spice blend all over the tenderloins, then use your hands to rub it in.","In a large oven-safe skillet, heat the oil over medium-high heat.","Add the pork and cook, turning occasionally, until seared and browned on all sides, about 4 minutes total.","Transfer the pan to the oven and roast the pork tenderloin for 15 to 20 minutes, or until an instant-read thermometer reaches 140°F (60°C).","Place the skillet back on the stove and remove the pork to a plate, cover with foil, and let rest for 10 minutes.","To make the sauce: Add the shallot to the skillet and stir for a minute over medium heat until softened.","Pour the broth into the skillet to deglaze it, scraping all those delicious bits from the bottom, and simmer for 2 minutes, until slightly reduced.","Add the honey and, if desired, the butter (for a richer sauce) and stir together.","Remove from the heat and stir in the thyme.","Taste and season with salt and pepper.","Cut the pork tenderloin across into ½-inch (1.3cm) slices and arrange on a platter.","Spoon the shallot sauce over the pork.","Add the slices to a skillet on medium heat, cover the skillet, and ﬂip after a minute or so.","You can also reheat in the microwave for 1 to 2 minutes, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spicy-shrimp-and-parsnip-noodles','Spicy Shrimp and Parsnip Noodles','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,0,1,'fish',4,0.71,17,1,'[{"name":"coconut sugar","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"ﬁsh sauce","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"water","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"tamarind paste or fresh lime juice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"low-sodium tamari soy sauce","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"cayenne pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"extra-large shrimp","quantity":8,"unit":"ounces","unit_norm":"oz","category":"seafood"},{"name":"ﬁnely grated peeled fresh ginger","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"garlic cloves","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"green onions","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"parsnips","quantity":2,"unit":"medium","unit_norm":"","category":"pantry"},{"name":"eggs","quantity":2,"unit":"large","unit_norm":"","category":"dairy"},{"name":"mung bean sprouts","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"raw cashews","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"roughly chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"seconds until warmed through. Turn off the heat","quantity":30,"unit":"unit","unit_norm":"","category":"pantry"}]','["To make the sauce: In a medium bowl, stir together the coconut sugar, ﬁsh sauce, water, tamarind paste, tamari, and cayenne pepper.","Set aside.","To make the stir-fry: In a large skillet or wok, heat 1 tablespoon of the oil on medium-high heat and swirl the pan to coat the bottom.","Arrange the shrimp in a single ﬂat layer.","Cook the shrimp for 1 minute, then ﬂip and cook another 30 seconds, until lightly pink but not quite cooked all the way through.","Use tongs to remove the shrimp to a plate.","In the same skillet, add the remaining 1 tablespoon oil and sauté the ginger, garlic, and white parts of the green onion for 30 seconds.","Add the parsnip noodles and use tongs to stir the noodles with the aromatics.","Pour the sauce on top of the noodles and stir-fry for another 2 to 3 minutes, until the sauce has reduced and the noodles have softened.","Push the noodles to the side of the skillet, pour in the beaten eggs, and push them around until soft curds form, then incorporate the eggs with the noodles.","Return the shrimp to the skillet, add the bean sprouts, and stir-fry for of the green onions, and garnish with the cashews and cilantro before serving.","Thaw in the fridge overnight.","Then reheat in a skillet on the stove, or in the microwave in 30- second increments, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cilantro-lime-shrimp','Cilantro Lime Shrimp','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,1,0,'fish',4,0.71,8,1,'[{"name":"extra-large shrimp","quantity":1,"unit":"pound","unit_norm":"lb","category":"seafood"},{"name":"ground cumin","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"garlic","quantity":4,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"lime zest","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"fresh lime juice","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"roughly chopped fresh cilantro","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["In a large bowl, toss together the shrimp, cumin, and salt until well coated.","In a large skillet, heat the oil over medium heat.","Add the garlic and stir for 30 seconds.","Add the shrimp to the pan and arrange in a single ﬂat layer.","Cook the shrimp for 1 to 2 minutes undisturbed.","Flip the shrimp, cook for 1 minute more, then add the lime zest, lime juice, red pepper ﬂakes (if using), and cilantro.","Stir for another minute, or until the shrimp is cooked through.","Store in an airtight container in the fridge for 3 to 4 days.","Heat in a sauté pan on the stove or in the microwave in 30-second increments, until just warmed through.","You can also enjoy them cold topped on a salad—no reheating necessary. helpful tip While you may be tempted to marinate the shrimp for a couple of hours, avoid doing so as the lime juice can start to denature and “cook” the shrimp (similar to ceviche), making the shrimp a bit rubbery after it’s cooked."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('grilled-halibut-skewers-with-orange-chimichurri','Grilled Halibut Skewers with Orange Chimichurri','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,1,0,'fish',2,0.63,10,0,'[{"name":"ﬁnely chopped fresh parsley","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"garlic clove","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"extra-virgin olive oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"orange zest","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"fresh orange juice","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lemon juice","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"produce"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"halibut","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"seafood"},{"name":"zucchini","quantity":2,"unit":"medium","unit_norm":"","category":"produce"}]','["In a medium bowl, whisk together the parsley, garlic, olive oil, orange zest, orange juice, lemon juice, salt, and pepper.","In a separate medium bowl, gently toss the cubed halibut and two- thirds of the orange chimichurri (reserve the rest to drizzle at the end) until fully coated.","Marinate for 30 minutes in the fridge.","Preheat a grill or stovetop grill pan to medium-high heat.","Thread pieces of halibut and zucchini on skewers, alternating a piece of halibut with a slice of zucchini that’s folded back on itself like a ribbon, until you have about 4 pieces of halibut on each skewer.","Moisten a paper towel with a little avocado oil and pinch it between tongs, then carefully but quickly wipe the grates of the grill until coated and glossy, to prevent sticking.","Arrange the skewers on the grill, directly over the heat, and cook for 2 to 2½ minutes, then turn just once, and cook another 2 to 2½ minutes, until no longer translucent.","Halibut cooks quickly, so do keep an eye on it, as you don’t want it to overcook.","Transfer the skewers to a plate and accompany with the remaining orange chimichurri.","Store in an airtight container in the fridge for 2 to 3 days.","Place on a rimmed baking sheet and cover with aluminum foil (to prevent drying out), then reheat in a 275°F (140°C) oven for 10 to 15 minutes.","Or microwave in 30-second increments, until warmed through.","You can also enjoy the halibut cold, ﬂaked into a salad. helpful tip Since ﬁsh is more likely to stick to grills than chicken or beef, it’s important to ensure your grill is clean, well-oiled, and hot.","If you notice the halibut sticking, gently slide a spatula underneath to loosen it, rather than by pulling up on the skewers.","I recommend using ﬂat metal skewers or double skewers, which prevent the ﬁsh from rotating around the skewer as you ﬂip."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('almond-herb-crusted-cod','Almond-Herb Crusted Cod','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,0,1,'fish',4,0.773,8,1,'[{"name":"raw almonds","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"melted butter or extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"dairy"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"lemon zest","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"ﬁnely chopped fresh parsley","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"ﬁnely chopped fresh chives","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"cod ﬁllets","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"}]','["Preheat the oven to 400°F (200°C).","In a small bowl, stir together the almonds, butter, garlic, lemon zest, parsley, chives, salt, and pepper.","Place the cod on a rimmed baking sheet and evenly spread the mixture on top of the cod, pressing down a little with your ﬁngers to lightly compact it.","Bake for 13 to 15 minutes, or until the ﬁsh is opaque and ﬂakes easily with a fork and the top is lightly golden.","Before serving, squeeze fresh lemon juice on top.","Store in an airtight container in the fridge for 2 to 3 days.","Place on a rimmed baking sheet and cover with aluminum foil (to prevent drying out), then reheat in a 275°F (140°C) oven for 10 to 15 minutes.","Or microwave in 30-second increments, until warmed through.","You can also enjoy the cod cold, ﬂaked into a salad."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('blackened-cajun-trout','Blackened Cajun Trout','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,1,0,'fish',2,0.63,10,0,'[{"name":"sweet paprika","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"onion powder","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"dried oregano","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"dried thyme","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"cayenne pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"steelhead trout","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"seafood"},{"name":"olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven broiler to high and set an oven rack 6 to 8 inches (20 to 25cm) below the top heating element.","In a small bowl, stir together the paprika, salt, garlic powder, onion powder, oregano, thyme, cayenne pepper, and black pepper.","Rub both sides of the trout with oil and place on a rimmed baking sheet (don’t add parchment paper as it will burn when broiled).","Sprinkle the seasoning evenly over the trout, rubbing it in with your ﬁngers to make sure the trout is evenly coated.","Broil the trout for 5 to 8 minutes (depending on the thickness of your trout), or until it ﬂakes easily with a fork.","If frozen, thaw in the fridge overnight.","Place on a rimmed baking sheet and cover with aluminum foil (to prevent drying out), then reheat in a 275°F (140°C) oven for 10 to 15 minutes.","Or microwave in 30-second increments, until warmed through.","You can also turn leftover ﬂaked trout into spicy ﬁsh cakes! helpful tip If you’re worried about the level of spice, you can reduce the cayenne pepper to ⅛ teaspoon.","Or you can just use less of the spice mix and save any leftovers in a small container for sprinkling on chicken, salmon, or other protein in the future."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pan-seared-cod-in-romesco-sauce','Pan-Seared Cod in Romesco Sauce','From Downshiftology Healthy Meal Prep cookbook','italian','medium',20,15,35,4,NULL,1,0,1,0,1,'fish',3,0.693,9,0,'[{"name":"extra-virgin olive oil or an equal mix of butter and oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"dairy"},{"name":"cod ﬁllets","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"Romesco Sauce","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"coconut cream","quantity":1,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"drained capers","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"roughly chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"roughly chopped fresh basil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["In a large pan, heat the oil over medium heat.","Pat the cod dry with paper towels and season both sides with salt and pepper.","Place the cod in the pan and cook 3 to 4 minutes, until lightly golden, then ﬂip and cook an additional 3 minutes, until cooked through.","Remove the ﬁsh to a plate.","Stir together the romesco sauce and coconut cream in the pan and bring to a simmer.","Stir in the capers, parsley, and basil.","Return the cod to the pan and continue simmering until heated through.","Garnish with extra herbs.","If frozen, thaw in the fridge overnight, then place a piece of ﬁsh and some of the sauce in a pan on the stove over medium heat, or microwave in 30-second increments, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spicy-shrimp-with-tomatoes-and-feta','Spicy Shrimp with Tomatoes and Feta','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,1,0,1,'fish',4,0.693,13,0,'[{"name":"extra-virgin olive oil","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"yellow onion","quantity":0.5,"unit":"medium","unit_norm":"","category":"produce"},{"name":"grape or cherry tomatoes","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"garlic cloves","quantity":6,"unit":"unit","unit_norm":"","category":"produce"},{"name":"dried oregano","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"crushed red pepper ﬂakes","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"sweet or smoked paprika","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"can tomato sauce","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"extra-large shrimp","quantity":1.5,"unit":"pounds","unit_norm":"lb","category":"seafood"},{"name":"crumbled feta cheese","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"roughly chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["In a large pan, heat the oil over medium heat.","Add the onion and grape tomatoes and sauté for 4 to 5 minutes, until the onions start to soften and the tomatoes start to blister.","Add the garlic, oregano, red pepper ﬂakes, and paprika and sauté for an additional 1 to 2 minutes, stirring frequently.","Add the tomato sauce, salt, and pepper, stir everything together, then add the shrimp, and stir again, making sure the shrimp are coated in the sauce and evenly distributed throughout the pan.","Cover the pan, reduce the temperature to medium-low, and cook the shrimp for 5 minutes.","Remove the lid, sprinkle the feta on top, and simmer for an additional 2 to 3 minutes uncovered, to warm the feta and thicken the sauce.","Remove the pan from the heat and sprinkle with chopped parsley.","If frozen, thaw in the fridge overnight, then place the shrimp and sauce in a pan on the stove over medium heat.","You can also microwave in 30-second increments, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('grilled-salmon-steaks-with-fruit-salsa','Grilled Salmon Steaks with Fruit Salsa','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,0,0,1,0,'fish',3,0.63,5,0,'[{"name":"salmon steaks","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"Fruit Salsa","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Preheat a grill or stovetop grill pan to medium-high heat.","Brush both sides of the salmon steaks with oil, then season with the salt and pepper.","Moisten a paper towel with a little avocado oil and pinch it between tongs, then carefully but quickly wipe the grates of the grill until coated and glossy, to prevent sticking.","Grill the salmon for 5 to 7 minutes each side, depending on thickness.","To ﬂip, use a spatula underneath the ﬁsh rather than grabbing from the side with tongs (which may cause the salmon to fall apart).","Top each salmon steak with a portion of fruit salsa before serving.","Store the salmon and salsa in separate airtight containers in the fridge for 3 to 4 days (but see also Helpful Tip below).","The salmon can also be stored in the freezer for up to 3 months.","If frozen, thaw in the fridge overnight.","Place on a rimmed baking sheet and cover with aluminum foil (to prevent drying out), then reheat in a 275°F (140°C) oven for 10 to 15 minutes.","Or microwave in 30-second increments, until warmed through.","Top with fruit salsa. helpful tip I like to ﬂake any leftover salmon and mix it with any extra salsa, and store in the fridge.","Then it’s easy to top on salad greens with diced avocado and a drizzle of salad dressing for a quick- assembly meal."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tuna-zoodle-casserole-with-lemon-cashew-alfredo','Tuna Zoodle Casserole with Lemon Cashew Alfredo','From Downshiftology Healthy Meal Prep cookbook','asian','medium',20,15,35,6,NULL,1,0,1,1,0,'fish',3,0.71,17,1,'[{"name":"raw cashews","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"yellow onion","quantity":0.5,"unit":"small","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"fresh lemon juice","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"low-sodium vegetable broth","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"nutritional yeast","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"dried thyme","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"zucchini","quantity":2,"unit":"large","unit_norm":"","category":"produce"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"yellow onion","quantity":0.5,"unit":"small","unit_norm":"","category":"produce"},{"name":"celery ribs","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"frozen peas","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"cans tuna","quantity":2,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"ﬁnely chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"ﬁnely chopped fresh dill","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 350°F (177°C).","To make the alfredo sauce: In a high-powered blender on high speed, blend the cashews, onion, garlic, lemon juice, broth, nutritional yeast, thyme, salt, and pepper for 30 seconds, or until smooth and creamy.","To make the casserole: Spiralize the zucchini into ribbons or noodles and place them in a large mixing bowl.","In a medium pan over medium heat, heat the oil and sauté the onion and celery for 4 to 5 minutes, until softened and translucent.","Add the frozen peas and stir for another minute, until thawed.","Transfer the veggies to the bowl with the zucchini.","Flake the tuna into the bowl and add the parsley, dill, and alfredo sauce.","Stir together until well combined and creamy, then scrape the mixture into a 13 × 9-inch (23 × 33cm) casserole dish and bake for 15 to 20 minutes, until warmed through and the top starts to turn lightly golden.","Garnish with parsley and dill and serve with lemon slices.","Store in an airtight container in the fridge for 4 to 5 days.","Reheat in a 325°F (160°C) oven for about 8 to 10 minutes, or in the microwave for 1 to 2 minutes, until warmed through.","I don’t recommend freezing the casserole, as the zucchini will become thin and watery when thawed. helpful tip You can use tuna in oil or water (I prefer water).","I also recommend Wild Planet or Safe Catch brands because the meat is more chunky and ﬂaky rather than mushy."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('honey-ginger-sheet-pan-salmon','Honey-Ginger Sheet Pan Salmon','From Downshiftology Healthy Meal Prep cookbook','asian','medium',20,15,35,4,NULL,1,0,1,1,0,'fish',2,0.71,12,1,'[{"name":"head of broccoli","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"minced peeled fresh ginger","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"honey","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"low-sodium tamari soy sauce or coconut aminos","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"sesame oil","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"salmon ﬁllets","quantity":4,"unit":"unit","unit_norm":"","category":"seafood"},{"name":"frozen peas","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"green onions","quantity":2,"unit":"unit","unit_norm":"","category":"produce"}]','["Preheat the oven to 375°F (190°C).","On a rimmed baking sheet, drizzle the broccoli ﬂorets with the olive oil and sprinkle with ½ teaspoon of the salt and ¼ teaspoon of the pepper.","Toss together, then roast for 10 minutes.","In a small bowl, stir together the garlic, ginger, honey, tamari, sesame oil, and the remaining ½ teaspoon salt and ¼ teaspoon pepper.","Pat the salmon dry with a paper towel.","Remove the baking sheet from the oven, push the broccoli and cauliﬂower to the outer edges, add the peas, and place the salmon on the sheet pan.","Drizzle the marinade evenly on top of the salmon, then place the sheet pan back in the oven for another 12 to 15 minutes, until the salmon ﬂakes easily.","Remove from the oven, then sprinkle the green onions on top before serving.","If frozen, thaw in the fridge overnight.","Place on a rimmed baking sheet and cover with aluminum foil (to prevent drying out), then reheat in a 275°F (140°C) oven for 10 to 15 minutes.","Or microwave in 30-second increments, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('falafel','Falafel','From Downshiftology Healthy Meal Prep cookbook','mediterranean','medium',20,15,35,6,NULL,1,1,0,1,0,'none',1,0.71,13,1,'[{"name":"dried chickpeas","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"medium yellow onion","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"bunch of fresh parsley","quantity":1,"unit":"large","unit_norm":"","category":"pantry"},{"name":"bunch of fresh cilantro","quantity":1,"unit":"large","unit_norm":"","category":"pantry"},{"name":"green chile pepper","quantity":1,"unit":"small","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ground cardamom","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"chickpea ﬂour","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"baking soda","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"or 2 teaspoons water or lemon juice","quantity":1,"unit":"unit","unit_norm":"","category":"produce"}]','["Drain and rinse the chickpeas, then place them in a food processor.","Add the onion, parsley, cilantro, chile pepper, garlic, cumin, cardamom, salt, and pepper.","Pulse several times until the mixture resembles the texture of coarse sand.","Transfer the falafel mixture to a large bowl.","Stir in the ﬂour and baking soda.","Cover and refrigerate the mixture for 30 to 60 minutes.","Use your hands or an ice cream or falafel scoop to form the falafel into balls or patties.","If you ﬁnd the dough is too wet, you can add another tablespoon of ﬂour.","If it’s too dry and crumbly, add the water a little at a time.","To deep-fry the falafel: Pour about 3 inches oil into a large pot over medium heat.","Heat the oil to 350°F (180°C).","Cook the falafel in batches (about 6 to 8 at a time) for 1 to 2 minutes, until golden.","Then use a skimmer to remove them to a paper towel–lined plate.","To bake the falafel: Preheat the oven to 425°F (220°C).","Lightly spray or brush a rimmed baking sheet with oil.","Arrange the falafel on the baking sheet and lightly spray or brush the top side with oil.","Bake for 25 to 30 minutes, ﬂipping halfway through.","When you’re ready, thaw the dough in the fridge overnight, give it a stir, then form into balls or patties and cook."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('coconut-chickpea-curry','Coconut Chickpea Curry','From Downshiftology Healthy Meal Prep cookbook',NULL,'medium',20,15,35,4,NULL,1,1,0,0,1,'none',1,0.71,12,1,'[{"name":"coconut oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"medium yellow onion","quantity":1,"unit":"large","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"grated peeled fresh ginger","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"cans chickpeas","quantity":2,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"can full-fat coconut milk","quantity":1,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"low-sodium vegetable broth","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"curry powder","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"garam masala","quantity":1.5,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"bunch of cilantro","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"}]','["In a large skillet, heat the oil over medium-high heat.","Add the onion and sauté for 4 to 5 minutes, until softened.","Add the garlic and ginger and stir together for another minute, until fragrant.","Add the chickpeas, coconut milk, broth, curry powder, garam masala, cumin, and salt.","Stir everything together, bring to a boil, then reduce the heat to medium-low and simmer for 10 minutes, so that the ﬂavors can meld.","Remove from the heat and stir in the cilantro and lime juice.","Serve the curry over plain rice, Coconut Rice (this page), or cauliﬂower rice.","Garnish with more cilantro and lime slices.","You can store the curry by itself or with leftover rice.","If frozen, thaw in the fridge overnight.","Microwave the curry for 1 to 2 minutes, or cook on the stove, until warmed through. helpful tip Remember that curry powder, which contains turmeric, may stain plastic or silicone storage containers.","To avoid this, use glass storage containers."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemony-lentil-and-chickpea-soup','Lemony Lentil and Chickpea Soup','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,1,0,1,0,'none',1,0.63,12,0,'[{"name":"olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"yellow onion","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"celery ribs","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"low-sodium vegetable broth","quantity":6,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"red lentils","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"can chickpeas","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"dried oregano","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"roughly chopped fresh thyme","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"packed spinach or kale","quantity":2,"unit":"cups","unit_norm":"cup","category":"produce"}]','["In a large stockpot or Dutch oven, heat the oil over medium heat.","Add the onion and celery and sauté for 4 to 5 minutes, until the onion becomes translucent.","Add the garlic and sauté 1 minute more.","Add the broth, lentils, chickpeas, oregano, thyme, salt, and pepper and bring to a simmer.","Cover the pot and cook for 15 minutes, stirring occasionally.","Stir in the spinach and cook for 5 to 8 minutes more, until the lentils are softened and starting to break apart.","Remove the soup from the heat and stir in the lemon juice and zest.","Garnish with more thyme and pepper before serving.","If frozen, thaw in the fridge overnight.","Microwave the soup for 1 to 2 minutes, or cook on the stove, until warmed through. helpful tip Red lentils do work best in this recipe, so don’t swap in green or brown lentils.","They just won’t soften quite the same or create that luscious texture."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spiralized-sweet-potato-burrito-bake','Spiralized Sweet Potato “Burrito” Bake','From Downshiftology Healthy Meal Prep cookbook','mexican','medium',20,15,35,6,NULL,1,1,0,0,1,'none',2,0.773,17,1,'[{"name":"sweet potato","quantity":1,"unit":"small","unit_norm":"","category":"pantry"},{"name":"white rice","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"low-sodium vegetable broth","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"can crushed tomatoes","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"chili powder","quantity":3,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"ground cumin","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"dried oregano","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"garlic powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"can black beans","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"can corn","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"green bell pepper","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"yellow onion","quantity":0.5,"unit":"medium","unit_norm":"","category":"produce"},{"name":"grated mozzarella cheese","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"avocado","quantity":1,"unit":"medium","unit_norm":"","category":"pantry"},{"name":"to 45 minutes","quantity":40,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 400°F (200°C).","Place the sweet potato and rice in a 13 × 9-inch (33 × 23cm) casserole dish and toss to combine.","In a large bowl, whisk together the broth, tomatoes, chili powder, cumin, oregano, garlic powder, salt, and pepper.","Stir in the black beans, corn, bell pepper, and onion to combine, then pour on top of the sweet potato and rice.","Cover the casserole dish tightly with a lid or aluminum foil and bake for through.","Remove the lid, sprinkle the cheese on top, and bake uncovered another 5 minutes, until the cheese melts.","Top with avocado slices and cilantro and serve.","Store in an airtight container for 4 to 5 days in the fridge, or up to 3 months in the freezer.","If frozen, thaw in the fridge overnight, then reheat in a 325°F (160°C) oven for 5 to 10 minutes, or in the microwave for 1 to 2 minutes."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('white-gazpacho','White Gazpacho','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,1,0,1,0,'none',4,0.693,10,0,'[{"name":"English cucumbers","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"green grapes","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"slivered almonds","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"avocado","quantity":0.25,"unit":"medium","unit_norm":"","category":"pantry"},{"name":"olive oil","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"white balsamic or sherry vinegar","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"cold water","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"to 4 hours.","quantity":3,"unit":"unit","unit_norm":"","category":"pantry"}]','["In a high-powered blender on high speed, blend the cucumbers, grapes, almonds, garlic, avocado, oil, vinegar, salt, and water for 1 minute, or until creamy.","Transfer the gazpacho to an airtight container and refrigerate for","To serve, divide the gazpacho among four bowls and garnish with diced cucumber, grapes, and microgreens.","Thaw a frozen portion in the fridge the day before enjoying.","It’s normal for the gazpacho to separate, just give it quick stir! helpful tip I’ve peeled the cucumber to keep the gazpacho lighter in color.","But you can leave the peel on for a slightly greener more cucumber-ﬂavored gazpacho."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('carrot-and-cannellini-bean-fritters-with-herb-yogurt-sauce','Carrot and Cannellini Bean Fritters with Herb Yogurt Sauce','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,3,NULL,1,1,0,0,1,'none',3,0.63,15,0,'[{"name":"plain Greek yogurt","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"garlic clove","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"ﬁnely chopped fresh parsley","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ﬁnely chopped fresh chives","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"chia seeds","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"water","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"can cannellini beans","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"grated carrot","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"produce"},{"name":"green onions","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"almond ﬂour","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"roughly chopped fresh parsley","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"garlic clove","quantity":1,"unit":"unit","unit_norm":"","category":"produce"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"}]','["To make the sauce: In a small bowl, stir together the yogurt, garlic, parsley, chives, lemon juice, and salt.","Cover and refrigerate until ready to use.","To make the fritters: In a small bowl, stir together chia seeds and water and set aside for 15 minutes to let the chia seeds gel up.","Meanwhile, place the cannellini beans in a medium bowl and roughly mash them with the back of a fork.","Add the carrots, green onions, ﬂour, parsley, garlic, gelled chia seeds, salt, and pepper and stir together until well combined.","In a large pan, heat the oil over medium heat.","Scoop out 3 table-spoons of mixture and form into a fritter.","Fry for 2 to 3 minutes each side, until golden brown, then remove to a paper towel–lined plate to absorb any excess oil.","Serve with the herb yogurt sauce.","Let the fritters cool, then store in an airtight container in the fridge for 4 to 5 days, or in the freezer (with parchment paper in between) for up to 3 months.","Place a thawed fritter in the microwave for 20 to 30 seconds, heat in a pan on the stove with a little bit of oil, or place in a 350°F (180°C) oven, until warmed through. dietary swap If you eat eggs you can swap the gelled chia seeds with 1 large egg."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('portobello-mushroom-sheet-pan-fajitas','Portobello Mushroom Sheet Pan Fajitas','From Downshiftology Healthy Meal Prep cookbook','mexican','medium',20,15,35,6,NULL,1,1,0,1,0,'none',2,0.71,16,1,'[{"name":"chili powder","quantity":0.5,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"ground cumin","quantity":0.5,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"garlic powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"sweet paprika","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"oregano","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"portobello mushroom caps","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"yellow onion","quantity":1,"unit":"medium","unit_norm":"","category":"produce"},{"name":"bell peppers","quantity":2,"unit":"medium","unit_norm":"","category":"produce"},{"name":"avocado oil or extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"Cassava Flour Tortillas or gluten-free store-bought","quantity":6,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"avocado","quantity":1,"unit":"medium","unit_norm":"","category":"pantry"},{"name":"limes","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"crumbled queso fresco","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"to 25 minutes","quantity":20,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 450°F (230°C).","To make the seasoning: In a small bowl, stir together the chili powder, cumin, garlic powder, paprika, oregano, salt, and pepper.","To make the ﬁlling: On one rimmed baking sheet, place the sliced mushrooms.","On a second rimmed baking sheet, place the sliced onion and bell peppers.","Drizzle the oil over both baking sheets, then sprinkle the seasoning on top.","Toss the vegetables with the oil and spices and bake for","Assemble the fajitas by placing a portion of the mushrooms, onions, and bell peppers on a warmed tortilla.","Garnish with avocado, a squeeze of lime juice, cilantro, and queso fresco.","Store the mushroom, onions, and bell peppers in an airtight container in the fridge for 4 to 5 days.","Store the tortillas and other ingredients in separate airtight containers in the fridge.","Warm the mushroom, onions, and bell peppers in a pan on the stove, or in a 350°F (180°C) oven for 5 to 10 minutes, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('peas-and-prosciutto','Peas and Prosciutto','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,0,0,1,0,'pork',4,0.693,7,0,'[{"name":"olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"shallots","quantity":2,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"bag frozen peas","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"prosciutto","quantity":4,"unit":"ounces","unit_norm":"oz","category":"meat"}]','["In a large pan, heat the oil over medium heat.","Add the shallots and garlic and sauté for 1 minute, until softened.","Add the peas, salt, and pepper and sauté for 5 minutes, until the peas are warmed through.","Add the prosciutto and sauté for another 1 to 2 minutes.","Season to taste with additional salt and pepper before serving.","Store in an airtight container in the fridge for 4 to 5 days.","Sauté in a pan for 2 to 3 minutes, or heat in the microwave for 1 minute, until warmed through."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('balsamic-roasted-mushrooms','Balsamic Roasted Mushrooms','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,1,0,1,0,'none',3,0.773,8,1,'[{"name":"cremini or baby bell mushrooms","quantity":1,"unit":"pound","unit_norm":"lb","category":"produce"},{"name":"extra-virgin olive oil","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"balsamic vinegar","quantity":3,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"pure maple syrup","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"pantry"},{"name":"garlic cloves","quantity":3,"unit":"unit","unit_norm":"","category":"produce"},{"name":"roughly chopped fresh thyme","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"roughly chopped fresh parsley","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["Preheat the oven to 425°F (220°C).","In a large bowl, gently toss together the mushrooms, oil, vinegar, maple syrup, garlic, thyme, parsley, salt, and pepper to evenly coat the mushrooms.","Arrange the mushrooms in a single layer on a rimmed baking sheet or in a casserole dish, pouring any liquid on top.","Roast the mushrooms for 20 to 25 minutes, stirring two or three times, until tender.","Garnish with extra parsley before serving.","If frozen, thaw in the fridge overnight.","Reheat the mushrooms in the microwave for 1 to 2 minutes or gently toss them in a skillet, until warmed through. helpful tip Leftovers can be added to veggie noodle dishes, casseroles, soups, and stews.","You can also chop them up and add them to a breakfast scramble, omelet, or egg mufﬁn for a punch of savory ﬂavor!"]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('coconut-rice','Coconut Rice','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,8,NULL,1,1,0,0,1,'none',2,0.693,5,0,'[{"name":"can full-fat coconut milk","quantity":1,"unit":"unit","unit_norm":"","category":"dairy"},{"name":"water","quantity":1.25,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"honey","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"pantry"},{"name":"long-grain white rice","quantity":2,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"}]','["In a medium pot over high heat, stir together the coconut milk, water, honey, rice, and salt.","Bring it to a boil, then reduce the heat to low, add a lid, and simmer for 12 to 15 minutes, until the liquid is absorbed and the rice is tender.","If bubbles start to come out of the pot, adjust the lid so that steam can escape.","Remove the rice from the heat and let it rest covered for a couple of minutes.","Fluff with a fork before serving.","Make sure to read the tips in the Individual Meal Prep Ingredients chapter on safely storing rice after cooking (see this page).","If frozen, thaw in the fridge overnight.","Rice has a tendency to dry out, so sprinkle a tablespoon or two of water on it before reheating.","Reheat thawed rice in a covered pot on the stove, or in the microwave for 1 minute, or until warmed through. helpful tip I use regular full-fat coconut milk for a creamier texture, but you could use light coconut milk as well."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemon-herb-rice','Lemon Herb Rice','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,0,0,1,0,'chicken',2,0.63,9,0,'[{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"yellow onion","quantity":0.5,"unit":"medium","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"},{"name":"basmati rice","quantity":1.5,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"low-sodium chicken broth","quantity":2.5,"unit":"cups","unit_norm":"cup","category":"meat"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"ﬁnely chopped fresh herbs","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"minutes","quantity":4,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"minute","quantity":1,"unit":"unit","unit_norm":"","category":"pantry"}]','["In a large pan on medium heat, heat the oil and sauté the onion for 3 to rice and sauté another minute.","Add the broth, lemon juice, and salt.","Bring to a boil, then reduce the heat to low, cover with a lid, and cook for 12 to 15 minutes, until the liquid is absorbed and the rice is tender.","If bubbles start to come out of the pot, adjust the lid so that steam can escape.","Remove the rice from the heat and let it rest covered another 4 to 5 minutes.","Stir in the fresh herbs and serve.","Make sure to read the tips in the Individual Meal Prep Ingredients chapter on safely storing rice after cooking (see this page).","If frozen, thaw in the fridge overnight.","Rice has a tendency to dry out, so sprinkle a tablespoon or two of water on it before reheating.","Reheat in a covered pot on the stove or in the microwave for helpful tip I use parsley and dill in this recipe, but you could use a single herb or combine two or three of your favorite herbs.","Other combinations that work great are tarragon-thyme, cilantro-mint, parsley-oregano-basil, and parsley-mint-dill."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('roasted-green-beans-almondine','Roasted Green Beans Almondine','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,1,0,1,0,'none',4,0.773,7,1,'[{"name":"French haricots verts","quantity":1,"unit":"pound","unit_norm":"lb","category":"pantry"},{"name":"garlic cloves","quantity":4,"unit":"unit","unit_norm":"","category":"produce"},{"name":"sliced almonds","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"kosher salt","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"to 18 minutes","quantity":15,"unit":"unit","unit_norm":"","category":"pantry"}]','["Preheat the oven to 425°F (220°C).","In a medium bowl, toss the green beans with the garlic, sliced almonds, oil, salt, and pepper.","Spread the green beans out onto a rimmed baking sheet and bake for blistered.","If frozen, thaw in the fridge overnight.","Quickly sauté in a pan over medium-high heat or reheat in the microwave for 30 to 45 seconds, until warmed through. helpful tip Haricots verts are French green beans.","They’re slightly longer, skinnier, and more tender than regular green beans.","You might ﬁnd them loose or pretrimmed at the market in packaged bags.","If not pretrimmed, make sure to trim the ends."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cassava-flour-tortillas','Cassava Flour Tortillas','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,1,0,0,1,'none',2,0.71,6,1,'[{"name":"cassava ﬂour","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"cream of tartar","quantity":0.5,"unit":"teaspoon","unit_norm":"tsp","category":"dairy"},{"name":"baking soda","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"warm water","quantity":0.67,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["In a large bowl, stir together the ﬂour, cream of tartar, baking soda, and salt.","Add the oil and knead it with your hands into the dry ingredients for a minute.","The mixture will be dry and crumbly.","Add the warm water and knead for 2 to 3 more minutes.","The dough will be sticky at ﬁrst, but as the ﬂour absorbs the water, it will become more pliable.","Divide the dough into 6 parts, then roll each piece into a ball.","If you have an 8-inch tortilla press, press each ball of dough ﬂat into a tortilla between two sheets of parchment paper.","Without a tortilla press, place each ball of dough between two pieces of parchment paper and roll out into an approximate 6-inch (15cm) circle.","Heat a skillet or ﬂat griddle on medium-high heat.","Place one tortilla in the dry pan and cook for approximately 1 minute, until it starts to bubble and turn golden.","Flip and cook the other side for an additional minute.","Continue cooking all tortillas."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('roasted-potato-wedges-with-sriracha-aioli','Roasted Potato Wedges with Sriracha Aioli','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,6,NULL,1,1,0,1,0,'none',2,0.63,11,0,'[{"name":"garlic powder","quantity":2,"unit":"teaspoons","unit_norm":"tsp","category":"produce"},{"name":"onion powder","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"smoked paprika","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"kosher salt","quantity":1,"unit":"teaspoon","unit_norm":"tsp","category":"pantry"},{"name":"freshly ground black pepper","quantity":0.25,"unit":"teaspoon","unit_norm":"tsp","category":"produce"},{"name":"waxy potatoes","quantity":2,"unit":"pounds","unit_norm":"lb","category":"pantry"},{"name":"extra-virgin olive oil","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"mayonnaise","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"sriracha","quantity":2,"unit":"tablespoons","unit_norm":"tbsp","category":"pantry"},{"name":"fresh lime juice","quantity":1,"unit":"tablespoon","unit_norm":"tbsp","category":"produce"},{"name":"garlic cloves","quantity":2,"unit":"unit","unit_norm":"","category":"produce"}]','["Preheat the oven to 425°F (220°C).","To make the potatoes: In a small bowl, stir together the garlic powder, onion powder, paprika, salt, and pepper.","Set aside.","Cut each potato into 8 even wedges.","Place the potatoes in a medium bowl, drizzle with the oil, and add the seasoning.","Toss together to thoroughly coat.","Spread the potato wedges out on a rimmed baking sheet in a single layer, making sure one cut side is lying ﬂat for extra crispy edges.","Roast for 25 minutes, then ﬂip and roast an additional 15 to 20 minutes, until crispy on the outside and tender on the inside.","To make the sriracha aioli: In a small bowl, stir together the mayonnaise, sriracha, lime juice, and garlic.","Serve alongside the potato wedges.","Store the potatoes and aioli in separate airtight containers in the fridge.","The potato wedges will keep for 3 to 4 days; the aioli, for up to 1 week.","Place wedges on a rimmed baking sheet and reheat in a 350°F (180°C) oven for 5 to 8 minutes, or until warmed through. helpful tip If you have leftover aioli, drizzle it on tacos and fajitas, use it as a veggie dip, or slather it on lettuce-wrapped burgers."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pineapple-coconut-whip','Pineapple Coconut Whip','From Downshiftology Healthy Meal Prep cookbook','american','medium',20,15,35,4,NULL,1,1,0,0,1,'none',2,0.693,4,0,'[{"name":"percent okay with that! serves 4","quantity":100,"unit":"unit","unit_norm":"","category":"pantry"},{"name":"frozen pineapple chunks","quantity":4,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"pineapple juice","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"canned coconut cream","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["In a high-powered blender or food processor, blend the pineapple chunks, pineapple juice, and coconut cream for 1 minute or until smooth.","If your blender has a tamper, use that (see","Scoop the blended whip into individual serving glasses.","Once frozen, it will be quite hard.","Let it thaw on the counter for 25 to 30 minutes before scooping and serving. dietary swaps If you’re not a fan of coconut, you can swap that with a large scoop of your favorite dairy or dairy- free ice cream.","You can also use almond milk, cashew milk, oat milk, or another nondairy milk, but it won’t be quite as creamy."]','clean');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('hoisin-chicken-lettuce-cups','Hoisin Chicken Lettuce Cups','5-ingredient recipe: Hoisin Chicken Lettuce Cups',NULL,'easy',17,NULL,17,2,NULL,0,0,0,1,0,'chicken',2,1,5,0,'[{"name":"ripe mango","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"hoisin sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"skinless chicken breasts","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"romaine lettuce","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"cress","quantity":1,"unit":"punnet","unit_norm":"punnet","category":"produce"}]','["Put a griddle pan on a high heat. Cut the two cheeks off the mango, slice each into three lengthways, then slice off the skin and discard. Dice all the flesh into 1 cm cubes. Scrunch the stone over a bowl, to extract any pulp and juice, mix with the hoisin to make a dressing, and divide between two little pots.","Flatten the chicken breasts by pounding them with your fists until the fat end is the same thickness as the skinny end. Rub with 1 tablespoon of olive oil and a pinch of sea salt and black pepper, then griddle for 2 to 3 minutes on each side, or until bar-marked and cooked through. Meanwhile, trim the lettuce, click the leaves apart and divide between two plates, snipping the cress alongside.","Divide up the mango and the hoisin pots. Slice the chicken and arrange on the plates, then tuck in, using the lettuce cups as a receptacle to hold everything.","CARROT & GRAIN SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('carrot-grain-salad','Carrot & Grain Salad','5-ingredient recipe: Carrot & Grain Salad',NULL,'easy',18,NULL,18,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"mixed-colour baby heritage carrots","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"pomegranate","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"big bunch of fresh mint","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed cooked grains","quantity":1,"unit":"packet","unit_norm":"packet","category":"pantry"},{"name":"feta cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Wash the carrots, halve any larger ones, then place in a large cold non-stick frying pan with 1 tablespoon of olive oil and a pinch of sea salt and black pepper. Put on a medium-high heat for 15 minutes, or until golden and tender, tossing regularly. Meanwhile, halve the pomegranate, squeeze the juice from one half through a sieve into a large bowl, add 1 tablespoon of red wine vinegar and 2 teaspoons of extra virgin olive oil. Finely chop the top leafy half of the mint (reserving a few nice leaves), stir into the bowl, then taste and season to perfection.","Transfer the carrots to the dressing bowl, while you toss the grains in the pan for 1 minute with a splash of water to warm through. Tip into the bowl and mix with the dressed carrots, then divide between your plates.","Holding the remaining pomegranate half cut side down in your fingers, bash the back of it with a spoon so all the seeds tumble over the salads. Crumble or grate over the feta, sprinkle over the reserved mint leaves, and tuck in.","SORTA SALMON NIÇOISE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('broad-bean-salad','Broad Bean Salad','5-ingredient recipe: Broad Bean Salad',NULL,'easy',15,NULL,15,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"fresh podded or frozen broad beans","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"whole almonds","quantity":30,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"roasted red peppers in brine","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"bunch of fresh flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"Manchego cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"}]','["Boil the beans in a pan of boiling salted water for 3 minutes, then drain and pinch the skins off any larger beans. Toast the almonds in a dry griddle pan on a medium heat until lightly golden, tossing regularly, then remove and finely slice.","Drain the peppers and open out flat, then char on the hot griddle until bar-marked on one side only. Remove and slice 1cm thick. Finely slice the parsley stalks, pick the leaves, then toss with the broad beans, peppers, 1½ tablespoons of extra virgin olive oil and 1 tablespoon each of red wine vinegar and brine from the pepper jar. Taste, season to perfection with sea salt and black pepper, and divide between your plates.","Finely shave over the cheese with a speed-peeler, drizzle with 1 teaspoon of extra virgin olive oil, scatter over the almonds, and serve.","SMOKED SALMON PLATES"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('smoked-salmon-plates','Smoked Salmon Plates','5-ingredient recipe: Smoked Salmon Plates',NULL,'easy',15,NULL,15,2,NULL,0,0,1,0,1,'fish',3,1,5,0,'[{"name":"small cucumber","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh dill","quantity":6,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"smoked salmon","quantity":100,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"ripe avocado","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"cottage cheese","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Use a speed-peeler to strip the cucumber lengthways into fine ribbons. In a bowl, toss it with a small pinch of sea salt and 2 tablespoons of red wine vinegar, and scrunch to quickly pickle it. Pick and mix in most of the dill.","Drape and divide the smoked salmon between two plates. Halve, destone, peel and add the avocado. Pile the cucumber ribbons delicately to one side, filling the avocado halves with the cucumber liquor. Spoon over the cottage cheese, then drizzle with 1 teaspoon of extra virgin olive oil, add a pinch of black pepper from a height, pick over the remaining dill, and tuck on in.","DUCK & ORANGE SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('duck-orange-salad','Duck & Orange Salad','5-ingredient recipe: Duck & Orange Salad',NULL,'easy',24,NULL,24,2,NULL,0,0,0,1,0,'duck',4,0.887,5,0,'[{"name":"duck breast fillets","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"baguette","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"shelled unsalted walnut halves","quantity":15,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"regular or blood oranges","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"watercress","quantity":30,"unit":"g","unit_norm":"g","category":"produce"}]','["Score the duck skin, rub all over with sea salt and black pepper, then place skin side down in a large non-stick frying pan on a medium-high heat. Sear for 6 minutes, or until the skin is dark golden, then turn and cook for 5 minutes, or to your liking. Remove to a board to rest, leaving the pan on the heat.","Slice 10 thin slices of baguette (keeping the rest for another day). Place in the hot pan with the walnuts to toast and get golden in the duck fat, then remove and arrange the toasts on your plates. Meanwhile, top and tail the oranges, cut away the peel, then finely slice into rounds (removing any pips).","Finely slice the duck, place on the toasts, dotting any extra slices in between, then add the oranges in and around. Dress the watercress with any resting juices on the board, then sprinkle over. Finely grate or crumble over the walnuts, sprinkle from a height with a little extra seasoning, and serve.","TUNA BUTTER BEAN SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tuna-butter-bean-salad','Tuna Butter Bean Salad','5-ingredient recipe: Tuna Butter Bean Salad',NULL,'easy',15,NULL,15,2,NULL,0,0,1,0,1,'fish',2,1,5,0,'[{"name":"red onion","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"celery heart","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"bunch of fresh flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"butter beans","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"dairy"},{"name":"tuna in olive oil","quantity":1,"unit":"jar","unit_norm":"jar","category":"seafood"}]','["Peel the red onion and slice it as finely as you can. In a large bowl, scrunch it with ½ a tablespoon of red wine vinegar and a little pinch of sea salt. Trim and finely slice the celery and pile on top of the onion. Finely slice the parsley stalks, add to the bowl, then pick over the leaves.","Drain the beans and place in a single layer in a hot non-stick frying pan on a medium-high heat with 1 teaspoon of olive oil. Have faith, let them crisp up and get golden on the bottom, then turn so they crisp up on the other side.","Drizzle 1 tablespoon each of extra virgin olive oil and red wine vinegar over the onion salad, drain and flake in the tuna, then gently toss it all together. Divide the popped beans between your plates, pile the salad on top and sprinkle from a height with a good pinch of black pepper, then tuck in.","BEEF, BEETS & HORSERADISH"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-beets-horseradish','Beef, Beets & Horseradish','5-ingredient recipe: Beef, Beets & Horseradish',NULL,'easy',14,NULL,14,2,NULL,0,0,0,0,1,'beef',2,1,5,0,'[{"name":"raw mixed-colour baby beets","quantity":160,"unit":"g","unit_norm":"g","category":"produce"},{"name":"heaped teaspoons creamed horseradish","quantity":3,"unit":"","unit_norm":"","category":"dairy"},{"name":"heaped teaspoons half-fat crème fraîche","quantity":3,"unit":"","unit_norm":"","category":"dairy"},{"name":"watercress","quantity":50,"unit":"g","unit_norm":"g","category":"produce"},{"name":"finely sliced bresaola","quantity":40,"unit":"g","unit_norm":"g","category":"meat"}]','["Scrub the beets clean, reserving any nice leaves, then finely slice into matchsticks with good knife skills or using the julienne cutter on a mandolin (use the guard!). Dress with ½ a tablespoon each of extra virgin olive oil and red wine vinegar, the horseradish and crème fraîche, then season to perfection with sea salt and black pepper. Delicately toss with the watercress and any reserved beet leaves.","Divide up the bresaola between your plates, followed by the beet salad, then drizzle with 1 teaspoon of extra virgin olive oil, and serve.","CHERRY CHARD WILD RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cherry-chard-wild-rice','Cherry Chard Wild Rice','5-ingredient recipe: Cherry Chard Wild Rice',NULL,'easy',28,NULL,28,2,NULL,0,1,0,0,1,'none',4,0.887,5,0,'[{"name":"mixed wild rice","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mixed-colour chard","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"dried sour cherries","quantity":60,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"shelled unsalted walnut halves","quantity":20,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"feta cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Cook the rice in a pan of boiling salted water according to the packet instructions. Trim the chard stalks, cut them off and pop into a colander with the leaves on top, cover and steam above the rice for 3 minutes, then remove. Meanwhile, finely chop the cherries and, in a large bowl, mix with 1 tablespoon each of red wine vinegar and rice cooking water, then 1 tablespoon of extra virgin olive oil. Finely slice the walnuts, then the chard stalks, shred the leaves.","Drain the rice well, add to the cherry dressing bowl with all the chard and crumble in the feta. Toss well, then taste and season to perfection with sea salt and black pepper. Dish up, and sprinkle over the walnuts.","CRISPY SMOKED MACKEREL"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-smoked-mackerel','Crispy Smoked Mackerel','5-ingredient recipe: Crispy Smoked Mackerel',NULL,'easy',10,NULL,10,2,NULL,0,0,1,1,0,'fish',2,1,3,0,'[{"name":"smoked mackerel fillets","quantity":2,"unit":"","unit_norm":"","category":"seafood"},{"name":"vac-packed beetroots","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"watercress","quantity":50,"unit":"g","unit_norm":"g","category":"produce"}]','["2 teaspoons creamed horseradish (or use fresh, if you prefer)","2 tablespoons natural yoghurt","With a sharp knife, slash the mackerel skin at 1cm intervals, then place skin side down in a non-stick frying pan on a medium heat to get super golden and crisp. Meanwhile, drain the beets, saving the liquor. Finely slice the beets – I like to use a crinkle-cut knife. Arrange on your plates and pile the watercress on top.","Stir the horseradish into the yoghurt, then taste and season to perfection with sea salt and black pepper. Place the crispy mackerel on top of the salads, then dot around the horseradish yoghurt. Mix the beet juice with 1 tablespoon of extra virgin olive oil and drizzle over the top, then tuck in.","TASTY WARM LENTIL SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tasty-warm-lentil-salad','Tasty Warm Lentil Salad','5-ingredient recipe: Tasty Warm Lentil Salad',NULL,'easy',13,NULL,13,4,NULL,0,0,1,1,0,'fish',1,1,5,0,'[{"name":"anchovies in oil","quantity":1,"unit":"tin","unit_norm":"tin","category":"seafood"},{"name":"preserved lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"tenderstem broccoli","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"2 fresh mixed-colour chillies","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"packets of cooked lentils","quantity":2,"unit":"","unit_norm":"","category":"produce"}]','["Put all the anchovies and their oil into a blender with 1 tablespoon of liquor from the preserved lemon jar and a splash of water. Blitz until smooth, loosening with a little more water, if needed.","Trim the broccoli and blanch in a large pan of boiling salted water for 3 minutes, or until just tender, while you quarter the preserved lemon and trim away the seedy core, then finely chop the rind. Finely slice the chillies. Drain the broccoli, return to the pan over the heat and toss with the lemon, most of the chilli and 1 tablespoon of extra virgin olive oil. Add the lentils and toss for 2 minutes, then divide between plates, drizzle over the anchovy dressing and scatter with the reserved chilli. Finish with ½ a tablespoon of extra virgin olive oil.","TAHINI CARROT SLAW"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tahini-carrot-slaw','Tahini Carrot Slaw','5-ingredient recipe: Tahini Carrot Slaw',NULL,'easy',20,NULL,20,2,NULL,0,1,0,1,0,'none',1,1,5,0,'[{"name":"heaped tablespoons mixed seeds","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"clove of garlic","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed-colour carrots","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"crunchy eating apples","quantity":2,"unit":"","unit_norm":"","category":"produce"}]','["Toast the seeds in a dry non-stick frying pan on a medium heat until lightly golden, tossing regularly, then remove. Put three-quarters of the seeds into a pestle and mortar with a pinch of sea salt, and pound until fairly fine. Peel and add the garlic, then smash to a paste. Squeeze in the lemon juice, then muddle in 1 tablespoon of extra virgin olive oil and a tiny dribble of red wine vinegar to make a delicious tahini-style dressing.","Wash the carrots, then finely slice into matchsticks with good knife skills or using the julienne cutter on a mandolin (use the guard!). Core and slice the apples the same way, then toss both with the tahini dressing. Taste, season to perfection with salt and black pepper, then scatter over the remaining seeds.","WATERMELON, RADISH & FETA SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('prosciutto-celeriac-salad','Prosciutto Celeriac Salad','5-ingredient recipe: Prosciutto Celeriac Salad',NULL,'easy',10,NULL,10,2,NULL,0,0,0,0,1,'pork',4,1,5,0,'[{"name":"celeriac","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"wholegrain mustard","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"heaped tablespoons Greek yoghurt","quantity":2,"unit":"","unit_norm":"","category":"dairy"},{"name":"bunch of fresh tarragon","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"prosciutto","quantity":4,"unit":"slices","unit_norm":"slices","category":"meat"}]','["Peel the celeriac, then finely slice into matchsticks with good knife skills, using the julienne cutter on a mandolin (use the guard!), or a coarse box grater.","In a bowl, dress the celeriac with the mustard, yoghurt and 1 tablespoon each of extra virgin olive oil and red wine vinegar. Scrunch and massage together. Pick in the tarragon leaves, mix well, then taste and season to perfection with sea salt and black pepper. Divide between two plates, then wrap the prosciutto in waves around the outside. Drizzle with 1 teaspoon of extra virgin olive oil and sprinkle from a height with a pinch of pepper.","SWEET POTATO SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('super-green-spaghetti','Super Green Spaghetti','5-ingredient recipe: Super Green Spaghetti',NULL,'easy',13,NULL,13,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"dried spaghetti","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"cavolo nero","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"Parmesan cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"ricotta cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions. Meanwhile, peel the garlic. Tear the stems out of the cavolo and discard, adding the leaves and the garlic to the pasta pan for 5 minutes. Pour 1½ tablespoons of extra virgin olive oil into a blender, then finely grate in the Parmesan. Use tongs to carefully transfer the cavolo leaves and garlic straight into the blender and blitz for a few minutes until super-smooth. Taste and season to perfection with sea salt and black pepper.","Drain the pasta, reserving a mugful of cooking water. Return it to the pan and toss with the vibrant green sauce, loosening with a splash of reserved cooking water, if needed, then divide between your plates. Dot over the ricotta, drizzle with a tiny bit of extra virgin olive oil, and tuck right in.","EASY SAUSAGE CARBONARA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('easy-sausage-carbonara','Easy Sausage Carbonara','5-ingredient recipe: Easy Sausage Carbonara',NULL,'easy',15,NULL,15,2,NULL,0,0,0,0,1,'pork',4,1,5,0,'[{"name":"dried tagliatelle","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"sausages","quantity":3,"unit":"","unit_norm":"","category":"meat"},{"name":"bunch of fresh flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"large egg","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"Parmesan cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Meanwhile, squeeze the sausagemeat out of the skins, then, with wet hands, quickly shape into 18 even-sized balls. Roll and coat them in black pepper, then cook in a non-stick frying pan on a medium heat with ½ a tablespoon of olive oil until golden and cooked through, tossing regularly, then turn the heat off.","Finely chop the parsley, stalks and all, beat it with the egg and a splash of pasta cooking water, then finely grate and mix in most of the Parmesan.","Toss the drained pasta into the sausage pan, pour in the egg mixture, and toss for 1 minute off the heat (the egg will gently cook in the residual heat). Loosen with a good splash of reserved cooking water, season to perfection with sea salt and pepper, and finely grate over the remaining Parmesan.","CRAB & FENNEL SPAGHETTI"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crab-fennel-spaghetti','Crab & Fennel Spaghetti','5-ingredient recipe: Crab & Fennel Spaghetti',NULL,'easy',18,NULL,18,2,NULL,0,0,1,1,0,'fish',2,1,5,0,'[{"name":"bulb of fennel","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"dried spaghetti","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"fresh red chilli","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe mixed-colour cherry tomatoes","quantity":160,"unit":"g","unit_norm":"g","category":"produce"},{"name":"mixed brown & white crabmeat","quantity":160,"unit":"g","unit_norm":"g","category":"seafood"}]','["Put a large non-stick frying pan on a medium-low heat. Trim the fennel, pick and reserve any leafy tops, then halve the bulb and finely slice it. Place in the pan with 1 tablespoon of olive oil and cook with the lid on for 5 minutes. Meanwhile, cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water.","Deseed and finely slice the chilli, stir into the fennel pan and cook uncovered until soft and sticky, stirring occasionally. Halve the tomatoes and toss into the pan for 2 minutes, followed by the crabmeat and, 1 minute later, the drained pasta. Loosen with a splash of reserved cooking water, if needed, then season to perfection with sea salt and black pepper, sprinkle over any reserved fennel tops and drizzle with 1 teaspoon of extra virgin olive oil. Enjoy.","AUBERGINE PENNE ARRABBIATA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('aubergine-penne-arrabbiata','Aubergine Penne Arrabbiata','5-ingredient recipe: Aubergine Penne Arrabbiata',NULL,'easy',28,NULL,28,4,NULL,0,1,0,1,0,'none',2,0.887,5,0,'[{"name":"fresh mixed-colour chillies","quantity":12,"unit":"","unit_norm":"","category":"produce"},{"name":"aubergines","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"dried wholewheat penne","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"plum tomatoes","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"}]','["To make a quick chilli oil, halve and deseed the chillies. Fill a clean heatproof jar with olive oil, then pour it into a non-stick frying pan on a medium-low heat and add the chillies to confit. Meanwhile, put a pan of boiling salted water on for the pasta. Halve the aubergines lengthways and blanch in the water, covered, for 5 minutes, then lift out, leaving the water on the boil. Carefully scoop the soft chillies into the jar, then spoon in the oil, leaving 2 tablespoons in the pan (keep the jar of chilli oil to add a kick to future meals). Chop the aubergine into 3cm chunks, add to the pan with a pinch of sea salt and black pepper, then turn the heat up to high, stirring regularly.","Cook the pasta according to the packet instructions while you peel and finely slice the garlic, then fry with the aubergine for 2 minutes. Pour in the tomatoes, breaking them up with a wooden spoon, and half a tin’s worth of water. Add as many of the chillies as you dare to the sauce and simmer until the pasta is ready, then taste and season to perfection. Drain the pasta, reserving a mugful of cooking water, then toss the pasta through the sauce, loosening with a little reserved cooking water, if needed. Dish up.","HOT-SMOKED SALMON PASTA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('hot-smoked-salmon-pasta','Hot-Smoked Salmon Pasta','5-ingredient recipe: Hot-Smoked Salmon Pasta',NULL,'easy',12,NULL,12,4,NULL,0,0,1,0,1,'fish',3,1,5,0,'[{"name":"asparagus","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"dried taglierini or angel-hair pasta","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"hot-smoked salmon","quantity":250,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"half-fat crème fraîche","quantity":100,"unit":"ml","unit_norm":"ml","category":"dairy"}]','["Use a speed-peeler to strip the top tender half of the asparagus stalks into ribbons. Finely slice the remaining stalks, discarding the woody ends. Cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Meanwhile, roughly break the salmon into a large non-stick frying pan on a medium-high heat. Add the sliced asparagus stalks, and toss occasionally until the pasta’s ready.","Finely grate half the lemon zest into the salmon pan, squeeze in half the juice, then toss in the drained pasta, a good splash of reserved cooking water and the crème fraîche. Add the asparagus ribbons, toss again, then season to perfection with sea salt and black pepper. Serve with lemon wedges, for squeezing over.","SICILIAN TUNA PASTA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sicilian-tuna-pasta','Sicilian Tuna Pasta','5-ingredient recipe: Sicilian Tuna Pasta',NULL,'easy',14,NULL,14,4,NULL,0,0,1,1,0,'fish',2,1,3,0,'[{"name":"dried pasta shells","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"heaped teaspoons baby capers","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe mixed-colour cherry tomatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"}]','["1 tablespoon dried oregano, ideally the flowering kind","1 × 220g jar of tuna in olive oil","Cook the pasta in a pan of boiling salted water according to the packet instructions. Meanwhile, place a large non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil. Add the capers, fry until super-crispy, then scoop out and put aside, leaving the fragrant oil behind. Halve and add the tomatoes, then sprinkle in most of the oregano. Drain and flake in the tuna, add 2 ladlefuls of pasta cooking water, and simmer until the pasta is done.","Drain the pasta, reserving a mugful of cooking water, then toss the pasta into the tuna pan, loosening with a splash of reserved cooking water, if needed. Taste, season to perfection with sea salt and black pepper, then dish up. Sprinkle over the crispy capers and the remaining oregano from a height, drizzle with 1 teaspoon of extra virgin olive oil, and tuck in.","LEMONY COURGETTE LINGUINE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lemony-courgette-linguine','Lemony Courgette Linguine','5-ingredient recipe: Lemony Courgette Linguine',NULL,'easy',15,NULL,15,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"dried linguine","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mixed-colour courgettes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"bunch of fresh mint","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"Parmesan cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Meanwhile, slice the courgettes lengthways, then again into long matchsticks with good knife skills or using the julienne cutter on a mandolin (use the guard!). Place a large non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil, then add the courgettes. Cook for 4 minutes, tossing regularly, while you finely slice the mint leaves, then stir them into the pan.","Toss the drained pasta into the courgette pan with a splash of reserved cooking water. Finely grate in most of the Parmesan and a little lemon zest, squeeze in all the juice, toss well, then taste and season to perfection with sea salt and black pepper. Dish up, finely grate over the remaining Parmesan and drizzle with 1 teaspoon of extra virgin olive oil before tucking in.","GARLIC MUSHROOM PASTA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('garlic-mushroom-pasta','Garlic Mushroom Pasta','5-ingredient recipe: Garlic Mushroom Pasta',NULL,'easy',16,NULL,16,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"dried trofie or fusilli","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"mixed mushrooms","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Parmesan cheese","quantity":25,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"heaped tablespoons half-fat crème fraîche","quantity":2,"unit":"","unit_norm":"","category":"dairy"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Meanwhile, peel and finely slice the garlic. Place it in a large non-stick frying pan on a medium-high heat with ½ a tablespoon of olive oil, followed 1 minute later by the mushrooms, tearing up any larger ones. Season with sea salt and black pepper, and cook for 8 minutes, or until golden, tossing regularly.","Toss the drained pasta into the mushroom pan with a splash of reserved cooking water. Finely grate in most of the Parmesan, stir in the crème fraîche, taste, season to perfection, and dish up, finishing with a final grating of Parmesan.","SPICY ’NDUJA VONGOLE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spicy-nduja-vongole','Spicy ’Nduja Vongole','5-ingredient recipe: Spicy ’Nduja Vongole',NULL,'easy',15,NULL,15,2,NULL,0,1,0,1,0,'pork',2,1,5,0,'[{"name":"dried linguine","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"clams","quantity":500,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"’nduja","quantity":20,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"bunch of fresh flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"light rosé wine","quantity":100,"unit":"ml","unit_norm":"ml","category":"pantry"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions, draining 1 minute early and reserving a mugful of cooking water. Meanwhile, sort through the clams, giving any that aren’t tightly closed a tap. If they don’t close, discard them. Tear the ’nduja into a large cold non-stick frying pan, add 1 tablespoon of olive oil, place on a medium heat and let the ’nduja melt while you finely chop the parsley (stalks and all). Stir most of the parsley into the ’nduja pan with the clams and rosé, and put the lid on. After 3 or 4 minutes the clams will start to open – keep jiggling the pan until they’ve all opened, then remove from the heat, discarding any unopened clams.","Toss the drained pasta into the clam pan with a splash of reserved cooking water and simmer for 1 minute. Taste and season to perfection with sea salt and black pepper, if needed. Dish up, drizzle with a little extra virgin olive oil and scatter over the remaining parsley, and tuck in.","PORK PORCINI PASTA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-porcini-pasta','Pork Porcini Pasta','5-ingredient recipe: Pork Porcini Pasta',NULL,'easy',27,NULL,27,4,NULL,0,0,0,0,1,'pork',4,0.967,5,1,'[{"name":"dried porcini mushrooms","quantity":30,"unit":"g","unit_norm":"g","category":"produce"},{"name":"minced pork shoulder","quantity":300,"unit":"g","unit_norm":"g","category":"meat"},{"name":"onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"dried wholewheat penne","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"Parmesan cheese","quantity":50,"unit":"g","unit_norm":"g","category":"dairy"}]','["In a small bowl, cover the dried porcini with 400ml of boiling kettle water. Place the minced pork in a large shallow casserole pan with 1 tablespoon of olive oil, then break it up and fry on a high heat, stirring regularly. Meanwhile, peel and finely chop the onion, then the drained porcini, reserving the soaking water.","Stir the onion and porcini into the pan and fry for 10 minutes, or until golden. Add 1 tablespoon of red wine vinegar and the porcini water (discarding the last gritty bit). Simmer for 10 minutes on a low heat, while you cook the pasta in a pan of boiling salted water according to the packet instructions, draining 1 minute early and reserving a good mugful of cooking water.","Toss the drained pasta into the pork pan with 250ml of reserved cooking water, then finely grate in most of the Parmesan, taste and season to perfection with sea salt and black pepper. Toss over a low heat for 2 minutes to emulsify the sauce, then dish up. Finely grate over the remaining Parmesan, drizzle with a little extra virgin olive oil, and enjoy.","PEAR & GORGONZOLA FARFALLE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pear-gorgonzola-farfalle','Pear & Gorgonzola Farfalle','5-ingredient recipe: Pear & Gorgonzola Farfalle',NULL,'easy',15,NULL,15,2,NULL,0,1,0,0,1,'none',3,1,5,0,'[{"name":"dried farfalle","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"Gorgonzola cheese","quantity":75,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"radicchio or 2 red chicory","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"super-ripe pears","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"shelled unsalted walnut halves","quantity":30,"unit":"g","unit_norm":"g","category":"pantry"}]','["Cook the pasta in a medium pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Melt the cheese in a heatproof bowl above the pasta as it cooks, removing carefully when gooey.","Meanwhile, slice the radicchio 1cm thick. Place it in a large dry non-stick frying pan on a high heat to char for 5 minutes, turning halfway. Peel the pears with a speed-peeler, then quarter, core and finely slice lengthways. Toss into the pan, crumble in most of the walnuts, add a splash of pasta cooking water, reduce to a medium heat and pop the lid on, then leave to caramelize slightly.","Toss the drained pasta and oozy Gorgonzola into the pear pan with a splash of red wine vinegar, and a splash of reserved cooking water, if needed. Taste, season to perfection with sea salt and black pepper, crumble over the remaining walnuts and drizzle with 1 teaspoon of extra virgin olive oil.","ROSÉ PESTO PRAWN PASTA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('ros-pesto-prawn-pasta','Rosé Pesto Prawn Pasta','5-ingredient recipe: Rosé Pesto Prawn Pasta',NULL,'easy',12,NULL,12,2,NULL,0,0,1,1,0,'fish',4,0.863,5,0,'[{"name":"large raw shell-on king prawns","quantity":300,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"heaped teaspoons red pesto","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"dried taglierini or angel-hair pasta","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"light rosé wine","quantity":150,"unit":"ml","unit_norm":"ml","category":"pantry"}]','["Place 4 whole prawns in a large non-stick frying pan with 1 tablespoon of olive oil, off the heat. Pull off the rest of the prawn heads and chuck them into the pan for bonus flavour. Quickly pull the legs and tails off the prawns and peel off the shells. Run the tip of your knife down their backs and pull out the vein, then chop the prawns. Peel and finely slice the garlic. Put the frying pan on a medium-high heat and, after 2 minutes, stir in the garlic and chopped prawns, followed 1 minute later by the pesto, stirring regularly.","Meanwhile, cook the pasta in a pan of boiling salted water according to the packet instructions. Pour the rosé into the prawn pan and let it bubble and reduce for 1 minute. Drain the pasta, reserving a mugful of cooking water, then toss the pasta into the prawn pan, loosening with a little reserved cooking water, if needed. Toss over the heat for 1 minute, then taste, season to perfection with sea salt and black pepper, and dish up.","EGGS","SCRAMBLED EGG OMELETTE","EGG & MANGO CHUTNEY FLATBREADS","KOREAN EGGS & RICE","ASIAN FRIED EGGS","CHILLI CRAB SILKY OMELETTE","HOT-SMOKED SALMON FRITTATA","ALL-DAY MEXICAN BREAKFAST","EGG RIBBON SALAD","SMOKY MUSHROOM FRITTATA","SCRAMBLED EGG OMELETTE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('scrambled-egg-omelette','Scrambled Egg Omelette','5-ingredient recipe: Scrambled Egg Omelette',NULL,'easy',10,NULL,10,2,NULL,0,1,0,0,1,'none',2,1,5,0,'[{"name":"ripe mixed-colour tomatoes","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"bunch of fresh basil","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"1 fresh red chilli","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"ball of mozzarella","quantity":0.5,"unit":"","unit_norm":"","category":"dairy"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"}]','["Finely slice the tomatoes, arrange over a sharing platter, then dress with a little extra virgin olive oil, red wine vinegar, sea salt and black pepper. Pick most of the basil leaves into a pestle and mortar, pound with a pinch of salt into a paste, then muddle in 1 tablespoon of extra virgin olive oil to make a basil oil.","Finely slice the chilli. Finely chop the mozzarella. Place a 26cm non-stick frying pan on a medium heat with ½ a tablespoon of olive oil. Beat and pour in the eggs, then stir regularly with a rubber spatula, moving the eggs gently around the pan. When they’re lightly scrambled but still loose, stop stirring and scatter the mozzarella in the centre, then drizzle over the basil oil. Let the bottom of the eggs set for 1 minute, then – technique time – pick up the pan, tilt it down and, with your other hand, keep tapping your wrist until it shakes the eggs up the side of the pan; use the spatula to flip it back to the middle, then fold the top half back over, too. Turn it upside down on to the tomato platter, set side up.","Slice down the centre to reveal the oozy scrambled eggs in the middle. Scatter over the chilli (as much as you dare!) and remaining basil leaves, and tuck on in.","EGG & MANGO CHUTNEY FLATBREADS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('korean-eggs-rice','Korean Eggs & Rice','5-ingredient recipe: Korean Eggs & Rice',NULL,'easy',22,NULL,22,2,NULL,0,1,0,1,0,'none',2,0.887,5,0,'[{"name":"heaped tablespoon sesame seeds","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"basmati rice","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"kimchee","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"fresh coriander","quantity":4,"unit":"sprigs","unit_norm":"sprigs","category":"produce"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"}]','["Toast the sesame seeds in a dry 26cm non-stick frying pan on a medium heat. Once lightly golden, remove to a plate, reducing the heat to medium-low. Place the rice in the pan with a small pinch of sea salt, then pour in 400ml of water. Cover and cook for 10 minutes, or until the rice has absorbed all the liquid.","Finely chop the kimchee with half the coriander leaves, beat in the eggs, then pour over the rice, spreading it out evenly with a spatula. Cover and leave for another 5 to 10 minutes, or until the eggs are just set.","Loosen the edges with a spatula, then slide it out on to a plate – I like to fold one half back on itself to expose the underside. Scatter over the toasted sesame seeds, pick over the remaining coriander leaves, then tuck on in.","ASIAN FRIED EGGS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('asian-fried-eggs','Asian Fried Eggs','5-ingredient recipe: Asian Fried Eggs',NULL,'easy',10,NULL,10,2,NULL,0,1,0,1,0,'none',1,1,5,0,'[{"name":"spring onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"2 fresh mixed-colour chillies","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoons mixed sesame seeds","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"hoisin sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Trim the spring onions, very finely slice at an angle with the chillies, pop both into a bowl of ice-cold water, add a swig of red wine vinegar and put aside.","Place a large non-stick frying pan on a medium-high heat and lightly toast the sesame seeds for 1 minute. Drizzle in 1 tablespoon of olive oil, then crack in the eggs. Put a lid on the pan, and fry to your liking.","Place the eggs on your plates – I like one facing up and one facing down. From a height, drizzle over the hoisin (loosening with a splash of water first, if needed). Drain and scatter over the spring onions and chillies, stab the yolks, and enjoy.","CHILLI CRAB SILKY OMELETTE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chilli-crab-silky-omelette','Chilli Crab Silky Omelette','5-ingredient recipe: Chilli Crab Silky Omelette',NULL,'easy',10,NULL,10,1,NULL,0,0,1,0,1,'fish',2,1,5,0,'[{"name":"1 fresh red chilli","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed brown & white crabmeat","quantity":75,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"lemon","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"Cheddar cheese","quantity":10,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Deseed and finely chop the chilli. Mix as much as you dare with the crabmeat, a squeeze of lemon juice and a little sea salt and black pepper. Finely grate the cheese. Beat the eggs well, ready to go.","Get a 30cm non-stick frying pan nice and hot on a medium-high heat, then add a drizzle of olive oil and wipe it around and out with a ball of kitchen paper. Pour in the eggs, swirling them around the pan and up the sides. Working quickly, sprinkle over the cheese from a height, followed by the dressed crab, then turn the heat off. Use a rubber spatula to gently ease it away from the edges and quickly roll it up a few times – you want to create layers, so how you roll and whether it tears doesn’t matter, just don’t overcook it. Turn the omelette out on to a plate, drizzle with a little extra virgin olive oil, and tuck in.","HOT-SMOKED SALMON FRITTATA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('hot-smoked-salmon-frittata','Hot-Smoked Salmon Frittata','5-ingredient recipe: Hot-Smoked Salmon Frittata',NULL,'easy',13,NULL,13,2,NULL,0,0,1,0,1,'fish',2,1,5,0,'[{"name":"hot-smoked salmon","quantity":125,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"spring onions","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"heaped tablespoons half-fat crème fraîche","quantity":2,"unit":"","unit_norm":"","category":"dairy"},{"name":"Red Leicester cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the grill to high. Place a 26cm non-stick ovenproof frying pan on a medium-high heat. Put the salmon into the pan, breaking it up as it starts to sizzle. Trim, finely slice and add the spring onions, along with a pinch of black pepper. Stir occasionally for 5 minutes while, in a large bowl, you vigorously whisk the eggs until they’ve doubled in size.","Reduce the heat to low, stir in the crème fraîche and grate in the cheese. Pour the contents of the pan into the egg bowl, mix well, then pour back into the pan, swirling it around and up the sides. Grill for 5 minutes, or until golden, set and just cooked through – keep an eye on it. Loosen the edges with a spatula, then slide on to a board, slice, and serve.","ALL-DAY MEXICAN BREAKFAST"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('all-day-mexican-breakfast','All-Day Mexican Breakfast','5-ingredient recipe: All-Day Mexican Breakfast',NULL,'easy',15,NULL,15,2,NULL,0,1,0,1,0,'none',2,1,5,0,'[{"name":"2 fresh mixed-colour chillies","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"black beans","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"},{"name":"ripe avocado","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"lime","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Finely slice the chillies (use as much as you dare!). Sprinkle half of them into a 30cm non-stick frying pan on a medium heat with 1 teaspoon of olive oil. Once they start to sizzle, evenly crack in the eggs, then spoon the black beans and just half the juice from the tin in and around the eggs. Season with sea salt and black pepper, cover and cook the eggs to your liking.","Meanwhile, halve, peel and destone the avocado, slice into thin wedges, dress with the lime juice and season to perfection. Arrange the avocado around the pan, scatter over the rest of the chillies, stab the egg yolks, and dish up.","EGG RIBBON SALAD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('egg-ribbon-salad','Egg Ribbon Salad','5-ingredient recipe: Egg Ribbon Salad',NULL,'easy',15,NULL,15,2,NULL,0,0,0,0,1,'beef',4,1,5,0,'[{"name":"finely sliced bresaola","quantity":50,"unit":"g","unit_norm":"g","category":"meat"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"mixed-colour chicory","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Parmesan cheese","quantity":10,"unit":"g","unit_norm":"g","category":"dairy"}]','["Arrange the bresaola slices on your plates. Beat the eggs well. Get a 26cm non-stick frying pan nice and hot on a medium heat, then add a drizzle of olive oil and wipe it around and out with a ball of kitchen paper. Pour in just enough egg to thinly cover the base of the pan, swirling it up around the sides and pouring any excess back into your bowl, almost like an egg pancake. As soon as it’s set, use a rubber spatula to ease it away at the sides, and out on to a board. Repeat with the remaining egg. Cool, roll up and finely slice.","Trim and finely slice the chicory. Dress with the lemon juice and ½ a tablespoon of extra virgin olive oil, then toss with the egg ribbons, taste and season to perfection with sea salt and black pepper. Pile in the centre of the bresaola, shave over the Parmesan, then finish with a little extra virgin olive oil.","SMOKY MUSHROOM FRITTATA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('smoky-mushroom-frittata','Smoky Mushroom Frittata','5-ingredient recipe: Smoky Mushroom Frittata',NULL,'easy',24,NULL,24,4,NULL,0,0,0,0,1,'pork',3,0.83,5,1,'[{"name":"smoked streaky bacon","quantity":4,"unit":"rashers","unit_norm":"rashers","category":"meat"},{"name":"mixed mushrooms","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"large eggs","quantity":8,"unit":"","unit_norm":"","category":"pantry"},{"name":"Cheddar cheese","quantity":80,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"rocket","quantity":50,"unit":"g","unit_norm":"g","category":"produce"}]','["Preheat the oven to 200°C/400°F/gas 6. Slice the bacon and fry in 1 teaspoon of olive oil in a 26cm non-stick ovenproof frying pan on a medium heat for 2 minutes. Add the mushrooms, tearing up any larger ones. Season with sea salt and black pepper, then fry for 5 minutes, or until golden, tossing regularly.","Lightly beat the eggs, then pour into the pan and bomb over nuggets of cheese. Transfer to the oven for 10 minutes, or until nicely set. Loosen the edges with a spatula, then slide on to a board. Dress the rocket in a little extra virgin olive oil and red wine vinegar, and sprinkle on top.","CHICKEN","STICKY KICKIN’ WINGS","ROAST TIKKA CHICKEN","CHICKEN NOODLE STIR-FRY","CHICKEN POT PIE","GNARLY PEANUT CHICKEN","HARISSA CHICKEN TRAYBAKE","CRISPY GARLICKY CHICKEN","THAI RED CHICKEN SOUP","SWEET CHICKEN SURPRISE","FLAKY PASTRY PESTO CHICKEN","CREAMY MUSTARD CHICKEN","STICKY HOISIN CHICKEN","HERBY CHICKEN TRAYBAKE","STICKY KICKIN’ WINGS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sticky-kickin-wings','Sticky Kickin’ Wings','5-ingredient recipe: Sticky Kickin’ Wings',NULL,'easy',20,NULL,20,2,NULL,0,0,0,1,0,'chicken',1,1,5,0,'[{"name":"sesame seeds","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"large chicken wings","quantity":4,"unit":"","unit_norm":"","category":"meat"},{"name":"teriyaki sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"fresh red chilli","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"spring onions","quantity":2,"unit":"","unit_norm":"","category":"produce"}]','["Toast the sesame seeds in a dry 20cm non-stick frying pan on a medium heat until lightly golden, then remove to a plate. Still on the heat, sit the wings in the pan – they should fit snugly. Let them colour for 1 minute on each side, then add the teriyaki and just cover the wings with water. Halve the chilli lengthways and add to the pan. Simmer for 35 to 40 minutes, or until the chicken is tender and the sauce is nice and sticky, turning occasionally.","Add a splash of red wine vinegar to the pan and jiggle around to pick up the gnarly bits. Trim and finely slice the spring onions, scatter them over the chicken with the toasted sesame seeds, and get stuck in.","ROAST TIKKA CHICKEN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('roast-tikka-chicken','Roast Tikka Chicken','5-ingredient recipe: Roast Tikka Chicken',NULL,'easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,1,5,0,'[{"name":"potatoes","quantity":800,"unit":"g","unit_norm":"g","category":"produce"},{"name":"small head of cauliflower","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh coriander","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"tikka curry paste","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 180°C/350°F/gas 4. Wash the potatoes and chop into 3cm chunks. Trim the cauli stalk, remove any tough outer leaves, then chop the cauli and nice leaves the same size as the spuds. Finely slice the coriander stalks (reserving the leaves in a bowl of cold water). In a 30cm × 40cm roasting tray, toss the veg and coriander stalks with a pinch of sea salt and black pepper, and 1 tablespoon each of olive oil and red wine vinegar.","Sit the chicken in the tray and rub all over with the tikka paste, getting into all the nooks and crannies. Place the chicken directly on the bars of the oven, scrunch everything in the tray and place exactly underneath the chicken to catch the tasty juices. Roast for 1 hour, or until everything is golden and cooked through, turning the veg halfway. Sit the chicken on top of the veg to rest for 5 minutes, then sprinkle over the drained coriander leaves and serve, tossing the veg in all the tasty juices before dishing up.","CHICKEN NOODLE STIR-FRY"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-noodle-stir-fry','Chicken Noodle Stir-Fry','5-ingredient recipe: Chicken Noodle Stir-Fry',NULL,'easy',16,NULL,16,2,NULL,0,0,0,1,0,'chicken',2,1,5,0,'[{"name":"unsalted peanuts","quantity":30,"unit":"g","unit_norm":"g","category":"produce"},{"name":"skinless chicken breasts","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"black bean sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"medium egg noodles","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"tenderstem broccoli","quantity":200,"unit":"g","unit_norm":"g","category":"produce"}]','["Place a large non-stick frying pan on a medium heat and toast the peanuts as it heats up, tossing regularly, then remove and set aside, leaving the pan on the heat. Meanwhile, score the chicken lengthways at 1cm intervals, going about halfway through. In a bowl, toss the chicken with 1 tablespoon each of olive oil, red wine vinegar and black bean sauce to coat. Cook in the hot pan for 3 minutes on each side, or until dark, gnarly and cooked through.","Cook the noodles in a large pan of boiling salted water according to the packet instructions. Trim the broccoli (halving any thick stalks lengthways) and add to the water for the last 2 minutes. Remove the chicken to a board. Use tongs to carefully drag the just-cooked noodles and broccoli with a bit of their water straight into the frying pan. Pound half the peanuts in a pestle and mortar until fine, toss into the pan with the remaining black bean sauce until well mixed, then divide between your plates. Slice the chicken and place on top, scatter over the remaining peanuts, drizzle with a little extra virgin olive oil, and dig in.","CHICKEN POT PIE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-pot-pie','Chicken Pot Pie','5-ingredient recipe: Chicken Pot Pie',NULL,'easy',30,NULL,30,4,NULL,0,0,0,0,1,'chicken',1,0.967,5,1,'[{"name":"onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"chicken thighs","quantity":600,"unit":"g","unit_norm":"g","category":"meat"},{"name":"mixed mushrooms","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"fresh thyme","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"pantry"},{"name":"block of all-butter puff pastry","quantity":375,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 220°C/425°F/gas 7. Place a 30cm non-stick ovenproof frying pan on a high heat, with a smaller non-stick pan on a medium heat alongside. Pour 1 tablespoon of olive oil into the larger pan. Peel and roughly chop the onions, adding them to the larger pan as you go. Roughly chop two-thirds of the thighs, finely chop the rest, and add to the onion pan. Cook for 6 minutes, or until golden, stirring occasionally. Meanwhile, place the mushrooms in the dry pan, tearing up any larger ones. Let them toast and get nutty for 4 minutes, then tip into the chicken pan and strip in half the thyme leaves.","Remove the pan from the heat, add a pinch of sea salt and black pepper, then stir in 1 tablespoon of red wine vinegar and 150ml of water. Working quickly, roll out the pastry so it’s 2cm bigger than the pan, then place it over the filling, using a wooden spoon to push it into the edges. Very lightly criss-cross the pastry, then brush with 1 teaspoon of olive oil. Poke the remaining thyme sprigs into the middle of the pie. Bake at the bottom of the oven for 15 minutes, or until golden and puffed up. Easy!","GNARLY PEANUT CHICKEN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('gnarly-peanut-chicken','Gnarly Peanut Chicken','5-ingredient recipe: Gnarly Peanut Chicken',NULL,'easy',12,NULL,12,2,NULL,0,0,0,1,0,'chicken',2,1,5,1,'[{"name":"skinless chicken breasts","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"limes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"heaped tablespoons peanut butter","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"2 fresh red chillies","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Turn the grill on to medium-high. Score the chicken breasts in a criss-cross fashion, rub with 1 tablespoon of olive oil, a pinch of sea salt and black pepper and the finely grated zest of 1 lime. Place criss-cross side down in a cold 26cm non-stick ovenproof frying pan and put it on a medium-high heat, while you peel and finely grate the garlic into a bowl. Squeeze in the juice from 1½ limes, stir in the peanut butter and loosen with enough water to give you a spoonable consistency. Finely slice the chilli, then mix (as much as you dare!) through the sauce, taste and season to perfection.","Flip the chicken over, spoon over the sauce, then transfer to the grill, roughly 10cm from the heat, for 5 minutes, or until gnarly and cooked through. Finely grate over the remaining lime zest, then drizzle with 1 teaspoon of extra virgin olive oil. Serve with lime wedges, for squeezing over.","HARISSA CHICKEN TRAYBAKE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('harissa-chicken-traybake','Harissa Chicken Traybake','5-ingredient recipe: Harissa Chicken Traybake',NULL,'easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,1,5,1,'[{"name":"mixed-colour peppers","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"red onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"heaped teaspoons rose harissa","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"fresh mint","quantity":4,"unit":"sprigs","unit_norm":"sprigs","category":"produce"}]','["Preheat the oven to 180°C/350°F/gas 4. Deseed the peppers and tear into big chunks, peel and quarter the onions and break apart into petals, then place it all in a 30cm × 40cm roasting tray. Use a large sharp knife to carefully cut down the back of the chicken, so you can open it out flat, then score the legs. Add to the tray with the harissa, and a little sea salt, black pepper and red wine vinegar. Toss well, making sure you get into all the nooks and crannies of the chicken.","Sit the chicken flat on top of the veg, skin side up, and roast it all for 50 minutes, or until gnarly and cooked through. Pick over the mint leaves before dishing up.","CRISPY GARLICKY CHICKEN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-chicken-surprise','Sweet Chicken Surprise','5-ingredient recipe: Sweet Chicken Surprise',NULL,'easy',20,NULL,20,2,NULL,0,0,0,1,0,'chicken',1,1,5,0,'[{"name":"chicken legs","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"bulb of garlic","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed-colour seedless grapes","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"red vermouth","quantity":100,"unit":"ml","unit_norm":"ml","category":"pantry"},{"name":"fresh tarragon","quantity":4,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"}]','["Preheat the oven to 180°C/350°F/gas 4. Put a non-stick ovenproof frying pan on a high heat. Rub the chicken all over with ½ a tablespoon of olive oil, season with sea salt and black pepper and place skin side down in the pan. Fry for a couple of minutes until golden, then lightly squash the unpeeled garlic cloves with the heel of your hand and add to the pan. Pick in the grapes.","Turn the chicken skin side up, pour in the vermouth and transfer to the oven to roast for 40 minutes, or until the chicken is golden and tender, and the sauce is sticky and reduced. Add a splash of water to the pan and give it a gentle shimmy to pick up all the sticky bits. Pick over the tarragon, and dish up.","FLAKY PASTRY PESTO CHICKEN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('flaky-pastry-pesto-chicken','Flaky Pastry Pesto Chicken','5-ingredient recipe: Flaky Pastry Pesto Chicken',NULL,'easy',30,NULL,30,4,NULL,0,0,0,0,1,'chicken',4,0.887,5,0,'[{"name":"sheet of all-butter puff pastry","quantity":320,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"skinless chicken breasts","quantity":4,"unit":"","unit_norm":"","category":"meat"},{"name":"heaped teaspoons green pesto","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"ripe cherry tomatoes","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"green beans","quantity":400,"unit":"g","unit_norm":"g","category":"produce"}]','["Preheat the oven to 220°C/425°F/gas 7. Unroll the pastry, cut it in half lengthways, then cut each half widthways into 8 equal strips. Flatten the chicken breasts by pounding with your fist until the fat ends are the same thickness as the skinny ends. Place them in a roasting tray, season with sea salt and black pepper, spread over the pesto, then lay 4 overlapping strips of pastry over each breast, tucking them under at the edges. Brush with a little olive oil. Lightly dress the tomato vines in olive oil, season and put into a second tray. Place the chicken tray on the top shelf of the oven with the tomatoes below, and cook for 20 minutes, or until the pastry is golden and the chicken is cooked through.","Meanwhile, line up the beans, trim off just the stalk ends, then cook in a pan of boiling salted water for 7 minutes, or until tender. Remove the chicken to a board with half the tomatoes, squashing the rest in the tray and discarding the vines. Drain and toss in the beans, taste and season to perfection. Slice the chicken at an angle and serve on top of the beans, with the whole tomatoes.","CREAMY MUSTARD CHICKEN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('creamy-mustard-chicken','Creamy Mustard Chicken','5-ingredient recipe: Creamy Mustard Chicken',NULL,'easy',20,NULL,20,2,NULL,0,0,0,0,1,'chicken',2,1,5,0,'[{"name":"mixed mushrooms","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"red onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"skinless chicken breasts","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"wholegrain mustard","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"single cream","quantity":60,"unit":"ml","unit_norm":"ml","category":"dairy"}]','["Place a 30cm non-stick frying pan on a medium-high heat. Place all the mushrooms in the dry pan, tearing up any larger ones. Let them toast and get dark golden and nutty, tossing occasionally, while you peel and finely slice the red onion and slice the chicken breasts into 1cm-thick strips.","When the mushrooms look good, add the onion and chicken to the pan with 1 tablespoon of olive oil. Cook for 5 minutes, tossing often, then add the mustard, cream and 150ml of water. Bring to the boil, then simmer until you’ve just got a loose saucy consistency and the chicken is cooked through. Taste, season to perfection with sea salt and black pepper, and dish up.","STICKY HOISIN CHICKEN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sticky-hoisin-chicken','Sticky Hoisin Chicken','5-ingredient recipe: Sticky Hoisin Chicken',NULL,'easy',25,NULL,25,2,NULL,0,0,0,1,0,'chicken',1,0.967,5,1,'[{"name":"chicken legs","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"spring onions","quantity":8,"unit":"","unit_norm":"","category":"produce"},{"name":"2 fresh mixed-colour chillies","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"regular or blood oranges","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoons hoisin sauce","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Put a non-stick frying pan on a medium-high heat. Pull off the chicken skin, put both skin and legs into the pan, season with sea salt and black pepper and let the fat render out and the chicken get golden for 15 minutes, turning regularly. Meanwhile, trim the spring onions and halve across the middle, putting the white halves aside. Deseed the chillies, then finely slice lengthways with the green spring onions and pop both into a bowl of ice-cold water to curl and crisp up. Peel the oranges, finely slice into rounds, and arrange on your plates.","Remove the crispy skin, then toss the white spring onions into the pan. In a bowl, loosen the hoisin with a splash of red wine vinegar, then brush half of it all over the chicken. Cook for a final 5 minutes. Drain and divide up the crunchy salad, sit the chicken and soft spring onions on top, drizzle the remaining hoisin over the chicken and crack over the crispy skin.","HERBY CHICKEN TRAYBAKE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('herby-chicken-traybake','Herby Chicken Traybake','5-ingredient recipe: Herby Chicken Traybake',NULL,'easy',20,NULL,20,2,NULL,0,0,0,1,0,'chicken',1,0.943,5,1,'[{"name":"potatoes","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"chicken legs","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"garlic","quantity":6,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"fresh rosemary","quantity":2,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Preheat the oven to 180°C/350°F/gas 4. Scrub the potatoes, slice just under ½cm thick, and place in a 25cm × 30cm roasting tray with the chicken, ½ a tablespoon of olive oil and a pinch of sea salt and black pepper. Lightly squash and add the unpeeled garlic cloves, toss well, then arrange the spuds in a fairly even layer. Sit the chicken legs directly on the bars of the oven, skin side up, with the tray of potatoes directly underneath. Bake for 40 minutes.","When the time’s up, mix up the potatoes in the tasty tray juices, then sit the chicken on top. Strip the rosemary leaves off the sprigs, use a speed-peeler to peel strips of lemon zest, then toss both in 1 teaspoon of olive oil and sprinkle into the tray. Squeeze over half the lemon juice, then return to the oven for a final 10 minutes, or until the chicken is tender and super-golden.","FISH","SMOKY CHORIZO SALMON","CRAZY SIMPLE FISH PIE","SIZZLING SEARED SCALLOPS","QUICK ASIAN FISHCAKES","CRISPY SQUID & SMASHED AVO","SEARED SESAME TUNA","SO EASY FISH CURRY","CRISPY SKIN LEMON SOLE","CREAMY CORNISH MUSSELS","SMOKY PANCETTA COD","ASIAN TUNA STEAK SALAD","STICKY MANGO PRAWNS","ONE-PAN FABULOUS FISH","THAI-STYLE CRISPY SEA BASS","SPEEDY SPICED PRAWN SOUP","SMOKY CHORIZO SALMON"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crazy-simple-fish-pie','Crazy Simple Fish Pie','5-ingredient recipe: Crazy Simple Fish Pie',NULL,'easy',28,NULL,28,4,NULL,0,0,1,0,1,'fish',2,0.967,5,1,'[{"name":"undyed smoked haddock","quantity":400,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"bunches of spring onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"baby spinach","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Cheddar cheese","quantity":150,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"sheets of filo pastry","quantity":4,"unit":"","unit_norm":"","category":"pantry"}]','["Preheat the oven to 200°C/400°F/gas 6. In a bowl, cover the fish with boiling kettle water. Put aside to soak while you trim and roughly chop the spring onions, placing them into a 30cm non-stick ovenproof frying pan on a high heat with 1 tablespoon of olive oil. Stir and fry for 2 minutes, then pile the spinach on top, let it wilt down and turn the heat off.","Spoon 100ml of the soaking water over the spinach, then drain the fish, break up the pieces and sit them evenly around the pan. Finely grate over most of the cheese and season well with black pepper. Quickly layer the filo on top, tucking it around the fish and up the sides of the pan, tearing the last sheet on top in a nutty fashion. Grate over the last bit of cheese, drizzle with ½ a tablespoon of olive oil, and bake for 15 to 17 minutes, or until golden and crisp. Easy as pie!","SIZZLING SEARED SCALLOPS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sizzling-seared-scallops','Sizzling Seared Scallops','5-ingredient recipe: Sizzling Seared Scallops',NULL,'easy',18,NULL,18,2,NULL,0,0,1,1,0,'fish',3,0.863,5,0,'[{"name":"potatoes","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"frozen peas","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"bunch of fresh mint","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"8 raw king scallops","quantity":6,"unit":"","unit_norm":"","category":"seafood"},{"name":"firm black pudding","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"}]','["Wash the potatoes, chop into 3cm chunks and cook in a pan of boiling salted water for 12 minutes, or until tender, adding the peas for the last 3 minutes. Meanwhile, pick and finely chop most of the mint leaves and put aside. Place a non-stick frying pan on a medium-high heat. Once hot, put 1 tablespoon of olive oil and the remaining mint leaves in to crisp up for 1 minute, then scoop the leaves on to a plate, leaving the oil behind. Season the scallops with sea salt and black pepper and fry for 2 minutes on each side, or until golden. Crumble in the black pudding (discarding the skin) so it crisps up alongside.","Drain the peas and potatoes, return to the pan, mash well with the chopped mint and 1 tablespoon of extra virgin olive oil, taste and season to perfection. Plate up with the scallops and black pudding, drizzle lightly with extra virgin olive oil, and sprinkle over the crispy mint.","QUICK ASIAN FISHCAKES","1 stick of lemongrass","6cm piece of ginger","½ a bunch of fresh coriander (15g)","500g salmon fillets, skin off, pin-boned","4 teaspoons chilli jam","Whack the lemongrass against your work surface and remove the tough outer layer. Peel the ginger, then very finely chop with the inside of the lemongrass and most of the coriander, stalks and all, reserving a few nice leaves in a bowl of cold water. Chop the salmon into 1cm chunks over the mix on your board, then push half the salmon to one side. Chop the rest until super-fine, almost like a purée, then mix the chunkier bits back through it and season with sea salt and black pepper. Divide into 4, then shape and squash into 2cm-thick patties.","Place a large non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil. Cook the patties for 2 minutes on each side, or until nicely golden. Spoon the chilli jam over the fishcakes, add a splash of water to the pan, turn the heat off, and jiggle to coat. Serve sprinkled with the drained coriander.","CRISPY SQUID & SMASHED AVO"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-squid-smashed-avo','Crispy Squid & Smashed Avo','5-ingredient recipe: Crispy Squid & Smashed Avo',NULL,'easy',20,NULL,20,2,NULL,0,0,1,1,0,'fish',3,1,5,0,'[{"name":"squid","quantity":250,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"heaped tablespoons wholemeal flour","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"ripe avocado","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"limes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"hot chilli sauce","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"produce"}]','["Pour 1cm of olive oil into a large non-stick frying pan on a medium-high heat and leave to get hot – keep an eye on it. Meanwhile, slice the squid tubes into 1cm rings, then toss all the squid with the flour and a pinch of sea salt and black pepper until well coated. Halve and destone the avocado, then scoop the flesh into a bowl. Finely grate in the zest of 1 lime, squeeze in the juice, and mash until smooth. Taste, season to perfection, and divide between two plates.","To test if the oil is hot enough, carefully drop a piece of squid into the pan – if it sizzles and turns golden, it’s ready. Piece by piece, gently place the rest of the squid in the hot oil and cook, turning with tongs, until golden all over (work in batches, if you need to). Remove to a plate lined with kitchen paper to drain, then plate up over the avo. Drizzle over the chilli sauce and a little extra virgin olive oil, and serve with lime wedges, for squeezing over.","SEARED SESAME TUNA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('seared-sesame-tuna','Seared Sesame Tuna','5-ingredient recipe: Seared Sesame Tuna',NULL,'easy',10,NULL,10,2,NULL,0,0,1,1,0,'fish',4,1,5,0,'[{"name":"heaped tablespoon miso paste","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"tuna steaks","quantity":2,"unit":"","unit_norm":"","category":"seafood"},{"name":"sesame seeds","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"spring onions","quantity":8,"unit":"","unit_norm":"","category":"produce"},{"name":"sugar snap peas","quantity":150,"unit":"g","unit_norm":"g","category":"produce"}]','["Place a large non-stick frying pan on a medium-high heat. Rub the miso all over the tuna, then pat on the sesame seeds to cover. Place in the hot pan with 1 tablespoon of olive oil and sear for 1½ minutes on each side, so it’s beautifully golden on the outside but blushing in the middle. Remove to a board to rest. Quickly wipe out the pan with a ball of kitchen paper, then return to the heat.","Trim the spring onions and slice at an angle the same length as the sugar snaps, tossing both into the hot pan with a few drips of red wine vinegar and a pinch of sea salt for 2 minutes to lightly catch and char. Slice the sesame tuna and serve on top of the veg, drizzled with 1 teaspoon of extra virgin olive oil.","SO EASY FISH CURRY"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crispy-skin-lemon-sole','Crispy Skin Lemon Sole','5-ingredient recipe: Crispy Skin Lemon Sole',NULL,'easy',20,NULL,20,2,NULL,0,1,0,1,0,'none',2,1,3,0,'[{"name":"artichoke hearts in oil","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"mixed-colour courgettes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"}]','["2 × 200g sides of flat white fish, such as lemon sole, skin on, scaled","1–2 fresh mixed-colour chillies","Preheat the grill to high. Scoop out the artichokes, halve lengthways and place in a large non-stick ovenproof frying pan on a medium heat with 1 tablespoon of oil from their jar. Quarter the courgettes lengthways, cut out the core, slice them at an angle the same size as the artichokes and add to the pan. Cook for 10 minutes, stirring regularly. Finely slice the top leafy half of the mint, tossing half into the pan with a splash of water.","Rub the sole with a little olive oil, sea salt and black pepper, then lay skin side up on the veg. Place the pan directly under the grill for 7 to 10 minutes, or until the skin is wonderfully crisp – keep an eye on it! Meanwhile, finely slice the chillies, mix as much as you dare with the remaining mint, 2 tablespoons of red wine vinegar and 1 tablespoon of extra virgin olive oil, then taste and season to perfection. Plate up the veg and sole, pulling back half the crispy skin to expose the fish, then drizzle over the chilli mint dressing.","CREAMY CORNISH MUSSELS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('creamy-cornish-mussels','Creamy Cornish Mussels','5-ingredient recipe: Creamy Cornish Mussels',NULL,'easy',12,NULL,12,2,NULL,0,1,0,0,1,'fish',2,1,5,0,'[{"name":"mussels","quantity":600,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"fresh chives","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"Cornish cider","quantity":250,"unit":"ml","unit_norm":"ml","category":"produce"},{"name":"clotted cream","quantity":50,"unit":"g","unit_norm":"g","category":"dairy"}]','["Check the mussels – if any are open, give them a tap and they should close; if they don’t, discard them. Peel and finely slice the garlic. Finely chop the chives.","Put a large deep pan on a high heat. Pour in 1 tablespoon of olive oil, then add the garlic and most of the chives, followed 1 minute later by the cider. Bring to a fast boil, then add the mussels and clotted cream, cover and leave for 3 to 4 minutes, shaking the pan occasionally. When all the mussels have opened and are soft and juicy, they’re ready. If any remain closed, discard them.","Taste the sauce, season to perfection with sea salt and black pepper, then dish up and sprinkle over the remaining chives before tucking in.","SMOKY PANCETTA COD"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('asian-tuna-steak-salad','Asian Tuna Steak Salad','5-ingredient recipe: Asian Tuna Steak Salad',NULL,'easy',10,NULL,10,2,NULL,0,0,0,1,0,'fish',4,1,5,0,'[{"name":"radishes","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"heaped teaspoons pickled ginger","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"low-salt soy sauce","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"frozen soya beans","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"tuna steaks","quantity":2,"unit":"","unit_norm":"","category":"seafood"}]','["Finely chop 2 radishes with the pickled ginger, then dress with the soy, 1 tablespoon of extra virgin olive oil and 2 teaspoons of water and put aside. Very finely slice the remaining radishes with their leaves.","Place the beans in a non-stick frying pan on a high heat, cover with boiling kettle water, boil for 2 minutes, then drain. Return the pan to a medium-high heat. Rub the tuna with 1 teaspoon of olive oil and a pinch of sea salt and black pepper, then sear for 1½ minutes on each side, so it’s blushing in the middle.","Divide the beans and radishes between your plates, half-tear the tuna and place proudly on top, then spoon over the pickled ginger mixture, drizzling all the juices around the plate. Finish with 1 teaspoon of extra virgin olive oil.","STICKY MANGO PRAWNS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sticky-mango-prawns','Sticky Mango Prawns','5-ingredient recipe: Sticky Mango Prawns',NULL,'easy',20,NULL,20,2,NULL,0,0,1,1,0,'fish',4,1,5,0,'[{"name":"large raw shell-on king prawns","quantity":300,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"garlic","quantity":6,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"curry powder","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"heaped tablespoon mango chutney","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"lime","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Quickly pull the legs and tails off the prawns and peel off the shells, leaving the heads on for bonus flavour. Run the tip of your knife down their backs and pull out the vein. Put a large non-stick frying pan on a medium heat. Peel and very finely slice the garlic, fry with 1 tablespoon of olive oil until crisp, then scoop out and put aside, leaving the garlicky oil behind.","Stir the curry powder into the oil, then add the prawns. Fry for 4 minutes, or until the prawns are cooked through, tossing regularly. Stir in the mango chutney for 30 seconds, taste, season to perfection with sea salt and black pepper, then dish up. Scatter over the crispy garlic, finely grate over half the lime zest and serve with lime wedges, for squeezing over.","ONE-PAN FABULOUS FISH"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('one-pan-fabulous-fish','One-Pan Fabulous Fish','5-ingredient recipe: One-Pan Fabulous Fish',NULL,'easy',15,NULL,15,4,NULL,0,0,1,1,0,'fish',2,1,4,1,'[{"name":"white basmati rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"heaped teaspoons green olive tapenade","quantity":6,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe mixed-colour cherry tomatoes","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"bunch of fresh basil","quantity":0.5,"unit":"","unit_norm":"","category":"produce"}]','["500g white fish fillets, such as haddock, skin off, pin-boned","In a large shallow casserole pan on a high heat, mix the rice with 2 heaped teaspoons of tapenade, then pour over 600ml of water. Put the lid on and let it come to the boil while you halve the tomatoes and, in a bowl, mix them with 1 tablespoon each of olive oil and red wine vinegar. Taste, season to perfection with sea salt and black pepper, and tear in most of the basil leaves.","Cut the fish into four equal-sized pieces and place in the pan, pushing them into the rice. Scatter over the dressed tomatoes. Put the lid back on and boil for 10 minutes, or until the rice is cooked through, then remove the lid and cook for a further 2 minutes until all the liquid has evaporated. Spoon the remaining tapenade over the fish, pick over the remaining basil leaves, drizzle lightly with extra virgin olive oil, and dish up.","THAI-STYLE CRISPY SEA BASS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('thai-style-crispy-sea-bass','Thai-Style Crispy Sea Bass','5-ingredient recipe: Thai-Style Crispy Sea Bass',NULL,'easy',19,NULL,19,2,NULL,0,0,1,1,0,'fish',4,1,5,0,'[{"name":"spring onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"bunch of fresh coriander","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"whole sea bass","quantity":2,"unit":"","unit_norm":"","category":"seafood"},{"name":"Thai red curry paste","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"lime","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Trim and halve the spring onions, finely shred lengthways and place in a bowl of ice-cold water to crisp up. Pick in the coriander leaves, reserving the stalks.","Place a large non-stick frying pan on a medium-high heat. With a sharp knife, score the sea bass skin at 2cm intervals, then rub all over with the curry paste, inside and out, getting into all the cracks and crannies. Pack the coriander stalks into the cavities, season with sea salt and black pepper, then place in the hot pan with 1 tablespoon of olive oil. Cook for 3 to 4 minutes per side, or until dark golden and cooked through (depending on the thickness of your fish).","Drain and shake off the spring onions and coriander and pile on to your plates. Sit the sea bass on top, spooning over any spicy oil from the pan. Finely grate over the lime zest, and serve with lime halves, for squeezing over.","SPEEDY SPICED PRAWN SOUP"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('speedy-spiced-prawn-soup','Speedy Spiced Prawn Soup','5-ingredient recipe: Speedy Spiced Prawn Soup',NULL,'easy',20,NULL,20,4,NULL,0,0,1,1,0,'fish',4,0.943,5,1,'[{"name":"small frozen cooked peeled prawns","quantity":250,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"basmati rice","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"spring onions","quantity":8,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoons korma curry paste","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"light coconut milk","quantity":1,"unit":"tin","unit_norm":"tin","category":"pantry"}]','["Place the prawns in a bowl of cold water so they start to defrost. Meanwhile, dry fry and toast the rice for 3 minutes in a large shallow casserole pan on a high heat, stirring regularly, while you trim and finely slice the spring onions. Add 1 tablespoon of olive oil, the spring onions and korma paste to the pan. Stir for 2 minutes, then pour in the coconut milk and 2½ tins’ worth of water. Boil for 12 minutes, stirring everything occasionally.","With 6 minutes to go, drain the prawns, finely chop and stir into the soup. When the rice is cooked through and the soup is your desired consistency, taste, season to utter perfection with sea salt and black pepper, and dish up.","VEG","POTATO & ARTICHOKE AL FORNO","GNARLY GARLIC BRUSSELS","SPICED WHOLE ROAST CAULI","SPEEDY SPINACH CURRY","ASPARAGUS, EGGS & FRENCH DRESSING","BAKED GARLICKY MUSHROOMS","EASY RUSTIC GNOCCHI","AMAZING DRESSED BEETS","PAPPA AL POMODORO SOUP","CAJUN SWEET POTATOES","PEAS, BEANS, CHILLI & MINT","STICKY TERIYAKI AUBERGINE","POTATO & ARTICHOKE AL FORNO"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('gnarly-garlic-brussels','Gnarly Garlic Brussels','5-ingredient recipe: Gnarly Garlic Brussels',NULL,'easy',16,NULL,16,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"Brussels sprouts","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"shelled unsalted pistachios","quantity":30,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"pomegranate","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoons cottage cheese","quantity":2,"unit":"","unit_norm":"","category":"dairy"}]','["Trim the sprouts, discard any tatty outer leaves, then cut in half. Place cut side down in a single layer in a large dry non-stick frying pan on a high heat, and char for 5 minutes. Meanwhile, peel and finely slice the garlic. Crush the pistachios in a pestle and mortar. Halve the pomegranate, squeeze the juice of one half through a sieve into a bowl, then hold the other half cut side down in your fingers and bash the back of it with a spoon so all the seeds tumble out. Stir the sliced garlic into the sprouts with 1 tablespoon of olive oil and a couple of splashes of water, then cook for 1 more minute.","Divide the cottage cheese between your plates, spoon the gnarly sprouts on top, then sprinkle over the pomegranate seeds and pistachios. Drizzle over the pomegranate juice and 1 tablespoon of extra virgin olive oil, sprinkle with a pinch of sea salt and black pepper from a height, and serve. Delicious.","SPICED WHOLE ROAST CAULI"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('speedy-spinach-curry','Speedy Spinach Curry','5-ingredient recipe: Speedy Spinach Curry',NULL,'easy',16,NULL,16,2,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"unsalted cashew nuts","quantity":20,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"rogan josh curry paste","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"paneer cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"baby spinach","quantity":200,"unit":"g","unit_norm":"g","category":"produce"}]','["Put a large non-stick frying pan on a medium-high heat and toast the cashew nuts as it heats up, shaking the pan occasionally until lightly golden. Tip the cashews into a pestle and mortar, returning the pan to the heat.","Peel and finely slice the onion and place in the hot pan with 1 tablespoon of olive oil and the curry paste. Cook and stir for 8 minutes, then add 1 tablespoon of red wine vinegar. Let the vinegar cook away for 30 seconds, dice and add the paneer, then the spinach. Stir until the spinach wilts and all the liquid evaporates, then taste and season to perfection with sea salt and black pepper. Crush the cashew nuts and sprinkle over the top before serving. Yum.","ASPARAGUS, EGGS & FRENCH DRESSING"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('asparagus-eggs-french-dressing','Asparagus, Eggs & French Dressing','5-ingredient recipe: Asparagus, Eggs & French Dressing',NULL,'easy',15,NULL,15,2,NULL,0,0,0,1,0,'none',2,1,5,1,'[{"name":"small red onion","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"asparagus","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"bunch of fresh tarragon","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"heaped teaspoons Dijon mustard","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Peel and very finely chop the red onion, place in a bowl, cover with 4 tablespoons of red wine vinegar and add a very good pinch of sea salt. Lower the eggs into a pan of vigorously simmering water and boil for 5½ minutes exactly. Line up the asparagus, trim off the woody ends, and place in a colander above the eggs, covered, to steam while the eggs cook. Meanwhile, pick the tarragon leaves.","In a bowl, whisk the mustard with 6 tablespoons of extra virgin olive oil, adding it gradually, then pour in the soaking vinegar from the onion through a sieve, whisking constantly. Taste and season to perfection with black pepper.","When the time’s up on the eggs, divide the asparagus between your plates. Refresh the eggs under cold water until cool enough to handle, then peel, halve and plate up, sprinkled with the tarragon leaves and onion. Drizzle each plate with 1 tablespoon of dressing (save the rest for another day), season from a height with a pinch of pepper, and dig in.","BAKED GARLICKY MUSHROOMS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('baked-garlicky-mushrooms','Baked Garlicky Mushrooms','5-ingredient recipe: Baked Garlicky Mushrooms',NULL,'easy',30,NULL,30,2,NULL,0,1,0,0,1,'none',3,0.967,5,1,'[{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"bunch of fresh sage","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"ripe mixed-colour cherry tomatoes","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"large portobello mushrooms","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Cheddar cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 200°C/400°F/gas 6. Peel and very finely slice the garlic. Pick the sage leaves. Halve the cherry tomatoes. Peel the mushrooms, reserving the peel. Place it all (peel included) in a 25cm × 30cm roasting tray and drizzle with 1 tablespoon each of olive oil and red wine vinegar. Add a pinch of sea salt and black pepper and toss together. Pick out 12 perfect garlic slices and sage leaves for later, and sit the mushrooms stalk side up on the top. Bake for 10 minutes.","Remove the tray from the oven, crumble the cheese into the mushroom cups and sprinkle over the reserved garlic and sage. Return to the oven for 15 more minutes, or until the cheese is melted and everything’s golden, then dish up.","EASY RUSTIC GNOCCHI"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('easy-rustic-gnocchi','Easy Rustic Gnocchi','5-ingredient recipe: Easy Rustic Gnocchi',NULL,'easy',30,NULL,30,2,NULL,0,1,0,0,1,'none',4,0.887,5,0,'[{"name":"floury potatoes","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"asparagus","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"plain flour","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"bunch of fresh thyme","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"Parmesan cheese","quantity":50,"unit":"g","unit_norm":"g","category":"dairy"}]','["Wash the potatoes, chop into 3cm chunks and cook in a large pan of boiling salted water for 12 minutes, or until tender. Meanwhile, line up the asparagus, trim off the woody ends, then slice the stalks 1cm thick, leaving the tips whole.","Drain the potatoes and steam dry for 2 minutes, then return to the pan and mash well. Taste and season to perfection with sea salt and black pepper, then tip on to a clean work surface. Fill the empty pan with boiling kettle water and place on a high heat. Use your hands to scrunch the flour with the potato, then divide into 24 pieces. Squeeze each in your palm to compress, into little uneven gnocchi, then drop into the boiling water for 1 minute, or until they float.","Meanwhile, put the asparagus into a large non-stick frying pan on a medium-low heat with 1 tablespoon of olive oil, stirring occasionally. Strip in most of the thyme leaves, then use a slotted spoon to add the gnocchi straight in. Finely grate over most of the Parmesan and toss well, adding 100ml of gnocchi cooking water to emulsify it into a nice sauce. Taste, season to perfection, then dish up. Grate over the remaining Parmesan, strip over the remaining thyme, and finish with a little drizzle of extra virgin olive oil.","AMAZING DRESSED BEETS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pappa-al-pomodoro-soup','Pappa Al Pomodoro Soup','5-ingredient recipe: Pappa Al Pomodoro Soup',NULL,'easy',21,NULL,21,4,NULL,0,1,0,0,1,'none',4,0.887,5,0,'[{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"fresh basil","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"stale ciabatta","quantity":270,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"Parmesan cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Peel and finely slice the garlic, and place in a large pan on a medium heat with 1 tablespoon of olive oil, stirring regularly. Pick the baby basil leaves into a bowl of cold water for later, then pick the rest of the leaves into the pan. Before the garlic starts to colour, add the tomatoes and 2 tins’ worth of water, season with sea salt and black pepper, and bring to the boil, gently mashing the tomatoes.","Tear in the stale bread, stir, then leave to simmer on a low heat for 5 minutes, or until thick and delicious. Finely grate and stir in the Parmesan, then taste and season to perfection. Dish up, sprinkle over the reserved baby basil leaves and drizzle each bowlful with 1 tablespoon of good extra virgin olive oil. Heaven.","CAJUN SWEET POTATOES"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cajun-sweet-potatoes','Cajun Sweet Potatoes','5-ingredient recipe: Cajun Sweet Potatoes',NULL,'easy',20,NULL,20,4,NULL,0,1,0,0,1,'none',1,1,5,0,'[{"name":"sweet potatoes","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"bulb of garlic","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped teaspoon Cajun spice","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"Greek yoghurt","quantity":200,"unit":"ml","unit_norm":"ml","category":"dairy"},{"name":"spring onions","quantity":4,"unit":"","unit_norm":"","category":"produce"}]','["Preheat the oven to 180°C/350°F/gas 4. Quickly scrub the sweet potatoes clean, then slice into 3cm rounds. Place in a 25cm × 30cm roasting tray with the whole unpeeled garlic bulb, and toss with 1 tablespoon each of olive oil and red wine vinegar, a pinch of sea salt and black pepper and the Cajun spice. Arrange in a flat layer and roast for 1 hour, or until soft, gnarly and caramelized.","Once done, squeeze all the soft, sweet, creamy, mild roasted garlic out of the skins into the yoghurt, mash together, then taste and season to perfection. Trim and finely slice the spring onions. Spoon the yoghurt across a plate or platter, stack the sweet potato on top, drizzle with ½ a tablespoon of extra virgin olive oil, sprinkle over the spring onions, dish up and daddy dance.","PEAS, BEANS, CHILLI & MINT"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('peas-beans-chilli-mint','Peas, Beans, Chilli & Mint','5-ingredient recipe: Peas, Beans, Chilli & Mint',NULL,'easy',10,NULL,10,2,NULL,0,1,0,1,0,'none',1,1,5,0,'[{"name":"bunch of fresh mint","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh podded or frozen broad beans","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"fresh podded or frozen peas","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"fresh red chilli","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Rip off and reserve the top leafy half of the mint. Put the stalks in a pan of boiling salted water, then add the beans and peas to cook for 4 minutes. Meanwhile, halve and deseed the chilli and finely chop with the top leafy half of the mint. Place in a bowl, finely grate over a little lemon zest, then squeeze in all the juice. Add 2 tablespoons of extra virgin olive oil, mix, taste and season to perfection with sea salt and black pepper.","Drain the beans and peas, reserving a mugful of cooking water and discarding the mint stalks. Pinch the skins off any larger beans, then pour the beans and peas on to a platter, toss with a few splashes of reserved cooking water, then spoon over the dressing. Drizzle with 1 more tablespoon of extra virgin olive oil and toss together at the table before tucking in.","STICKY TERIYAKI AUBERGINE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sticky-teriyaki-aubergine','Sticky Teriyaki Aubergine','5-ingredient recipe: Sticky Teriyaki Aubergine',NULL,'easy',20,NULL,20,2,NULL,0,1,0,1,0,'none',2,0.863,5,0,'[{"name":"large aubergine","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"spring onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh red or yellow chilli","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"unsalted peanuts","quantity":20,"unit":"g","unit_norm":"g","category":"produce"},{"name":"teriyaki sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Put a 26cm non-stick frying pan on a high heat and pour in 250ml of water. Halve the aubergine lengthways, quickly slash the skin of each half a few times and place skin side up in the pan, then season with sea salt and black pepper. Cover and cook for 10 minutes, or until it boils dry and begins to sizzle (listen for the change in sound). Meanwhile, trim the spring onions. Cut the whites into 3cm lengths at an angle and put aside. Deseed the chilli and finely slice lengthways with the green part of the spring onions. Place both in a bowl of ice-cold water and put aside to crisp up.","When the aubergine starts to sizzle, add 1 tablespoon of olive oil, the white spring onion and the peanuts to the pan, stirring regularly. After 2 minutes, add a splash of water, drizzle in the teriyaki and reduce to a medium heat. Turn the aubergine, jiggle the pan and let it get sticky for a few minutes, then dish up, sprinkled with the drained green spring onion and chilli.","BEEF","EPIC RIB-EYE STEAK","GINGER SHAKIN’ BEEF","SIZZLING SIRLOIN","ITALIAN SEARED BEEF","MESSY MEATBALL BUNS","STEAK SANDWICH","BANGIN’ BEEF STEW","DUKKAH BEEF CARPACCIO","MELTIN’ MUSTARDY BEEF","LIVER, BACON & ONIONS","RENDANG BEEF & CAULI RICE","QUICK STEAK STIR-FRY","EPIC RIB-EYE STEAK"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('ginger-shakin-beef','Ginger Shakin’ Beef','5-ingredient recipe: Ginger Shakin’ Beef',NULL,'easy',16,NULL,16,2,NULL,0,0,0,1,0,'beef',4,1,5,0,'[{"name":"sirloin steak","quantity":300,"unit":"g","unit_norm":"g","category":"meat"},{"name":"cm piece of ginger","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"miso paste","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"runny honey","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"pak choi","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Pull the fat off the sirloin, finely slice the fat and place it in a cold non-stick frying pan. Put on a medium-high heat to crisp up while you peel and matchstick the ginger, then add that to crisp up, too. Cut off the sinew, then dice the steak into 3cm chunks and toss with the miso until well coated. Scoop the crispy fat and ginger out and put aside, then add the steak chunks to the pan. Cook for 4 minutes, tossing regularly, then drizzle in the honey and 1 tablespoon of red wine vinegar. Toss for 1 more minute until shiny and sticky.","Meanwhile, halve the pak choi, cook in a pan of boiling water for just 1 minute so they retain a bit of crunch, then drain well and plate up. Spoon over the steak and sticky juices from the pan, and finish with the reserved crispy bits.","SIZZLING SIRLOIN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sizzling-sirloin','Sizzling Sirloin','5-ingredient recipe: Sizzling Sirloin',NULL,'easy',30,NULL,30,2,NULL,0,0,0,1,0,'beef',4,0.887,5,0,'[{"name":"large aubergines","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"sirloin steak","quantity":300,"unit":"g","unit_norm":"g","category":"meat"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"ripe mixed-colour cherry tomatoes","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"bunch of fresh basil","quantity":0.5,"unit":"","unit_norm":"","category":"produce"}]','["Prick the aubergines, then microwave in a covered bowl on high for 10 minutes, or until soft. Meanwhile, pull the fat off the sirloin and place the fat in a large cold non-stick frying pan. Put on a medium-high heat to render as it heats up, moving it around to coat the pan, while you cut off the sinew, then rub the steak with a pinch of sea salt and black pepper. Peel and finely slice the garlic, and halve the tomatoes.","Sear the steak in the hot pan for 2 minutes on each side for medium, or to your liking, then remove to a plate to rest, discarding the piece of fat. Sprinkle the garlic straight into the pan. Discard the aubergine stalks, chop up the flesh and add to the pan with any tasty juices, then toss in the tomatoes for 2 minutes. Tear in most of the basil leaves, stir in 1 tablespoon of red wine vinegar, taste and season to perfection, and plate up.","Slice the steak, place on top, pick over the remaining basil, then drizzle with 1 teaspoon of extra virgin olive oil and the resting juices.","ITALIAN SEARED BEEF"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('italian-seared-beef','Italian Seared Beef','5-ingredient recipe: Italian Seared Beef',NULL,'easy',10,NULL,10,2,NULL,0,0,0,0,1,'beef',4,1,5,0,'[{"name":"pine nuts","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"rump steak","quantity":250,"unit":"g","unit_norm":"g","category":"meat"},{"name":"heaped teaspoons green pesto","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"rocket","quantity":40,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Parmesan cheese","quantity":15,"unit":"g","unit_norm":"g","category":"dairy"}]','["Put a large non-stick frying pan on a high heat, toasting the pine nuts as it heats up, tossing regularly and removing when golden. Cut the fat off the rump, finely chop the fat and place in the pan to render and crisp up while you cut the sinew off the rump, then season it with sea salt and black pepper. Place between two sheets of greaseproof paper and bash to 1cm thick with a rolling pin, also tenderizing the meat. Scoop out and reserve the crispy bits of fat, then sear the steak in the hot pan for 1 minute on each side, until golden but still blushing in the middle. Remove to a board.","Spread the pesto over a sharing platter. Thinly slice the steak at an angle, then plate up. Pile the rocket on top, then scatter over the pine nuts and reserved crispy fat, if you like. Mix the steak resting juices with 1 tablespoon of extra virgin olive oil and drizzle over. Shave over the Parmesan, tossing before serving.","MESSY MEATBALL BUNS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('messy-meatball-buns','Messy Meatball Buns','5-ingredient recipe: Messy Meatball Buns',NULL,'easy',21,NULL,21,4,NULL,0,0,0,0,1,'beef',4,0.887,5,0,'[{"name":"lean minced beef","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"heaped teaspoons green pesto","quantity":8,"unit":"","unit_norm":"","category":"pantry"},{"name":"plum tomatoes","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"},{"name":"ball of mozzarella","quantity":1,"unit":"","unit_norm":"","category":"dairy"},{"name":"soft burger buns","quantity":4,"unit":"","unit_norm":"","category":"pantry"}]','["Use your clean hands to scrunch the minced beef with half the pesto and a pinch of sea salt and black pepper. Split into 12 pieces and, with wet hands, roll into balls. Brown the balls all over in a non-stick frying pan on a high heat with 1 tablespoon of olive oil, shaking the pan regularly.","Once the balls are golden and gnarly, pour in the tomatoes, breaking them up with a wooden spoon, along with just a quarter of a tin’s worth of water. Bring to the boil, slice the mozzarella and lay over the balls, pop the lid on and leave to thicken for 5 minutes on a medium heat. Meanwhile, warm your buns in a large dry non-stick frying pan or in the oven on a low heat.","Split each bun and spread 1 heaped teaspoon of pesto inside. Divvy up the balls and mozzarella with a little sauce, serving the rest on the side for dunking.","STEAK SANDWICH"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('steak-sandwich','Steak Sandwich','5-ingredient recipe: Steak Sandwich',NULL,'easy',14,NULL,14,2,NULL,0,0,0,0,1,'beef',4,1,5,0,'[{"name":"sirloin steak","quantity":250,"unit":"g","unit_norm":"g","category":"meat"},{"name":"large onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"American mustard","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"nice bread","quantity":4,"unit":"slices","unit_norm":"slices","category":"pantry"},{"name":"provolone or fontina cheese","quantity":50,"unit":"g","unit_norm":"g","category":"dairy"}]','["Pull the fat off the sirloin, finely slice the fat and place it in a large cold non-stick frying pan. Put on a medium-high heat to render as it heats up, moving it around to coat the pan, while you peel and slice the onion into 1cm-thick rounds. Add them to the pan to char for 10 minutes, turning halfway. Meanwhile, cut off the sinew, then place the steak between two sheets of greaseproof paper and pound with your fist until just under 1cm thick. Sprinkle with a pinch of sea salt and black pepper, then brush all over with the mustard and cut into two.","Add a good splash of red wine vinegar to the onion, toss for 1 minute over the heat, then divide between two slices of bread, leaving the pan on the heat. Sear the steaks in the screaming hot pan for just 40 seconds on each side, then slice and lay over the cheese, cover, turn the heat off and leave to melt for just 40 seconds more. Lay the steak on top of the onion, pop the other slices of bread on top, drizzle with a little extra virgin olive oil, and devour.","BANGIN’ BEEF STEW"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bangin-beef-stew','Bangin’ Beef Stew','5-ingredient recipe: Bangin’ Beef Stew',NULL,'easy',20,NULL,20,4,NULL,0,0,0,1,0,'beef',3,1,5,1,'[{"name":"mixed-colour peppers","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped teaspoon allspice","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"lean stewing beef","quantity":600,"unit":"g","unit_norm":"g","category":"meat"},{"name":"fresh bay leaves","quantity":10,"unit":"","unit_norm":"","category":"pantry"},{"name":"garlic","quantity":8,"unit":"clove","unit_norm":"clove","category":"produce"}]','["Preheat the oven to 160°C/325°F/gas 3. Place a large shallow casserole pan on a high heat. Deseed the peppers and chop into fingers, then place in the pan with 1 tablespoon of olive oil, a pinch of sea salt and black pepper and the allspice. Chop the beef a similar size and stir into the pan with the bay. Crush in the unpeeled garlic through a garlic crusher and fry for 2 minutes, tossing regularly.","Add 2 tablespoons of red wine vinegar and 500ml of water to the pan. Cover, then cook in the oven for 2 hours, or until dark and sticky. Loosen with a splash of water, if needed, mix up, taste, season to perfection, and serve.","DUKKAH BEEF CARPACCIO"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('dukkah-beef-carpaccio','Dukkah Beef Carpaccio','5-ingredient recipe: Dukkah Beef Carpaccio',NULL,'easy',12,NULL,12,4,NULL,0,0,0,1,0,'beef',4,1,5,0,'[{"name":"piece of fillet steak","quantity":500,"unit":"g","unit_norm":"g","category":"meat"},{"name":"radishes","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"pomegranate","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"preserved lemons","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoon dukkah","quantity":1,"unit":"","unit_norm":"","category":"pantry"}]','["Rub the steak all over with ½ a tablespoon of olive oil and a pinch of sea salt and black pepper. Get a non-stick frying pan hot on a high heat, then sear the steak on all sides for 3 minutes in total. Remove to a board.","Finely slice the radishes, reserving any nice leaves. Halve the pomegranate and holding one half cut side down in your fingers, bash the back of it with a spoon so all the seeds tumble out into a bowl. Squeeze the juice from the remaining half through a sieve into a separate bowl. Quarter the preserved lemons and trim away the seedy core. Finely chop the rind and add to the pomegranate juice with 1 tablespoon each of extra virgin olive oil and red wine vinegar, then taste and season to perfection.","Slice the steak as finely as you can, then use the side of your knife to flatten and stretch out each slice. Divide between your plates, sprinkle over the radishes and leaves, then spoon over the dressing. Scatter over the dukkah and pomegranate seeds, then finish with a drizzle of extra virgin olive oil.","MELTIN’ MUSTARDY BEEF"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('liver-bacon-onions','Liver, Bacon & Onions','5-ingredient recipe: Liver, Bacon & Onions',NULL,'easy',15,NULL,15,1,NULL,0,0,0,1,0,'pork',2,1,5,0,'[{"name":"red onion","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh sage","quantity":2,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"sourdough bread","quantity":1,"unit":"slice","unit_norm":"slice","category":"pantry"},{"name":"smoked streaky bacon","quantity":1,"unit":"rasher","unit_norm":"rasher","category":"meat"},{"name":"slice of calves’ liver","quantity":125,"unit":"g","unit_norm":"g","category":"pantry"}]','["Peel and very finely slice the red onion. Place in a large non-stick frying pan on a medium-high heat with 1 teaspoon of olive oil. Reserving 2 nice leaves, pick, finely slice and add the rest of the sage. Cook for 5 minutes, tossing regularly.","Push the onions to one side, and add the bread and bacon to the pan. As soon as they crisp up, flip them over. Drizzle the soft, golden onions with a little red wine vinegar, toss with tongs, then move them on top of the bread, so they don’t catch. Once the bacon is golden, move that on top of the onions.","Lightly season the liver, then add to the pan to sear for just 1 minute on each side, so it’s golden on the outside, blushing in the middle. Add the 2 reserved sage leaves alongside, with 1 teaspoon of olive oil to crisp them up, then serve.","RENDANG BEEF & CAULI RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('rendang-beef-cauli-rice','Rendang Beef & Cauli Rice','5-ingredient recipe: Rendang Beef & Cauli Rice',NULL,'easy',24,NULL,24,4,NULL,0,0,0,1,0,'beef',3,0.967,5,1,'[{"name":"lean minced beef","quantity":500,"unit":"g","unit_norm":"g","category":"meat"},{"name":"cauliflower","quantity":1,"unit":"head","unit_norm":"head","category":"produce"},{"name":"heaped teaspoon rendang powder","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"fresh mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"light coconut milk","quantity":1,"unit":"tin","unit_norm":"tin","category":"pantry"}]','["Place the minced beef in a large shallow casserole pan with 1 tablespoon of olive oil, then break it up and fry on a high heat, stirring regularly. Click off and discard any tatty outer leaves from the cauliflower, putting the nice leaves into a food processor. Halve the cauliflower, breaking up one half into the processor. Cut little bite-sized florets off the other half into the mince pan, chucking all the stalks into the processor as you go. Stir the rendang powder into the pan and cook it all for 10 minutes, or until crispy, stirring regularly.","Meanwhile, pick half the mint leaves into the processor, add a pinch of sea salt and black pepper, and blitz until fine. Tip into a heatproof bowl, cover, and microwave on high for 4 to 5 minutes. Reserving the baby leaves, pick the remaining mint leaves into the pan, toss well, then pour in the coconut milk and half a tin’s worth of water. Bring to the boil, simmer for 5 minutes, then taste, season to perfection, and scatter over the reserved mint leaves. Give the cauli rice a good mix up, and serve on the side.","QUICK STEAK STIR-FRY"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('quick-steak-stir-fry','Quick Steak Stir-Fry','5-ingredient recipe: Quick Steak Stir-Fry',NULL,'easy',16,NULL,16,2,NULL,0,0,0,1,0,'beef',4,0.943,5,1,'[{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"cm piece of ginger","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"asparagus","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"fillet steaks","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"black bean sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"}]','["Peel and very finely slice the garlic and ginger. Put into a large cold non-stick frying pan with 1 tablespoon of olive oil, and place on a medium heat, stirring regularly. Once crisp and lightly golden, scoop out of the pan and put aside, leaving the garlicky oil behind. Line up the asparagus spears and trim off the woody ends, then add the spears to the hot pan. Season the steaks with sea salt and black pepper, add alongside the asparagus and turn the heat up to high. Cook for just 3 minutes, turning everything regularly.","Toss in the black bean sauce and 1 tablespoon of red wine vinegar for 1 minute – this will give you medium-rare steaks. Alternatively, cook to your liking. Slice the steaks, dish up, then scatter over the crispy garlic and ginger.","PORK","CRAZY GOOD PORK BURGER","SAUSAGE & APPLE BAKE","PORK & MASH GRATIN","GOLDEN PORK ESCALOPE","PEACHY PORK CHOPS","CHICKPEA CHARD PORK","STICKY PORK STIR-FRY","COMFORTING SAUSAGE BAKE","CRAZY GOOD PORK BURGER"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('crazy-good-pork-burger','Crazy Good Pork Burger','5-ingredient recipe: Crazy Good Pork Burger',NULL,'easy',16,NULL,16,1,NULL,0,0,0,0,1,'pork',2,1,5,1,'[{"name":"ripe sweet pear","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed spinach","quantity":50,"unit":"g","unit_norm":"g","category":"produce"},{"name":"minced pork","quantity":150,"unit":"g","unit_norm":"g","category":"meat"},{"name":"soft burger bun","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"blue cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"}]','["Slice the pear lengthways as finely as you can. Toss gently with the salad leaves, a little drizzle each of extra virgin olive oil and red wine vinegar, and a pinch of black pepper. Scrunch the minced pork in your clean hands with a pinch of seasoning, then shape into a 1cm-thick patty. Rub with 1 teaspoon of olive oil, then place in a large non-stick frying pan on a high heat for 2 minutes, while you halve and toast the bun alongside, removing it when golden.","Flip the burger, then, after 2 minutes, crumble the blue cheese next to it to melt. Move the burger on top of the oozy cheese, jiggle around to coat, then put it on your bun base. Stack in as much pear and salad as the bun will hold, pop the lid on, squash and devour, with any extra salad on the side.","SAUSAGE & APPLE BAKE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sausage-apple-bake','Sausage & Apple Bake','5-ingredient recipe: Sausage & Apple Bake',NULL,'easy',20,NULL,20,4,NULL,0,0,0,1,0,'pork',1,1,5,1,'[{"name":"large red onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"eating apples","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"parsnips","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"chipolatas","quantity":12,"unit":"","unit_norm":"","category":"pantry"},{"name":"runny honey","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Preheat the oven to 180°C/350°F/gas 4. Place a large non-stick ovenproof frying pan on a medium-high heat. Peel the onions, cut into quarters and quickly break apart into petals directly into the pan, tossing regularly, then add 1 tablespoon of olive oil and a pinch of sea salt and black pepper. Quarter and core the apples, then toss into the pan. Use a speed-peeler to peel the parsnips into long strips. Stir 1 tablespoon of red wine vinegar into the frying pan, then pile the parsnip strips on top of the apples and onions.","Lay the sausages on top, then drizzle with 1 tablespoon of olive oil and add a pinch of black pepper from a height. Bake for 30 minutes, then drizzle over the honey and return to the oven for 5 minutes, or until golden and delicious.","PORK & MASH GRATIN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-mash-gratin','Pork & Mash Gratin','5-ingredient recipe: Pork & Mash Gratin',NULL,'easy',30,NULL,30,4,NULL,0,0,0,0,1,'pork',4,0.967,5,1,'[{"name":"potatoes","quantity":800,"unit":"g","unit_norm":"g","category":"produce"},{"name":"piece of pork fillet","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"fresh sage","quantity":2,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"Cheddar cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"prosciutto","quantity":4,"unit":"slices","unit_norm":"slices","category":"meat"}]','["Preheat the grill to high. Wash the potatoes, chop into 3cm chunks, then cook in a large pan of boiling salted water with the lid on for 12 minutes, or until tender. Meanwhile, put a shallow casserole pan on a high heat. Season the pork with sea salt and black pepper, then place in the pan with 1 tablespoon of olive oil and sear for 3 minutes, turning regularly, while you pick the sage leaves. Remove the pork to a plate, toss the sage leaves into the fat in the pan for just 5 seconds, then scoop on to a plate, leaving the pan off the heat to use again.","Drain the spuds, tip into the casserole pan, grate over half the cheese, add 1 tablespoon of extra virgin olive oil and mash well, loosening with a splash of water, if needed. Taste, season to perfection, and spread out to the edges. Grate over the remaining cheese, sit the pork on top, then gratinate under the grill for 10 minutes. Lay the prosciutto around the pork in waves, sprinkle over the crispy sage, then grill for 2 more minutes, or until the pork is cooked to your liking. Rest for 2 minutes, then slice the pork and dish up.","GOLDEN PORK ESCALOPE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('golden-pork-escalope','Golden Pork Escalope','5-ingredient recipe: Golden Pork Escalope',NULL,'easy',16,NULL,16,1,NULL,0,0,0,0,1,'pork',4,1,5,0,'[{"name":"olive bread","quantity":1,"unit":"slice","unit_norm":"slice","category":"produce"},{"name":"fresh oregano","quantity":4,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"pork escalope","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"ripe mixed-colour cherry tomatoes","quantity":100,"unit":"g","unit_norm":"g","category":"produce"},{"name":"feta cheese","quantity":10,"unit":"g","unit_norm":"g","category":"dairy"}]','["Blitz the bread into fine crumbs in a food processor with half the oregano leaves. Place the pork between two sheets of greaseproof paper, then bash and flatten with a rolling pin to ½cm thick. Pat the crumbs on to both sides, then bash again until they stick. Place a large non-stick frying pan on a medium-high heat and, once hot, drizzle in 1 tablespoon of olive oil. Cook the breaded escalope for 3 minutes on each side, or until dark golden.","Meanwhile, halve the tomatoes and pick the remaining oregano leaves. Transfer the escalope to your plate, wipe the pan out with a ball of kitchen paper, then add the tomatoes and remaining oregano with ½ a tablespoon of olive oil and 1 tablespoon of red wine vinegar. Toss for 1 minute, taste, season to perfection with sea salt and black pepper, then dish up and crumble over the feta.","PEACHY PORK CHOPS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('peachy-pork-chops','Peachy Pork Chops','5-ingredient recipe: Peachy Pork Chops',NULL,'easy',28,NULL,28,2,NULL,0,0,0,1,0,'pork',3,0.887,5,0,'[{"name":"pork chops","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"fresh rosemary","quantity":2,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"peach halves in juice","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"},{"name":"bourbon","quantity":50,"unit":"ml","unit_norm":"ml","category":"pantry"}]','["Preheat the grill to high. Slice the rind off the chops, score the fat side of it in a criss-cross fashion and place skin side up in a tray. Pop under the grill for 5 minutes to crisp up into crackling – keep an eye on it. Season the chops with sea salt and black pepper, score the remaining fat in a criss-cross fashion, then sit the chops together fat edges down in a large cold non-stick frying pan. Place on a high heat for 3 to 4 minutes, or until golden and the fat has rendered out, using tongs to ensure they’re in good contact with the pan. Gently turn the chops on to their sides to cook for 5 minutes on each side.","Meanwhile, peel and finely slice the garlic. Strip the rosemary leaves off the sprigs. Remove the chops to a plate, drain 90% of the fat from the pan into a jar to use for cooking another day, then sprinkle the garlic into the pan. Stir regularly until golden, then add the rosemary and four drained peach halves, flat side down. Jiggle over the heat until golden, then return the chops to the pan, add the bourbon and carefully set fire to it with a match (stand back!). Once the flames begin to subside, dish up with the crispy crackling.","CHICKPEA CHARD PORK"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chickpea-chard-pork','Chickpea Chard Pork','5-ingredient recipe: Chickpea Chard Pork',NULL,'easy',29,NULL,29,4,NULL,0,0,0,1,0,'pork',1,0.967,5,1,'[{"name":"piece of pork fillet","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"roasted peeled peppers in brine","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"rainbow chard","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"heaped teaspoon fennel seeds","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"chickpeas","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"}]','["Put a large shallow casserole pan on a high heat. Season the pork with sea salt and black pepper, then place in the pan with 1 tablespoon of olive oil and sear for 5 minutes, turning halfway. Meanwhile, drain the peppers and quickly dice into 1cm chunks, then trim and finely slice the chard, stalks and all.","Remove the pork to a plate, then add the fennel seeds, peppers and all the chard to the pork fat left behind in the pan. Stir and fry for 2 minutes, then pour in the chickpeas and their juice, stir, and bring to the boil. Sit the pork back in so it’s touching the base of the pan, pour over any resting juices, cover, and simmer gently on a medium heat for 12 minutes, or until the pork is just cooked through and it all smells incredible, turning the pork occasionally.","Rest for 2 minutes, slice the pork, season the chickpeas to perfection, adding a splash of red wine vinegar, drizzle with extra virgin olive oil, and serve.","STICKY PORK STIR-FRY"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sticky-pork-stir-fry','Sticky Pork Stir-Fry','5-ingredient recipe: Sticky Pork Stir-Fry',NULL,'easy',18,NULL,18,4,NULL,0,0,0,1,0,'pork',1,1,5,1,'[{"name":"pork shoulder","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"mixed-colour baby heritage carrots","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"spring onions","quantity":8,"unit":"","unit_norm":"","category":"produce"},{"name":"teriyaki sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"runny honey","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Put a large shallow casserole pan on a high heat. Chop the pork into 3cm chunks and place in the pan with 1 tablespoon of olive oil and a pinch of sea salt and black pepper. Trim and add the whole baby carrots (halving any larger ones), then cook for 12 minutes, or until everything is golden, tossing regularly. Meanwhile, trim and slice the spring onions.","Add a splash of water to the pan to deglaze it, then stir in the spring onions, teriyaki sauce and honey. Cook for another 3 minutes, tossing regularly until it’s all shiny and sticky, then taste, season to perfection, and serve.","COMFORTING SAUSAGE BAKE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('comforting-sausage-bake','Comforting Sausage Bake','5-ingredient recipe: Comforting Sausage Bake',NULL,'easy',20,NULL,20,4,NULL,0,0,0,1,0,'pork',1,0.943,5,1,'[{"name":"ripe mixed-colour cherry tomatoes","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"rosemary focaccia","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"white beans","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"chipolatas","quantity":12,"unit":"","unit_norm":"","category":"pantry"}]','["Preheat the oven to 180°C/350°F/gas 4. Halve the cherry tomatoes, peel and finely slice the garlic, and tear the bread into bite-sized chunks. Place it all in a 30cm × 35cm roasting tray, pour in the beans and their juice, drizzle with 1 tablespoon each of olive oil and red wine vinegar, add a splash of water, and mix it all together. Quickly pinch and twist each chipolata in the middle to make it into two mini ones, then randomly dot them around your bake, lightly pressing them into the beans and tomatoes.","Roast for 45 minutes, or until everything is golden, bubbling and delicious.","LAMB","TENDER LAMB SHOULDER","LAMB KOFTA FLATBREADS","LOVELY LAMB HOTPOTS","AROMATIC LAMB CURRY","ALE BARLEY LAMB SHANKS","SPRING LAMB","SUCCULENT LAMB STEW","STICKY LAMB CHOPS","TENDER LAMB SHOULDER"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tender-lamb-shoulder','Tender Lamb Shoulder','5-ingredient recipe: Tender Lamb Shoulder',NULL,'easy',20,NULL,20,8,NULL,0,0,0,1,0,'lamb',2,1,5,0,'[{"name":"dried chickpeas","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"preserved lemons","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe plum tomatoes","quantity":1,"unit":"kg","unit_norm":"kg","category":"produce"},{"name":"lamb shoulder","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"heaped teaspoons ras el hanout","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Pour the dried chickpeas into a 30cm × 40cm roasting tray. Quarter the preserved lemons and trim away the seedy core, then finely chop the rind and add to the tray with a good splash of liquor from their jar. Roughly chop the tomatoes, adding them to the tray as you go.","Drizzle the lamb with 1 tablespoon of olive oil, then rub all over with the ras el hanout and a pinch of sea salt and black pepper. Sit the lamb in the tray, pour in 1 litre of water, cover tightly with tin foil and place in a cold oven. Turn the temperature to 170°C/325°F/gas 3 and leave the lamb in there for 6 hours, or until the chickpeas are cooked through and the lamb is pullable – after 3 hours, stir a splash of water into the chickpeas, covering tightly again with foil.","To serve, taste the chickpeas, season to perfection, and drizzle with 1 tablespoon of extra virgin olive oil, then pull the lamb apart with two forks.","LAMB KOFTA FLATBREADS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lamb-kofta-flatbreads','Lamb Kofta Flatbreads','5-ingredient recipe: Lamb Kofta Flatbreads',NULL,'easy',15,NULL,15,2,NULL,0,0,0,0,1,'lamb',2,1,5,0,'[{"name":"minced lamb","quantity":250,"unit":"g","unit_norm":"g","category":"meat"},{"name":"rose harissa","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"red cabbage","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"seeded wholemeal tortillas or flatbreads","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"cottage cheese","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Put a griddle pan on a high heat. Scrunch the minced lamb and harissa in your clean hands until well mixed. Divide into 6 pieces, then shape into koftas with your fingertips, leaving dents in the surface to increase the gnarly bits as they cook. Griddle for 4 to 5 minutes on each side, or until sizzling and golden.","Meanwhile, shred the red cabbage as finely as you can. Sprinkle with a pinch of sea salt and black pepper, drizzle with 1 tablespoon of red wine vinegar, then scrunch together to quickly pickle it.","Warm your tortillas or flatbreads, sprinkle over the cabbage, spoon over the cottage cheese, add the koftas, drizzle with a little extra harissa, and tuck in.","LOVELY LAMB HOTPOTS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lovely-lamb-hotpots','Lovely Lamb Hotpots','5-ingredient recipe: Lovely Lamb Hotpots',NULL,'easy',20,NULL,20,4,NULL,0,0,0,1,0,'lamb',1,1,5,1,'[{"name":"red onions","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"lamb neck fillet","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"mint sauce","quantity":6,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"umami paste","quantity":4,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"potatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"}]','["Preheat the oven to 170°C/325°F/gas 3. Peel and roughly chop the onions, dice the lamb into 3cm chunks, then divide both between four 15cm ovenproof bowls, placing the bowls on a large oven tray. Add 1 teaspoon each of mint sauce and umami paste to each of the bowls, followed by 150ml of water and a little pinch of sea salt and black pepper. Stir well.","Quickly scrub the potatoes and rattle them through the thick slicer attachment of a food processor so they’re just under ½cm thick. Divide between the bowls, overlapping them slightly to cover. Press down on the potato layer to compact everything, then cover with tin foil and bake for 2 hours, removing the foil for the last 30 minutes. Spoon over the remaining mint sauce, and tuck in.","AROMATIC LAMB CURRY"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('aromatic-lamb-curry','Aromatic Lamb Curry','5-ingredient recipe: Aromatic Lamb Curry',NULL,'easy',20,NULL,20,4,NULL,0,0,0,0,1,'lamb',2,1,5,1,'[{"name":"lamb shoulder","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"large onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"large aubergines","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"rogan josh curry paste","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"natural yoghurt","quantity":200,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 180°C/350°F/gas 4. Put a large shallow casserole pan on a high heat. Dice the lamb into 3cm chunks and place in the pan fat side down. Peel the onions, dice with the aubergines to the same size as the lamb, then stir into the pan. Season with sea salt and black pepper, stir in the curry paste and 1 tablespoon of red wine vinegar, then transfer to the oven for 1 hour, or until tender, stirring halfway and loosening with a splash of water, if needed.","Taste the curry, season to perfection, ripple through the yoghurt, drizzle over ½ a tablespoon of extra virgin olive oil, hit it with lots of black pepper, and serve.","ALE BARLEY LAMB SHANKS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spring-lamb','Spring Lamb','5-ingredient recipe: Spring Lamb',NULL,'easy',24,NULL,24,2,NULL,0,0,0,1,0,'lamb',4,0.887,5,0,'[{"name":"baby new potatoes","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"frozen peas","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"piece of lamb rump","quantity":200,"unit":"g","unit_norm":"g","category":"meat"},{"name":"fresh basil","quantity":4,"unit":"sprigs","unit_norm":"sprigs","category":"produce"},{"name":"heaped tablespoon yellow pepper or green pesto","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Halve any larger potatoes, then cook in a pan of boiling salted water for 15 minutes, or until tender, adding the peas to the party for the last 3 minutes.","Meanwhile, rub the lamb all over with 1 teaspoon of olive oil, and a pinch of sea salt and black pepper. Starting fat side down, sear the lamb in a non-stick frying pan on a medium-high heat for 10 minutes, turning regularly until gnarly all over but blushing in the middle, or use your instincts to cook to your liking. Remove to a plate to rest, then, with the frying pan on a low heat, make a liquor by stirring in a splash of water and a little red wine vinegar to pick up all those nice sticky bits, leaving it to tick away slowly until needed.","Drain the potatoes and peas, tip into the liquor pan, pick over most of the basil, add the pesto and toss it all well. Serve with the lamb, sliced thinly, then pour over the resting juices. Pick over the remaining basil leaves, and tuck in.","SUCCULENT LAMB STEW"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('succulent-lamb-stew','Succulent Lamb Stew','5-ingredient recipe: Succulent Lamb Stew',NULL,'easy',20,NULL,20,6,NULL,0,0,0,1,0,'lamb',2,1,5,1,'[{"name":"bunch of fresh rosemary","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"lamb shoulder","quantity":800,"unit":"g","unit_norm":"g","category":"meat"},{"name":"mixed-colour olives","quantity":150,"unit":"g","unit_norm":"g","category":"produce"},{"name":"silverskin pickled onions","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"}]','["Preheat the oven to 170°C/325°F/gas 3. Place a 30cm shallow casserole pan on a high heat, strip in the rosemary leaves, add 1 tablespoon of olive oil, and crisp up for 1 minute while you dice the lamb into 3cm chunks. Scoop out the rosemary and put aside, adding the lamb to the pan for 2 minutes to get some colour. Meanwhile, squash the olives and remove the stones.","Drain the pickled onions and stir into the pan with the olives. Toss well, then pour in the tinned tomatoes, breaking them up with a wooden spoon, as well as 2 tins’ worth of water. Cover and cook in the oven for 2 hours, or until thick, delicious and tender, stirring halfway and loosening with a splash of water, if needed. Taste, season to perfection with sea salt and black pepper, sprinkle over the crispy rosemary leaves, and serve. Simple.","STICKY LAMB CHOPS"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sticky-lamb-chops','Sticky Lamb Chops','5-ingredient recipe: Sticky Lamb Chops',NULL,'easy',15,NULL,15,2,NULL,0,0,0,1,0,'lamb',2,0.943,5,1,'[{"name":"lamb chops","quantity":6,"unit":"","unit_norm":"","category":"meat"},{"name":"mixed-colour baby heritage carrots","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"garlic","quantity":8,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"oranges","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"bunch of fresh thyme","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"}]','["Score the fat of the lamb chops, season them with sea salt and black pepper, then line them up, like a rack, and sit them together fat edges down in a large shallow casserole pan on a medium-high heat. Leave for 5 minutes to render and crisp up. Trim and add the whole baby carrots (halving any larger ones) and the unpeeled garlic cloves alongside, turning the carrots regularly.","Gently turn the chops on to their sides, to cook for 2 minutes on each side, or until golden, but still pink in the middle. Meanwhile, use a speed-peeler to peel strips of zest from 1 orange. Sprinkle them into the pan with the thyme sprigs, and toss it all together for just 30 seconds to get the flavours going.","Remove the chops to a plate to rest, then squeeze the juice from all 3 oranges into the pan. Let the juice bubble and reduce until sticky, quickly toss the lamb back in with its resting juices, then hey presto, time to dish up.","RICE & NOODLES","EGG-FRIED RICE","SWEET & SOUR CHICKEN NOODLES","BAKED SAFFRON RICE","BLACK TAHINI NOODLES","SPICED LENTILS & RICE","SESAME SHIITAKE EGG NOODLES","ITALIAN BAKED RICE","HAM & EGG CURRIED NOODLES","HOISIN PAK CHOI RICE","EGG-FRIED RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('egg-fried-rice','Egg-Fried Rice','5-ingredient recipe: Egg-Fried Rice',NULL,'easy',10,NULL,10,2,NULL,0,1,0,1,0,'none',1,1,5,0,'[{"name":"spring onions","quantity":6,"unit":"","unit_norm":"","category":"produce"},{"name":"sachet of cooked brown basmati rice","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"heaped teaspoons chilli jam","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"firm silken tofu","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"}]','["Put a large non-stick frying pan on a medium-high heat. Trim and finely slice the spring onions and fry with 1 tablespoon of olive oil for 1 minute. Add the rice, chilli jam, a splash of water and a pinch of sea salt and black pepper, then toss for 2 minutes until everything is well coated.","Push the rice to the sides of the pan, making a big well in the middle. Crack the eggs into the well, then use a rubber spatula to start gently moving the eggs around to create big curds. Break in the tofu, then fold the rice back through the egg until it’s all looking good. Taste and season to perfection. Lightly oil the inside of a bowl, add the egg-fried rice, gently compacting it with the spatula, then proudly turn out on to a plate, retro style.","SWEET & SOUR CHICKEN NOODLES"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-sour-chicken-noodles','Sweet & Sour Chicken Noodles','5-ingredient recipe: Sweet & Sour Chicken Noodles',NULL,'easy',20,NULL,20,2,NULL,0,0,0,1,0,'chicken',1,1,5,1,'[{"name":"chicken thighs","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"fine rice noodles","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"sugar snap peas","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Worcestershire sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"chilli jam","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"produce"}]','["Pull the skin off the chicken. Place the skin in a large non-stick frying pan on a medium heat to render and get golden, turning occasionally. Cut the bones out of the thighs and chuck into the pan for bonus flavour, then chop the meat into 2cm pieces. Move the skin and bones to one side of the pan, then add the meat alongside and cook for 5 minutes, or until golden, stirring occasionally. Once crispy, remove, chop and reserve the skin, discarding the bones.","Meanwhile, cook the noodles in boiling salted water according to the packet instructions. Halve the sugar snaps lengthways. Once soft, drain the noodles, reserving a mugful of cooking water, then refresh under cold water. Use scissors to snip the noodles into roughly 8cm lengths.","Stir the Worcestershire sauce and chilli jam into the chicken pan and let the jam melt, then add the sugar snaps and noodles. Toss over the heat for 2 minutes, adding a splash of reserved noodle water to loosen, if needed. Taste and season to perfection with sea salt and black pepper, then dish up and sprinkle over the reserved crispy chicken skin.","BAKED SAFFRON RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('baked-saffron-rice','Baked Saffron Rice','5-ingredient recipe: Baked Saffron Rice',NULL,'easy',26,NULL,26,4,NULL,0,1,0,0,1,'none',4,0.967,5,1,'[{"name":"red onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"small pinches of saffron","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"heaped tablespoons natural yoghurt","quantity":4,"unit":"","unit_norm":"","category":"dairy"},{"name":"sun-dried tomato paste","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"white basmati rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 200°C/400°F/gas 6. Peel and finely chop the red onions. Place a 25cm × 30cm roasting tray on a high heat on the hob, pour in 1 tablespoon of olive oil, add the onions and fry for 4 minutes, or until soft and sweet, stirring regularly. Meanwhile, place half the saffron in 600ml of boiling kettle water. In a bowl, cover the remaining saffron with 1 tablespoon of boiling water, steep for 10 seconds, then mix with the yoghurt and put aside.","Stir the tomato paste, rice and a pinch of sea salt and black pepper into the onion tray, then pour in the saffron water and bring to the boil. Once boiling, carefully transfer to the oven for 15 minutes, or until the rice has absorbed all the liquid, fluffed up beautifully and is golden and crisp on top.","Spoon the saffron yoghurt over the rice, drizzle it all with 1 tablespoon of extra virgin olive oil, fork and mix it all together, and dish up.","BLACK TAHINI NOODLES"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('black-tahini-noodles','Black Tahini Noodles','5-ingredient recipe: Black Tahini Noodles',NULL,'easy',13,NULL,13,2,NULL,0,1,0,1,0,'none',2,1,5,0,'[{"name":"fine rice noodles","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"limes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"cress","quantity":1,"unit":"punnet","unit_norm":"punnet","category":"produce"},{"name":"black sesame seeds","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"teriyaki sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Cook the noodles in boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Meanwhile, finely grate the zest of 1 lime, snip the cress and put both aside. Toast the sesame seeds in a dry non-stick frying pan on a high heat for 1 minute, tossing regularly. Reserving one quarter of the seeds, pound the rest in a pestle and mortar until fairly fine, then muddle in the teriyaki and the juice of 1 lime. Taste, season to perfection with sea salt and black pepper, and you’ve got a black tahini!","Toss the noodles and black tahini together, loosening with a splash of reserved noodle water. Serve sprinkled with the lime zest, cress and reserved seeds, with lime wedges on the side, for squeezing over.","SPICED LENTILS & RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spiced-lentils-rice','Spiced Lentils & Rice','5-ingredient recipe: Spiced Lentils & Rice',NULL,'easy',25,NULL,25,2,NULL,0,1,0,1,0,'none',1,0.967,5,1,'[{"name":"dried red split lentils","quantity":75,"unit":"g","unit_norm":"g","category":"produce"},{"name":"onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoons balti curry paste","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"mixed-colour kale","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"sachet of cooked brown basmati rice","quantity":1,"unit":"","unit_norm":"","category":"pantry"}]','["Cook the lentils in a pan of boiling salted water according to the packet instructions. Meanwhile, peel and finely slice the onions, put them into a large shallow casserole pan on a medium heat with ½ a tablespoon of olive oil and the balti paste, and cook for 15 minutes, or until soft and golden, stirring regularly. Tear in the kale (discarding any tough stalks), add a splash of lentil cooking water, cover and leave for 2 minutes.","Drain the lentils, toss into the casserole pan with the rice, cover again, and leave for a final 3 minutes. Toss it all together, taste, season to perfection with sea salt and black pepper, and dish up. Delicious.","SESAME SHIITAKE EGG NOODLES"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sesame-shiitake-egg-noodles','Sesame Shiitake Egg Noodles','5-ingredient recipe: Sesame Shiitake Egg Noodles',NULL,'easy',13,NULL,13,2,NULL,0,1,0,1,0,'none',3,1,5,1,'[{"name":"shiitake mushrooms","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"egg noodles","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"sesame seeds","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"kicap manis","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Halve the mushrooms, then dry toast in a large non-stick frying pan on a medium-high heat for 8 minutes, or until golden and nutty, tossing occasionally. Meanwhile, cook the noodles in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Peel and finely slice the garlic, add to the mushroom pan with 1 tablespoon of olive oil and cook for a further 2 minutes, tossing regularly.","Pound the sesame seeds until fine in a pestle and mortar, then toss into the pan with the noodles, kicap manis and a good splash of reserved noodle water until everything is well coated. Taste, season to perfection with sea salt and black pepper, if needed, and dish right up.","ITALIAN BAKED RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('italian-baked-rice','Italian Baked Rice','5-ingredient recipe: Italian Baked Rice',NULL,'easy',20,NULL,20,4,NULL,0,0,0,0,1,'pork',4,1,5,1,'[{"name":"onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"fennel salami","quantity":60,"unit":"g","unit_norm":"g","category":"meat"},{"name":"Arborio risotto rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"heaped tablespoon mascarpone cheese","quantity":1,"unit":"","unit_norm":"","category":"dairy"},{"name":"Parmesan cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 180°C/350°F/gas 4. Place a large shallow casserole pan on a high heat. Peel and quarter the onions and quickly break apart into petals straight into the pan. Char for 4 minutes, tossing regularly. Reduce to a medium heat and stir in 1 tablespoon of olive oil and the salami, then the rice, followed 1 minute later by 1.2 litres of boiling kettle water and the mascarpone. Finely grate and stir in the Parmesan with a pinch of sea salt and black pepper.","Transfer the pan to the oven for 40 minutes, or until the rice has absorbed all the liquid and is just cooked through. Drizzle with 1 tablespoon of extra virgin olive oil and dish up, seasoning to perfection at the table.","HAM & EGG CURRIED NOODLES"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('ham-egg-curried-noodles','Ham & Egg Curried Noodles','5-ingredient recipe: Ham & Egg Curried Noodles',NULL,'easy',10,NULL,10,2,NULL,0,0,0,1,0,'pork',1,1,5,0,'[{"name":"egg noodles","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"spring onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"roast ham","quantity":100,"unit":"g","unit_norm":"g","category":"meat"},{"name":"curry powder","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Cook the noodles in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of cooking water. Meanwhile, trim and finely slice the spring onions, and finely slice the ham.","Place the ham in a non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil and the curry powder. While it gets nicely golden, beat the eggs. Pour them into the pan, moving them around with a rubber spatula until they start to cook, then stir in the noodles and most of the spring onions. Toss over the heat for 2 minutes, then taste and season to perfection with sea salt and black pepper, loosening with a splash of reserved noodle water, if needed. Dish up the noodles, scatter over the remaining spring onions and finish with 1 teaspoon of extra virgin olive oil.","HOISIN PAK CHOI RICE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('hoisin-pak-choi-rice','Hoisin Pak Choi Rice','5-ingredient recipe: Hoisin Pak Choi Rice',NULL,'easy',15,NULL,15,2,NULL,0,1,0,1,0,'none',1,0.863,5,0,'[{"name":"white basmati rice","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"spring onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"fresh mixed-colour chillies","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"pak choi","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"hoisin sauce","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Cook the rice in a pan of boiling salted water according to the packet instructions, then drain. Meanwhile, trim and finely slice the spring onions, putting the white slices into a bowl. Deseed and finely chop the chillies, add to the bowl with 1 tablespoon of red wine vinegar and a little sea salt and black pepper, and mix well to make a dressing.","Halve the pak choi lengthways and place in a large non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil. Once charred, toss in the green spring onion slices, then stir in the hoisin. Let it glaze for 1 minute, then mix in the rice for 1 final minute. Spoon over the chilli dressing, and serve up.","SWEET TREATS","CHERRY CHOCOLATE MOUSSE","ALMOND PASTRY PUFF","APPLE CRUMBLE COOKIES","ORANGE POLENTA CAKE","CHOCOLATE RYE COOKIES","SPEEDY STEAMED PUDDING POTS","FLAMING RUM ’N’ RAISIN","CHOCOLATE ORANGE SHORTBREAD","PEACH & ALMOND ALASKA","PLUM TARTE TATIN","PINEAPPLE CARPACCIO","FROZEN BANOFFEE CHEESECAKE","WATERMELON GRANITA","BOOZY PEARS & CHOCOLATE","MANGO RICE PUDDING","HONEY BERRY FILO SMASH","BUDDY’S FLAPJACK BISCUITS","WALNUT-WHIP AFFOGATO","ST CLEMENT’S POLENTA BISCUITS","BERRY MERINGUE RIPPLE","CHERRY CHOCOLATE MOUSSE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('almond-pastry-puff','Almond Pastry Puff','5-ingredient recipe: Almond Pastry Puff',NULL,'easy',28,NULL,28,6,NULL,0,1,0,0,1,'none',4,0.83,5,1,'[{"name":"blanched almonds","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"double cream","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"icing sugar","quantity":75,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"block of all-butter puff pastry","quantity":375,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 220°C/425°F/gas 7. Line a baking tray with greaseproof paper. Blitz the almonds in a food processor until nice and fine. With the processor still running, add the cream, icing sugar, 1 egg and a pinch of sea salt until combined, stopping to scrape down the sides with a spatula, if needed.","Halve the pastry, shape into two rounds and, working quickly, dusting with icing sugar as you go to stop the pastry sticking, roll out between two sheets of greaseproof paper until they’re just under ½cm thick. Place one round on the lined tray. Spread the almond paste on top, leaving a 2cm gap at the edges. Put the other round on top and gently push together. Quickly seal the edges with the back of a fork. Eggwash the top, then dust over an extra layer of sugar.","Gently push your finger into the middle of the pastry, then, with a sharp knife, very delicately make little lines from the centre to the outside. Bake on the bottom of the oven for 12 to 15 minutes, or until puffed up and golden, dusting with a little extra icing sugar before dishing up.","APPLE CRUMBLE COOKIES","100g dried apple","200g self-raising flour","100g unsalted butter (cold)","100g golden caster sugar","1 large egg","Preheat the oven to 200°C/400°F/gas 6. Line two trays with greaseproof paper and rub with olive oil. Whiz the apple in a food processor until finely chopped, then add the flour, cubed butter, sugar and a pinch of sea salt. Blitz to fine crumbs for 1 minute, then remove 3 tablespoons of the mix and set aside. Pulse in the egg until combined, stopping to scrape down the sides, if needed.","Divide into 24 pieces, roll into balls, then press down lightly into 4cm rounds, lining them up on the trays as you go. Sprinkle over the reserved mix, lightly pressing it into the cookies. Bake for 8 to 10 minutes, or until lightly golden. Leave to cool slightly, then transfer to a wire cooling rack. Yum!","ORANGE POLENTA CAKE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('flaming-rum-n-raisin','Flaming Rum ’N’ Raisin','5-ingredient recipe: Flaming Rum ’N’ Raisin',NULL,'easy',10,NULL,10,4,NULL,0,1,0,0,1,'none',2,0.943,5,1,'[{"name":"large scoops of vanilla ice cream","quantity":4,"unit":"","unit_norm":"","category":"dairy"},{"name":"golden sultanas","quantity":60,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"raisins","quantity":60,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"ginger nut biscuits","quantity":6,"unit":"","unit_norm":"","category":"produce"},{"name":"dark spiced rum","quantity":100,"unit":"ml","unit_norm":"ml","category":"pantry"}]','["Get your ice cream out of the freezer. Put the sultanas, raisins and a splash of water into a pan on a medium heat, so they plump up for a few minutes as the water evaporates. Meanwhile, smash up the biscuits in a pestle and mortar and divide between four bowls, adding a nice round ball of ice cream to each.","When the water’s gone, pour the rum over the sultanas and raisins and carefully set fire to it with a match, if you like (stand back!). Once the flames begin to subside, spoon the mixture over your ice cream balls. Heaven.","CHOCOLATE ORANGE SHORTBREAD","150g unsalted butter (at room temperature)","200g plain flour","50g golden caster sugar, plus extra to sprinkle","1 orange","50g dark chocolate (70%)","Preheat the oven to 190°C/375°F/gas 5. Grease a 20cm square baking tin and line with greaseproof paper. In a bowl, mix together the butter, flour, sugar and the finely grated zest of half the orange by rubbing the mixture between your thumbs and fingertips. Squash and pat into dough – don’t knead it – then push into the lined tin in a 1cm-thick layer. Prick all over with a fork, then bake for 20 minutes, or until lightly golden. Remove, sprinkle over a little extra sugar while it’s still warm, then leave to cool.","Meanwhile, melt the chocolate in a heatproof bowl over a pan of gently simmering water, then remove. Cut the shortbread into 12 finger portions, then transfer to a wire cooling rack. Drizzle with the chocolate, then finely grate over the remaining orange zest. Cut up the orange, and serve on the side!","PEACH & ALMOND ALASKA"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('peach-almond-alaska','Peach & Almond Alaska','5-ingredient recipe: Peach & Almond Alaska',NULL,'easy',26,NULL,26,4,NULL,0,1,0,0,1,'none',4,0.887,5,0,'[{"name":"flaked almonds","quantity":80,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"peach halves in juice","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"},{"name":"large scoops of vanilla ice cream","quantity":4,"unit":"","unit_norm":"","category":"dairy"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"golden caster sugar","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the grill to high. Toast the almonds on a tray as it heats up, keeping a close eye on them and removing as soon as lightly golden. Slice up the peaches and divide between four ovenproof bowls, along with their juice. Sit a nice round scoop of ice cream on top of each, and place in the freezer.","Separate the eggs. Put the whites into the bowl of a free-standing mixer (save the yolks for another recipe), add a pinch of sea salt and whisk until the mixture forms stiff peaks (you could use an electric hand whisk). With the mixer still running, gradually add the sugar until combined. Spoon into a piping bag (I like a star-shaped nozzle) or a large sandwich bag that you can snip the corner off.","Remove the bowls from the freezer and scatter over the toasted almonds. Pipe the meringue over the ice cream as delicately or roughly as you like. Now – I work two at a time to retain maximum control – pop the bowls under the grill for just 2 minutes, or until golden. Remove carefully and serve right away.","PLUM TARTE TATIN"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('plum-tarte-tatin','Plum Tarte Tatin','5-ingredient recipe: Plum Tarte Tatin',NULL,'easy',24,NULL,24,6,NULL,0,1,0,0,1,'none',2,0.967,5,1,'[{"name":"ripe mixed-colour plums","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"ground cinnamon","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"maple syrup","quantity":120,"unit":"ml","unit_norm":"ml","category":"pantry"},{"name":"sheet of all-butter puff pastry","quantity":320,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"large scoops of vanilla ice cream","quantity":6,"unit":"","unit_norm":"","category":"dairy"}]','["Preheat the oven to 220°C/425°F/gas 7. Place a 26cm non-stick ovenproof frying pan on a medium heat. Halve and destone the plums, add to the pan with 30ml of water, and cook for 1 minute. From a height, sprinkle over half the cinnamon, then evenly pour over the maple syrup. Place the pastry over the plums, using a wooden spoon to push it into the edges of the pan, and trimming off any excess to patch up little gaps, if needed.","Bake at the bottom of the oven for 16 minutes, or until golden and puffed up. Making sure you use oven gloves to protect your hands, confidently and very carefully turn the tarte out on to a plate bigger than the pan. Dish up with nice round scoops of ice cream, sprinkle over the remaining cinnamon from a height and drizzle lightly with extra virgin olive oil before serving.","PINEAPPLE CARPACCIO"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pineapple-carpaccio','Pineapple Carpaccio','5-ingredient recipe: Pineapple Carpaccio',NULL,'easy',10,NULL,10,4,NULL,0,1,0,1,0,'none',3,1,5,0,'[{"name":"fresh mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"ripe pineapple","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"blueberries","quantity":100,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Greek-style coconut yoghurt","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"lime","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Pick the mint leaves into a pestle and mortar, reserving a small handful of leaves to one side. Pound the rest into a paste, then muddle in 1 to 2 tablespoons of extra virgin olive oil to make a mint oil. Top and tail the pineapple, then slice off the skin. Quarter lengthways, remove the core, then finely slice lengthways. Arrange on a large platter or divide between your plates. Take the time to halve the blueberries, then sprinkle over the top.","Ripple some mint oil through the yoghurt (saving the rest for another recipe), then spoon over the fruit. Finely grate over the lime zest from a height and squeeze over the juice. Finely slice and sprinkle over the reserved mint leaves, then drizzle with a tiny bit of extra virgin olive oil (yes, you heard it – delicious).","FROZEN BANOFFEE CHEESECAKE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('watermelon-granita','Watermelon Granita','5-ingredient recipe: Watermelon Granita',NULL,'easy',14,NULL,14,8,NULL,0,1,0,0,1,'none',2,1,5,0,'[{"name":"small watermelon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"stem ginger in syrup","quantity":60,"unit":"g","unit_norm":"g","category":"produce"},{"name":"limes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"bunch of fresh mint","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"natural yoghurt","quantity":8,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Cut off the watermelon rind, then chop the flesh into chunks, picking out any seeds. Roughly chop the ginger and place in a large sealable freezer bag with the watermelon chunks. Finely grate in the lime zest, squeeze in all the juice, then freeze flat for at least 8 hours, or until super-hard.","When ready to serve, pick and reserve the baby mint leaves, then pick the rest into a food processor. Tip in the frozen watermelon mixture and blitz to a pink snow (in batches, if you need to). Serve 2 heaped tablespoons of granita per person, with 1 tablespoon of yoghurt, a drizzle of ginger syrup from the jar and a few baby mint leaves. It’s nice to use chilled plates, bowls or glasses here.","BOOZY PEARS & CHOCOLATE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('honey-berry-filo-smash','Honey Berry Filo Smash','5-ingredient recipe: Honey Berry Filo Smash',NULL,'easy',14,NULL,14,4,NULL,0,1,0,1,0,'none',4,0.943,5,1,'[{"name":"sheets of filo pastry","quantity":3,"unit":"","unit_norm":"","category":"pantry"},{"name":"heaped teaspoons runny honey","quantity":6,"unit":"","unit_norm":"","category":"pantry"},{"name":"shelled pistachios","quantity":40,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"raspberries","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Greek-style coconut yoghurt","quantity":400,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 180°C/350°F/gas 4. Lay 1 sheet of filo on an oiled baking tray, drizzle with 1 heaped teaspoon of honey from a height, then repeat. Lay the final sheet of filo over the top and drizzle with a little olive oil. Scatter over the pistachios, then bake for 10 minutes, or until everything is golden. Meanwhile, crush half the raspberries with a fork and ripple them through the yoghurt, then divide between your plates.","Shake the pistachios on to a board, then lightly crush. Snap off pieces of crispy filo and arrange nicely on top of the yoghurt. Scatter over the pistachios and remaining raspberries, then drizzle over the remaining honey from a height.","BUDDY’S FLAPJACK BISCUITS","100g unsalted butter (at room temperature)","100g mixed dried fruit & nuts","100g porridge oats","100g self-raising flour","100g golden syrup","Preheat the oven to 180°C/350°F/gas 4. Line a deep 20cm square baking tin with greaseproof paper and rub with olive oil. Pulse the butter, dried fruit and nuts, oats and flour in a food processor until the mix comes together and away from the sides, then pulse in the syrup until fully combined.","Transfer to the lined tin, flattening to the edges. Bake for 15 to 20 minutes, or until golden. Remove from the oven, slice into 16 squares ready to cut, and leave to cool in the tin for 5 minutes. Use the paper to lift out on to a wire rack, and leave to cool completely. Simple, easy, delicious – spread the word!","WALNUT-WHIP AFFOGATO"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('walnut-whip-affogato','Walnut-Whip Affogato','5-ingredient recipe: Walnut-Whip Affogato',NULL,'easy',9,NULL,9,4,NULL,0,1,0,0,1,'none',2,0.943,5,1,'[{"name":"dark chocolate","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"unsalted butter","quantity":20,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"shelled unsalted walnut halves","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large scoops of vanilla ice cream","quantity":4,"unit":"","unit_norm":"","category":"dairy"},{"name":"long shots of espresso","quantity":4,"unit":"","unit_norm":"","category":"pantry"}]','["Melt the chocolate and butter with a pinch of sea salt in a heatproof bowl over a pan of gently simmering water, then remove. Reserving 4 perfect walnut halves for decoration, slice or crumble up the rest.","Roll your ice cream into nice round scoops and divide between four teacups. Scatter over the sliced or crumbled walnuts, pour a shot of hot espresso into each cup, stick a walnut proudly on top, then drizzle over the melted chocolate.","ST CLEMENT’S POLENTA BISCUITS","100g unsalted butter (cold)","50g fine polenta","150g self-raising flour","100g golden caster sugar, plus extra to sprinkle","2 lemons (or oranges)","Preheat the oven to 180°C/350°F/gas 4. Line two trays with greaseproof paper and rub with olive oil. Cube the butter and place in a food processor with the polenta, flour and sugar. Finely grate in the zest of 1 lemon (or orange), then pulse to combine. Squeeze in the juice of half a lemon (or orange), and pulse again to bring the mixture together into a ball of dough.","Divide into 24 pieces, roll into balls and place on the trays, leaving a 5cm gap between them. With your thumb, create a 1cm-deep dent in the centre of each ball. Finely grate the remaining lemon (or orange) zest and scatter into the dents, followed by a little sprinkle of caster sugar. Bake for 10 minutes, or until lightly golden. Transfer to a wire rack to cool, then tuck in.","BERRY MERINGUE RIPPLE"]','rescued-deterministic');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lamb-green-beans-cheese-salad','Lamb, Green Beans & Cheese Salad','5-ingredient recipe: I Wanted To Challenge Myself To Put These Classically French Ingredients Together In A Surprising Way, And So This Salad Was Born – Smoky Beans, Oozy Cheese And A Punchy Mustardy Dressing. Voilà!','mediterranean','easy',18,NULL,18,2,NULL,0,0,0,0,1,'lamb',3,0.925,5,0,'[{"name":"fine green beans","quantity":160,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Dijon mustard","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"wheel of goat’s cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"shelled unsalted walnut halves","quantity":20,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"lamb’s lettuce","quantity":60,"unit":"g","unit_norm":"g","category":"meat"}]','["Place a large non-stick frying pan on a high heat. Trim the beans and dry fry for 10 minutes, or until nicely blistered and tender, tossing occasionally. Meanwhile, mix the mustard and 4 tablespoons each of red wine vinegar and extra virgin olive oil in a jam jar with a big pinch of sea salt and black pepper. Put the lid on and shake to emulsify (I like to make a batch and save it in the fridge for another day). Once tender, remove the beans to a large bowl with 2 tablespoons of the dressing and toss together.","Turn the heat to medium, then halve the goat’s cheese across the middle and place cut side up in the pan. Crumble the walnuts in and around the pan, spooning them on to the melting cheese when they’re beautifully golden and toasted. Leave for a couple of minutes – the cheese will start to melt and burst out of the sides to create crispy bits, but with an oozy and delicious middle. Turn off the heat and leave to stand for 1 minute while you toss the lamb’s lettuce with the mustardy beans. Divide everything between two plates, using a fish slice to carefully transfer the melty goat’s cheese on top.","A REALLY FRENCH SALAD","NAKED SALAD TUNISIENNE","JUICY RIPE TOMATOES, CUCUMBER, APPLE & FRESH MINT","My kids absolutely love this stripped-back version of a salad Tunisienne. Traditionally served with tuna, boiled eggs and olives, I think of it as a Tunisian-style niçoise. Amazing spooned over grilled fish."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-asparagus-cherry-tomatoes-salad','Pork, Asparagus & Cherry Tomatoes Salad','5-ingredient recipe: Salmorejo Is A Cold And Creamy Classic Spanish Soup, Which I’Ve Used As Inspiration For My Sauce. I’Ve Made It Thicker, A Bit Like Mayo, And It Eats So Well With The Asparagus, Pata Negra And Smoky Paprika.','mediterranean','easy',14,NULL,14,4,NULL,0,0,0,1,0,'pork',3,1,5,0,'[{"name":"asparagus","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"mixed-colour cherry tomatoes","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"sourdough bread","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"Pata Negra or quality Spanish ham","quantity":100,"unit":"g","unit_norm":"g","category":"meat"},{"name":"smoked paprika","quantity":null,"unit":"","unit_norm":"","category":"pantry"}]','["Place a griddle pan on a high heat. Snap the woody ends off the asparagus, then add the stalks to the pan and cook until tender and bar-marked all over, turning occasionally. Meanwhile, place the tomatoes in a blender (I’ve used yellow and orange here, but any combination works well) with 2 tablespoons of olive oil and a pinch of sea salt and black pepper. Remove the crusts from the bread, run the bread quickly under the tap, squeeze out the water, then add to the blender. Whiz until super-smooth with 1 teaspoon of red wine vinegar, adding a splash of water to loosen, if needed. Season to perfection and divide between plates. Top with the grilled asparagus, arrange the ham nicely on top, drizzle with a little extra virgin olive oil and dust with smoked paprika, to serve.","GRILLED ASPARAGUS","RUBY BULGUR SALAD","RED PEPPER DRESSING, HUNG YOGHURT & GREENS","Using bulgur in lots of different ways – in soups, stews and salads – is common all over the Med, and what I love about this is that it could be a lunch, a side with meat or fish, or part of a table of dishes."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('red-peppers-yoghurt-salad','Red Peppers & Yoghurt Salad','5-ingredient recipe: Using Bulgur In Lots Of Different Ways – In Soups, Stews And Salads – Is Common All Over The Med, And What I Love About This Is That It Could Be A Lunch, A Side With Meat Or Fish, Or Part Of A Table Of Dishes.','mediterranean','easy',30,NULL,30,4,NULL,0,1,0,0,1,'none',2,0.812,5,0,'[{"name":"natural yoghurt","quantity":500,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"bulgur wheat","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"seasonal greens","quantity":320,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"roasted red peppers","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"heaped teaspoon ground cinnamon","quantity":1,"unit":"","unit_norm":"","category":"pantry"}]','["Line a sieve with a few pieces of kitchen paper, tip in the yoghurt, then pull up the paper and very gently apply pressure so that the liquid starts to drip through into a bowl. Leave in the fridge to drain. Meanwhile, cook the bulgur in a large pan of boiling salted water according to the packet instructions. Wash and trim the greens, as necessary, finely chopping any stalks. Place the stalks in a colander with a lid on top and place above the bulgur pan to steam. After 5 minutes, add the leaves and steam for a further 5 minutes, or until just wilted. Lay the greens out on a clean tea towel and once cool enough to handle, pile them in the centre, wrap them up and wring out really well to remove the excess liquid. Finely chop, season to taste and toss with a little extra virgin olive oil, then put aside.","Meanwhile, drain the peppers, tip them into a blender and whiz with the cinnamon and 1 tablespoon each of extra virgin olive oil and red wine vinegar. Drain the bulgur and leave to steam for 5 minutes, then tip into a serving bowl. Pour over the dressing and mix well, then season to perfection. Spoon the greens on top, dollop over the hung yoghurt and drizzle with extra virgin olive oil, if you like.","RUBY BULGUR SALAD","CREAMY WHITE BEAN SALAD","CHARRED BROCCOLI, HERBY ONION PICKLE & BOQUERONES","Using nutritious creamy beans in contrast with charred broccoli, crunchy pickles and the tang of anchovies takes this salad to the next level – serve warm or cold, and as tapas, a light lunch or side."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-figs-cheese-salad','Pork, Figs & Cheese Salad','5-ingredient recipe: The Joy Of My Mediterranean Travels Has Inspired Me To Blend Classic Flavours Like Dukkah From Egypt With Traditional Spanish Ham, Figs And Honey, And Bring Them Together In A Surprising, Delicious Way.','mediterranean','easy',20,NULL,20,2,NULL,0,0,0,0,1,'pork',3,0.925,5,0,'[{"name":"runny honey","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"dukkah","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"tub of cottage cheese","quantity":1,"unit":"","unit_norm":"","category":"dairy"},{"name":"perfectly ripe figs","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Pata Negra or quality Spanish ham","quantity":50,"unit":"g","unit_norm":"g","category":"meat"}]','["Drizzle the honey into a pan over a medium heat and leave to bubble away for about 3 minutes, or until you’ve got a dark golden caramel – please don’t be tempted to stir, taste or touch the mixture, just give the pan a gentle swirl occasionally. Meanwhile, lightly oil a piece of greaseproof paper, sprinkle the dukkah over a 15cm x 15cm area, then carefully pour the caramel over the top and it will naturally settle and cool. (To clean the pan effortlessly, pour in 2.5cm of water, pop the lid on and simmer for 5 minutes.) Once completely cool, snap up the praline and bash in a pestle and mortar until fine.","Divide the cottage cheese between two plates, quarter and scatter over the figs, and arrange the Pata Negra in and around the plate. Scatter over a few good pinches of the dukkah praline (save the rest in an airtight container for another day) and drizzle with extra virgin olive oil, to finish.","PS","If you don’t fancy making the caramel, simply swap the honey for sesame snaps, and bash them to a powder with the dukkah.","FANCY FIG SALAD","GRILLED FATTOUSH SALAD","SWEET ONION, PITTA BREAD & CUCUMBER, SUMAC DRESSING","Fattoush is a humble Lebanese salad, and here I’ve enjoyed twisting the flavours by quite brutally grilling the cucumber, onion and pitta, but then tossing them with a delicate sumac dressing."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-garlic-squid-salad','Pork, Garlic & Squid Salad','5-ingredient recipe: There’S No Need For A Boring Salad, And For Me This Is Super-Fun, Exciting And Fast To Make – Think A Bacon And Squid-Loaded Surf And Turf-Style Baguette, Acting Like A Giant Crouton On A Sea Of Leaves.','mediterranean','easy',12,NULL,12,2,NULL,0,0,0,1,0,'pork',3,0.925,5,0,'[{"name":"smoked streaky bacon","quantity":2,"unit":"rashers","unit_norm":"rashers","category":"meat"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"whole squid","quantity":300,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"small rustic baguette","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"green chicory","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["Finely slice the bacon and peel and finely slice the garlic. Place the bacon in a large non-stick frying pan on a high heat with 1 tablespoon of olive oil and fry for 2 minutes, adding the garlic halfway and tossing regularly. Add the squid and a good pinch of black pepper and cook for a further 2 minutes, or until tender. Slice the squid into ½cm rings, roughly chopping the tentacles, then put back into the pan and toss together. Slice the baguette at a slight angle, then push the squid to one side of the pan and toast the bread until golden on both sides with all the lovely garlicky pan juices.","Meanwhile, trim and click off the chicory leaves, dress with 1 tablespoon each of extra virgin olive oil and red wine vinegar, and season to perfection. Divide the dressed chicory between plates, then pile the squid and crispy bacon on to the hot toasts and place on top.","SEARED SQUID SALAD","CHAR & CHOP SALAD","RIPE TOMATOES, FRESH DILL, GARLIC, CHILLI & FLATBREADS","Inspired by Palestinian Gazan dagga, I love that a few moments of charring and chopping tomatoes, plus a confident use of dill and seasoning, can transform the everyday into something extraordinary."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('parsley-cucumber-green-peppers','Parsley, Cucumber & Green Peppers','5-ingredient recipe: Vibrant, Fresh And Full Of Flavour, This Take On The Spanish Favourite Gazpacho, A Cold Soup, Is Sure To Hit The Spot. Perfect For A Light Lunch, Starter, Supper, Or Just A Moment Of Pure Refreshment.','mediterranean','easy',15,NULL,15,4,NULL,0,1,0,1,0,'none',4,0.925,5,0,'[{"name":"ciabatta loaf","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"flat-leaf parsley","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"shelled unsalted pistachios","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"cucumber","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"green peppers","quantity":2,"unit":"","unit_norm":"","category":"produce"}]','["Cut 8 thin slices of ciabatta, and toast until golden. Tear the remaining bread into a blender. Keep back a little of each of the remaining ingredients for garnish. Rip the parsley into the blender with the pistachios, chop and add the cucumber, and tear in the peppers, discarding the seeds and stalks.","Pour in 200ml of cold water along with 3 tablespoons each of extra virgin olive oil and red wine vinegar, then season well with sea salt and black pepper. Whiz together, then add 300g of ice and blitz again until silky smooth – you may need to work in batches. Taste and adjust the seasoning, if needed. Serve sprinkled with the reserved garnishes (leave whole or finely chop in a delicate fashion, whatever you prefer) and a drizzle of extra virgin olive oil, if you like. An extra ice cube or two is always a nice touch, too. Serve the crispy toasts alongside for dunking.","GREEN GAZPACHO","BUTTER BEANS ON TOAST","CRISPY CHORIZO, FRESH PARSLEY & TANGY PEPPER SAUCE","Celebrating simple Spanish vibes, this vibrant dish really delivers on both speed and flavour. We’re hero-ing big fat creamy butter beans, which teamed with chorizo and pepper sauce are a real joy."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fennel-tomatoes-bowl','Fennel & Tomatoes Bowl','5-ingredient recipe: When You’Ve Got A Beautiful Whole Fish, It Doesn’T Need Much To Really Shine. This Method Utilizes Every Part Of The Bream, With Delicate Flaky Fish Fillets As Well As A Flavoursome Lip-Smacking Soup.','mediterranean','easy',45,NULL,45,2,NULL,0,1,0,1,0,'none',2,0.757,2,1,'[{"name":"large bulb of fennel","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe tomatoes","quantity":600,"unit":"g","unit_norm":"g","category":"produce"}]','["1 x 400g whole bream, scaled, gutted, gills removed","1 small baguette (200g)","2 tablespoons garlic mayo","Trim the fennel, reserving any leafy tops in a bowl of cold water. Remove and roughly chop the outer layers, and very finely slice the tender inner core as best you can. Add all the finely sliced fennel to the bowl of water, then place the rest in a large shallow casserole pan on a medium-high heat with 2 tablespoons of olive oil. Cook for 10 minutes, or until starting to caramelize, stirring regularly.","Roughly chop and add the tomatoes, then pour in 500ml of water. Bring to the boil, lay the fish on top, cover the pan and simmer gently for 10 minutes, turning the fish halfway. Remove the cooked fish to a plate, let it cool a little, then use two forks to lift the fillets away from the bones, discarding the skin and fins. Return all the bones and the head to the pan and boil on a high heat for 5 minutes. Carefully pour the entire contents of the pan into a blender and blitz until smooth, extracting maximum goodness and flavour, then season to perfection. Adjust the consistency to your liking with a splash of water, if needed, then push through a coarse sieve into warm soup bowls. Drain the fennel and dress with a little extra virgin olive oil and red wine vinegar. Serve with toasted bread, a blob of garlic mayo, the fish fillets and the dressed fennel. Finish with extra virgin olive oil, if you like.","SIMPLE MARSEILLES FISH SOUP","TOMATOES ON TOAST","HERBY GOAT’S CHEESE & CRUNCHY SMOKY ALMONDS","Stuffed with a creamy herby filling, then squashed into a rustic baguette, with a beautiful liquor for dunking, this humble dish is a celebration of beautiful bang-in-season tomatoes with a French twist."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tomatoes-parsley-cheese-salad','Tomatoes, Parsley & Cheese Salad','5-ingredient recipe: Stuffed With A Creamy Herby Filling, Then Squashed Into A Rustic Baguette, With A Beautiful Liquor For Dunking, This Humble Dish Is A Celebration Of Beautiful Bang-In-Season Tomatoes With A French Twist.','mediterranean','easy',30,NULL,30,2,NULL,0,1,0,0,1,'none',4,0.812,5,0,'[{"name":"really ripe round tomatoes","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"smoked almonds","quantity":20,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"curly parsley","quantity":4,"unit":"sprigs","unit_norm":"sprigs","category":"produce"},{"name":"soft goat’s cheese","quantity":70,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"small rustic baguette","quantity":1,"unit":"","unit_norm":"","category":"pantry"}]','["Use the tip of a knife to carefully cut the stalk away from the top of each tomato, then blanch in a pan of boiling water for 50 seconds. Drain and rinse under cold water, then carefully peel and discard the skin. Using your hand to hold each tomato in shape, carefully use a teaspoon to scoop the insides into a coarse sieve over a bowl. Push the juicy goodness through the sieve into the bowl, add a thimble of red wine vinegar, then season to perfection with sea salt and black pepper.","Bash most of the smoked almonds in a pestle and mortar until fine. Tear the top leafy half off the parsley and place in a bowl of ice-cold water. Finely chop the stalks and add to the bashed almonds with the goat’s cheese, then mix together, loosening with a splash of water. Slice the baguette in half lengthways and toast until lightly golden. Meanwhile, spoon the cheese filling into a sandwich bag, cut off the corner and squeeze the filling into the tomatoes. Drizzle the inside of the toasted baguette with extra virgin olive oil, then place the tomatoes on the base. Drain the parsley well and toss with a little more oil, then scatter over the top. Finely chop and sprinkle over the remaining almonds, then pop the lid on and cut into slices. Serve with the tomato liquor, for dunking.","TOMATOES ON TOAST","MUSHROOM SOUP","SOUR CREAM RIPPLE, CRISPY MUSHROOMS","Inspired by the small but mighty Montenegro, where cooking is all about extracting maximum flavour from fresh local produce, this dark and delicious soup uses mushrooms in two exciting ways."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-garlic-onion-bowl','Chicken, Garlic & Onion Bowl','5-ingredient recipe: Inspired By The Small But Mighty Montenegro, Where Cooking Is All About Extracting Maximum Flavour From Fresh Local Produce, This Dark And Delicious Soup Uses Mushrooms In Two Exciting Ways.','mediterranean','easy',30,NULL,30,4,NULL,0,0,0,0,1,'chicken',2,0.892,5,1,'[{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"frozen chopped mixed onion","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"chestnut mushrooms","quantity":750,"unit":"g","unit_norm":"g","category":"produce"},{"name":"litre chicken or vegetable stock","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"sour cream","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Preheat the oven to 180°C. Peel and finely slice the garlic, then place it in a large casserole pan on a medium-high heat with 2 tablespoons of olive oil and the frozen mixed veg. Fry for a few minutes while you slice 500g of the mushrooms, then add them to the pan with a good pinch of black pepper. Cook for 10 minutes, or until golden, then pour in the stock and cook for a further 10 minutes. Meanwhile, slice the remaining 250g of mushrooms (slice them so you have some beautiful cross-sections, throwing any trimmings into the soup as you go), place on a tray with a drizzle of olive oil and a pinch of sea salt and pepper, and roast for 15 minutes, or until beautifully golden and crisp.","When the time’s up, blitz the soup to your desired consistency, then season to perfection. Divide between warm soup bowls, ripple 1 tablespoon of sour cream into each, and top with the crispy mushrooms and a little drizzle of extra virgin olive oil, if you like.","MUSHROOM SOUP","EPIC TOMATO BREAD","CRISPY GARLIC & CHORIZO, MOLTEN MANCHEGO","Here, I’m celebrating a classic Spanish combo, but how I’ve put them together is definitely not typical. Super-fun and undeniably delicious, this is perfect served as part of a lunch or tapas spread."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-garlic-cherry-tomatoes-salad','Pork, Garlic & Cherry Tomatoes Salad','5-ingredient recipe: Here, I’M Celebrating A Classic Spanish Combo, But How I’Ve Put Them Together Is Definitely Not Typical. Super-Fun And Undeniably Delicious, This Is Perfect Served As Part Of A Lunch Or Tapas Spread.','mediterranean','easy',15,NULL,15,4,NULL,0,0,0,0,1,'pork',4,0.925,5,0,'[{"name":"chorizo","quantity":100,"unit":"g","unit_norm":"g","category":"meat"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"ciabatta loaf","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"ripe mixed-colour cherry tomatoes","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Manchego cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 180°C. Slice the chorizo and peel and finely slice the garlic, place in a large non-stick ovenproof frying pan and toss with 1 tablespoon of olive oil, then place in the oven for 6 minutes, or until golden and caramelized. Carefully halve the ciabatta lengthways and warm alongside. Meanwhile, put half the tomatoes into a blender with 1 tablespoon of red wine vinegar and 2 tablespoons of extra virgin olive oil, season with sea salt and black pepper, then blitz. Push through a coarse sieve into a bowl. Quarter the remaining tomatoes and dress with just a little extra virgin olive oil, salt and red wine vinegar. Coarsely grate the Manchego.","Place the ciabatta spongy side up on a board, then spoon over and cover with the tomato sauce. Sprinkle over the dressed tomatoes, then divide over the chorizo and garlic, spooning most of the excess oil into a jam jar (for tasty cooking another day). Immediately sprinkle the cheese into the hot pan and allow the residual heat to gently melt it into a chorizo fondue. Pour directly over the bread as evenly as possible (your guests will go wild!), then slice up and serve.","EPIC TOMATO BREAD","CRISPY SARDINE TOASTS","QUICK RED CABBAGE, FRESH CHILLI & FENNEL SEED PICKLE","I love the way these easy Istanbul-inspired sizzling sardine toasts get so crispy and the sardines cook right into the bread. Contrast with a cold, crunchy, quick pickle, and it’s pure happiness on a plate."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-seeds-red-cabbage-salad','Fish, Seeds & Red Cabbage Salad','5-ingredient recipe: I Love The Way These Easy Istanbul-Inspired Sizzling Sardine Toasts Get So Crispy And The Sardines Cook Right Into The Bread. Contrast With A Cold, Crunchy, Quick Pickle, And It’S Pure Happiness On A Plate.','mediterranean','easy',15,NULL,15,4,NULL,0,0,1,1,0,'fish',1,1,5,1,'[{"name":"heaped tablespoon fennel seeds","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"a red cabbage","quantity":0.25,"unit":"","unit_norm":"","category":"produce"},{"name":"2 mixed-colour chillies","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"ciabatta loaf","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"fresh sardines","quantity":12,"unit":"","unit_norm":"","category":"seafood"}]','["Toast the fennel seeds in a large non-stick frying pan on a medium heat for 1 minute, then pour in 2 tablespoons of olive oil, fry for 1 further minute and tip into a large bowl. Very finely slice or grate the red cabbage and chilli(es), and toss into the bowl with 4 tablespoons of red wine vinegar and a generous pinch of sea salt and black pepper. Leave aside to quickly pickle.","Carefully halve the ciabatta lengthways, drizzle with olive oil, then cut each half into 6 slices. Open out the sardines and firmly press on to the spongy side of each ciabatta slice, flesh side down. Preheat a griddle or non-stick frying pan to high, then place the toasts in the pan fish side down and cook for 2 minutes on each side, or until golden and crispy – you’ll need to work in batches. Stack up 3 toasts per person and serve, with the fresh chilli and fennel seed pickle on top.","CRISPY SARDINE TOASTS","BAKED TOMATO SOUP","SWEET PEPPERS, CIABATTA, RICOTTA, GARLIC","Thick bread soups are common all around Italy, but the baked versions really stand out for me – a real family favourite that everyone loves because it leaves you feeling warm, cosy and fulfilled."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('peppers-garlic-tomatoes-bowl','Peppers, Garlic & Tomatoes Bowl','5-ingredient recipe: Thick Bread Soups Are Common All Around Italy, But The Baked Versions Really Stand Out For Me – A Real Family Favourite That Everyone Loves Because It Leaves You Feeling Warm, Cosy And Fulfilled.','mediterranean','easy',20,NULL,20,6,NULL,0,1,0,0,1,'none',2,1,5,1,'[{"name":"mixed-colour peppers","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"plum tomatoes","quantity":3,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"ciabatta loaf","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"ricotta cheese","quantity":250,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 180°C. Deseed the peppers and chop into 2cm chunks, then place in a large casserole pan on a medium heat with 2 tablespoons of olive oil and a pinch of sea salt and black pepper. Peel and finely slice the garlic, add to the pan, then reduce the heat to low and cook for 20 minutes, or until the peppers are soft and sweet, stirring regularly and adding splashes of water, if needed. Scrunch in the tomatoes through clean hands and pour in 2 tins’ worth of water. Bring to the boil, while you slice the ciabatta 1cm thick. Stir the bread into the soup, then spoon over the ricotta and bake for 25 minutes, or until crisp on top and bubbling around the edges. Season to perfection, then divide between warm bowls and drizzle with a little extra virgin olive oil, if you like.","BAKED TOMATO SOUP","SAUSAGE SANDWICH","MANCHEGO-STUFFED PEPPERS & OLIVE TAPENADE","It doesn’t take a genius to work out that crispy golden sausage in a soft bun with sweet charred peppers stuffed with oozy Manchego cheese and fragrant tapenade is a great thing, any day. Enjoy!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-red-peppers-tapenade-bowl','Pork, Red Peppers & Tapenade Bowl','5-ingredient recipe: It Doesn’T Take A Genius To Work Out That Crispy Golden Sausage In A Soft Bun With Sweet Charred Peppers Stuffed With Oozy Manchego Cheese And Fragrant Tapenade Is A Great Thing, Any Day. Enjoy!','mediterranean','easy',18,NULL,18,4,NULL,0,0,0,0,1,'pork',3,0.925,5,0,'[{"name":"brioche buns","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"sausages","quantity":6,"unit":"","unit_norm":"","category":"meat"},{"name":"large jarred roasted red peppers","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Manchego cheese","quantity":80,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"black olive tapenade","quantity":4,"unit":"tsp","unit_norm":"tsp","category":"produce"}]','["Halve the brioche buns and quickly toast in a large dry non-stick frying pan on a medium-high heat, then put aside. Squeeze the sausages out of their skins into a bowl, then divide into 4 and with wet hands flatten out into 1cm-thick patties. Drizzle 1 tablespoon of olive oil into the pan, add the patties and cook for 2 minutes on each side, or until golden and cooked through, then remove to a plate. Meanwhile, drain the peppers and cut the Manchego into 4 slices (discarding any rind). Carefully stuff the peppers with the Manchego slices, then cook in the pan until starting to ooze, turning occasionally.","To serve, spread 1 teaspoon of olive tapenade over the base of each bun. Place a sausage patty on each one, then top with the Manchego-stuffed peppers and the bun lids, and get stuck in.","SAUSAGE SANDWICH","TASTY CHICKPEA SOUP","MIXED SPICE, PLUM TOMATOES, BROKEN ODDS & ENDS PASTA","In Morocco they have a soup similar to this called harira, often eaten after a day of fasting. It’s everything you want in a good soup – it’s fulfilling and comforting, and made with humble ingredients."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('onion-chickpeas-tomatoes','Onion, Chickpeas & Tomatoes','5-ingredient recipe: In Morocco They Have A Soup Similar To This Called Harira, Often Eaten After A Day Of Fasting. It’S Everything You Want In A Good Soup – It’S Fulfilling And Comforting, And Made With Humble Ingredients.','mediterranean','easy',35,NULL,35,4,NULL,0,1,0,1,0,'none',1,0.887,5,0,'[{"name":"frozen chopped mixed onion","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"heaped teaspoon mixed spice","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"or 2 tins of chickpeas","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"random leftover dried pasta","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"}]','["Tip the frozen mixed veg into a large, deep pan on a medium heat with 1 tablespoon of olive oil and the mixed spice. Cook for 10 minutes, or until golden, stirring regularly. Tip in the chickpeas (juices and all), then scrunch in the tomatoes through clean hands, followed by 2 tins’ worth of water and the pasta, snapping any bigger bits as you go. Bring to the boil, then reduce to a simmer and leave to blip away for 20 minutes, or until thickened and reduced, stirring and mashing occasionally, and adding splashes of water, if needed. Season to perfection with sea salt and black pepper, and serve with a drizzle of extra virgin olive oil and an extra pinch of mixed spice, if you like.","TASTY CHICKPEA SOUP","MY HOT MED SARNIE","JUICY CHICKEN, ROASTED RED PEPPERS, PESTO & BLACK OLIVES","When the bread is crisp, light and toasted in tasty pan juices, then covered in pesto and stuffed full of beautiful Mediterranean ingredients, you just know it’s going to be off-the-chart on the flavour front."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tomatoes-garlic-parsley','Tomatoes, Garlic & Parsley','5-ingredient recipe: My Greek-Cypriot Sister, Georgie, Got Me On To This Combo, And What A Ray Of Sunshine It Has Brought To Our Kitchen Table – The Kids Absolutely Love It! Feel Free To Scatter In Any Delicate Seasonal Veg.','mediterranean','easy',26,NULL,26,2,NULL,0,1,0,0,1,'none',4,0.887,5,0,'[{"name":"large ripe tomatoes","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"bunch of flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"dried orzo","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"halloumi cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Grate the tomatoes on to a plate using the fine side of a box grater, discarding any skin and seeds. Peel and slice the garlic, then place in a large non-stick frying pan on a medium heat with 2 tablespoons of olive oil and fry for 3 minutes, or until lightly golden. Meanwhile, pick a few pretty parsley leaves for garnish, then finely chop the rest (stalks and all) and add to the pan. Cook for 2 minutes, then tip in the tomatoes along with 500ml of water. Bring to the boil for a few minutes, then add the pasta and cook for a further 14 minutes, or until the pasta is just tender and the sauce has thickened, stirring regularly and adding splashes of water to loosen, if needed. Coarsely grate and stir through most of the halloumi, then taste and season to perfection with sea salt and black pepper. Grate over the remaining halloumi, scatter with the parsley leaves and drizzle with extra virgin olive oil, if you like.","GREEK-CYPRIOT PASTA","LEMONY ROCKET FARFALLE","SMASHED PISTACHIOS, PARMESAN & EXTRA VIRGIN OLIVE OIL","I’ve seen some incredible pasta sauces in the Sicilian islands made using pistachios, local cheeses and different herbs, such as rocket – finished with lemon, they’re so vivid and packed full of flavour."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('rocket-lemons-cheese-salad','Rocket, Lemons & Cheese Salad','5-ingredient recipe: I’Ve Seen Some Incredible Pasta Sauces In The Sicilian Islands Made Using Pistachios, Local Cheeses And Different Herbs, Such As Rocket – Finished With Lemon, They’Re So Vivid And Packed Full Of Flavour.','mediterranean','easy',15,NULL,15,6,NULL,0,1,0,0,1,'none',4,1,5,0,'[{"name":"dried farfalle","quantity":480,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"rocket","quantity":120,"unit":"g","unit_norm":"g","category":"produce"},{"name":"lemons","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Parmesan cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"shelled unsalted pistachios","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of starchy cooking water. Meanwhile, place most of the rocket in a blender, finely grate in the lemon zest and squeeze in all the juice. Drizzle in 6 tablespoons of extra virgin olive oil, then add the Parmesan, 2 tablespoons of starchy cooking water and most of the pistachios, and whiz until smooth. When the time’s up, toss the pasta and sauce together, loosening with a splash of starchy cooking water, if needed. Finely chop the remaining pistachios and sprinkle the remaining rocket over the top. Finish with an extra grating of Parmesan and a drizzle of extra virgin olive oil.","LEMONY ROCKET FARFALLE","CHESTNUT CARBONARA","SMOKY PANCETTA, CREAMY PECORINO & BLACK PEPPER SAUCE","Oh my days, why has it taken me so long to infiltrate one of my favourite pasta dishes with beautiful chestnuts that can be nutty, crumbly and savoury, but sweet and smooth all at the same time."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-parmesan-bacon-salad','Pork, Parmesan & Bacon Salad','5-ingredient recipe: Oh My Days, Why Has It Taken Me So Long To Infiltrate One Of My Favourite Pasta Dishes With Beautiful Chestnuts That Can Be Nutty, Crumbly And Savoury, But Sweet And Smooth All At The Same Time.','mediterranean','easy',15,NULL,15,2,NULL,0,0,0,0,1,'pork',4,0.925,5,0,'[{"name":"random leftover dried pasta","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"smoked pancetta or streaky bacon","quantity":3,"unit":"rashers","unit_norm":"rashers","category":"meat"},{"name":"vac-packed chestnuts","quantity":180,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large eggs","quantity":4,"unit":"","unit_norm":"","category":"pantry"},{"name":"pecorino or Parmesan","quantity":20,"unit":"g","unit_norm":"g","category":"dairy"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of starchy cooking water. With 4 minutes to go, finely slice the pancetta and place in a large non-stick frying pan on a medium heat with 1 tablespoon of olive oil. Once sizzling, crumble in the chestnuts and add a generous pinch of black pepper, then stir regularly until golden and crisp.","Meanwhile, separate the eggs, putting the yolks into a bowl (save the whites for making meringues another day), then finely grate in the cheese and mix together. Tip the drained pasta into the chestnut pan, then remove from the heat and wait 2 minutes for the pan to cool slightly (if the pan’s too hot, it’ll scramble; get it right and it’ll be smooth, silky and deliciously elegant). Loosen the egg mixture with a splash of the reserved cooking water, then pour over the pasta, tossing and stirring vigorously – the egg will gently cook in the residual heat. Season to perfection. Adjust the consistency with extra cooking water, if needed, and finish with a fine grating of cheese, if you like.","CHESTNUT CARBONARA","TUNISIAN PRAWN SPAGHETTI","FRAGRANT ROSE HARISSA, ZINGY LEMON & FRESH PARSLEY","Tunisians are one of the biggest pasta eaters on the planet and they have a whole load of their own pasta shapes and techniques. Harissa really amplifies the sweetness of the prawns here – delicious!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-parsley-lemon-salad','Fish, Parsley & Lemon Salad','5-ingredient recipe: Tunisians Are One Of The Biggest Pasta Eaters On The Planet And They Have A Whole Load Of Their Own Pasta Shapes And Techniques. Harissa Really Amplifies The Sweetness Of The Prawns Here – Delicious!','mediterranean','easy',22,NULL,22,2,NULL,0,0,1,1,0,'fish',4,0.887,5,0,'[{"name":"dried spaghetti","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large raw shell-on king prawns","quantity":8,"unit":"","unit_norm":"","category":"seafood"},{"name":"rose harissa","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"bunch of flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions. Meanwhile, peel the prawns, removing and reserving the heads and leaving the tails on. I like to run a small sharp knife down the back of each, discarding the vein, so they butterfly when they cook. Toss the prawns with the harissa and leave to briefly marinate. Place the prawn heads in a large frying pan on a medium heat with 1 tablespoon of olive oil and fry until golden all over, stirring regularly and gently squashing to extract amazing flavour. Roughly chop and reserve the top leafy half of the parsley, then finely slice the stalks and add them to the pan with a pinch of sea salt and black pepper. Fry for 1 minute, then add the marinated prawns and cook for 1 minute on each side. Using tongs, drag the pasta into the pan, squeeze in half the lemon juice, throw in the parsley leaves, then toss together, loosening with a splash of starchy cooking water, if needed. To serve, pick out and discard the crispy prawn heads and cut the remaining lemon half into wedges for squeezing over.","TUNISIAN PRAWN SPAGHETTI","ROASTED SQUASH LASAGNE","GOLDEN CHESTNUTS, OOZY TALEGGIO & FRAGRANT CRISPY SAGE","Stacking up the pasta sheets and turning them on their side gives this autumnal lasagne a truly wonderful texture. With crispy sage and toasted chestnuts in the mix too, it’s a proper treat for the tastebuds."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('squash-cheese-salad','Squash & Cheese Salad','5-ingredient recipe: Stacking Up The Pasta Sheets And Turning Them On Their Side Gives This Autumnal Lasagne A Truly Wonderful Texture. With Crispy Sage And Toasted Chestnuts In The Mix Too, It’S A Proper Treat For The Tastebuds.','mediterranean','easy',45,NULL,45,4,NULL,0,1,0,0,1,'none',3,0.757,5,1,'[{"name":"butternut or onion squash","quantity":1,"unit":"","unit_norm":"","category":"dairy"},{"name":"bunch of sage","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"vac-packed chestnuts","quantity":180,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"fresh lasagne sheets","quantity":10,"unit":"","unit_norm":"","category":"pantry"},{"name":"Taleggio cheese","quantity":200,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 200°C. Carefully cut the squash in half lengthways, scoop out and discard the seeds, then rub all over with sea salt, black pepper and olive oil. Place flesh side up on a tray and roast for 1 hour, or until tender. Meanwhile, drizzle 2 tablespoons of olive oil into a non-stick frying pan on a medium heat, pick in the sage leaves and cook until crispy, then remove to kitchen paper. Add the chestnuts to the pan, tossing regularly and removing when lightly golden and crisp.","When the squash is done, lay the 10 pasta sheets out on a flat surface, then break up, scoop and divide the squash flesh on to the pasta. Crumble over most of the chestnuts and tear over most of the cheese, then stack up and lightly press together 5 sheets, and repeat. Slice each stack lengthways into 3 strips and arrange sideways in an oiled 20cm x 20cm baking dish. Pour over 150ml of boiling kettle water. Crumble over the remaining chestnuts and tear over the remaining cheese. Cover with tin foil and bake for 30 minutes, or until golden and cooked through, removing the foil halfway and topping with the crispy sage leaves for the final 5 minutes. Finish with a drizzle of extra virgin olive oil, if you like.","ROASTED SQUASH LASAGNE","GREEK CHICKEN PASTA","SWEET TOMATO SAUCE, MACARONI & GRATED HALLOUMI","On the Greek island of Andros they serve variations of this undeniably delicious pasta – it’s the easiest thing to put together and the Oliver squad loves it (the teenagers thought the halloumi was peng!)."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-onion-tomatoes','Chicken, Onion & Tomatoes','5-ingredient recipe: On The Greek Island Of Andros They Serve Variations Of This Undeniably Delicious Pasta – It’S The Easiest Thing To Put Together And The Oliver Squad Loves It (The Teenagers Thought The Halloumi Was Peng!).','mediterranean','easy',30,NULL,30,8,NULL,0,0,0,0,1,'chicken',3,0.892,5,1,'[{"name":"chicken thighs","quantity":1,"unit":"kg","unit_norm":"kg","category":"meat"},{"name":"frozen chopped mixed onion","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"dried macaroni","quantity":600,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"halloumi cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"}]','["Brown the chicken thighs all over in a large non-stick casserole pan on a high heat with 2 tablespoons of olive oil, then remove to a plate. Tip in the frozen mixed veg and soften for 5 minutes, then put the chicken back into the pan with 2 tablespoons of red wine vinegar and allow it to cook away. Scrunch in the tomatoes through clean hands, then pour in 1 tin’s worth of water. Bring to the boil, then leave to blip away on a low heat for 1 hour, or until the chicken is falling off the bone, stirring occasionally.","When the time’s up, cook the pasta in a pan of boiling salted water according to the packet instructions, then drain. Meanwhile, strip all the chicken meat from the bones and shread apart with forks, returning it to the sauce as you go and discarding any skin and bones. Taste the sauce and season to perfection. To serve, stir the pasta into the sauce and grate in most of the halloumi. Finish drizzled with 1 tablespoon of extra virgin olive oil and with the remaining halloumi grated over the top.","GREEK CHICKEN PASTA","SWEET PEA ORECCHIETTE","BROKEN POTATOES, SPRING ONIONS & GRATED PECORINO","My family love the southern Italian orecchiette pasta shape – perfect for catching the gorgeous sweet peas – and the double carb hit of diced potato with tangy pecorino and olive oil is blissful."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('potatoes-spring-onions-peas-salad','Potatoes, Spring Onions & Peas Salad','5-ingredient recipe: My Family Love The Southern Italian Orecchiette Pasta Shape – Perfect For Catching The Gorgeous Sweet Peas – And The Double Carb Hit Of Diced Potato With Tangy Pecorino And Olive Oil Is Blissful.','mediterranean','easy',30,NULL,30,4,NULL,0,1,0,0,1,'none',1,0.887,5,0,'[{"name":"potatoes","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"spring onions","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"frozen peas","quantity":320,"unit":"g","unit_norm":"g","category":"produce"},{"name":"dried orecchiette","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"pecorino cheese","quantity":80,"unit":"g","unit_norm":"g","category":"dairy"}]','["Peel the potatoes and chop into 1cm cubes, trim and slice the spring onions, then place in a large non-stick frying pan on a high heat with 2 tablespoons of olive oil and 250ml of boiling kettle water. Reduce to a simmer, then cover and cook for 15 minutes, or until the potatoes are just tender, adding the peas for the last 5 minutes, stirring occasionally. Meanwhile, cook the pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of starchy cooking water. Tip the drained pasta into the pea and potato pan, finely grate in the pecorino, then toss together, adding splashes of cooking water to loosen, if needed. Season to perfection, and finish with an extra grating of pecorino and a drizzle of extra virgin olive oil, if you like.","SWEET PEA ORECCHIETTE","CRAB MEATBALLS","LINGUINE & ARRABBIATA SAUCE","The Mediterraneans love to make meatballs using all kinds of fish and seafood. I’ve used delicate picked crab in this tasty pasta – it’s super-easy to make and feels really special and impressive. Yum!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-garlic-mint-salad','Beef, Garlic & Mint Salad','5-ingredient recipe: Utterly Delicious, These Ingredients Are Not Things I Ever Thought Would Work In Combination With Pasta, But This Dish Is Pungent Yet Fragrant, And The Comforting Flavours Are Both Familiar And Surprising.','mediterranean','easy',25,NULL,25,4,NULL,0,0,0,1,0,'beef',3,0.812,3,0,'[{"name":"minced lamb","quantity":400,"unit":"g","unit_norm":"g","category":"meat"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"}]','["300g dried tubular pasta, such as gomiti or macaroni","250g natural yoghurt","Place the minced lamb in a large non-stick frying pan on a medium-low heat with 1 tablespoon of olive oil and fry for 3 minutes, or until browned all over. Peel and finely chop 3 cloves of garlic and add to the pan, followed by 1 tablespoon of red wine vinegar, a splash of water, a pinch of sea salt and lots of black pepper. Cook for a further 5 minutes, stirring regularly, then mash with a potato masher to soften. Pick the baby mint leaves and reserve for garnish, then pick and finely chop the rest and add to the pan. Reduce the heat to low and leave to tick away while you cook the pasta in a pan of boiling salted water according to the packet instructions.","Peel and finely grate the remaining garlic clove, mix with the yoghurt and season with a pinch of salt and pepper. Drain the pasta, reserving a mugful of starchy cooking water, then tip the pasta straight into the lamb pan. Cook for 1 minute, then add the garlicky yoghurt and toss together, loosening with a splash of cooking water, if needed. Sprinkle over the reserved mint leaves, to serve.","TURKISH-INSPIRED PASTA","MUSSEL TAGLIATELLE","GARLIC, MUSHROOMS, MANCHEGO & FRESH-CUT PASTA","Across the Mediterranean I’ve witnessed a number of dishes featuring the beautiful marriage of mushrooms and seafood – there’s just something so delicious and delicate about it, you have to try it."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mushrooms-garlic-cheese-salad','Mushrooms, Garlic & Cheese Salad','5-ingredient recipe: Across The Mediterranean I’Ve Witnessed A Number Of Dishes Featuring The Beautiful Marriage Of Mushrooms And Seafood – There’S Just Something So Delicious And Delicate About It, You Have To Try It.','mediterranean','easy',15,NULL,15,2,NULL,0,1,0,0,1,'fish',3,1,5,1,'[{"name":"portobello mushrooms","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"mussels","quantity":600,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"fresh lasagne sheets","quantity":250,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"Manchego cheese","quantity":40,"unit":"g","unit_norm":"g","category":"dairy"}]','["Peel the mushrooms and slice ½cm thick, then place in a dry non-stick casserole pan on a high heat with the lid on and cook for 3 minutes, shaking regularly, while you peel and finely slice the garlic. Remove the lid, add 2 tablespoons of olive oil and the garlic, then season with sea salt and black pepper. Cook for 3 minutes, while you check the mussels – if any are open, give them a tap and they should close; if they don’t, discard them. Slice the lasagne sheets lengthways into 1cm strips and boil the kettle.","Stir the mussels and pasta into the pan with just enough boiling kettle water to cover the pasta (about 350ml), then pop the lid on and let it bubble away for around 4 minutes, or until the mussels have opened and are soft and juicy, shaking the pan occasionally. If any remain closed, discard them. Coarsely grate the cheese into the pan, toss together, and season to perfection. Divide between bowls, and serve with an extra grating of Manchego and a drizzle of extra virgin olive oil, if you like.","MUSSEL TAGLIATELLE","SPEEDY TUNA PASTA","SWEET CHERRY TOMATOES, FRAGRANT BASIL & CHILLI","Tomato and basil is a flavour combo that transports me straight to the islands of Italy. Teamed with super-fresh tuna and a chilli heat, this simple pasta will have you dreaming of balmy summer nights."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-red-chilli-cherry-tomatoes-salad','Beef, Red Chilli & Cherry Tomatoes Salad','5-ingredient recipe: Tomato And Basil Is A Flavour Combo That Transports Me Straight To The Islands Of Italy. Teamed With Super-Fresh Tuna And A Chilli Heat, This Simple Pasta Will Have You Dreaming Of Balmy Summer Nights.','mediterranean','easy',14,NULL,14,2,NULL,0,0,0,1,0,'beef',4,1,5,0,'[{"name":"dried spaghetti","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"fresh red chilli","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe mixed-colour cherry tomatoes","quantity":160,"unit":"g","unit_norm":"g","category":"produce"},{"name":"tuna steak","quantity":1,"unit":"","unit_norm":"","category":"seafood"},{"name":"bunch of basil","quantity":0.5,"unit":"","unit_norm":"","category":"produce"}]','["Cook the pasta in a pan of boiling salted water according to the packet instructions. Meanwhile, finely slice the chilli, tomatoes, tuna steak and basil leaves (reserving a few baby leaves for garnish), and scrape into a large serving bowl. Add 2 tablespoons of extra virgin olive oil and 1 tablespoon of red wine vinegar, mix well, then season to perfection with sea salt and black pepper. Once the pasta is cooked, use tongs to drag it straight into the bowl, letting a splash of starchy cooking water go with it. Toss until well mixed, loosening with an extra splash of cooking water, if needed – the residual heat of the steamy pasta will start to delicately cook the tuna, just enough to give you a truly elegant dish. Scatter over the reserved basil leaves and serve with a drizzle of extra virgin olive oil, if you like.","SPEEDY TUNA PASTA","MOROCCAN PASTA","ARTICHOKES, MARINATED OLIVES, GARLIC & TOMATOES","On my travels in Morocco I was happily surprised to see angel hair pasta used in many different ways – not just in stews and simple pasta dishes like this, but also as stuffings and side dishes."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('olives-garlic-hearts-salad','Olives, Garlic & Hearts Salad','5-ingredient recipe: On My Travels In Morocco I Was Happily Surprised To See Angel Hair Pasta Used In Many Different Ways – Not Just In Stews And Simple Pasta Dishes Like This, But Also As Stuffings And Side Dishes.','mediterranean','easy',15,NULL,15,2,NULL,0,1,0,1,0,'none',2,1,5,0,'[{"name":"vermicelli or angel hair pasta","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mixed marinated olives","quantity":75,"unit":"g","unit_norm":"g","category":"produce"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"artichoke hearts in oil","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"plum tomatoes","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"}]','["Cook the vermicelli or angel hair pasta in a pan of boiling salted water according to the packet instructions, then drain, reserving a mugful of starchy cooking water. Meanwhile, destone the olives (if needed), peel and finely chop the garlic, place them in a large non-stick frying pan (including the olive marinade ingredients) on a medium heat with the artichokes and 2 tablespoons of the oil from the artichoke jar, and fry until lightly golden. Crush and push the tomatoes through a coarse sieve into the pan, and season to perfection with sea salt and black pepper. Simmer for a few minutes, then toss the vermicelli or pasta and sauce together, loosening with a splash of cooking water, if needed.","MOROCCAN PASTA","ASPARAGUS CARBONARA","SMOKED PANCETTA, EGG YOLKS, BLACK PEPPER & PECORINO","I never get bored cooking this dish – it comes together so effortlessly. I just love the contrast between the dark peppery pancetta and delicate asparagus, all coated in the silky egg and cheese sauce."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('aubergines-chickpeas-lemons-salad','Aubergines, Chickpeas & Lemons Salad','5-ingredient recipe: Vibing Off Flavours From The Levantine Coast, I’M Using Chickpeas In Two Different Ways To Max Out On Both Flavour And Texture. Peeled Blackened Aubergine Adds A Smoky Depth That’S Hard To Beat.','mediterranean','easy',22,NULL,22,2,NULL,0,1,0,1,0,'none',1,0.812,5,0,'[{"name":"aubergines","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"sesame seeds","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"or 1 tin of chickpeas","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"lemons","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"radishes","quantity":200,"unit":"g","unit_norm":"g","category":"produce"}]','["Prick the aubergines, then carefully blacken them over a direct flame on the hob (or under the grill), turning with tongs until soft inside. Meanwhile, toast the sesame seeds in a large non-stick frying pan on a high heat until golden, tossing regularly. Put two-thirds of the toasted seeds into a blender, saving the rest for later. Drain the chickpeas (reserving the juice) and add two-thirds to the blender with the juice of 1 lemon and 2 tablespoons of extra virgin olive oil. Blitz until super-smooth, loosening with splashes of chickpea juice, if needed, then season to perfection and divide between plates.","Halve the radishes, toss with the remaining lemon juice and season with sea salt to quickly pickle. Once cool enough to handle, carefully remove the aubergine skin, then halve lengthways leaving them intact at the stalk, and season with salt and black pepper. Return the frying pan to a medium heat with a drizzle of olive oil, and scatter in the remaining chickpeas. Push the chickpeas to one side, then add the aubergines and cook for 5 minutes, or until the chickpeas are golden and crispy and the aubergine is starting to caramelize, turning as needed. Divide between plates, scatter over the reserved toasted sesame seeds and radishes, and finish with a drizzle of extra virgin olive oil, if you like.","SMOKY TENDER AUBERGINE","ROGUE RATATOUILLE RISOTTO","GRILLED MEDITERRANEAN VEG, FRAGRANT BASIL & TANGY GOAT’S CHEESE","I love this quick and simple one-pan dish with a passion – it’s a crowd-pleaser, bringing Italy and Provence together. Purists would judge the frozen veg base hack, but I guarantee they’re missing out."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-basil-cheese-bowl','Chicken, Basil & Cheese Bowl','5-ingredient recipe: I Love This Quick And Simple One-Pan Dish With A Passion – It’S A Crowd-Pleaser, Bringing Italy And Provence Together. Purists Would Judge The Frozen Veg Base Hack, But I Guarantee They’Re Missing Out.','mediterranean','easy',35,NULL,35,4,NULL,0,0,0,0,1,'chicken',2,0.887,5,0,'[{"name":"frozen chargrilled Mediterranean veg","quantity":700,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"risotto rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"litres chicken or vegetable stock","quantity":1.2,"unit":"","unit_norm":"","category":"meat"},{"name":"basil","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"goat’s cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"}]','["Tip the frozen veg into a large, deep pan on a medium-high heat with 2 tablespoons of olive oil. Cook for 10 minutes, or until soft, stirring regularly, then remove half to a bowl. Add the rice to the pan and stir for 2 minutes. Add ladlefuls of hot stock and wait until each has been fully absorbed before adding another, stirring constantly for 16 to 18 minutes, or until the rice is perfectly cooked, adding extra splashes of water, if needed. Pick and finely slice most of the basil leaves and stir into the pan with the reserved veg, most of the goat’s cheese and 1 tablespoon of extra virgin olive oil, and season to perfection. Adjust the consistency so it’s nice and oozy with a splash of boiling kettle water, if needed. Divide between plates, then scatter over the remaining basil leaves and goat’s cheese, to finish.","ROGUE RATATOUILLE RISOTTO","GLORIOUS STUFFED SQUASH","MIXED HERBY GRAINS, OOZY CODDLED EGG & HARISSA DRESSING","Inspired by my travels to North Africa and their love for stuffed veg, this dish brings drama to the table, where you break and mix the oozy egg through the herby grain filling just before devouring."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('potatoes-cheese-bowl','Potatoes & Cheese Bowl','5-ingredient recipe: I Tried A Secret Recipe For Potato Bombas At A Famous Breakfast Restaurant Called La Cova Fumada In Barcelona, And Wanted To Create My Own Version, Turning The Humble Potato Into A Thing Of Wonder.','mediterranean','easy',45,NULL,45,6,NULL,0,1,0,0,1,'none',2,0.677,5,0,'[{"name":"large potatoes","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"Manchego cheese","quantity":150,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"fresh breadcrumbs","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"arrabbiata sauce","quantity":1,"unit":"jar","unit_norm":"jar","category":"pantry"}]','["Prick the potatoes all over with a fork and microwave on high for 30 minutes, or until tender, turning halfway. Once cool enough to handle, halve and scrape the insides into a bowl. Mash until smooth and season to perfection. Separate the eggs, putting the whites into a shallow bowl. Add the yolks to the potatoes and mash to combine. Chop most of the Manchego into 1cm cubes, then work into the mash mixture. Beat the egg whites. Divide the mash mixture into 6 and roll into balls, flattening slightly. Dip in the beaten egg whites, allowing any excess to drip off, then roll in breadcrumbs to coat.","Pour 1cm of olive oil into a non-stick frying pan over a medium-high heat. Once hot, carefully add the potato bombas and cook for 6 minutes, or until beautifully golden, turning halfway – you may need to work in batches. Meanwhile, heat the spicy arrabbiata sauce in a pan. Divide between plates and place the bombas on top, finely grate over the remaining Manchego, season to taste with sea salt and black pepper, and drizzle over a little extra virgin olive oil, if you like.","POTATO BOMBAS","MY MUJADARA","SPICED LENTILS & BULGUR, CRISPY ONIONS & YOGHURT","A much-loved and relied-on frugal Levantine dish, mujadara is outrageously tasty for the simplicity of its preparation and can be embellished with seasonal veg and leftover cooked meat, if you have it."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('onions-lentils-yoghurt','Onions, Lentils & Yoghurt','5-ingredient recipe: A Much-Loved And Relied-On Frugal Levantine Dish, Mujadara Is Outrageously Tasty For The Simplicity Of Its Preparation And Can Be Embellished With Seasonal Veg And Leftover Cooked Meat, If You Have It.','mediterranean','easy',45,NULL,45,4,NULL,0,1,0,0,1,'none',1,0.677,5,0,'[{"name":"large onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"heaped tablespoons cumin seeds","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"dried brown lentils","quantity":150,"unit":"g","unit_norm":"g","category":"produce"},{"name":"bulgur wheat","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"natural yoghurt","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Put a small sturdy saucepan on a medium-high heat and pour in 2cm of olive oil. Peel and very finely slice 1 onion, then deep-fry until nicely golden and crisp, and drain on kitchen paper – you’ll need to work in batches. To check the oil is up to temperature, add a piece of onion – it’s ready once the onion turns golden and floats (or when the oil reaches 180°C on a thermometer).","Meanwhile, peel and chop the remaining onion, place in a large non-stick frying pan on a medium heat, along with the cumin seeds and 1 tablespoon of olive oil, and fry for 10 minutes, or until sweet and soft. Add the lentils, bulgur and 1.2 litres of water, bring to the boil, then simmer for 25 minutes, or until the lentils and bulgur are cooked and almost all the water has been absorbed. Taste and season to perfection with sea salt and black pepper, then fold through half the crispy onions. Divide between plates, and top with dollops of yoghurt and the remaining crispy onions.","PS","If you don’t fancy deep-frying, you can buy crispy onions ready-done from most supermarkets.","MY MUJADARA","RUNNER BEAN STEW","SWEET TOMATO, GARLIC & OREGANO SAUCE, TANGY CHEESE","I think a lot of people get stuck in a rut with how they cook their beans, but stewing them with simple flavours can give you something exciting to beautifully complement meat, fish or other veg dishes."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beans-garlic-tomatoes-salad','Beans, Garlic & Tomatoes Salad','5-ingredient recipe: I Think A Lot Of People Get Stuck In A Rut With How They Cook Their Beans, But Stewing Them With Simple Flavours Can Give You Something Exciting To Beautifully Complement Meat, Fish Or Other Veg Dishes.','mediterranean','easy',45,NULL,45,4,NULL,0,1,0,0,1,'none',4,0.832,5,1,'[{"name":"runner beans","quantity":400,"unit":"g","unit_norm":"g","category":"produce"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"bunch of oregano","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"feta cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 180°C. Trim the beans and speed-peel the sides to remove any tough stringy bits. Peel and finely slice the garlic, then place in a large casserole or ovenproof frying pan on a medium heat with 2 tablespoons of olive oil. Pick in the oregano, and cook until the garlic is very lightly golden, stirring regularly. Add the tomatoes, breaking them up with a potato masher, and season with a pinch of sea salt and black pepper. Bring to a simmer, then lay in the beans, pushing them down into the sauce. Cover with a scrunched-up piece of wet greaseproof, place in the oven for 30 minutes, or until the beans are tender and the sauce has thickened, then remove the paper. Crumble over the feta and either serve straight away or place in the oven for a final 10 minutes – the choice is yours.","RUNNER BEAN STEW","MINTY COURGETTE TART","GOLDEN FLAKY PASTRY, BLACK OLIVE TAPENADE & GOAT’S CHEESE","Inspired by cooking amazing courgettes with a wonderful Syrian lady called Majda, who had fled to Marseille and started up an incredible restaurant, this is my unconventional take on a pissaladière."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('courgettes-mint-tapenade','Courgettes, Mint & Tapenade','5-ingredient recipe: Inspired By Cooking Amazing Courgettes With A Wonderful Syrian Lady Called Majda, Who Had Fled To Marseille And Started Up An Incredible Restaurant, This Is My Unconventional Take On A Pissaladière.','mediterranean','easy',35,NULL,35,4,NULL,0,1,0,0,1,'none',2,0.892,5,1,'[{"name":"courgettes","quantity":1.5,"unit":"kg","unit_norm":"kg","category":"produce"},{"name":"heaped teaspoon dried mint","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"sheet of ready-rolled puff pastry","quantity":320,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"black olive tapenade","quantity":6,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"goat’s cheese","quantity":80,"unit":"g","unit_norm":"g","category":"dairy"}]','["Trim and peel the courgettes, quarter lengthways, cut away and discard the seedy core, then roughly chop and place in a large shallow casserole pan on a medium heat with 2 tablespoons of olive oil and the dried mint. Cook gently for 30 minutes, stirring regularly, then mash half the courgettes with a potato masher and fold back through the rest. Season to perfection and leave to cool for 5 minutes.","Preheat the oven to 200°C. Unroll the pastry sheet on its paper and place on a baking tray. Spoon over the cooled courgettes, leaving a 1cm border around the edge, then fold up the sides, pressing at the corners to secure. Brush the exposed pastry with a little oil, and cook at the bottom of the oven for 30 minutes, or until the pastry is beautifully golden and puffed up. Randomly dot over the olive tapenade, break over the fresh goat’s cheese, then take to the table and serve up.","PS","If you want to use courgette flowers, like I have in the picture, have a go at growing them yourself (it’s really easy!), or buy them from farmers’ markets, as you’ll rarely find them in supermarkets. Simply open them out, arrange on top of the tart and drizzle with a little oil before baking.","MINTY COURGETTE TART","SQUASH TAGINE","CREAMY CHICKPEAS, RAS EL HANOUT, OLIVES & DATES","Hero-ing the humble squash, I’ve cooked this Moroccan-inspired tagine in a casserole pan to make it more accessible, but please use a tagine if you have one. The dates melt to create an incredible sauce."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('dates-chickpeas-green-olives-salad','Dates, Chickpeas & Green Olives Salad','5-ingredient recipe: Hero-Ing The Humble Squash, I’Ve Cooked This Moroccan-Inspired Tagine In A Casserole Pan To Make It More Accessible, But Please Use A Tagine If You Have One. The Dates Melt To Create An Incredible Sauce.','mediterranean','easy',20,NULL,20,4,NULL,0,1,0,0,1,'none',1,1,5,1,'[{"name":"butternut squash","quantity":1,"unit":"","unit_norm":"","category":"dairy"},{"name":"Medjool dates","quantity":100,"unit":"g","unit_norm":"g","category":"produce"},{"name":"ras el hanout","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"or 2 tins of chickpeas","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"marinated green olives","quantity":100,"unit":"g","unit_norm":"g","category":"produce"}]','["Scrub the squash, then carefully halve lengthways and chop into 4cm chunks, roughly chopping the seeds (I like to leave the skin on because it’s nutty and delicious). Place the seeds in a large shallow casserole pan on a medium-high heat with a little drizzle of olive oil, tossing regularly – as soon as they start to pop, scoop them into a small bowl. Put the squash in the pan with 1 tablespoon of olive oil, and spend 10 minutes letting it get beautifully brown on each side, turning with tongs. Meanwhile, destone the dates and place in a bowl with 500ml of boiling kettle water.","Stir the ras el hanout into the pan, then pour in the chickpeas (juice and all) and add the dates and their soaking water. Tear in the olives (destone, if needed), then cover and cook for 20 minutes. Remove the lid, and let it simmer and reduce to a thick consistency – about 5 minutes (give it an extra 5 minutes if using tinned chickpeas). Season to perfection, then sprinkle over the crispy seeds and an extra pinch of ras el hanout. Serve as is, or with steamed couscous or bread on the side.","SQUASH TAGINE","CUCUMBER FRITTERS","SUPER-CRISP BATTER, CHEAT’S TZATZIKI & LEMON","These little morsels are wonderful, and make a fantastic starter or meze. What’s brilliant here is that you can elevate cucumber to a whole other level, but you can also swap in other seasonal veg."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('green-peppers-tomatoes-potatoes-bowl','Green Peppers, Tomatoes & Potatoes Bowl','5-ingredient recipe: The Sound Of Tunisian Kafteji Being Chopped In The Streets Is Epic. Typically The Vegetables Are Deep-Fried, Which Not Everyone Has Access To, So This Is My Healthier, Oven-Version Of This Great Dish.','mediterranean','easy',50,NULL,50,2,NULL,0,1,0,1,0,'none',1,0.677,3,0,'[{"name":"green peppers","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"large ripe tomatoes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Maris Piper potatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"}]','["1 tablespoon harissa or rose harissa, plus extra to serve","2 large eggs","Preheat the oven to 200°C. Trim, halve and deseed the peppers and halve the tomatoes, then place them in a large roasting tray, cut side up. Season with sea salt and black pepper, then roast for 35 minutes, or until tender. Meanwhile, scrub the potatoes and slice in half lengthways, then again into ½cm moons. Dress with 1 tablespoon of olive oil, season to taste, then spread out in a single layer on a large baking tray and roast for 25 minutes, or until golden and crisp. When the time’s up on the peppers and tomatoes, chop them until fine, discarding any tough skin. Scrape into a bowl, dress with the harissa and season to taste with salt, pepper and red wine vinegar. Fry the eggs to your liking and serve on the side, along with the crispy potatoes. Drizzle with a little harissa, to taste, and tuck in.","HOME-STYLE KAFTEJI","AUBERGINE FLATBREADS","HOT MARINATED OLIVES, TANGY FETA & DRIED OREGANO","Inspired by the flatbread work I’ve seen in Greek and Turkish street food, this makes a delicious lunch. It’s a super-quick dough, plus blackening aubergines gives them the most extraordinary flavour."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('aubergine-olives-bowl','Aubergine & Olives Bowl','5-ingredient recipe: Inspired By The Flatbread Work I’Ve Seen In Greek And Turkish Street Food, This Makes A Delicious Lunch. It’S A Super-Quick Dough, Plus Blackening Aubergines Gives Them The Most Extraordinary Flavour.','mediterranean','easy',25,NULL,25,2,NULL,0,1,0,1,0,'none',2,0.812,3,0,'[{"name":"large aubergine","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"self-raising flour","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mixed marinated olives","quantity":10,"unit":"","unit_norm":"","category":"produce"}]','["2 sprigs or 1 heaped teaspoon dried flowering oregano","50g feta cheese","Prick the aubergine, carefully blacken over a direct flame on the hob (or under the grill), turning with tongs until soft inside, then place in a bowl to cool. Meanwhile, put the flour in a bowl with a pinch of sea salt, then gradually add 100ml of water, mixing with a fork as you go. Tip on to a flour-dusted surface and knead for a few minutes until smooth, then cover and leave to briefly rest. Dust the surface with more flour, then split the dough in half and roll each piece out into an oval shape, roughly 20cm long. Place a large non-stick pan on a high heat, then lay in the dough and cook for 2½ minutes on each side, or until golden and cooked through – you’ll need to work in batches. Meanwhile, chop the olives (destone, if needed), plus any of the marinating ingredients.","Once you’ve cooked the flatbreads, put the pan back on a very low heat. Leaving the juices in the bowl, slice the aubergine in half lengthways, then use a teaspoon to scrape out the flesh into the bowl, discarding any skin. Add 1 tablespoon each of extra virgin olive oil and red wine vinegar and half the oregano. Stir and break up with a spoon, then season to perfection with salt and black pepper. Spoon the dressed aubergine on to the flatbreads. Scatter the chopped olives into the pan with 1 tablespoon of olive oil, allow to sizzle for 30 seconds, then spoon over the aubergine. Crumble over the feta, then put the remaining oregano sprig between your hands and rub together over the flatbreads so that the dried leaves and flowers rain down on top (or simply scatter).","AUBERGINE FLATBREADS","WINTER GREENS GNOCCHI","VIVID BLACK CABBAGE & MASCARPONE GORGONZOLA SAUCE","Typically gnocchi is served like a pasta course in Italy, but unconventionally I love serving it like you would a potato side, and this is the most surprising way to celebrate winter’s brassica bounty."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('gnocchi-cheese-salad','Gnocchi & Cheese Salad','5-ingredient recipe: Typically Gnocchi Is Served Like A Pasta Course In Italy, But Unconventionally I Love Serving It Like You Would A Potato Side, And This Is The Most Surprising Way To Celebrate Winter’S Brassica Bounty.','mediterranean','easy',20,NULL,20,4,NULL,0,1,0,0,1,'none',2,0.925,5,0,'[{"name":"shelled unsalted walnut halves","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"cavolo nero","quantity":400,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mascarpone cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"Gorgonzola cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"potato gnocchi","quantity":800,"unit":"g","unit_norm":"g","category":"produce"}]','["Toast the walnuts in a frying pan on a medium heat until golden, then put aside. Tear the stems out of the cavolo nero and discard, then blanch in boiling salted water for 4 minutes. Use tongs to carefully transfer two-thirds of the cavolo straight into a blender, leaving the pan of water on the heat. Remove the remaining cavolo to a board and roughly chop it. Add the mascarpone and most of the Gorgonzola to the blender and blitz until super-smooth, loosening with a splash of cooking water, if needed. Taste and season to perfection with sea salt and black pepper.","Cook the gnocchi in the pan of boiling water for 3 minutes, or until they float to the surface, then drain and toss in the pan with the green sauce and chopped cavolo. Crumble over and fold through most of the walnuts, break over the remaining Gorgonzola and walnuts, then either serve straight away or pop under the grill for a few minutes, until beautifully gratinated.","WINTER GREENS GNOCCHI","ROASTED CAULIFLOWER","CHEAT’S ROMESCO SAUCE & CRUSHED ROASTED ALMONDS","Life is better with romesco sauce in it! Whether you’re using it to celebrate beautiful vegetables, like this cauliflower, or eating it with fish, poultry or lamb, it’s a joy to make and a pleasure to eat."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('aubergines-garlic-lentils-bowl','Aubergines, Garlic & Lentils Bowl','5-ingredient recipe: This Is My Version Of A Popular Palestinian Dish. The Word ‘Rumman’ Translates As Pomegranate – This Traditionally Uses Pomegranate Molasses, But For Ease I’Ve Used Fresh Pomegranate, Which I Love.','mediterranean','easy',20,NULL,20,4,NULL,0,1,0,1,0,'none',1,0.925,5,0,'[{"name":"aubergines","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"baharat spice mix","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"dried brown lentils","quantity":175,"unit":"g","unit_norm":"g","category":"produce"},{"name":"large ripe pomegranate","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Quarter the aubergines, then cook for 6 minutes under a hot grill, or until softened and lightly charred, turning regularly. Remove to a board and roughly chop. Peel and finely slice the garlic, place it in a large non-stick frying pan on a medium heat with 1 tablespoon of olive oil and fry until lightly golden, then remove half to a plate for garnish. Add half the chopped aubergine to the pan with the rest of the garlic, along with the spice mix, cook for a few minutes, then add the lentils and 1.5 litres of water. Halve the pomegranate, then, holding one half cut side down in the palm of your hand, bash the back with a spoon so all the seeds tumble out into a bowl and add a good squeeze of juice. Squeeze the rest of the juice into the pan, then simmer on medium for 45 minutes, or until the lentils are tender.","When the time’s up, add the rest of the aubergine and most of the pomegranate seeds to the pan, stir well, then taste and season to perfection with sea salt and black pepper. Divide between plates, scatter with the crispy garlic and remaining pomegranate seeds, and finish with a drizzle of extra virgin olive oil, if you like. Delicious served with pitta bread and fresh herbs, if you have any.","RUMMANIYEH","TORTILLA FRITTATA","ROASTED PEPPER, TENDER ONION & POTATO, GOLDEN EGG, WATERCRESS","Inspired by the much-loved Spanish tortilla, this hybrid tortilla frittata is a beautiful gift for any home, and once you’ve mastered this method, try swapping in peas, artichokes or mushrooms."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('onion-potatoes-red-peppers-salad','Onion, Potatoes & Red Peppers Salad','5-ingredient recipe: Inspired By The Much-Loved Spanish Tortilla, This Hybrid Tortilla Frittata Is A Beautiful Gift For Any Home, And Once You’Ve Mastered This Method, Try Swapping In Peas, Artichokes Or Mushrooms.','mediterranean','easy',20,NULL,20,4,NULL,0,1,0,1,0,'none',1,1,5,1,'[{"name":"onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"potatoes","quantity":1,"unit":"kg","unit_norm":"kg","category":"produce"},{"name":"large eggs","quantity":5,"unit":"","unit_norm":"","category":"pantry"},{"name":"roasted red peppers","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"watercress","quantity":80,"unit":"g","unit_norm":"g","category":"produce"}]','["Peel and very finely slice the onion and potatoes, then toss and mix together. Pour 1cm of olive oil into a 24cm non-stick ovenproof frying pan on a medium heat. After 1 minute, add the potato and onion mix (don’t season at this stage, as it will draw the moisture out of the potatoes) and fry gently for 25 minutes, or until tender but mostly without colour, lightly tossing occasionally. Drain the potatoes and onions and leave to cool slightly. Beat the eggs in a bowl, add the cooked potato and onion, then gently fold together and leave for 5 minutes – the potato will start to absorb the egg, and you should see little bubbles surrounding the potato and onion. Drain and finely slice the peppers, then fold into the egg mixture and season to perfection with sea salt and black pepper. Preheat the oven to 160°C.","Quickly wipe out the pan, drizzle in a little olive oil, then place on a low heat. Pour the egg mixture straight into the pan and spread out. Leave for 5 minutes, then bake for 10 minutes. When the time’s up, remove from the oven, leave to rest in the pan for 5 minutes, then run a knife around the edge to loosen. Quickly and confidently turn it out, using a plate or flat lid that’s bigger than the pan, and serve sprinkled with a little salt and a pinch of watercress. Delicious hot or cold.","TORTILLA FRITTATA","STUFFED COURGETTES","MINT, FETA & GRAIN FILLING, TOMATO SAUCE","In the Med you cannot escape the love of stuffing veg, which is often misunderstood back at home – the bonus flavour and texture achieved from cooking veg inside veg is really quite remarkable."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('onions-olives-squash','Onions, Olives & Squash','5-ingredient recipe: Around The Med You’Ll See Cooking Methods That Extract The Sweetness From Veg, And With A Swig Of Vinegar You Can Achieve A Wonderful Sweet And Sour Flavour, Taking Humble Veg To The Next Level.','mediterranean','easy',55,NULL,55,4,NULL,0,1,0,0,1,'none',4,0.695,4,1,'[{"name":"butternut squash","quantity":1,"unit":"","unit_norm":"","category":"dairy"},{"name":"onions","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed marinated olives","quantity":150,"unit":"g","unit_norm":"g","category":"produce"},{"name":"pine nuts","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"}]','["500g mixed seasonal greens, such as rainbow chard, cavolo nero","Scrub the squash, then carefully halve lengthways and deseed (I like to leave the skin on because it’s nutty and delicious) and peel the onions. Slice and dice everything into 1cm cubes. Place in a large non-stick frying or casserole pan on a medium heat with 2 tablespoons of olive oil and cook for 25 minutes, stirring regularly. Stir in 2 tablespoons of red wine vinegar, then cover and cook for a further 25 minutes, or until sweet and tender. Chop the olives (destone, if needed), plus any of the marinating ingredients, and stir into the pan with the pine nuts. Season to perfection.","Meanwhile, prep the greens, discarding any tough stalks (I like to finely chop any tender stalks and add them to the squash pan). Blanch the greens in a large pan of boiling salted water for 30 seconds, until just tender but still full of life, then drain well and lay out on a clean tea towel. Once cool enough to handle, pile them in the centre, wrap them up, and wring out really well to remove the excess liquid. Roughly chop and divide between plates. Spoon over the squash mixture and serve at your will.","SQUASH AGRODOLCE","PIES & PARCELS","PLEASE SELECT A RECIPE","TAP FOR TEXT VERSION","PIES & PARCELS","SPINACH & FETA PIE","CRISPY PRAWN PARCELS","FETA FILO TURNOVERS","STUFFED CABBAGE LEAVES","STUFFED FOLDED FLATBREAD","TRAYBAKED PESTO PIZZA PIE","SPINACH & FETA PIE","FRAGRANT DILL & GOLDEN CRUNCHY SESAME SEEDS","Across Greece you’ll find wonderful savoury pies bursting with spinach, dill and feta, which inspired me to make this simple 5-ingredient variation. Heavy on the sesame, it’s a really beautiful thing."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('spinach-cheese-bowl','Spinach & Cheese Bowl','5-ingredient recipe: Across Greece You’Ll Find Wonderful Savoury Pies Bursting With Spinach, Dill And Feta, Which Inspired Me To Make This Simple 5-Ingredient Variation. Heavy On The Sesame, It’S A Really Beautiful Thing.','mediterranean','easy',40,NULL,40,6,NULL,0,1,0,0,1,'none',4,0.757,5,1,'[{"name":"frozen spinach","quantity":350,"unit":"g","unit_norm":"g","category":"produce"},{"name":"self-raising flour","quantity":500,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"bunches of dill","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"feta cheese","quantity":200,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"sesame seeds","quantity":75,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 220°C. Defrost the spinach and squeeze out any excess liquid. Put the flour in a bowl with a pinch of sea salt, then gradually add 325ml of water, mixing with a fork as you go. Once it comes together, use flour-dusted hands to knead until the bowl is clean and the dough is smooth, then transfer to a large oiled surface to rest. Finely chop the dill and spinach (stalks and all), then crumble over the feta and mix well with a pinch of black pepper.","Stretch out the dough on the oiled surface to roughly 40cm x 60cm – I use my hands but you can use a rolling pin, if you prefer. Carefully lift the dough so half of it sits in an oiled 30cm x 40cm tray, with the rest overhanging. Evenly spread the spinach mixture across the dough in the tray, leaving a 2cm gap around the edges. Carefully fold over the overhanging half and press or twist the edges to seal. Rub the top with olive oil, then sprinkle over the sesame seeds, firmly pressing and patting them into the dough. Bake on the bottom shelf of the oven for 25 minutes, or until beautifully golden. Delicious hot, at room temperature or cold from the fridge.","SPINACH & FETA PIE","CRISPY PRAWN PARCELS","DELICATE GOLDEN PASTRY, HARISSA OIL & ZINGY LEMON","My job in this recipe was to make an achievable pastry, similar to the classic brik pastry I tasted in Tunisia, but have struggled to make for years. This is super-fun, just be confident and give it a go."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-lemon-prawns-salad','Fish, Lemon & Prawns Salad','5-ingredient recipe: My Job In This Recipe Was To Make An Achievable Pastry, Similar To The Classic Brik Pastry I Tasted In Tunisia, But Have Struggled To Make For Years. This Is Super-Fun, Just Be Confident And Give It A Go.','mediterranean','easy',45,NULL,45,4,NULL,0,0,1,1,0,'fish',4,0.677,5,0,'[{"name":"strong bread flour","quantity":250,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large raw peeled king prawns","quantity":400,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"large egg","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"rose harissa","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Pour 150ml of boiling kettle water into a bowl with a large pinch of sea salt. Leave for 2 minutes to cool, then use a fork to mix in the flour until it’s dry enough to handle. Knead for 5 minutes, or until smooth and elastic. Rub a 50cm x 50cm clean surface lightly with olive oil. Place the dough on top, cover with the bowl and leave for 10 minutes to relax. Meanwhile, roughly chop half the prawns, and very finely chop the rest. Whisk the egg, and add the prawns. Finely grate in half the lemon zest and season with salt and black pepper. Loosen the harissa with 2 tablespoons of extra virgin olive oil.","Split the dough in half, then gently flatten one piece out as much as possible, leaving the other piece covered. Bit by bit, pull a corner up and gently ease out, stretch and pull it, repeating around 360° of the dough until you have a large, really thin sheet (roughly 40cm x 40cm). Slice the sheet into 6 rough rectangles, and dollop a little harissa in the middle of each. Divide half the prawn mixture between the rectangles, then confidently stretch each corner over the filling to make 6 rustic parcels, embracing their natural shape and patching up as needed. Place a large non-stick frying pan on a medium heat with 1 teaspoon of olive oil, then confidently add the briks (don’t worry if any of the filling spills out) and cook for 2½ minutes on each side, or until golden and crispy. Repeat with the remaining dough and filling. Serve with lemon wedges and an extra drizzle of harissa oil, if you like.","CRISPY PRAWN PARCELS","FETA FILO TURNOVERS","FRESH MARJORAM, RUNNY HONEY & PISTACHIO SPRINKLE","When I was a teenager visiting Cyprus on holiday, I was wowed by the recipes that would cook feta rather than just serve it in salads raw. For me, this is so incredibly simple, satisfying and impressive."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-cabbage-tomatoes','Pork, Cabbage & Tomatoes','5-ingredient recipe: I Absolutely Love Stuffed Cabbage Dishes But They Often Have Lots Of Ingredients And Stages, So I’Ve Really Stripped This Down With A Few Shortcuts To Make It Accessible And Achievable In A Busy Home.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,0,1,'pork',2,1,5,1,'[{"name":"large Savoy cabbage","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"spicy pork sausages","quantity":6,"unit":"","unit_norm":"","category":"meat"},{"name":"packets of cooked basmati rice","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"round Camembert cheese","quantity":1,"unit":"","unit_norm":"","category":"dairy"}]','["Preheat the oven to 180°C. Trim and click off 8 large cabbage leaves (I like the ones that are slightly yellower – save the rest for another day). Trim off any dry tough stalks and blanch the leaves in a large pan of boiling salted water for 6 minutes, or until bendy and foldable, then drain. Cool under cold running water, then pat dry with a clean tea towel. Meanwhile, remove the sausages from their skins, season with sea salt and black pepper, then scrunch and mix together with the rice. Divide into 8 pieces and squeeze each into a rough cylinder shape.","Open out the cabbage leaves and place a piece of sausage mix in the centre of each. Fold up and roll to create 8 parcels. Scrunch the tomatoes through clean hands into a large shallow casserole pan. Add ½ a tin’s worth of water, season to perfection and bring to a simmer on the hob. Carefully arrange the cabbage parcels on top, seam side down. Score around the rim of the Camembert and nestle into the centre, then bake for 30 minutes. Spoon most of the cheese over the cabbage parcels, then bake for a final 10 minutes, or until beautifully golden. To serve, sprinkle with an extra pinch of pepper and drizzle with extra virgin olive oil, if you like. Delicious with crusty bread or mash.","STUFFED CABBAGE LEAVES","STUFFED FOLDED FLATBREAD","MEDITERRANEAN VEG, FRESH MINT, PISTACHIO & TANGY FETA","Inspired by the traditional Turkish flatbreads called pide, this is my stripped-back expression that still packs a flavour punch, and gives you a portable lunch or dinner that can be enjoyed hot or cold."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mint-cheese-bowl','Mint & Cheese Bowl','5-ingredient recipe: Inspired By The Traditional Turkish Flatbreads Called Pide, This Is My Stripped-Back Expression That Still Packs A Flavour Punch, And Gives You A Portable Lunch Or Dinner That Can Be Enjoyed Hot Or Cold.','mediterranean','easy',20,NULL,20,4,NULL,0,1,0,0,1,'none',4,1,5,1,'[{"name":"frozen chargrilled Mediterranean veg","quantity":700,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"self-raising flour","quantity":400,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"shelled unsalted pistachios","quantity":30,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"feta cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"}]','["Preheat the oven to 200°C. Tip the frozen veg into a large non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil. Cook for 15 minutes, or until super-soft and sweet, stirring regularly. Meanwhile, put the flour in a bowl with a small pinch of sea salt, then gradually add 275ml of water, mixing with a fork as you go. Tip on to a flour-dusted surface and knead for a few minutes until smooth, then cover and leave to rest.","When the time’s almost up on the veg, pick and roughly chop the mint leaves. Bash or chop the pistachios until fine, then mix half into the veg along with most of the mint leaves. Crumble in half the feta and season to perfection. Divide the dough into 4 pieces, then roll each one out to roughly 12cm x 16cm. Spoon a quarter of the filling into the middle of each piece of dough, then pinch and crimp the shortest corners together (like in the picture). Transfer to an oiled baking tray and break over the remaining feta. Brush the dough with olive oil and bake for 20 minutes, or until golden and cooked through. Scatter over the remaining mint leaves and pistachios, to serve.","STUFFED FOLDED FLATBREAD","TRAYBAKED PESTO PIZZA PIE","FRAGRANT ARTICHOKES, SWEET CHERRY TOMATOES & MOZZARELLA","Who doesn’t love pizza? There are all sorts of wonderful variations out there and this cheat’s dough is a great last-minute go-to for an easy meal. Just a little prep and the oven does the rest for you."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fennel-tomatoes-cheese-salad','Fennel, Tomatoes & Cheese Salad','5-ingredient recipe: Making Italian Favourite Risotto With Just 5 Ingredients Requires A Staunch Commitment To Big Flavour. Juicy Mussels Are Often Under-Utilized, But They’Re Great Value, Healthy And A Super-Sustainable Choice.','mediterranean','easy',40,NULL,40,4,NULL,0,1,0,0,1,'fish',4,0.677,5,0,'[{"name":"large bulb of fennel","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"ripe tomatoes","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"risotto rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"mussels","quantity":1,"unit":"kg","unit_norm":"kg","category":"pantry"},{"name":"Parmesan cheese","quantity":30,"unit":"g","unit_norm":"g","category":"dairy"}]','["Trim the fennel, reserving any leafy tops in a bowl of cold water, then finely chop the rest and place in a large, deep pan on a medium heat with 2 tablespoons of olive oil. Cook for 10 minutes, or until soft, stirring regularly. Meanwhile, slice the tomatoes into sixths and remove the seedy core (to save waste, push the seeds through a coarse sieve to get all of the lovely sweet juices).","Fill and boil the kettle. Add the rice to the pan and stir for 2 minutes. Add a good splash of boiling kettle water and wait until it’s been fully absorbed before adding another, stirring constantly and adding more water for 12 minutes. Check the mussels, tap any open ones and if they don’t close, discard. Stir the mussels, tomatoes and any juices into the rice, then cover and cook for 7 minutes, or until the mussels have fully opened (discard any that remain closed) and the rice is cooked. Turn the heat off, finely grate and stir in the Parmesan with 2 tablespoons of extra virgin olive oil, and season to perfection. While the rice relaxes for a couple of minutes, I like to remove half the mussels from their shells. Serve sprinkled with the reserved fennel tops and an extra grating of Parmesan, if you like.","OOZY MUSSEL RISOTTO","PANCETTA PRAWN SKEWERS","JUICY TOMATO SALAD WITH CRISPY GARLIC & ROSEMARY","Celebrating a small handful of ingredients popular across much of southern Europe, this simple salad takes less than 20 minutes to put together. Use ripe in-season tomatoes for the very best flavour."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-tomatoes-garlic','Pork, Tomatoes & Garlic','5-ingredient recipe: Celebrating A Small Handful Of Ingredients Popular Across Much Of Southern Europe, This Simple Salad Takes Less Than 20 Minutes To Put Together. Use Ripe In-Season Tomatoes For The Very Best Flavour.','mediterranean','easy',18,NULL,18,2,NULL,0,0,0,1,0,'pork',4,0.925,5,0,'[{"name":"ripe mixed-colour tomatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"large raw shell-on king prawns","quantity":8,"unit":"","unit_norm":"","category":"seafood"},{"name":"smoked pancetta","quantity":4,"unit":"rashers","unit_norm":"rashers","category":"meat"},{"name":"large woody sprigs of rosemary","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"}]','["Finely slice the tomatoes and arrange nicely on serving plates. Sprinkle with a little sea salt and black pepper, then drizzle with 1 tablespoon of extra virgin olive oil and ½ a tablespoon of red wine vinegar. Peel the prawns, leaving the heads and tails on, then I like to run a small sharp knife down the back of each, discarding the vein, so they butterfly when they cook. Cut each rasher of pancetta in half, and wrap one piece around each prawn. Strip most of the leaves off the rosemary sprigs, then use the stalks to skewer up the prawns (or use wooden skewers). Peel and finely slice the garlic.","Put a large non-stick frying pan on a high heat and, once hot, add the prawns with a little olive oil. Cook for 2 minutes, then flip over and add the rosemary leaves. Cook for a further 2 minutes, or until golden and crisp, adding the garlic for the final minute. Serve everything on top of the tomatoes.","PANCETTA PRAWN SKEWERS","SIZZLING SQUID","CHORIZO, TOMATO, MINT & LEMON SAUCE","All over the Mediterranean you see really big and bold combinations of surf and turf, and how beautifully it works together – this recipe comes with the harmony of all my favourite ingredients."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-tomatoes-mint-salad','Pork, Tomatoes & Mint Salad','5-ingredient recipe: All Over The Mediterranean You See Really Big And Bold Combinations Of Surf And Turf, And How Beautifully It Works Together – This Recipe Comes With The Harmony Of All My Favourite Ingredients.','mediterranean','easy',16,NULL,16,2,NULL,0,0,0,1,0,'pork',4,0.925,5,0,'[{"name":"large super-ripe tomatoes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"whole squid","quantity":300,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"chorizo or spicy sausage","quantity":70,"unit":"g","unit_norm":"g","category":"meat"},{"name":"bunch of mint","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Finely grate the tomatoes on a box grater, discarding the skin. Slice into the squid and open it out like a book, lightly score on the inside at ½cm intervals in a criss-cross fashion, slice off and reserve the tentacles, then season with sea salt and black pepper. Slice the chorizo (or break apart if using spicy sausage) and pick the mint leaves. Preheat a large non-stick frying pan on a very high heat. After 3 minutes, drizzle in 1 tablespoon of olive oil, lay the squid in the pan scored side down and use a fish slice to press down on it for 1 minute, then add the tentacles and the chorizo (or spicy sausage). Scatter in half the mint leaves and cook for 3 minutes, tossing regularly.","Remove the scored squid to a plate, then tip the tomatoes into the pan and squeeze in a little lemon juice. Cook for a further 2 minutes, or until thickened and reduced, then divide between plates. Slice the scored squid ½cm thick and scatter over the sauce along with the rest of the mint leaves. Serve with the rest of the lemon cut into wedges, for squeezing over.","SIZZLING SQUID","STICKY LEMONY PRAWNS","CHARRED COURGETTES, MIXED GRAINS & PISTACHIOS","The way the Greeks embrace grains inspired me to put this dish together. Celebrating courgettes, lemon and pistachios, as well as beautiful prawns, the interesting way of serving it makes it surprising."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-courgettes-lemons-salad','Fish, Courgettes & Lemons Salad','5-ingredient recipe: The Way The Greeks Embrace Grains Inspired Me To Put This Dish Together. Celebrating Courgettes, Lemon And Pistachios, As Well As Beautiful Prawns, The Interesting Way Of Serving It Makes It Surprising.','mediterranean','easy',28,NULL,28,2,NULL,0,0,1,1,0,'fish',4,0.812,5,0,'[{"name":"courgettes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"large raw shell-on king prawns","quantity":8,"unit":"","unit_norm":"","category":"seafood"},{"name":"shelled unsalted pistachios","quantity":30,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"lemons","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"cooked mixed grains","quantity":1,"unit":"packet","unit_norm":"packet","category":"pantry"}]','["Put a large non-stick frying pan on a high heat. Trim and very finely slice the courgettes into rounds and – in batches – lightly char in the hot dry pan in a single layer on one side only, removing to a bowl once done. Meanwhile, peel the prawns, leaving the heads and tails on, then I like to run a small sharp knife down the back of each, discarding the vein, so they butterfly when they cook. Toss with 1 tablespoon of olive oil and season with sea salt and black pepper. Bash or chop the pistachios until fairly fine, then use a speed-peeler to remove strips of peel from one of the lemons.","When all the courgettes are done, add the grains to the bowl with the juice of 1 lemon, 2 tablespoons of extra virgin olive oil and half the pistachios, then season to perfection. Turn the heat down to medium-high, throw in the prawns and lemon peel and fry for 1 minute. Flip the prawns, then tip over the grain mixture and use a spatula to press the grains in and around the prawns. Cook for 3 minutes, then cover with a serving plate that just sits inside the pan and confidently flip out – don’t worry if it breaks apart. Scatter over the remaining pistachios and serve with lemon wedges for squeezing over.","STICKY LEMONY PRAWNS","BLACK SQUID","CRISPY OREGANO, GARLIC, BLACK PUDDING & RED WINE","The Spanish love black pudding and seafood combinations – as do I – which has inspired this very quick, deep and delicious stew that really contrasts and elevates the delicate nature of the squid."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-garlic-squid-salad','Fish, Garlic & Squid Salad','5-ingredient recipe: The Spanish Love Black Pudding And Seafood Combinations – As Do I – Which Has Inspired This Very Quick, Deep And Delicious Stew That Really Contrasts And Elevates The Delicate Nature Of The Squid.','mediterranean','easy',16,NULL,16,2,NULL,0,0,1,1,0,'fish',2,1,5,0,'[{"name":"whole squid","quantity":300,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"bunch of oregano","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"black pudding","quantity":200,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"red wine","quantity":200,"unit":"ml","unit_norm":"ml","category":"pantry"}]','["Trim off and reserve the squid tentacles, then slice up the rest, tossing it in a little olive oil and sea salt. Drizzle 1 tablespoon of olive oil into a large non-stick frying pan on a medium-high heat, pick in the oregano and fry until crispy, then remove to a plate. Peel and slice the garlic, add to the pan and fry until lightly golden. Crumble in the black pudding, discarding the skin, then add the squid tentacles and cook for a further 3 minutes, breaking up the black pudding with a spoon as you go. Stir in the wine, allow it to bubble and cook away, then add a good splash of water (to loosen to a ragù consistency) and season to perfection with salt and black pepper. Turn the heat down to medium-low and lay over the sliced squid. Pop the lid on and cook for a final 5 minutes, or until the squid is beautifully tender. Serve sprinkled with the crispy oregano and a drizzle of extra virgin olive oil, if you like.","BLACK SQUID","EPIC PRAWNS & BEANS","HARISSA & GARLICKY SOURDOUGH CROUTONS","Such a quick and delicious meal – the bright red colour of Tunisian harissa never fails to brighten up a humble jar or tin of beans. To contrast that, simply cooked garlicky prawns and croutons. Wow!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-garlic-beans-salad','Fish, Garlic & Beans Salad','5-ingredient recipe: Such A Quick And Delicious Meal – The Bright Red Colour Of Tunisian Harissa Never Fails To Brighten Up A Humble Jar Or Tin Of Beans. To Contrast That, Simply Cooked Garlicky Prawns And Croutons. Wow!','mediterranean','easy',20,NULL,20,2,NULL,0,0,1,1,0,'fish',4,1,5,0,'[{"name":"sourdough bread","quantity":175,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large raw peeled king prawns","quantity":300,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"garlic","quantity":6,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"or 1 tin of cannellini beans","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"harissa or rose harissa","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Slice the bread into 2.5cm cubes. Place in a large non-stick frying pan on a high heat and toast until golden, turning regularly. Meanwhile, devein the prawns. Place in a bowl with 1 tablespoon of olive oil and a pinch of sea salt and black pepper, then peel and finely slice the garlic, add to the prawns and toss together. Tip the beans into a saucepan (juices and all), add the harissa, then cover and simmer gently for 5 minutes, or until thickened, stirring occasionally. As soon as the bread is golden, tip the contents of the bowl into the frying pan. Add a splash of red wine vinegar, then cook for 2 minutes, or until the prawns are just cooked, tossing regularly. Taste the beans and season to perfection, then divide between plates. Top with the prawns and crispy croutons, and get stuck in.","EPIC PRAWNS & BEANS","CALAMARI STEW","TOMATOES, PEAS, BEANS & CRÈME FRAÎCHE RIPPLE","I grew up thinking of stews as being mainly meat-based, but in the Mediterranean they have some incredible seafood ones. I’ve used frozen peas and beans here, but swap in fresh or jarred, if you like."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-garlic-pea','Fish, Garlic & Pea','5-ingredient recipe: I Grew Up Thinking Of Stews As Being Mainly Meat-Based, But In The Mediterranean They Have Some Incredible Seafood Ones. I’Ve Used Frozen Peas And Beans Here, But Swap In Fresh Or Jarred, If You Like.','mediterranean','easy',40,NULL,40,4,NULL,0,0,1,0,1,'fish',1,0.752,5,0,'[{"name":"whole squid","quantity":600,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"frozen bean and pea mix","quantity":320,"unit":"g","unit_norm":"g","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"half-fat crème fraîche","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"}]','["Place the squid in a large non-stick frying pan over a medium heat with 1 tablespoon of olive oil and fry for 3 minutes, turning regularly. Peel and finely slice the garlic, add to the pan and fry for a further 3 minutes, then go in with the frozen beans and peas. Scrunch in the tomatoes through clean hands and give everything a good stir, then cover and stew gently over a low heat for 30 minutes, or until the squid is beautifully tender, stirring occasionally. Remove and slice the squid into chunky pieces, stir it back through the stew and season to perfection with sea salt and black pepper. Ripple through the crème fraîche, then drizzle with a little extra virgin olive oil and serve with crusty bread, if you like.","CALAMARI STEW","PRAWN RICE","VERY SLOW-COOKED ONIONS, SWEET PEPPERS & LEMON","In Catalonia you’ll find an abundance of incredible rice dishes before you even see a paella, so I’ve taken some of the learning from my travels to produce this very delicious, simple dish that people love."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-onions-peppers','Fish, Onions & Peppers','5-ingredient recipe: In Catalonia You’Ll Find An Abundance Of Incredible Rice Dishes Before You Even See A Paella, So I’Ve Taken Some Of The Learning From My Travels To Produce This Very Delicious, Simple Dish That People Love.','mediterranean','easy',20,NULL,20,4,NULL,0,0,1,1,0,'fish',4,1,5,1,'[{"name":"onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"large raw shell-on king prawns","quantity":12,"unit":"","unit_norm":"","category":"seafood"},{"name":"mixed-colour peppers","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"paella rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Boil the kettle. Peel and finely chop the onions, then place in a casserole pan with 2 tablespoons of olive oil on a medium-low heat and cook for 30 minutes, or until dark golden brown, stirring regularly (this base is truly important to the deep delicious flavour – the darker the better). Meanwhile, peel away the shells from 7 of the prawns, then remove the heads (most of the amazing flavour comes from the heads), devein, roughly chop and put aside for later. Place the heads and shells in a small pan with 1 tablespoon of olive oil. Cook for 2 minutes, squashing and turning, to create a delicious prawn oil, then add 1 litre of boiling kettle water and leave to simmer and reduce slightly to make a stock.","Meanwhile, deseed the peppers and dice into 1cm pieces. When the time’s up on the onions, add the rice to the pan and cook for 2 minutes. Strain the stock into a large measuring jug, top up with boiling water until you have 800ml, then tip into the rice pan. Cook for 15 minutes with the lid on, stirring in the peppers for the last 5 minutes, then add the chopped prawns, give everything a good stir and season to perfection with sea salt and black pepper. Peel and devein the remaining prawns, leaving the heads and tails on, then arrange nicely on top and use a spatula to press them down into the rice. Cover and cook for a further 5 minutes, then uncover. When you hear the rice start to crackle a little bit, it’s time to serve up. Cut the lemon into wedges for squeezing over.","PRAWN RICE","CROATIAN MUSSELS","GARLIC BREADCRUMBS, WHITE WINE & TOMATOES","Super-quick and easy, this recipe was inspired by a Croatian seafood dish called buzara, which means stew. I’ve added tomatoes, which are great mates with wine, herbs and garlicky breadcrumbs."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('garlic-parsley-cherry-tomatoes','Garlic, Parsley & Cherry Tomatoes','5-ingredient recipe: Super-Quick And Easy, This Recipe Was Inspired By A Croatian Seafood Dish Called Buzara, Which Means Stew. I’Ve Added Tomatoes, Which Are Great Mates With Wine, Herbs And Garlicky Breadcrumbs.','mediterranean','easy',14,NULL,14,2,NULL,0,1,0,1,0,'fish',2,1,5,1,'[{"name":"garlic bread","quantity":50,"unit":"g","unit_norm":"g","category":"produce"},{"name":"mussels","quantity":600,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"flat-leaf parsley","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"ripe mixed-colour cherry tomatoes","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"white wine","quantity":150,"unit":"ml","unit_norm":"ml","category":"pantry"}]','["Whiz the garlic bread into fine breadcrumbs and toast in a large casserole pan on a medium heat, stirring regularly. Meanwhile, check the mussels – if any are open, give them a tap and they should close, if they don’t discard them. Finely chop the parsley (stalks and all), and halve the tomatoes. When the breadcrumbs are golden, remove most of them to a plate. Turn the heat up to high, add the mussels, parsley, wine and tomatoes along with 1 tablespoon of olive oil, and cook for 2 minutes. Give it a really good stir, then add 50ml of water and put the lid on for 3 minutes.","When all the mussels have opened and are soft and juicy, they’re ready. If any remain closed, discard them. Plate up, drizzle with a little extra virgin olive oil and serve the rest of the crispy breadcrumbs on the side for scattering over.","CROATIAN MUSSELS","SEA & MOUNTAIN SKEWERS","PRAWNS, HAM & MUSHROOMS, BURNT LEEKS & CREAMY BEANS","Right the way across the Mediterranean, foods from the sea and mountains collide in truly beautiful ways. And, even more fascinatingly, the friendship between prawns and mushrooms here is divine."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-leeks-mushrooms-salad','Pork, Leeks & Mushrooms Salad','5-ingredient recipe: Right The Way Across The Mediterranean, Foods From The Sea And Mountains Collide In Truly Beautiful Ways. And, Even More Fascinatingly, The Friendship Between Prawns And Mushrooms Here Is Divine.','mediterranean','easy',45,NULL,45,2,NULL,0,0,0,1,0,'pork',4,0.615,5,0,'[{"name":"medium leeks","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"large raw shell-on king prawns","quantity":8,"unit":"","unit_norm":"","category":"seafood"},{"name":"mixed mushrooms","quantity":160,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Pata Negra or quality Spanish ham","quantity":40,"unit":"g","unit_norm":"g","category":"meat"},{"name":"white beans","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"}]','["Preheat the oven to 180°C. Place the whole leeks straight on to the bars of the oven for 40 minutes, or until blackened. Meanwhile, remove the prawn heads, squashing the juices into a small bowl (sounds gross, but trust me!). Peel away the shells, leaving the tails on, then devein and put aside. Place the prawn shells and heads into a small non-stick pan with 4 tablespoons of olive oil. Cook for 10 minutes on a medium heat, squashing and turning regularly, to create a prawn oil, then discard the shells and heads. Meanwhile, finely slice any larger mushrooms and tear the Pata Negra into small pieces (if needed), then carefully divide and thread the prawns, mushrooms and Pata Negra between 4 skewers (I sometimes like to use long woody rosemary sprigs), not packing them too tightly together.","Strip off and discard the outer leaves from the leeks, then finely chop the rest and place in a medium non-stick frying pan with the beans (juices and all) and the reserved prawn juices. Bring to a simmer, then season to perfection with sea salt and 1 tablespoon of red wine vinegar, adding a splash of water to loosen, if needed. Cook the skewers in a large non-stick frying pan on a medium-high heat (or on a barbecue) with a drizzle of olive oil for 5 minutes, or until golden and just cooked through, turning occasionally and lightly pressing down with a fish slice. Spoon the beans on to a warm serving platter, then place the skewers on top and drizzle with the prawn oil, to serve.","SEA & MOUNTAIN SKEWERS","FISH","PLEASE SELECT A RECIPE","TAP FOR TEXT VERSION","FISH","BREAM & ROASTED GRAPES","SEARED TUNA SALAD","STEAMED FISH AÏOLI","HARISSA SEA BASS","LIME-CURED SEA BASS","QUICK SALT COD","WHITE FISH STEW","SIMPLE STEAMED FISH","ELEGANT FISH CARPACCIO","CRISPY-SKINNED MACKEREL","BREAM & ROASTED GRAPES","CREAMY MUSTARD SAUCE & WILTED BABY SPINACH","Cooking with a Greek chef who specialized in historical regional cooking, I was surprised to see him roast grapes over fire, but the acidity and sweetness is amazing with fish, and this is my expression."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-green-beans-olives-salad','Beef, Green Beans & Olives Salad','5-ingredient recipe: Fresh Tuna Is So Delicious And Quick To Cook. Blistering The Green Beans Is A Game-Changer. I’M Feeling The Vibes Of A French Niçoise Salad, But The Tangy Feta-Dressed Potatoes Nod To The Greek Islands.','mediterranean','easy',14,NULL,14,2,NULL,0,0,0,0,1,'beef',4,0.925,5,0,'[{"name":"green beans","quantity":220,"unit":"g","unit_norm":"g","category":"produce"},{"name":"mixed marinated olives","quantity":10,"unit":"","unit_norm":"","category":"produce"},{"name":"tuna steaks","quantity":2,"unit":"","unit_norm":"","category":"seafood"},{"name":"new potatoes","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"},{"name":"feta cheese","quantity":70,"unit":"g","unit_norm":"g","category":"dairy"}]','["Put a large non-stick frying pan on a high heat. Trim the beans and place in the pan until nicely charred, tossing occasionally. Rub ½ a tablespoon of the olive marinade or olive oil over the tuna. Tear up the olives (destone, if needed). Drain and slice the potatoes. Smash up the feta with a splash of its brine in a pestle and mortar or a blender until smooth, adding a splash of water to loosen, if needed. Season with black pepper, toss with the potatoes, then divide between plates.","When the beans are done, toss with the torn olives and a small drizzle each of red wine vinegar and extra virgin olive oil, and scatter over the potatoes. Return the pan to a high heat and sear the tuna for 1 minute on each side, so it’s beautifully golden on the outside but blushing pink in the middle. To serve, I like to tear the tuna over the salad, then finish with an extra pinch of pepper.","SEARED TUNA SALAD","STEAMED FISH AÏOLI","NEW POTATOES, BABY CARROTS & FRESH BASIL","In the south of France they serve a popular dish of boiled seasonal veg and eggs, garlic mayo and salt cod called ‘aïoli’ (meaning the whole dish, not just the mayo), and this is my 5-ingredient version."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-potatoes-parsley-salad','Fish, Potatoes & Parsley Salad','5-ingredient recipe: Although Portugal Doesn’T Have A Coastline In The Med, They’Re Included, And This Take On Fish And Chips, Inspired By Bacalhau À Brás, Is My Stripped-Back Version Of Their Much-Loved Comfort Food Dish.','mediterranean','easy',30,NULL,30,2,NULL,0,0,1,1,0,'fish',2,0.812,5,0,'[{"name":"cod fillets","quantity":2,"unit":"","unit_norm":"","category":"seafood"},{"name":"Maris Piper potatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"large eggs","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"bunch of flat-leaf parsley","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"black olive tapenade","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"produce"}]','["Season the cod very generously all over with sea salt (don’t worry, we’ll rinse it away later) and leave aside. Meanwhile, scrub and chop the potatoes into 1cm cubes, then place in a large non-stick frying pan on a medium heat with 2 tablespoons of olive oil and a pinch of salt and black pepper. Cook for 10 minutes, or until slightly golden, tossing occasionally.","Rinse the fish and pat dry with kitchen paper (this fast salting will season the fish, but most importantly will make it flakier and juicier). Push the potatoes to one side of the pan, then add the fish and cook for 3½ minutes on each side, or until just cooked, not forgetting to take care of the potatoes. Meanwhile, beat the eggs together in a bowl. Pick half the parsley leaves and put aside, then finely chop the rest (stalks and all) and add to the eggs. Remove the pan from the heat, transfer the fish to a plate, then pour the egg mixture over the crispy potatoes in the pan. Toss vigorously together for 30 seconds (the residual heat of the pan will just cook the eggs to a silky-soft scramble), then divide between serving plates. Remove and discard the fish skin, and flake the flesh over the potatoes, then dot over the olive tapenade. Scatter with the remaining parsley leaves, dressed with a little extra virgin olive oil and red wine vinegar. Delicious served with a fresh green salad.","QUICK SALT COD","WHITE FISH STEW","SILKY SLOW-COOKED LEEK & LEMON SAUCE","This unassuming-looking dish is an incredibly delicious way to cook and serve fish, using the classic Greek technique of turning the cooking broth into a silky sauce using the liaison of eggs and lemon."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-peppers-leek','Fish, Peppers & Leek','5-ingredient recipe: Inspired By Flavours That Will Transport You To The Greek Coast, This Delicate Dish Simply Celebrates White Fish Fillets. Easy To Halve If You’Re Serving Two, You’Ll Be Glad To Have This One Up Your Sleeve.','mediterranean','easy',32,NULL,32,4,NULL,0,0,1,1,0,'fish',2,0.892,5,1,'[{"name":"white fish fillets","quantity":4,"unit":"","unit_norm":"","category":"seafood"},{"name":"mixed-colour peppers","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"large leek","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"bunch of oregano","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"},{"name":"large juicy orange","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["To amplify the flakiness, very generously dust the fish with sea salt (don’t worry, we’ll rinse it away later) and leave aside. Put a large shallow casserole pan on a medium heat. Chop the peppers into 2cm chunks, discarding the seeds and stalks, adding them to the pan as you go with 2 tablespoons of olive oil. Quarter the leek lengthways and wash, then slice 2cm thick. Add to the pan, season with salt and black pepper, and cook for 15 minutes, or until sweet and lightly golden, stirring regularly and adding splashes of water, if needed. Strip the oregano leaves into a pestle and mortar with a pinch of salt and pound into a paste. Squeeze in half the orange juice, then add 1 tablespoon of red wine vinegar and 2 tablespoons of extra virgin olive oil and muddle together.","Rinse the fish and pat dry with kitchen paper. Nestle the fish into the veg, squeeze in the remaining orange juice and add 100ml of water, then cover the pan, reduce the heat to low and cook for 7 minutes, or until the fish is just cooked. Drizzle the orange dressing over the fish and veg and serve.","SIMPLE STEAMED FISH","ELEGANT FISH CARPACCIO","FRESH BREAM, GREEN CHILLI, ZINGY LIME, GRAPES & ROCKET","We all need a great fishmonger in our lives, whether it’s a shop, market, van or online. Eating raw fish is not rocket science, it’s incredibly easy, healthy and delicious, but it needs to be super-fresh."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-potatoes-parsley-bowl','Chicken, Potatoes & Parsley Bowl','5-ingredient recipe: Herby Salsas Are Much Loved In Catalan Cooking, So, Inspired By A Recent Trip To Barcelona, I’Ve Embellished This Chicken And These Rich, Stock-Cooked Potatoes With A Vibrant Nutty Number.','mediterranean','easy',35,NULL,35,4,NULL,0,0,0,1,0,'chicken',2,0.892,5,1,'[{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"potatoes","quantity":1,"unit":"kg","unit_norm":"kg","category":"produce"},{"name":"flat-leaf parsley","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"bulb of garlic","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"blanched hazelnuts","quantity":40,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 180°C. Rub the chicken all over with olive oil, sea salt and black pepper, then brown in a large casserole pan on a high heat, removing it to a plate once golden all over (roughly 5 minutes). Meanwhile, peel the potatoes and chop into 5cm chunks. Pour 700ml of water into the pan, then add the parsley stalks, garlic bulb (reserving 1 garlic clove for later) and the potatoes. Bring to the boil on the hob for 15 minutes, season lightly, then pop the chicken on top and place in the oven for 1 hour 15 minutes, or until the chicken is golden and cooked through.","Meanwhile, peel and finely chop the reserved garlic clove, very finely chop the parsley leaves, and roughly chop the hazelnuts. Decant into a small serving bowl, stir in 3 tablespoons of extra virgin olive oil and 4 tablespoons of water, and season to perfection. Transfer the chicken and potatoes to a serving platter, spoon over the herby salsa and serve the garlic bulb on the side, for squeezing over.","POT-ROAST CHICKEN","BAHARAT CHICKEN SHISH","SPICED YOGHURT MARINADE, LEMON & ROASTED GARLIC","Inspired by the Turkish shish, this is a very simple, delicious kebab that anyone can make, using a blend of fragrant spices. I love the contrast between the crispy outside and the juicy tender inside."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-potatoes-peppers-salad','Chicken, Potatoes & Peppers Salad','5-ingredient recipe: Roasting Chicken Directly On The Oven Bars Means You Get Super-Crispy Skin And All The Tasty Juices Rain Down On To The Lucky Veg Below. Spanish Favourite Paprika Gives You Big Flavour All Round.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,0.925,5,0,'[{"name":"potatoes","quantity":1,"unit":"kg","unit_norm":"kg","category":"produce"},{"name":"mixed-colour peppers","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"heaped tablespoon smoked paprika","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"thyme","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"pantry"}]','["Preheat the oven to 200°C. Scrub the potatoes and chop into 3cm chunks. Chop the peppers roughly the same size, removing the seeds and stalks. Place it all in a large roasting tray and toss with 1 tablespoon of olive oil and a little sea salt and black pepper. Using a large sharp knife, carefully cut the chicken in half. Drizzle with 1 tablespoon each of olive oil and red wine vinegar, then rub all over with the paprika and a pinch of salt and pepper. Put the tray of veg on the bottom shelf of the oven, sit the chicken halves skin side up directly on the oven shelf above, then roast for 40 minutes.","When the time’s up, rub the thyme with a drizzle of olive oil. Pull out the tray of veg, give it a good shake, then strip and scatter over half the thyme. Lay the rest of the thyme sprigs on top of the chicken and roast for a final 5 minutes, or until everything is beautifully cooked through, then serve.","CRISPY PAPRIKA CHICKEN","ROAST DUCK WITH GRAPES","GROUND CLOVES, CARAMELIZED ONIONS & ROSEMARY","I was enchanted by the grilling, roasting and serving of fresh grapes with rich meat or fish dishes I saw on some of the Greek islands. It works incredibly well – naturally sweet and sour. So delicious!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('duck-red-onions-grapes-salad','Duck, Red Onions & Grapes Salad','5-ingredient recipe: I Was Enchanted By The Grilling, Roasting And Serving Of Fresh Grapes With Rich Meat Or Fish Dishes I Saw On Some Of The Greek Islands. It Works Incredibly Well – Naturally Sweet And Sour. So Delicious!','mediterranean','easy',20,NULL,20,6,NULL,0,0,0,1,0,'duck',2,0.925,5,0,'[{"name":"whole duck","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"ground cloves","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"red onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"rosemary","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"pantry"},{"name":"mixed-colour seedless grapes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"}]','["Preheat the oven to 180°C. In a large roasting tray, rub the duck and neck (reserve the livers, kidneys and heart) all over with 1 tablespoon of olive oil, the cloves and a really good pinch of sea salt and black pepper. Peel and quarter the onions, throw them into the tray with the neck and toss together, then add 2 tablespoons of water and sit the duck on top. Stuff half the rosemary into the cavity, then roast for 1 hour 30 minutes. Remove from the oven, skim off most of the fat (reserve it in a jam jar) and baste the duck with the tray juices. Pick in the grapes, then roast for a further 30 minutes, or until the duck legs are tender. Remove the duck to a serving platter and spoon half the grapes and onions into a bowl. Place the tray over a medium heat, pour in 500ml of boiling kettle water, and simmer for 5 minutes, mashing the grapes and scraping up any sticky goodness from the bottom of the tray.","Meanwhile, chop the livers, kidneys and heart into 1cm dice. Drizzle a good splash of the duck fat into a non-stick saucepan over a medium heat. Pick in the remaining rosemary leaves, leave to sizzle until crisp, then remove to kitchen paper. Add the chopped giblets and toss over the heat for 3 minutes, or until cooked through. Pass the contents of the tray through a coarse sieve into the pan and season to taste. Add the reserved grapes and onions, toss together over a low heat, then spoon over the duck and sprinkle with rosemary. Pour the gravy into a jug and serve alongside.","ROAST DUCK WITH GRAPES","GARLIC CHICKEN","CREAMY CHICKPEAS, SPINACH & SUMAC","Inspired by some of the wonderful flavours of Lebanon, this quick dish is perfect for an easy meal. Hunting out nice fat jarred chickpeas is game-changing when it comes to both flavour and texture."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-garlic-chickpeas-salad','Chicken, Garlic & Chickpeas Salad','5-ingredient recipe: Inspired By Some Of The Wonderful Flavours Of Lebanon, This Quick Dish Is Perfect For An Easy Meal. Hunting Out Nice Fat Jarred Chickpeas Is Game-Changing When It Comes To Both Flavour And Texture.','mediterranean','easy',18,NULL,18,2,NULL,0,0,0,1,0,'chicken',1,0.925,5,0,'[{"name":"garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"skinless chicken breasts","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"chickpeas","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"baby spinach","quantity":250,"unit":"g","unit_norm":"g","category":"produce"},{"name":"heaped teaspoon sumac","quantity":1,"unit":"","unit_norm":"","category":"pantry"}]','["Peel the garlic cloves and slice lengthways, then place in a large non-stick frying pan on a high heat with 1 tablespoon of olive oil, stirring regularly. Slice each chicken breast lengthways into 3 strips, then toss with a pinch of sea salt and black pepper. Once the garlic is nicely golden, quickly remove from the pan with a slotted spoon, leaving the flavoured oil behind. Go in with the chicken and cook for 5 minutes, or until golden and cooked through, turning regularly.","Remove the chicken from the pan and tip in the chickpeas (juices and all). Add the spinach, along with most of the garlic and 1 tablespoon of red wine vinegar, then toss over the heat until the spinach has wilted and the chickpeas are hot through. Season to perfection with salt and pepper, then return the chicken to the pan and finish with the reserved garlic and a generous dusting of sumac.","GARLIC CHICKEN","LEMON-TZATZIKI CHICKEN","FLUFFY PAN-JUICE RICE, JAMMY ONIONS & ROASTED LEMONS","A brilliant Greek-inspired one-pan family dish. Tzatziki makes a fantastic ready-to-go marinade – it’s untraditional used like this, but I can totally vouch for its deliciousness and ability to tenderize meat."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-lemons-onions-bowl','Chicken, Lemons & Onions Bowl','5-ingredient recipe: A Brilliant Greek-Inspired One-Pan Family Dish. Tzatziki Makes A Fantastic Ready-To-Go Marinade – It’S Untraditional Used Like This, But I Can Totally Vouch For Its Deliciousness And Ability To Tenderize Meat.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,1,5,1,'[{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"tubs of tzatziki","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"lemons","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"mixed-colour onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"basmati rice","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"}]','["Use a sharp knife to carefully cut down the back of the chicken, so you can open it out flat. Rub half the tzatziki all over the chicken with the juice of ½ a lemon and good pinch of sea salt and black pepper, then cover and leave to marinate in the fridge for at least 2 hours, preferably overnight. Preheat the oven to 180°C. Peel the onions, then very finely chop half an onion and place in a bowl with the juice of ½ a lemon and a pinch of salt to make a pickle. Quarter the rest of the onions and place in a deep tray or ovenproof pan, then halve and add the remaining lemon. Place the chicken skin side up on top (it should fit snugly) and drizzle with ½ a tablespoon of olive oil. Roast for 1 hour 10 minutes, or until beautifully golden and the leg meat pulls easily away from the bone.","When the time’s up, remove the chicken with half the roasted onions and one jammy lemon half to a board for later. Using tongs, carefully squeeze the other jammy lemon half into the pan of tray juices, then cut off and discard the white pith and finely slice the skin, along with the rest of the onions. Put them back into the pan or tray along with the rice and 600ml of boiling salted water, then cover and cook on the hob on a medium-low heat for 12 minutes, or until tender. Spoon the rice into a serving dish, place the chicken, any resting juices and the reserved roasted onions on top, and spoon over the remaining tzatziki. Drizzle with 1 tablespoon of extra virgin olive oil and serve with the pickle and the reserved cooked lemon half, for squeezing over.","LEMON-TZATZIKI CHICKEN","CHICKEN & MERGUEZ STEW","BEAUTIFUL BAY MARINADE, SLOW-COOKED ONIONS & BEANS","This is a really delicious Tunisian-style casserole, using the French cassoulet as inspiration to create massive flavour with hardly any ingredients. Feel free to add a little harissa into the mix, if you like."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-onions-beans','Chicken, Onions & Beans','5-ingredient recipe: This Is A Really Delicious Tunisian-Style Casserole, Using The French Cassoulet As Inspiration To Create Massive Flavour With Hardly Any Ingredients. Feel Free To Add A Little Harissa Into The Mix, If You Like.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,1,5,1,'[{"name":"onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Merguez sausages","quantity":5,"unit":"","unit_norm":"","category":"meat"},{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"fresh bay leaves","quantity":12,"unit":"","unit_norm":"","category":"pantry"},{"name":"mixed beans","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"}]','["Peel, halve and roughly slice the onions, then place in a large casserole pan on a medium heat with 1 tablespoon of olive oil. Squeeze the meat from 1 of the sausages into the pan and fry for 20 minutes, stirring regularly and breaking up the sausage. Meanwhile, carefully cut up the chicken (you’ll need to split the legs into thighs and drumsticks and remove the wings), and cut the breast into quarters (on the bone) – have a go at this yourself, or ask your butcher to do it for you.","Remove the stalks from 8 of the bay leaves, bash the leaves to a mush with a pinch of sea salt in a pestle and mortar, then muddle in 1 tablespoon each of extra virgin olive oil and red wine vinegar. Rub half of the marinade all over the chicken, getting into all the nooks and crannies. Put a large non-stick frying pan on a medium-high heat with 1 tablespoon of olive oil, and brown the remaining sausages with the thighs, drumsticks and wings, transferring them to the casserole pan when beautifully golden. Brown the breast skin side down for 3 minutes, then transfer to the casserole pan. Meanwhile, drain one of the tins of beans, then tip both tins into the casserole pan with the rest of the bay leaves. Gently mix together, then turn the heat down to medium-low and cook for 30 minutes with the lid on, or until beautifully tender. Drizzle over the rest of the bay marinade, to serve.","CHICKEN & MERGUEZ STEW","ZA’ATAR CHICKEN","BAKED IN A CRUST WITH LEMON & STICKY ONIONS","Using a simple flour and water dough that bakes into a crust ensures you get incredibly juicy meat, every time. Za’atar, a beautiful herby spice mix from the Levantine coast, provides big flavour here."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-onions-lemon-bowl','Chicken, Onions & Lemon Bowl','5-ingredient recipe: Using A Simple Flour And Water Dough That Bakes Into A Crust Ensures You Get Incredibly Juicy Meat, Every Time. Za’Atar, A Beautiful Herby Spice Mix From The Levantine Coast, Provides Big Flavour Here.','mediterranean','easy',40,NULL,40,4,NULL,0,0,0,1,0,'chicken',1,0.757,5,1,'[{"name":"za’atar","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"plain flour","quantity":500,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 180°C. Mix the za’atar with a pinch of sea salt and black pepper and 2 tablespoons of olive oil, then rub all over the chicken, getting into all the nooks and crannies. Place the chicken in a snug-fitting casserole pan on a high heat, turning with tongs for 15 minutes, or until golden all over. Meanwhile, peel and quarter the onions, stab the lemon all over with a fork, then quarter lengthways. Put the flour into a bowl and gradually mix in 300ml of water with a fork until you have a dough. Knead until smooth, then roll out on a flour-dusted surface until a little bigger than the pan.","Lift up the chicken and place the onions underneath with 2 tablespoons of red wine vinegar. Sit the chicken back on top and nestle the lemon wedges around it, sitting some wedges in the cavity and on the wings so they don’t pierce the dough. Remove the pan from the heat and lay the dough over the top, carefully pinching it at the edges to seal. Place in the oven for 1 hour 10 minutes, then crack open and discard the crust. Baste the chicken with the juices, then serve with rice, couscous or flatbreads.","ZA’ATAR CHICKEN","COUSCOUS & CHICKEN BAKE","TZATZIKI MARINADE, SWEET RED PEPPERS & CHARRED ONION","Couscous is used across the Mediterranean in so many wonderful ways – here I’m putting it centre stage to create the most outrageous bake, with a crispy outside and beautifully fluffy centre."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('red-peppers-salad','Red Peppers Salad','5-ingredient recipe: Couscous Is Used Across The Mediterranean In So Many Wonderful Ways – Here I’M Putting It Centre Stage To Create The Most Outrageous Bake, With A Crispy Outside And Beautifully Fluffy Centre.','mediterranean','easy',15,NULL,15,4,NULL,0,1,0,1,0,'none',2,1,2,1,'[{"name":"roasted red peppers","quantity":1,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"tubs of tzatziki","quantity":2,"unit":"","unit_norm":"","category":"pantry"}]','["1kg mixed chicken thighs and drumsticks, skin on, bone in","4 red onions","300g couscous","Preheat the oven to 180°C. Whiz one of the jarred peppers in a blender with 1 tub of tzatziki and a pinch of sea salt and black pepper. Pour over the chicken and leave to marinate for at least 2 hours in the fridge, preferably overnight. Peel and quarter the onions, place them in a 28cm non-stick ovenproof frying pan with 1 tablespoon of olive oil on a medium heat for 10 minutes, or until dark and gnarly, turning regularly, then remove to a plate. Drizzle 1 tablespoon of olive oil into the pan, then add the marinated chicken and brown for 10 minutes, turning regularly. Place the onions back in the pan, tear in the remaining peppers, then roast in the oven for 25 minutes.","Meanwhile, in a bowl, just cover the couscous with boiling kettle water, season with salt and pepper, and cover. Leave to hydrate for 3 minutes, then fluff up with a fork. When the time’s up, remove the pan from the oven, tip over the couscous and carefully pat down to compress. Roast for 10 minutes, then confidently and carefully turn out on to a large plate or platter and top with dollops of the remaining tzatziki. Serve straight from the oven and let everyone dig in.","COUSCOUS & CHICKEN BAKE","CHICKPEA CHICKEN","FENNEL MARINADE, SUPER-JUICY TOMATO SALAD","In the south of France I really enjoyed eating the chickpea-flour chips called ‘panisse’, and I’ve used them as inspiration for this chickpea and roast chicken salad, with lovely texture and epic flavour."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-chickpeas-seeds-salad','Chicken, Chickpeas & Seeds Salad','5-ingredient recipe: In The South Of France I Really Enjoyed Eating The Chickpea-Flour Chips Called ‘Panisse’, And I’Ve Used Them As Inspiration For This Chickpea And Roast Chicken Salad, With Lovely Texture And Epic Flavour.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,0.925,5,0,'[{"name":"chickpeas","quantity":3,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"fennel seeds","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"whole chicken","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"mixed-colour tomatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"mixed salad leaves","quantity":180,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 180°C. Drain the chickpeas really well, then tip into a food processor and pulse with a good pinch of sea salt and black pepper, keeping a bit of texture. Line a large baking tray with greaseproof paper and spread half the chickpea mixture in the centre, flattening it down slightly. Squash and scrunch little handfuls of the remaining mixture and dot around the edges of the tray (think golf-ball sized), then place the tray at the bottom of the oven. Bash the fennel seeds in a pestle and mortar with a good pinch of salt and pepper, then muddle in 1 tablespoon each of olive oil and red wine vinegar. Carefully cut down the back of the chicken to open it out, then rub the marinade all over. Place directly on the bars of the oven, above the tray of chickpeas, and roast for 1 hour, or until beautifully golden and cooked through, turning the tray of chickpeas halfway – you’ll end up with a mixture of crispy and wonderfully stodgy chickpeas, flavoured with delicious chicken juices.","Finely chop the tomatoes, toss them in a bowl with the salad leaves and 1 tablespoon of extra virgin olive oil, and season to perfection. Portion up the chicken and serve with the chickpeas and salad.","CHICKPEA CHICKEN","SUMAC CHICKEN","ROASTED FLATBREADS, DARK & STICKY ONIONS, PINE NUTS","A Palestinian-style spiced chicken flatbread, much-loved and cooked all year round, but especially during the olive oil harvest – the flavour of each ingredient really shines in this comforting meal."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('duck-broccoli-orange-salad','Duck, Broccoli & Orange Salad','5-ingredient recipe: Celebrating Some Classic French Ingredients, This Exciting Dish Is About Big Flavour And Texture, But Minimum Work. Plus, It’S On The Table In Only 20 Minutes, Making It A Perfect Midweek Dinner For Two.','mediterranean','easy',22,NULL,22,2,NULL,0,0,0,1,0,'duck',4,0.812,5,0,'[{"name":"duck breast fillets","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"sage","quantity":2,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"purple sprouting broccoli","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"large juicy orange","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"white beans","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"}]','["Score the duck skin, rub all over with sea salt and black pepper, then place the fillets skin side down in a cold non-stick frying pan and turn the heat on to medium. Cook for 8 minutes without moving the duck, until the fat is well rendered and the skin is golden and crisp. Turn the duck over and cook for a further 4 minutes, basting with the fat. Meanwhile, pick the sage leaves. Trim the broccoli stalks, halving the stems lengthways. Top and tail the orange, trim off the skin and either slice into rounds or segments, and toss with 1 teaspoon of red wine vinegar and a small pinch of salt and pepper.","When the time’s up, remove the duck to a plate to rest, leaving the pan on the heat. Add the sage leaves for 1 minute, or until crispy, jiggling the pan occasionally and transferring them to the duck plate as you go. Cook the broccoli in the pan for 4 minutes, or until lightly charred. Pour in the beans (juices and all), then cover and cook for 3 minutes. Season to perfection, divide between plates and drizzle over any resting juices. Slice the duck and arrange on top, and scatter over the crispy sage and orange.","QUICK CRISPY DUCK","JUICY CHARRED CHICKEN","FLUFFY COUSCOUS, EASY POMEGRANATE, CUCUMBER & MINT SALSA","Celebrating some of the flavours common on the Levantine coast, as well as speed and excitement, just a kiss of pomegranate juice will give you gnarly, caramelized chicken with the juiciest inside."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-mint-pomegranate-salad','Chicken, Mint & Pomegranate Salad','5-ingredient recipe: Celebrating Some Of The Flavours Common On The Levantine Coast, As Well As Speed And Excitement, Just A Kiss Of Pomegranate Juice Will Give You Gnarly, Caramelized Chicken With The Juiciest Inside.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'chicken',1,1,5,1,'[{"name":"mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"wholewheat couscous","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large ripe pomegranate","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"cucumber","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"skinless chicken breasts","quantity":4,"unit":"","unit_norm":"","category":"meat"}]','["Tear off the top leafy half of the mint, then finely chop and place in a bowl. Put the stalks into another bowl with the couscous, just cover with boiling kettle water, season with sea salt and cover. Leave to hydrate. Halve the pomegranate and, holding one half cut side down in your fingers, bash the back of it with a spoon so all the seeds tumble into the mint bowl, then repeat with the other half. Cut the cucumber into ½cm dice and add to the bowl with 2 tablespoons each of extra virgin olive oil and red wine vinegar. Toss well and season to perfection.","Put a large non-stick frying pan on a medium-high heat. Score the chicken breasts lengthways at 1cm intervals, going about halfway through. Rub with 1 tablespoon of olive oil and a pinch of salt and black pepper, then squeeze over the juice from a few pomegranate seeds (nicked from the salsa). Cook for 8 minutes, or until gnarly and cooked through, turning regularly. Discard the mint stalks from the couscous, fluff up with a fork, mix in half the salsa and divide between plates. Slice the chicken and arrange on top, with the remaining salsa. Finish with extra virgin olive oil, if you like.","JUICY CHARRED CHICKEN","CHICKEN TRAYBAKE","AUBERGINE, SHAWARMA-SPICED RICE, CRUSHED NUTS & DRIED FRUIT","There’s something so satisfying about dishes where the oven does all the work. Inspired by flavours from the Levantine coast, the rice and aubergine absorb big flavour from the chicken and spice."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-aubergine-thighs-salad','Chicken, Aubergine & Thighs Salad','5-ingredient recipe: There’S Something So Satisfying About Dishes Where The Oven Does All The Work. Inspired By Flavours From The Levantine Coast, The Rice And Aubergine Absorb Big Flavour From The Chicken And Spice.','mediterranean','easy',20,NULL,20,2,NULL,0,0,0,1,0,'chicken',1,1,5,1,'[{"name":"aubergine","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"chicken thighs","quantity":4,"unit":"","unit_norm":"","category":"meat"},{"name":"luxury fruit and nut mix","quantity":50,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"heaped tablespoon shawarma paste","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"basmati rice","quantity":150,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 200°C. Trim the aubergine and halve lengthways, use the tip of a knife to score down the length of the skin at 1cm intervals, then halve each piece again. Place in a 20cm x 25cm baking dish with the chicken, and toss with 1 tablespoon each of olive oil and red wine vinegar and a pinch of sea salt and black pepper. Roast for 25 minutes. Meanwhile, finely chop the fruit and nuts.","Boil the kettle. Remove the dish from the oven, then stir in the paste, half the fruit and nuts, and the rice. Stir in 300ml of boiling kettle water, then return to the oven for 25 minutes, or until the rice is cooked and the chicken pulls easily away from the bone. Give the rice a little fork up, sprinkle over the remaining chopped fruit and nuts, and serve.","CHICKEN TRAYBAKE","CHICKEN & CHIPS","STICKY ONIONS, JAMMY ROASTED LEMON & FRESH OREGANO","There’s something wonderfully humble about the combo of chicken and potatoes, and inspired by my trips to Greece, this expression of something we know and love is guaranteed to please."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-onion-tomatoes-salad','Beef, Onion & Tomatoes Salad','5-ingredient recipe: I Love Cooking Short Ribs! You Can Buy Them Easily From Your Butcher, And They’Ll Give You The Most Melt-In-The-Mouth Meat, But Also The Incredible Flavour From The Bones Gives The Sauce A Real Depth.','mediterranean','easy',35,NULL,35,6,NULL,0,0,0,1,0,'beef',3,0.892,4,1,'[{"name":"beef short ribs","quantity":6,"unit":"","unit_norm":"","category":"meat"},{"name":"frozen chopped mixed onion","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Rioja red wine","quantity":300,"unit":"ml","unit_norm":"ml","category":"pantry"},{"name":"plum tomatoes","quantity":3,"unit":"tins","unit_norm":"tins","category":"produce"}]','["3 teaspoons coarse-cut dark Seville orange marmalade","Preheat the oven to 160°C. Place a large non-stick frying pan on a medium-high heat. Season the ribs very generously with black pepper and a pinch of sea salt, then toss to coat. Place in the hot pan with 1 tablespoon of olive oil and brown all over for 10 minutes, turning regularly with tongs, then remove to a snug-fitting high-sided roasting tray or casserole pan, bone side down. Tip the frozen mixed veg into the frying pan juices and cook for a further 10 minutes to soften, then pour in the wine and allow most of it to bubble and cook away. Add the tomatoes, breaking them up with a potato masher, then half fill each tin with water, swirl around and pour into the pan. Bring to the boil and season lightly with salt and pepper. Pour the sauce over the ribs, then cover and cook in the oven for 4 hours, or until the meat is beautifully tender, basting occasionally and adding splashes of water, if needed.","When the meat’s tender, spoon the excess fat off the tray into a jam jar (save for tasty cooking another day). Heat the marmalade in a pan with a splash of water, then, taking pride, spoon it over the meat and bone of the short ribs, and put back into the oven for 10 minutes to set the glaze. Serve with a carb of your choice and some steamed seasonal greens.","RIOJA SHORT RIBS","HERBY STEAK & CRISPY POTATOES","GREEN PESTO, JUICY MIXED-COLOUR TOMATO SALAD & CRUSHED PISTACHIOS","Inspired by pistou, a beautiful French condiment made with smashed basil, garlic and oil, this tasty dish is a joy to eat. I’ve swapped in pesto for ease, but buy fresh for amplified flavour and texture."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-potatoes-tomatoes-bowl','Beef, Potatoes & Tomatoes Bowl','5-ingredient recipe: Inspired By Pistou, A Beautiful French Condiment Made With Smashed Basil, Garlic And Oil, This Tasty Dish Is A Joy To Eat. I’Ve Swapped In Pesto For Ease, But Buy Fresh For Amplified Flavour And Texture.','mediterranean','easy',30,NULL,30,2,NULL,0,0,0,1,0,'beef',4,0.812,5,0,'[{"name":"red-skinned potatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"sirloin steak","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"fresh green pesto or pistou","quantity":4,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"ripe medium mixed-colour tomatoes","quantity":6,"unit":"","unit_norm":"","category":"produce"},{"name":"shelled unsalted pistachios","quantity":20,"unit":"g","unit_norm":"g","category":"pantry"}]','["Scrub the potatoes, chop into 2cm chunks, then place in a large non-stick frying pan on a medium heat with 2 tablespoons of olive oil and season with sea salt and black pepper. Fry for 20 minutes, or until golden and cooked through, stirring regularly, then remove to a bowl. Put the pan back on a high heat.","Cut the fat off the steak, then roughly chop the fat and place in the pan to render. Generously season the steak, rub all over with 2 teaspoons of pesto, and cook for 3 minutes on each side for medium rare, or to your liking. Remove to a plate to rest. Return the potatoes to the pan to warm through, while you slice the tomatoes 1cm thick and arrange on serving plates. Dress with a splash of red wine vinegar and a drizzle of extra virgin olive oil, and season to perfection. Spoon over the potatoes, then slice and divide up the steak, pouring over any resting juices. Spoon over the remaining pesto, then bash and scatter over the pistachios. Finish with a drizzle of extra virgin olive oil, if you like.","HERBY STEAK & CRISPY POTATOES","CREAMY MUSTARDY PORK","GOLDEN MIXED MUSHROOMS, CRÈME FRAÎCHE & PEPPERY ROCKET","This is one of those really fast, impressive meals inspired by my time spent cooking and eating in France. People always think sauces are complicated, but this one comes together in no time at all."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-mushrooms-rocket','Pork, Mushrooms & Rocket','5-ingredient recipe: This Is One Of Those Really Fast, Impressive Meals Inspired By My Time Spent Cooking And Eating In France. People Always Think Sauces Are Complicated, But This One Comes Together In No Time At All.','mediterranean','easy',10,NULL,10,2,NULL,0,0,0,0,1,'pork',3,1,5,0,'[{"name":"pork fillet","quantity":300,"unit":"g","unit_norm":"g","category":"meat"},{"name":"mixed mushrooms","quantity":200,"unit":"g","unit_norm":"g","category":"produce"},{"name":"heaped tablespoon wholegrain mustard","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"heaped tablespoons crème fraîche","quantity":2,"unit":"","unit_norm":"","category":"dairy"},{"name":"rocket","quantity":40,"unit":"g","unit_norm":"g","category":"produce"}]','["Place a large non-stick frying pan on a high heat. Slice the pork into 6 medallions, bashing to flatten slightly, and roughly slice the mushrooms. Place them in the pan with 1 tablespoon of olive oil and cook for 2 minutes on each side, or until the mushrooms are golden and the pork is just cooked through, then remove just the mushrooms to a plate. Go in with the mustard and crème fraîche and cook for 1 last minute, loosening with a splash of water, if needed. Taste and season to perfection with sea salt and black pepper, divide between plates, then scatter over the golden mushrooms and rocket, and finish with a drizzle of extra virgin olive oil. Nice served with rice.","CREAMY MUSTARDY PORK","ROLLED BRAISED STEAKS","TAPENADE & TALEGGIO STUFFING, RICH TOMATO SAUCE","There’s something really special about elevating a cheaper cut of meat, like topside of beef, by rolling it up with thoughtful flavour combos, then slow-cooking until scrumptious and tender. I just love it."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-tapenade-red','Beef, Tapenade & Red','5-ingredient recipe: There’S Something Really Special About Elevating A Cheaper Cut Of Meat, Like Topside Of Beef, By Rolling It Up With Thoughtful Flavour Combos, Then Slow-Cooking Until Scrumptious And Tender. I Just Love It.','mediterranean','easy',30,NULL,30,6,NULL,0,0,0,0,1,'beef',3,0.892,5,1,'[{"name":"topside minute steaks","quantity":6,"unit":"","unit_norm":"","category":"meat"},{"name":"black olive tapenade","quantity":6,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Taleggio cheese","quantity":100,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"sage","quantity":1,"unit":"sprig","unit_norm":"sprig","category":"pantry"},{"name":"tomato and red wine sauce","quantity":2,"unit":"jars","unit_norm":"jars","category":"produce"}]','["Preheat the oven to 180°C. Place one of the steaks between two pieces of greaseproof paper, then use a rolling pin to evenly bash it out to just under ½cm thick. Repeat with the rest of the steaks, then lay them all out on a clean work surface. Spread 1 teaspoon of tapenade over the surface of each steak, tear over the Taleggio, then roll up and secure with a piece of butcher’s string.","Pick the sage leaves into a large casserole pan on a medium-high heat with 3 tablespoons of olive oil and fry until crispy, then remove to kitchen paper. Add the rolled steaks to the pan and brown all over for 4 minutes, then pour in the two jars of sauce. Half fill each jar with water, swirl around and tip into the pan. Bring to a simmer, then cover and place in the oven for 1 hour. Remove the lid, turn the steaks over, then cook for a further 20 minutes without the lid, or until the steaks are tender when pinched. Remove the steaks to a board, then snip off and discard the strings. Skim any fat from the surface of the sauce and drizzle it over the steaks. Taste and season the sauce to perfection, pour on to a large serving platter, then slice up the steaks and arrange them across the top. Scatter with the crispy sage leaves and serve. Amazing as is, or with bread, mash, polenta or spaghetti.","ROLLED BRAISED STEAKS","STUFFED ONIONS","HERBY SAUSAGE & FETA FILLING, TOMATO RICE","Across the Greek islands they stuff many different vegetables with grains, herbs and all kinds of wonderful things, and this is my version, celebrating the best of onions filled with simple ingredients."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-onions-tomatoes-bowl','Pork, Onions & Tomatoes Bowl','5-ingredient recipe: Across The Greek Islands They Stuff Many Different Vegetables With Grains, Herbs And All Kinds Of Wonderful Things, And This Is My Version, Celebrating The Best Of Onions Filled With Simple Ingredients.','mediterranean','easy',10,NULL,10,4,NULL,0,0,0,0,1,'pork',4,1,5,1,'[{"name":"large mixed onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"herby sausages","quantity":6,"unit":"","unit_norm":"","category":"meat"},{"name":"feta cheese","quantity":60,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"plum tomatoes","quantity":1,"unit":"tin","unit_norm":"tin","category":"produce"},{"name":"basmati rice","quantity":250,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 200°C. Peel the onions and halve widthways across the middle, then place in a large shallow casserole pan. Season with sea salt and black pepper, drizzle over 1 tablespoon of olive oil, then roast for 30 minutes. Squeeze the sausagemeat into a bowl, discarding the skins, scrunch in most of the feta, then put aside. When the time’s up on the onions, use tongs to transfer them to a board. Carefully remove and roughly chop the cores, then add just the chopped onion to the pan and place over a medium heat. Scrunch in the tomatoes through clean hands and pour in 1 tin’s worth of water, bring to a simmer, then add the rice, and mix together well.","Unclick and separate the onions into rings (like you can see in the picture), then roughly divide the sausage mixture between the rings. Arrange nicely on top of the rice, squashing them in, right up to the edges to cover the rice. Drizzle with 1 tablespoon of olive oil, then roast for 20 minutes, or until golden on top and the rice is cooked through. Crumble over the remaining feta and serve up.","STUFFED ONIONS","PORK & PEPPERS","CRISPY ARTICHOKES, CHICKPEAS & ARTICHOKE ALIOLI","This is a celebration of Spanish flavours coming together in a beautiful way. Mastering a super-juicy pork chop is key, and my advice is to cook two thick chops for four, instead of four thin dry ones."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lamb-aubergines-tomatoes','Lamb, Aubergines & Tomatoes','5-ingredient recipe: Slow-Cooking To Achieve Melt-In-The-Mouth Meat Is One Of My Favourite Things To Do, And This Tender Lamb Dish Centred Around The North African Spice Mix Ras El Hanout Is Just So Incredibly Comforting.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'lamb',2,1,5,1,'[{"name":"lamb shanks","quantity":4,"unit":"","unit_norm":"","category":"meat"},{"name":"ras el hanout","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"aubergines","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"mixed beans","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"}]','["Preheat the oven to 200°C. Rub the lamb shanks all over with 1 tablespoon each of olive oil and red wine vinegar and half the ras el hanout. Place in a large casserole pan and roast for 40 minutes, turning halfway. Meanwhile, prick the aubergines, then carefully blacken them over a direct flame on the hob (or under the grill), turning with tongs until soft inside.","Once cool enough to handle, carefully remove the aubergine skin, adding the flesh to the pan when the roasting time is up. Scrunch in the tomatoes through clean hands, add a pinch of sea salt and black pepper, the remaining ras el hanout and the beans (juices and all), then stir well. Turn the oven down to 160°C, cover and cook for 2 hours 30 minutes, or until meltingly tender and falling off the bone. Dust with extra ras el hanout and serve. Nice as it is, or with rice or warm flatbreads.","TENDER LAMB SHANKS","LAMB MEATBALLS","TZATZIKI & MINT SAUCE, CHARRED RED PEPPERS & LEMON","Walking around the buzzing city of Thessaloniki I saw many different expressions of meatballs in all kinds of shapes and sizes, which inspired this simply beautiful plate – a delicious mezze dish or starter."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-lemon-mint-bowl','Beef, Lemon & Mint Bowl','5-ingredient recipe: Walking Around The Buzzing City Of Thessaloniki I Saw Many Different Expressions Of Meatballs In All Kinds Of Shapes And Sizes, Which Inspired This Simply Beautiful Plate – A Delicious Mezze Dish Or Starter.','mediterranean','easy',25,NULL,25,4,NULL,0,0,0,1,0,'beef',2,0.812,5,0,'[{"name":"lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"tub of tzatziki","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"mint","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"roasted red peppers","quantity":0.5,"unit":"jar","unit_norm":"jar","category":"produce"},{"name":"minced lamb","quantity":400,"unit":"g","unit_norm":"g","category":"meat"}]','["Finely grate the lemon zest and put aside. Squeeze half the lemon juice into a blender, add the tzatziki and pick in most of the mint leaves, then whiz to a smooth sauce. Season to perfection with sea salt and black pepper, then put aside. Drain and finely chop one of the peppers, then place in a bowl with half the lemon zest, the lamb, a pinch of salt and plenty of pepper. Scrunch and mix together really well, then divide into 8 and squeeze into long oval-shaped rustic meatballs.","Drizzle 1 tablespoon of olive oil into a large non-stick frying pan on a high heat, then dot in the meatballs and cook for 10 minutes, or until golden and cooked through, turning occasionally. Drain and slice the remaining peppers and add to the pan, in and around the meatballs, for the last 2 minutes, turning halfway. Divide the sauce between plates, top with the meatballs and peppers, then scatter over the remaining lemon zest and mint leaves. Slice the remaining lemon half into wedges, for squeezing over. Delicious served with a hunk of bread for mopping up the sauce.","LAMB MEATBALLS","SUMPTUOUS PORK STEW","CRISPY SAGE, ONION, SWEET TOMATOES & SQUASH MASH","This stew is simplicity itself. The flavour I’m trying to create is what the Italians call agrodolce – sweet and sour: sweetness from the slow-cooked onions, and sourness from cooking away the vinegar."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-onions-tomatoes-salad','Beef, Onions & Tomatoes Salad','5-ingredient recipe: This Stew Is Simplicity Itself. The Flavour I’M Trying To Create Is What The Italians Call Agrodolce – Sweet And Sour: Sweetness From The Slow-Cooked Onions, And Sourness From Cooking Away The Vinegar.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,0,1,'beef',2,1,5,1,'[{"name":"sage","quantity":2,"unit":"sprigs","unit_norm":"sprigs","category":"pantry"},{"name":"pork cheeks or shoulder steaks","quantity":600,"unit":"g","unit_norm":"g","category":"meat"},{"name":"onions","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"plum tomatoes","quantity":2,"unit":"tins","unit_norm":"tins","category":"produce"},{"name":"large butternut squash","quantity":1,"unit":"","unit_norm":"","category":"dairy"}]','["Preheat the oven to 160°C. Pick the sage leaves into a large casserole pan on a medium heat with 3 tablespoons of olive oil and fry until crispy, then remove to kitchen paper, leaving the flavoured oil behind. Slice the pork into 2cm chunks, toss with 2 teaspoons of black pepper and a pinch of sea salt, then brown in the pan while you peel, roughly chop and add the onions. Add a good swig of red wine vinegar, then cook for 20 minutes, or until dark and caramelized, stirring occasionally. Scrunch in the tomatoes through clean hands, then pour in 2 tins’ worth of water. Pop the lid on, cook in the oven for 2 hours 30 minutes, or until beautifully tender, then taste and season to perfection.","With 1 hour 15 minutes to go, halve and deseed the squash, transfer it to a baking tray, then rub all over with 1 tablespoon of olive oil and a pinch of salt and pepper. Place in the oven to roast until tender, and add a splash of water to the stew, if needed. To serve, scoop out the soft squash flesh and plate up alongside the stew, scattered with the crispy sage leaves.","SUMPTUOUS PORK STEW","GIANT BAKED BEANS","MINI SAUSAGE MEATBALLS, SWEET TOMATOES & TANGY FETA","Mediterraneans love their beans – all kinds of different varieties – and inspired by some delicious mezze I had in Thessaloniki, I came up with this very simple, tasty dish that we all love at home."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('beef-beetroot-cheese-salad','Beef, Beetroot & Cheese Salad','5-ingredient recipe: Here, I’M Celebrating A Cheaper Cut Of Steak – Cooked Medium-Rare, Sliced Thinly, Then Buddied With The Undeniable Flavours Of Sweet Beets And Balsamic, And Goat’S Cheese And Tarragon, It’S A Real Treat.','mediterranean','easy',16,NULL,16,2,NULL,0,0,0,0,1,'beef',3,1,5,0,'[{"name":"vac-packed cooked beetroot","quantity":180,"unit":"g","unit_norm":"g","category":"produce"},{"name":"skirt steak","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"thick balsamic vinegar","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"soft goat’s cheese","quantity":70,"unit":"g","unit_norm":"g","category":"dairy"},{"name":"bunch of tarragon","quantity":0.5,"unit":"","unit_norm":"","category":"pantry"}]','["Trim, then slice the beets ½cm thick. Preheat a large non-stick frying pan on a high heat. Season the steak with sea salt and black pepper, place in the pan with 1 tablespoon of olive oil and fry for 5 minutes, or until medium-rare, turning and moving it around the pan regularly, then remove to a plate to rest. Put the beets into the pan, then drizzle in the balsamic and toss for a few minutes, to glaze. Divide the beets between serving plates, then thinly slice and layer over the goat’s cheese. Slice the steak thinly across the grain and divide between the plates, drizzling over any resting juices. Pick the tarragon leaves, toss in a little extra virgin olive oil and red wine vinegar, then scatter over the top.","STEAK TAGLIATA","PULLED LAMB SHOULDER","BAHARAT SPICES, PICKLED VEG, FLATBREADS & HOUMOUS","A wonderful feasting dish, celebrating Eastern Mediterranean baharat spices, with quick-pickled veg, homemade flatbreads, houmous dressing and meltingly tender meat – it really is a spectacular meal."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lamb-shoulder-salad','Lamb & Shoulder Salad','5-ingredient recipe: A Wonderful Feasting Dish, Celebrating Eastern Mediterranean Baharat Spices, With Quick-Pickled Veg, Homemade Flatbreads, Houmous Dressing And Meltingly Tender Meat – It Really Is A Spectacular Meal.','mediterranean','easy',20,NULL,20,10,NULL,0,0,0,1,0,'lamb',3,0.925,3,0,'[{"name":"baharat spice mix","quantity":1,"unit":"jar","unit_norm":"jar","category":"pantry"},{"name":"lamb shoulder","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"self-raising flour","quantity":1,"unit":"kg","unit_norm":"kg","category":"pantry"}]','["2 x 320g packs of pepper, onion, carrot and cabbage stir-fry mix","2 x 200g tubs of houmous","Preheat the oven to 150°C. Mix most of the spice mix with 2 tablespoons each of olive oil and red wine vinegar and a good pinch of sea salt and black pepper, then rub all over the lamb. Place in a roasting tray with a good splash of water, cover tightly with tin foil, then roast for 5 hours, or until beautifully tender and pullable. Remove the foil, baste with the juices, then roast for a final 20 minutes.","Meanwhile, put the flour into a bowl with a small pinch of sea salt, then gradually add 600ml of water, mixing with a fork as you go. Tip on to a flour-dusted surface and knead for a few minutes, until smooth. Divide the dough into 10, then place on a flour-dusted tray and cover with a damp cloth, until needed. Tip the veg mix into a large bowl and dress with 4 tablespoons of red wine vinegar and a good pinch of salt and pepper. Toss and leave aside to pickle. With 30 minutes to go, roll the dough into rounds, roughly 25cm in diameter. Dry-fry in a large non-stick frying pan on a high heat until golden and puffed up – you’ll need to work in batches. Keep warm under a clean tea towel. Drain off the lamb fat (keep in a jam jar for tasty cooking another day). Stir a good splash of boiling kettle water into the meat juices, scraping any sticky bits from the bottom of the tray. Transfer the houmous to a serving bowl with a pinch of spice and let it down with a good splash of water, then shred the lamb, discarding the bones, and toss in the tray juices. To serve, load the flatbreads with pickled veg, shredded lamb, houmous dressing and a pinch of spice.","PULLED LAMB SHOULDER","PORK & PRUNES","SWEET CARROTS & CRISPY ROSEMARY CRACKLING","The beautiful Greek island of Skopelos hails dried prunes as one of its most prized ingredients and they use them in so many tasty ways, like in this rustic stew, to bring deep sweet-savouriness."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-olives-lemon-bowl','Pork, Olives & Lemon Bowl','5-ingredient recipe: Delicately Breaded Meat Fried Until Crisp And Juicy Is Enjoyed All Over The Mediterranean. Served With A Much-Loved Soft-Cooked Egg, Salty Olives And A Hit Of Zingy Lemon Juice, This Is Truly Scrumptious.','mediterranean','easy',20,NULL,20,2,NULL,0,0,0,1,0,'pork',2,0.925,5,0,'[{"name":"fine dried breadcrumbs","quantity":100,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"large eggs","quantity":3,"unit":"","unit_norm":"","category":"pantry"},{"name":"pork fillet","quantity":1,"unit":"","unit_norm":"","category":"meat"},{"name":"mixed marinated olives","quantity":8,"unit":"","unit_norm":"","category":"produce"},{"name":"lemon","quantity":0.5,"unit":"","unit_norm":"","category":"produce"}]','["Tip the breadcrumbs on to a large plate, and whisk 1 egg in a shallow bowl. Slice the fillet into 4 equal pieces. One at a time, use your fist or a rolling pin to bash out and tenderize each piece of pork between sheets of greaseproof paper, to ½cm thick. Season with sea salt and black pepper, dip each piece in the egg, letting any excess drip off, then turn in the breadcrumbs, pressing to coat. Chop the olives (destone, if needed), plus any of the marinating ingredients, and slice the lemon into wedges.","I like to cook a portion at a time: place 2 escalopes in a large non-stick pan on a medium-high heat with a good splash of olive oil and cook for 1½ minutes on each side, or until golden and cooked through, frying 1 egg alongside after the second flip, to your liking – angle the pan and spoon any excess oil over the egg to help it cook. Remove the escalopes to a plate lined with kitchen paper to drain, then plate up, and top with the fried egg. Scatter over half the olives, then repeat with the remaining ingredients. Serve with lemon wedges for squeezing over.","PORK ESCALOPE","LAMB TANGIA","SPICED TOMATO & OLIVE BROTH & VERMICELLI RICE NOODLES","This has to be one of the easiest, most delicious dishes that you can put together and just let blip away in the oven, developing rich, beautiful flavour over time that the noodles can go on to absorb."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lamb-tomatoes-olives-salad','Lamb, Tomatoes & Olives Salad','5-ingredient recipe: This Has To Be One Of The Easiest, Most Delicious Dishes That You Can Put Together And Just Let Blip Away In The Oven, Developing Rich, Beautiful Flavour Over Time That The Noodles Can Go On To Absorb.','mediterranean','easy',20,NULL,20,4,NULL,0,0,0,1,0,'lamb',3,1,5,0,'[{"name":"lamb neck","quantity":1.2,"unit":"kg","unit_norm":"kg","category":"meat"},{"name":"ras el hanout","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"ripe mixed-colour tomatoes","quantity":1,"unit":"kg","unit_norm":"kg","category":"produce"},{"name":"mixed marinated olives","quantity":100,"unit":"g","unit_norm":"g","category":"produce"},{"name":"nests of vermicelli","quantity":3,"unit":"","unit_norm":"","category":"pantry"}]','["Preheat the oven to 180°C. Place the lamb neck in a large pot (or tangia) with the ras el hanout. Quarter and deseed the tomatoes, adding the tomato petals to the pot, along with the olives (and marinating ingredients). Pour over 1.5 litres of boiling kettle water, pop the lid on and cook in the oven for 3 hours, or until the lamb is tender and falling off the bone. Taste and season the broth to perfection, crumble in the noodles, making sure they’re submerged, then cover and wait 5 minutes for the noodles to rehydrate and absorb the tasty broth. To serve, remove and shred the lamb, discarding any gristly bits and bones, and return the lamb to the pot. Toss together, and finish with a drizzle of extra virgin olive oil and an extra dusting of ras el hanout.","LAMB TANGIA","BALSAMIC PORK STEW","CELERY, MIXED SPICE, BLACK PEPPER, ONION & TOMATO SAUCE","This comforting Italian stew has a real depth of flavour and layers of gentle spice. Plus, slow-cooking pork and vinegar is a total joy. Any leftovers can be gratefully tossed through pasta and Parmesan."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('oranges','Oranges','5-ingredient recipe: I’Ve Had The Privilege Of Trying All Kinds Of Baklava, Flavoured In Many Beautiful Ways, And This Is My 5-Ingredient Homage, Using Accessible Ingredients And A Simple Method For Max Flavour And Texture.','mediterranean','easy',45,NULL,45,10,NULL,0,1,0,1,0,'none',2,0.757,5,1,'[{"name":"large juicy oranges","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"runny honey","quantity":1,"unit":"jar","unit_norm":"jar","category":"pantry"},{"name":"nests of vermicelli","quantity":2,"unit":"","unit_norm":"","category":"pantry"},{"name":"luxury fruit and nut mix","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"filo pastry","quantity":1,"unit":"pack","unit_norm":"pack","category":"pantry"}]','["Finely grate half the orange zest into a large non-stick frying pan and squeeze in all the juice. Add the honey and place on a medium heat until syrupy, gently swirling the pan occasionally (careful – it’s hot!). Leave aside to cool. Preheat the oven to 170°C. Cover the vermicelli with boiling kettle water to soften, then drain, squeezing out any excess liquid. Meanwhile, tip half the fruit and nuts into a food processor and blitz until super-fine, then add the rest and pulse a few times – you want a mixture of fine and chunky. Put a small handful of the mixture aside for later, then tip the vermicelli into the food processor and pulse a few times. Rub a 30cm non-stick ovenproof frying pan with olive oil, lightly rub half the filo sheets with oil, then layer into the pan, leaving the pastry overhanging. Evenly scatter over the vermicelli and nut mixture, then lightly rub the remaining filo with oil, layer them over and tuck in the edges, pressing to compact – there’s no need to be neat. Carefully pre-slice into portions, any way you like, then bake for 30 minutes, scattering over the remaining fruit and nuts for the last 5 minutes.","Remove from the oven, use a fish slice to gently press down on the pastry, then evenly pour over the syrup and leave to cool for 2 hours. When you’re ready to serve, place on a very low heat to release the baklava, then either serve from the pan or carefully and confidently turn out on to a board.","KINDA BAKLAVA","LEMON SHERBET","AMARETTI CRUMB, SQUASHED BLACKBERRIES","In the baking hot Mediterranean sun there’s probably nothing more refreshing than an iced dessert, and this is an interesting recipe where the citrus gives the dairy a wonderful sherbety fizz. Delicious!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bean-cheese-bowl','Bean & Cheese Bowl','5-ingredient recipe: Inspired By The Much-Loved Baked Cheesecakes You Find In Parts Of The Mediterranean, This Tasty, Cheeky Little Pudding Is Dead Easy To Put Together, But The Finished Result Looks Super-Impressive.','mediterranean','easy',20,NULL,20,12,NULL,0,1,0,0,1,'none',2,1,5,1,'[{"name":"icing sugar","quantity":300,"unit":"g","unit_norm":"g","category":"pantry"},{"name":"tubs of cream cheese","quantity":4,"unit":"","unit_norm":"","category":"dairy"},{"name":"vanilla bean paste","quantity":5,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"large eggs","quantity":5,"unit":"","unit_norm":"","category":"pantry"},{"name":"plain flour","quantity":70,"unit":"g","unit_norm":"g","category":"pantry"}]','["Preheat the oven to 220°C. Boil the kettle. Line the base of a 23cm springform cake tin with a round of greaseproof paper, rub the tin with a little olive oil and lightly dust with icing sugar. Sieve 300g of icing sugar into a large bowl and beat with the cream cheese and vanilla until smooth, then – one at a time – whisk in the eggs, and finally sieve and whisk in the flour. Pour into the lined tin, wrap the base in tin foil to protect the seal, then place inside a deep roasting tray and carefully half-fill the tray with boiling kettle water. Bake on the top shelf of the oven for 20 minutes, or until golden and loosely set in the middle, with a slight wobble. Leave to cool in the water for 15 minutes, then put aside to cool completely. Cover, then chill for at least 4 hours before slicing. Delicious with fresh seasonal fruit.","BAKED CHEESECAKE","EASY PEACH GRANITA","SWEET VANILLA, FRESH MINT, YOGHURT & VODKA","This is one of the easiest, most refreshing puds, and minus the booze it’s super-healthy. Have a play around with plums, strawberries, raspberries or melon, or experiment with your favourite combos."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('peas-green-beans-home-salad','Peas, Green Beans & Home Salad','Recipe from Carla Lalli Music: Just-picked sugar snap peas are sweet, firm, and juicy, and have no starchiness to them. They’re completely enjoyable raw, but charring gives the edible pods a little unexpected smoky bitterness. This dish lets you have it both ways, along with plenty of creamy cheese to play up the crunchiness of the peas.',NULL,'medium',45,NULL,45,6,NULL,0,1,0,0,1,'none',3,0.575,10,1,'[{"name":"Mozzarella","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Sugar snap peas","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Crusty bread","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Green beans","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Crushed red pepper stirred into olive oil instead of Calabrian chiles At Home","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Olive oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Flaky sea salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Lemon","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Crushed Calabrian chiles in oil","quantity":null,"unit":"","unit_norm":"","category":"pantry"}]','["Toasted sesame oil or hazelnut oil instead of Calabrian chiles or olive oil 2 (8-ounce) balls buffalo mozzarella or 1 (1-pound) ball salted fresh mozzarella Extra-virgin olive oil, for drizzling and brushing Flaky sea salt 1 pound sugar snap peas, trimmed","Kosher salt, freshly ground pepper","6 thick-cut slices crusty bread, such as miche","1 lemon","Crushed Calabrian chiles in oil, for serving","Place mozzarella on a serving platter, drizzle with olive oil, and season with flaky salt. Let sit at room temperature at least 1 hour before serving to take off the chill, which is key for creamy oozy insides and the best flavor. (In a perfect world, that mozzarella would never have been refrigerated, but these are imperfect times.) Prepare a grill for medium-high direct heat.","In a medium bowl, drizzle sugar snap peas with some olive oil and toss to coat. Season with salt and pepper. Set a wire rack or grill basket on grill, add half of peas, and grill, tossing occasionally, until charred in spots, about 3 minutes. (Or, char half the peas in a dry cast-iron skillet over high heat.) Return peas to bowl with raw ones and toss to combine.","Generously brush both sides of bread with olive oil. Grill until lightly toasted, about 2 minutes (or use a dry cast-iron skillet over medium-high heat). Holding the uncut lemon in one hand, rub the lemon peel vigorously against the surface of the toast to pick up some of the zest and release some essential oils. Cut the bread into quarters or rectangular soldiers.","Add peas to platter with cheese and drizzle more olive oil over everything. Spoon up some of the chiles and their oil and drizzle over.","Serve with spoons for the cheese, along with grilled bread and flaky salt for making perfect bites.","Hot to Trot","Jarred Calabrian chiles, from the southernmost region of Italy, are molto spicy and intensely","flavored. If you love hot stuff, they’re worth a try. You can find them at specialty grocers and online.","Savory summer melon salad","When some melons are at their peak, they can be insanely aromatic and very sweet. I’ve always loved savory preparations for that reason—think cantaloupe with prosciutto or lots of black pepper, watermelon with feta, honeydew with salt and olive oil. All delicious. This is in the same vein—the fish sauce adds saltiness and umami, the melon is sweet but also vegetal (it’s a gourd, like squash and cucumber), and the lime has the zing. You can skip the MSG if you want, but I wouldn’t."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('grapefruit-shallot-beets-bowl','Grapefruit, Shallot & Beets Bowl','Recipe from Carla Lalli Music: This is a riff on scallops with brown butter and lemon, but with beets instead of scallops and grapefruit in place of lemon. I prefer good old-fashioned white or oro blanco grapefruit for its high acidity; if you’re using a ruby red, which is sweeter, shake a few extra drops of cider vinegar over the dish right before serving.',NULL,'medium',45,NULL,45,6,NULL,0,1,0,0,1,'none',2,0.575,17,1,'[{"name":"Grapefruit","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Shallot","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Beets","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Mint","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Any color beets will work","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Cilantro instead of mint","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Ginger","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Flaky sea salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Cider vinegar","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Toasted sesame oil","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Olive oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Butter","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Unseasoned rice vinegar or sherry vinegar instead of cider vinegar 1 white grapefruit","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"inch piece fresh ginger","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Kosher salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"cider vinegar","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["1 teaspoon toasted sesame oil, plus more for drizzling 3 softball-size beets (about 1½ pounds), trimmed, scrubbed, peeled, and cut into 1- to 1½-inch-thick wedges","2 tablespoons extra-virgin olive oil","Flaky sea salt","3 tablespoons unsalted butter","Mint leaves, for serving","Prep the grapefruit, which you’re going to use three ways: First, use a vegetable peeler to remove 3 or 4 long wide strips of zest, avoiding the bitter white pith underneath. Set zest aside. Next, take off a thin slice from the top and bottom of grapefruit and upend it on a cut side.","Using a thin sharp knife and following the curve of the fruit, cut away peel and pith to expose flesh. Slice off a 2-inch-thick round from one end of grapefruit and squeeze juice from that piece into a small bowl; you’ll have about 2 tablespoons. Slice remaining grapefruit crosswise into ½-inch-thick rounds and transfer to a platter. Pick out seeds.","Put ginger into a small mesh sieve set over bowl with grapefruit juice and press down on solids so that ginger juice drips into bowl. Set grapefruit-ginger juice aside (discard solids).","Place shallot slices in a small bowl, cover with cold water, and use your fingertips to separate into individual rings. Soak for 5 minutes, then drain and return to same bowl. Season with salt and add vinegar and 1 teaspoon sesame oil. Set pickled shallots aside.","Season beets with salt. In a large skillet, heat olive oil over medium-high heat until shimmering. Place beets in pan with a flat side down.","Cook until almost charred underneath, 6 to 8 minutes, shaking skillet occasionally to make sure they aren’t sticking. Turn beets and cook on","second flat side until golden brown, 4 to 5 minutes. Cut into one and taste to check doneness—it should be firm at the center, but no longer completely raw. Transfer to platter with grapefruit and tuck grapefruit slices between and around beet wedges. Season with flaky salt. Let skillet cool for 2 to 3 minutes.","Pour off any oil from skillet and carefully wipe out with paper towel.","Return to medium heat, add grapefruit-ginger juice, swirl, and cook just until mixture simmers (this will happen almost immediately).","Add butter and reserved zest and cook until butter is browned and smells nutty, about 4 minutes (if you’re using a pan with a dark surface, spoon a little onto a white plate to check color).","Spoon pan sauce over beets and grapefruit. Top with pickled shallots, along with any juices in bowl. Serve topped with mint.","Chicories with garlic bread croutons","When we first met, my husband claimed to not like bitter greens, and was skeptical of radicchio, escarole, arugula—","even endive. Because those are some of my most beloved leafy things, I felt it was my duty to show him The Way. This particular way is to create a booby trap of cheesy, garlicky croutons that tuck themselves inside the ruffled and resilient lettuces, creating unavoidable, forkable opportunities."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-celery-green-cabbage-salad','Pork, Celery & Green Cabbage Salad','Recipe from Carla Lalli Music: Deploying bacon and peanuts seemed like a good place to start.',NULL,'medium',45,NULL,45,4,NULL,0,0,0,1,0,'pork',3,0.637,19,1,'[{"name":"Celery","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Green cabbage","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Fennel or Brussels sprouts for the celery","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Omit the celery and double the cabbage","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Kohlrabi or cauliflower for the cabbage At Home","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Bacon","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Peanuts","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Soy sauce","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Unseasoned rice vinegar","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Chili oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Pancetta or pork sausage meat for the bacon","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Hot sauce for the chili oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"celery or 2 celery hearts","quantity":0.5,"unit":"bunch","unit_norm":"bunch","category":"produce"},{"name":"ounces thick-cut bacon","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"green cabbage","quantity":0.25,"unit":"head","unit_norm":"head","category":"produce"},{"name":"soy sauce","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"unseasoned rice vinegar","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Chili oil","quantity":null,"unit":"","unit_norm":"","category":"produce"}]','["Cut celery stalks crosswise on a long diagonal into ¼-inch pieces. Snap off the light green celery leaves from the innermost stalks and set those aside.","Place bacon in a large cold skillet, then place over medium heat.","Cook, stirring occasionally, until bacon renders most of its fat and starts to curl up and turn golden but is nowhere near crisp, about 5","minutes. Add peanuts, increase heat to medium-high, and cook, stirring frequently, until peanuts take on some color, about 2 minutes.","Add celery and cabbage, season lightly with salt, and cook, tossing, just until celery is browned in spots but still crunchy, and the cabbage is bright green and tender, but still has some bite to it, about 4 minutes.","Add soy sauce and vinegar and toss through.","Transfer to a serving platter. Drizzle with chili oil and top with reserved celery leaves.","Charred broccoli salad","Searing broccoli lets you straddle the line between raw and cooked in this crunchy salad. I like rich, buttery Marcona almonds against the rustic broccoli, but regular almonds will work, too. Because the broccoli is so sturdy, this dish holds well, and the dates will continue to soften and absorb flavor as time goes on. It’s a good one to make ahead for dinner, or take to a friend’s place."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('potatoes-lime-tahini-bowl','Potatoes, Lime & Tahini Bowl','Recipe from Carla Lalli Music: The first time I made this dish I wrote a note to myself that said “Yum! Not much to look at, but yum.” You will have extra tahini butter left over: Scrape it into a jar and chill it. It will keep for at least a week and is an easy dinner fixer. Toss it with warm grains, udon noodles, or a tray of roasted vegetables; spread it onto a seared steak while it rests, or use it to top broiled salmon or snapper.',NULL,'medium',45,NULL,45,6,NULL,0,1,0,0,1,'none',2,0.495,13,0,'[{"name":"Sweet potatoes","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Acorn or butternut squash","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Butter","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Tahini","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Soy sauce","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Toasted sesame oil","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Lime","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Flaky sea salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Sesame seeds","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Creamy peanut butter for tahini","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Walnut oil in place of sesame oil","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Unseasoned rice vinegar for lime juice","quantity":null,"unit":"","unit_norm":"","category":"produce"}]','["Crushed toasted peanuts or pepitas for sesame seeds 3 pounds sweet potatoes, any color (6 small or 3 large), scrubbed 6 tablespoons unsalted butter, at room temperature 2 tablespoons tahini 1 tablespoon soy sauce","2 teaspoons toasted sesame oil","¼ cup fresh lime juice, plus wedges for serving Kosher salt, freshly ground pepper","Flaky sea salt and toasted sesame seeds, for serving Bring a few inches of water to a boil in a medium stockpot fitted with a steamer basket. Halve the sweet potatoes crosswise if large and place them in the steamer. Cover, reduce the heat to medium, and steam until potatoes are completely tender, about 30 minutes. I use a cake tester to check doneness, but the tines of a fork or tip of a paring knife would work, too.","Meanwhile, in a small bowl, combine the butter, tahini, soy sauce, sesame oil, and lime juice and use a spatula, spoon, or fork to smash them together (you will think the butter and the liquids will never fully combine, but don’t give up—it will happen). Season tahini butter with salt and a generous amount of pepper.","Use tongs to transfer cooked potatoes to a large plate or platter. When just cool enough to handle, split potatoes in half and spread tahini butter generously onto flesh. Don’t be skimpy: The tahini butter is a sauce, not a schmear. Top with a liberal coating of sesame seeds and season with flaky salt. Serve with more lime wedges—these really come alive with lots of bright citrus.","Egg-centric","These decidedly savory recipes prove that the addition of an egg is all that’s needed to push a side dish onto center stage.","Slow-cooked dozen-egg frittata","BLTs with bacon-fat fried eggs","Omelet with whipped ricotta for two","Poached egg and silky braised greens","Fried grains with bacon, mushrooms, and kimchi","Aioli and all the things for dipping","Carbonara stracciatella","Slow-cooked dozen-egg frittata","Until I came across the slow-cook frittata method from the legendary Brooklyn pizzeria Franny’s, I’d always cooked them over medium-high heat on the stovetop and then flashed them under the broiler to brown the top side at the end. This gentle-heat process creates a dense and creamy texture, and it made me an instant convert. A dozen eggs might seem like a lot, but it’s the right amount for six people."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('tendrils-ricotta-salad','Tendrils & Ricotta Salad','Recipe from Carla Lalli Music: Making one big omelet and folding it in half is easy, whereas making two smaller rolled omelets is hard. Even if you nail it, one person gets stuck with a not-quite-hot omelet. I probably wouldn’t mess with pea tendrils and a creamy ricotta filling on a weekday morning, but I’d serve this breakfast for dinner any night.',NULL,'medium',45,NULL,45,2,NULL,0,1,0,0,1,'none',2,0.575,2,1,'[{"name":"Ricotta","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Pea tendrils","quantity":null,"unit":"","unit_norm":"","category":"produce"}]','["Small-curd cottage cheese or cream cheese for the ricotta Any other tender greens, such as baby kale or small watercress for the pea tendrils At Home","Parmigiano","Salt and pepper","Eggs","Olive oil","White wine vinegar","Cheddar, Monterey Jack, or Grana Padano can replace the Parm Sherry vinegar or cider vinegar for the white wine vinegar 4 ounces fresh ricotta ¼ cup grated Parmigiano","Kosher salt, freshly ground pepper","6 large eggs","3 tablespoons extra-virgin olive oil, divided","2 cups pea tendrils","1 tablespoon white wine vinegar In a small bowl, combine ricotta and Parmigiano and whisk energetically until mixture is very well blended and slightly aerated.","Season with salt and pepper and set aside.","In a medium bowl, whisk eggs until very smooth and no visible streaks of egg whites remain. Season with salt and pepper. Heat a medium nonstick skillet over medium heat with 1 tablespoon olive oil. Add eggs and cook, stirring slowly in long passes across entire surface of pan and all the way around edges, until large curds form and underside is set, 1 to 2 minutes. Rap pan firmly against stovetop a few times to settle eggs into skillet. Spoon ricotta mixture across eggs, over to one side of center line. Continue to cook eggs until underside is light golden brown, about 1 minute longer. Use a spatula to lift plain half of omelet up and over the other half (as though you were folding a tortilla in half to make a taco). Slide omelet onto a cutting board.","In a medium bowl, toss pea tendrils with vinegar and remaining 2","tablespoons oil. Season with salt and pepper. Halve omelet crosswise and serve with pea tendril salad on top.","Poached egg and silky braised greens","Listen up: Swiss chard stems and ribs are a treasure—earthy, sweet, and resilient—as desirable as the ruffly leaves that surround them. Give them a head start before adding the leaves so they can soften a bit, sending vegetal juices into the pan to mingle with the garlic and olive oil. Don’t balk at the amount of olive oil here, either. The leaves will melt into the saucy cooking liquid, creating a perfect soft landing for a runny egg."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-parsley-aromatic-salad','Fish, Parsley & Aromatic Salad','Recipe from Carla Lalli Music: Even when there is nothing to eat, there is always spaghetti aglio e olio. There’s lots of parsley in this version—maybe enough to convince yourself you’re getting a serving of greens. Keep this dish in mind when you’re staring down a bunch of herbs in the crisper drawer.',NULL,'medium',45,NULL,45,4,NULL,0,0,1,0,1,'fish',4,0.575,10,1,'[{"name":"Parsley","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Basil would lend more aromatic","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"chives in place of parsley would amplify the garlicky and pungent flavors At Home","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Spaghetti","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Olive oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Anchovy fillets","quantity":null,"unit":"","unit_norm":"","category":"seafood"},{"name":"Crushed red pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Parmigiano","quantity":null,"unit":"","unit_norm":"","category":"dairy"}]','["Any other long pasta, such as bucatini or linguine, can replace the spaghetti Kosher salt, freshly ground pepper","1 pound spaghetti","⅓ cup extra-virgin olive oil","10 garlic cloves, smashed","2 oil-packed anchovy fillets (optional)","½ teaspoon crushed red pepper, plus more for serving 1 cup lightly packed chopped fresh parsley leaves and tender stems","Parmigiano, for serving","Bring a large pot of salted water to a boil for pasta. Add pasta and set a timer for 2 to 3 minutes less than package instructions (it should be very al dente and will finish cooking in the sauce).","Meanwhile, in a large skillet or Dutch oven, heat oil and garlic over medium heat, stirring occasionally, until bubbles appear and garlic is starting to turn translucent, 2 to 3 minutes. Season garlic with salt and pepper (I like a lot of pepper, and I like how its flavor opens up in the oil). Continue cooking, breaking garlic into smaller pieces with the edge of a wooden spoon, until golden brown and softened, 3 to 4","minutes more. Add anchovies (if using) and crushed red pepper and stir until anchovies disintegrate, about 1 minute. If pasta is not yet done, slide skillet off heat.","Scoop out a cup of pasta cooking liquid, then drain spaghetti and transfer to skillet along with ½ cup pasta water. Bring to a simmer over medium heat, add parsley, and cook, tossing constantly with tongs and adding more pasta water as needed, until pasta is al dente and sauce is just thick enough to coat pasta but there’s still plenty of extra sauce in skillet, 2 to 3 minutes.","Serve with more crushed red pepper and Parmigiano for grating over.","Caprese mac and cheese","You probably didn’t think you needed a mac and cheese for summer months. Surprise! This is a nostalgic take on a room-temperature, portable pasta my mom used to make every August when I was a teenager: She’d toss together marinated tomatoes, milky fresh mozzarella, and basil with just-drained pasta that would melt the cheese on contact. My version is baked, but the way it tastes takes me back to those summers."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-beets-squash-salad','Chicken, Beets & Squash Salad','Recipe from Carla Lalli Music: 2 to',NULL,'medium',45,NULL,45,4,NULL,0,0,0,0,1,'chicken',2,0.575,3,1,'[{"name":"Chicken","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Beets","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"inch pieces of butter-nut squash","quantity":2,"unit":"","unit_norm":"","category":"dairy"}]','["Fennel or acorn squash wedges, cauliflower florets, or whole Brussels sprouts for all or some of the beets","Torn radicchio or escarole leaves, savoy or napa cabbage leaves, or kale leaves for all or some of the beets","Add a thinly sliced lemon to the vegetables","Fennel seeds","Crushed red pepper","Salt and pepper","Olive oil","Aniseeds, cumin seeds, or coriander seeds can replace the fennel seeds 2 teaspoons fennel seeds","1 teaspoon crushed red pepper","1 whole chicken (3½ to 4½ pounds), backbone removed Kosher salt, freshly ground pepper","8 to 10 medium beets, any color, greens trimmed 4 tablespoons extra-virgin olive oil, divided","Set oven racks in upper third and lowest position of oven, place a 10-inch cast-iron skillet on lower rack, and preheat oven to 500°F. (A preheated skillet jump-starts the browning process and dramatically reduces cooking time.) Lightly crush fennel and crushed red pepper in a mortar and pestle or spice grinder. Season chicken on both sides with salt and black pepper, then with fennel–crushed red pepper mix-ture. Scrub and peel beets and cut into 2-inch wedges (quarters or sixths, depending on their size). Toss beets and 2 tablespoons oil on a rimmed baking sheet. Season with salt and pepper.","Carefully remove hot skillet from oven and place on the stovetop over high heat. Pour in remaining 2 tablespoons oil. Carefully lay chicken in skillet, skin side down. Use a spatula to press firmly down on chicken to make sure skin is in firm contact with pan. Cook until edges of skin are golden brown, about 2 minutes. Lay a sheet of foil over chicken, then place a second cast-iron pan, Dutch oven, or other heavy pot on top as a weight. This will help chicken maintain contact with the pan while it roasts, shortening the cooking time and helping the skin brown.","Return pan to lower rack and cook for 30 minutes. A thermometer inserted into thickest part of breast, avoiding bone, should register 150°F; temperature will continue to climb when chicken is resting.","Roast beets on upper rack until tender when pierced with a cake tester, 25 to 30 minutes.","Turn chicken skin side up and let rest for 20 minutes. Serve with beets and any accumulated juices in skillet.","Chicken cutlets with spicy coconut dressing","Don’t shake the can of coconut milk before opening it—","you’ll use the layer of cream on top in this sweet and spicy dressing, which is mellowed by the cooling iceberg lettuce and rich dark-meat chicken. Transfer the unused coconut milk to a clean jar and refrigerate it for making soup or a curry (it will hold for several days)."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-cherry-tomatoes-basil-salad','Chicken, Cherry Tomatoes & Basil Salad','Recipe from Carla Lalli Music: 2 to',NULL,'medium',45,NULL,45,4,NULL,0,0,0,1,0,'chicken',2,0.575,11,1,'[{"name":"Cherry tomatoes","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Basil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Chicken thighs","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Green beans","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"0.5 roughly chopped tomatoes for the cherry tomatoes Replace half the basil with parsley","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"small fennel bulb","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Olive oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"All-purpose flour","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Red wine vinegar","quantity":null,"unit":"","unit_norm":"","category":"pantry"}]','["Half a small red onion, thinly sliced, for the garlic Lemon juice or white wine vinegar for the red wine vinegar 12 ounces cherry tomatoes, halved, divided 4 garlic cloves, 1 finely grated, 3 thinly sliced 2 tablespoons extra-virgin olive oil, divided","Handful of basil leaves","Kosher salt, freshly ground pepper","4 bone-in, skin-on chicken thighs, patted dry","¼ cup all-purpose flour, for dusting","8 ounces thin green beans, trimmed, halved crosswise 1 tablespoon red wine vinegar","Toss half of the cherry tomatoes with the grated garlic, 1 tablespoon olive oil, and basil. Season with salt and pepper. Let salsa sit so tomatoes release some juices and flavors can marry.","Meanwhile, debone the chicken thighs: Working with one thigh at a time, place a chicken on a cutting board, skin side down. Press your finger against the flesh to locate the thigh bone that runs from one end to the other. Using a sharp paring knife, make short swift cuts along the length of the bone on one side to separate the flesh. Rotate chicken 180° and repeat on other side of bone. Wiggle the tip of your knife underneath the bone, angle blade upward, and cut bone out completely. Place thigh on a large plate and repeat with remaining thighs.","Place flour on a dinner plate. Season chicken on both sides with salt and pepper, then dredge very lightly in flour, patting excess off until only a sheer coating remains. Heat a large skillet, preferably not cast-iron, over medium-high heat. Pour in remaining 1 tablespoon olive oil, then lay thighs into pan, skin side down.","Cook chicken, undisturbed, until skin is deep golden brown and flesh is cooked about halfway through, 6 to 8 minutes. Turn chicken and cook on second side until chicken is cooked through, about 4 minutes more. Transfer thighs to a platter.","Return pan to medium-high heat and cook green beans, shaking pan occasionally, until charred in spots, 4 to 5 minutes. Season with salt and pepper. Add sliced garlic and reserved (plain) tomatoes to pan.","Season again with salt and pepper and cook until tomatoes begin to soften and garlic is translucent, 1 to 2 minutes. Remove pan from heat and stir in vinegar, scraping up any browned bits in pan.","Serve chicken thighs with beans and tomatoes, with fresh tomato salsa spooned over.","Rosemary chicken ragu with pressure cooker polenta","The great thing about making a ragu from dark-meat chicken instead of red meat is that it takes a third of the time to cook, but it starts the same way—by browning the protein slowly and deliberately, and using that time to prep the vegetables that sweeten and deepen the sauce. In case that is all sounding too old-world for you, I’ve busted out my trusty pressure cooker to make a pot of polenta in less time than it takes to brown the chicken skin. Balance!"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-basil-herbs-salad','Chicken, Basil & Herbs Salad','Recipe from Carla Lalli Music: 4 to',NULL,'medium',45,NULL,45,6,NULL,0,0,0,1,0,'chicken',2,0.575,12,1,'[{"name":"Chicken wings","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Mint and/or basil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Chicken drumsticks for the wings","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Omit the herbs","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Oregano","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Granulated garlic","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Smoked paprika","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Sugar","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"MSG","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Grapeseed oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Lime","quantity":null,"unit":"","unit_norm":"","category":"produce"}]','["The truly essential spices are the paprika, the sugar, and the granulated garlic. If you don’t have one of the others, don’t sweat it.","1 tablespoon kosher salt","1 teaspoon dried oregano","1 teaspoon granulated garlic","1 teaspoon smoked paprika","1 teaspoon sugar","½ teaspoon MSG, plus more for serving","4 pounds chicken wings","2 tablespoons grapeseed oil","1 cup small fresh mint and/or basil leaves","2 limes, cut into wedges","In a small bowl, combine salt, oregano, granulated garlic, smoked paprika, sugar, and MSG. Pat chicken wings dry and arrange on a rimmed baking sheet lined with foil. Season on both sides with spice mix. Let wings sit 30 minutes at room temperature, or transfer to a zip-top bag and refrigerate for up to 24 hours.","Place racks in center and top positions of oven and preheat to 375°F.","Drizzle wings with oil and toss to coat. Bake on center rack until wings are cooked through and skin is golden brown, about 30 minutes, turning with tongs halfway through. This initial cooking time renders some of the fat from the wings, which in turn allows the skin to crisp in next step.","Remove baking sheet from oven. Heat broiler. Broil wings on upper rack until skin is deeply browned and starting to char at edges, 5 to 7","minutes, turning wings every 2 to 3 minutes (because there is sugar in the rub, and because every broiler is different, this could happen very quickly; watch closely).","Transfer the wings to a platter and top with herbs. Serve with lime wedges for squeezing over.","My way duck confit","There was a day, many years ago, when I felt like preparing duck confit, but I didn’t want to make a special trip and shell out big bucks for the quart (or more) of duck fat that most recipes call for. “Won’t the duck make enough of its own fat?”","I thought lazily. I decided to try it. I added a splash of water to the pot with the duck legs to help the fat render early on, covered the pot, and took it very low and slow. Whaddya know —it worked. Traditionalists will say this is a hack recipe, and that’s fine. It’s a shortcut, but it works just as well as the original. Another word for that is…improvement."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-chives-grapeseed','Fish, Chives & Grapeseed','Recipe from Carla Lalli Music: Dry scallops are fresh, unadulterated, highest-quality scallops, and they are the only ones to use in this dish. If they’re not labeled dry, that means they’ve been treated with a liquid preservative that will ruin any hope you have of getting a good crusty sear on them (and that stuff doesn’t taste so nice, either). Ask before you buy.',NULL,'medium',45,NULL,45,4,NULL,0,0,1,0,1,'fish',4,0.637,17,1,'[{"name":"Large dry sea scallops","quantity":null,"unit":"","unit_norm":"","category":"seafood"},{"name":"Chives","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Small bay scallops Parsley in place of chives","quantity":null,"unit":"","unit_norm":"","category":"seafood"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Grapeseed oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Butter","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Hazelnuts","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Lemon","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Olive oil or canola oil for grapeseed","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Almonds or pine nuts for the hazelnuts","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Omit nuts altogether","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Unseasoned rice vinegar or fresh grapefruit juice for lemon juice 1 pound large dry sea scallops","quantity":null,"unit":"","unit_norm":"","category":"seafood"},{"name":"Kosher salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"grapeseed oil","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"unsalted butter","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"raw hazelnuts","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"fresh lemon juice","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Use your fingers to pull off the side muscle from the scallops and brush away any stray bits of shell or grit. Pat scallops dry with paper towels, then arrange on a large plate and season both sides with salt and pepper.","Heat a medium skillet, preferably stainless steel, over medium-high heat for a couple of minutes. When a drop of water dances on the surface of the skillet, add oil, which should immediately thin out and shimmer. Carefully place scallops into pan, flat side down, and cook, undisturbed, until you can see that they’re dark brown on the edge that’s in contact with the pan, about 4 minutes. Using a pair of tongs, a thin spatula, or a metal spoon, turn scallops onto second side and cook until just barely cooked through, about 1 minute more. Transfer to a serving plate.","Pour off any residual oil from skillet and place over medium heat.","Add butter and nuts to pan and cook, stirring often, until butter foams and then darkens, and nuts are lightly toasted, about 3 minutes.","Add lemon juice and cook, scraping up any browned bits with a wooden spoon, until sauce is slightly thickened, about 30 seconds. If sauce reduces too much or looks thick and greasy, stir in a couple tablespoons of water to loosen and reemulsify. Add chives and taste sauce; adjust with more lemon juice or salt as needed.","Spoon pan sauce and nuts over scallops to serve.","Crispy-skinned black sea bass with salt-and-butter radishes","The flavor of cooked radishes can be a bit gassy (they’re in the cabbage family, after all). Raw ones can be sharp and pungent. What’s a girl to do?! This recipe splits the difference, sautéing them enough to mellow their bite, but maintaining enough crunch to contrast with a delicate fish fillet. Starting the fillets in a barely warm skillet keeps the skin from curling up, which helps it brown and crisp, a trick I learned from my esteemed colleague Chris Morocco."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('fish-radishes-scallions-salad','Fish, Radishes & Scallions Salad','Recipe from Carla Lalli Music: The flavor of cooked radishes can be a bit gassy (they’re in the cabbage family, after all). Raw ones can be sharp and pungent. What’s a girl to do?! This recipe splits the difference, sautéing them enough to mellow their bite, but maintaining enough crunch to contrast with a delicate fish fillet. Starting the fillets in a barely warm skillet keeps the skin from curling up, which helps it brown and crisp, a trick I learned from my esteemed colleague Chris Morocco.',NULL,'medium',45,NULL,45,4,NULL,0,0,1,1,0,'fish',4,0.575,6,1,'[{"name":"Radishes","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Black sea bass","quantity":null,"unit":"","unit_norm":"","category":"seafood"},{"name":"Scallions","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Chives","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"watermelon radishes for small red ones","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"small piece daikon or kohlrabi for radishes","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Skin-on striped bass, red snapper, branzino, or trout for black sea bass Mint, basil, cilantro, or dill for chives","Grapeseed oil","Butter","Salt and pepper","Flaky sea salt","Lime","Ghee in place of oil and butter","Lemon or a wedge of grapefruit for lime","1 bunch small radishes, any type or color, tops removed, scrubbed 1 teaspoon grapeseed oil","2 tablespoons unsalted butter, divided","4 skin-on black sea bass fillets (6 to 8 ounces each) Kosher salt, freshly ground pepper","1 bunch scallions (white and pale-green parts only), thinly sliced crosswise Small handful of chives, thinly sliced","Flaky sea salt, for serving","1 lime, cut into wedges","Thinly slice radishes and soak them in a medium bowl of ice water for 5 minutes, which will firm them up and reduce their spiciness. Drain and blot dry with a clean kitchen towel or paper towels.","Put oil and 1 tablespoon butter in a large nonstick skillet and place over medium heat. Pat fish dry on both sides with paper towels, season with salt and pepper, and place, skin side down, into pan. Gently press on fillets with a flexible spatula to encourage skin to make contact with skillet’s surface. Cook, gently pressing down occasionally, until skin is very brown and crisp and flesh is opaque except for a thin strip down middle of flesh side, 6 to 8 minutes. Carefully turn fillets and cook on flesh side until just cooked through, about 1 minute longer. Transfer fillets to four plates or a serving platter.","Wipe out skillet and place over medium-high heat. Add remaining 1","tablespoon butter. When it begins to foam, add radishes and scallions, season with salt and pepper, and cook, tossing, until scallions are just wilted and radishes soften enough to be bendable but still have some crunch, about 2 minutes. Spoon radishes and pan sauce over and around fish and top with chives and a pinch of flaky sea salt. Serve with limes for squeezing over.","Pan-roasted salmon with cauli-tartar sauce and chive vinaigrette","When I crave salmon, I want the flesh rare in the middle, the skin to be sleek as glass, and the belly part of the fillet rich, fatty, and juicy. For me, only pan-roasting will do. It’s worth paying a little bit more for well-sourced salmon. If the price per pound is too good to be true, the fish is probably not too good."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('scallions-salad','Scallions Salad','Recipe from Carla Lalli Music: 4 to',NULL,'medium',45,NULL,45,6,NULL,0,1,0,1,0,'fish',2,0.575,4,1,'[{"name":"Serrano chile","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Scallions","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Clams","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Crusty bread","quantity":null,"unit":"","unit_norm":"","category":"pantry"}]','["Use a couple of shallots, a leek, or a handful of ramps in place of the scallions, and omit garnishing the finished dish with them raw 6 pounds mussels instead of clams At Home","Olive oil","Ginger","Garlic","Butter","A few slices of bacon, cut into pieces, a spoonful of black bean paste, or some miso can replace the ginger and/or garlic","2 tablespoons olive oil, plus more for drizzling 2-inch piece fresh ginger, peeled and crushed","3 garlic cloves, smashed","1 small serrano chile, thinly sliced","2 bunches scallions (white and pale-green parts only), thinly sliced, divided","4 dozen littleneck or Manila clams, scrubbed Thick slices of rustic country bread, for dipping 4 tablespoons (2 ounces) unsalted butter Prepare a grill for medium-high direct heat. (If you don’t have a grill, do everything as written on your stovetop.)","Place a large cast-iron or heavy stainless steel skillet on grill grates and add oil. When oil is hot, add ginger, garlic, chile, and half of scallions and stir until vegetables are sizzling, about 1 minute. Add clams and ½ cup water (or white wine, if you have a bottle open), toss to coat, and cover skillet with a lid, baking sheet, or large piece of foil. Cook, checking and stirring every few minutes, until the clams begin to open, 5 to 10 minutes. Transfer cooked clams to a large shallow bowl or platter with a slotted spoon as they open, but be quick about it. If you end up with a couple stubborn clams that refuse to open, discard them. They might be filled with sand, or they might be conscientious objectors. Either way, don’t eat them. Keep pan sauce warm, off to the side.","Drizzle bread generously with oil on both sides. Place over direct heat and grill until golden brown and delicious looking on both sides, 2 to 3 minutes (or toast in a toaster and then drizzle with oil). Set aside.","Add butter to pan sauce and slide skillet back over direct heat. As soon as butter is foaming, about 1 minute, return clams and any accumulated liquid to sauce, shower with remaining scallions, and toss to coat. Serve clams with bread and a large empty bowl for discarding the shells.","Grilled squid salad with cucumbers, herbs, and smoky chickpeas","Don’t be squeamish about squid: It is incredibly affordable, very accessible, mild flavored, and sustainable. The best ways to cook it are hot and fast or low and slow. This is an example of the first way—keep your paws off of it until grill marks appear on the first side, at which point it will be almost completely cooked through."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('pork-ribs-salad','Pork & Ribs Salad','Recipe from Carla Lalli Music: I like St. Louis ribs because they’ve got plenty of meat on top of the rib bone, and plenty of fat to prevent them from drying out. By teaming up your pressure cooker (or multicooker) and your broiler, you can have shreddy, falling-apart ribs on a weeknight. True story! If you don’t have a pressure cooker or a multicooker (yet), wrap the ribs in a double layer of foil and bake on a rimmed baking sheet in a 300°F oven until very tender, about three hours. The subsequent steps are the same.',NULL,'medium',45,NULL,45,4,NULL,0,0,0,0,1,'pork',2,0.557,17,0,'[{"name":"St. Louis pork ribs","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Use baby back ribs instead","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Salt","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Fish sauce","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Cider vinegar","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Brown sugar","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Butter","quantity":null,"unit":"","unit_norm":"","category":"dairy"},{"name":"Cayenne","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Mustard seeds","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Use white distilled vinegar instead of cider vinegar Use maple syrup instead of brown sugar","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Ground mustard can replace mustard seeds","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"racks St. Louis pork ribs","quantity":2,"unit":"","unit_norm":"","category":"meat"},{"name":"kosher salt","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"cider vinegar","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"dark brown sugar","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"unsalted butter","quantity":6,"unit":"tbsp","unit_norm":"tbsp","category":"dairy"},{"name":"0.5 teaspoons mustard seeds","quantity":1,"unit":"","unit_norm":"","category":"pantry"}]','["Cut each rack of ribs in half between two center-most bones and season all over with 2 tablespoons salt.","Place a steamer insert in a pressure cooker and add 1 inch of water.","Add ribs to pot, seal lid, and cook at high pressure for 12 minutes.","Release pressure naturally. Transfer ribs to two foil-lined rimmed baking sheets. (At this stage ribs can be cooled, then covered and refrigerated for up to 2 days before proceeding, if you wish.) Heat broiler.","In a small bowl, whisk together fish sauce, cider vinegar, brown sugar, melted butter, cayenne, mustard seeds, and remaining 1 tablespoon salt until sugar and salt dissolve. Brush or spoon half of mixture over both sides of ribs. Turn ribs meaty side up and broil until glaze is golden brown, about 4 minutes. Brush with remaining glaze and broil until ribs are dark golden and crisp, about 4 minutes more.","Let cool 5 minutes, then cut into smaller pieces to serve.","Butter-basted rib eye with crunchy fennel salad","What do these classics have in common: Duck confit and frisée. Breaded veal cutlet and tomato-arugula salad. Barbecue and pickles. Chicago-style hot dogs and this sassy little steak and salad dinner. Rich marbled meats are extra-delicious when served with cool, crunchy, acidic vegetables. It’s a fact, and the combo never gets old.","3 to"]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lamb-herbs-seeds','Lamb, Herbs & Seeds','Recipe from Carla Lalli Music: Lamb chops cut from the rib section aren’t cheap, so whenever I make this it feels like a special occasion, even when it’s a Saturday night in the summer with my family. Try to get small lamb chops that have not been Frenched, or trimmed of the layer of fat and deckle that sits on top of the bone. That’s the best part—lamb fat is king! This is a great springtime dinner with the asparagus on this page.',NULL,'medium',45,NULL,45,4,NULL,0,0,0,1,0,'lamb',3,0.495,7,0,'[{"name":"Lamb chops","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Mixed fresh herbs","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Lamb shoulder chops are good","quantity":null,"unit":"","unit_norm":"","category":"meat"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Coriander seeds","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Olive oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Red wine vinegar","quantity":null,"unit":"","unit_norm":"","category":"pantry"}]','["Fennel seeds, sumac, cumin seeds, or mustard seeds can replace coriander Use lemon wedges instead of vinegar","16 lamb rib chops, untrimmed (about 3 pounds)","Kosher salt, freshly ground pepper","1 teaspoon coriander seeds, lightly crushed","2 cups mixed chopped fresh herbs, such as rosemary, basil, mint, chives, dill, and/or parsley","½ cup extra-virgin olive oil","Red wine vinegar, for serving","Season lamb chops with salt, pepper, and coriander seeds and transfer to a glass baking dish or a large zip-top bag. Add herbs and olive oil and smush everything around to coat. Let sit at room temperature for 1 hour, or cover and refrigerate for up to 2 days.","Prepare a grill for medium-high direct heat. Lift chops out of marinade, letting excess drip off. Season lightly with salt. Grill, turning every 2 minutes, until chops are charred, fat is starting to render, and a thermometer inserted into center of chops registers 125°F for medium-rare to medium, 6 to 8 minutes. Transfer to a platter and season with a few dashes of red wine vinegar. Let rest for 10 minutes. I highly recommend eating these with your hands.","Slow-roasted lamb shoulder and beans with magic green sauce Slow-roasted lamb shoulder and beans with magic green sauce; Pomegranate-parsley tabbouleh (this page)","Despite a slightly hefty-looking ingredient list, this is a hands-off, minimal-effort meal, perfect for Sunday dinners when you’re not sure if four people or nine people will be at the table. The worst thing that can happen is that there will be shreddy meat leftovers and you’ll get to make tacos or sandwiches or fried rice during the week. The magic thing about the green sauce is that it works seamlessly with any combination of tender herbs, so you can tweak it to your preferences, or for the herbs you happen to have on hand."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('carrots-chickpeas-onion','Carrots, Chickpeas & Onion','Recipe from Carla Lalli Music: I spent two days with vegetable whisperer Jeremy Fox, the chef at Rustic Canyon Wine Bar in Santa Monica, California, on an assignment for Bon Appétit, and will be forever grateful for his advice on cooking beans: “If the broth tastes good,” he told me, “the beans will taste good.” Letting the beans sit in the flavorful stock they’ve helped to create infuses them with flavor to their very center. The other key to cooking beans is patience—lower the heat to maintain the barest possible simmer, which will help keep the skins intact as they slowly soften.',NULL,'medium',45,NULL,45,8,NULL,0,1,0,1,0,'none',1,0.495,18,0,'[{"name":"Carrots","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Thyme","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Sage","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"Dried chickpeas","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Yellow onion","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Salt and pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Olive oil","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Crushed red pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"Any dried bean","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"shallots for the onion","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"whole dried chile for the crushed red pepper","quantity":null,"unit":"","unit_norm":"","category":"produce"},{"name":"pound dried chickpeas","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"page)","quantity":null,"unit":"","unit_norm":"","category":"pantry"},{"name":"carrots","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"large yellow onion","quantity":0.5,"unit":"","unit_norm":"","category":"produce"},{"name":"garlic cloves","quantity":5,"unit":"","unit_norm":"","category":"produce"},{"name":"kosher salt","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Freshly ground pepper, extra-virgin olive oil, and crushed red pepper, to taste Handful of thyme sprigs","In a large stockpot, combine chickpeas, carrots, onion, garlic, and 1","tablespoon salt and cover with cold water by 3 inches. Bring to a boil over medium-high heat, then immediately reduce heat to medium-low. Set the lid askew, and let beans simmer very, very gently—adding water to the pot as needed to keep beans submerged—until they are completely tender but not mushy, about 1 hour 30 minutes. (This may go faster if the beans have been soaked, or could take longer, depending on the age of the beans.) Avoid the urge to stir the pot.","Agitation will cause the skins to split and the broth will be cloudy; occupy yourself with something else to do and let time do its thing.","Remove pot from heat and season bean liquid purposely and fearlessly with salt, black pepper, olive oil, and crushed red pepper.","The broth should be tasty enough to sip on its own. Squeeze the thyme in your hand to release its aromatic oils, then submerge into the broth and let the beans cool.","To serve, use a slotted spoon to scoop out onion, carrots, and thyme.","Return liquid to a simmer over medium. Taste and adjust seasoning one last time.","Yogi’s kitchari with sizzled spices","I was doing an Ayurvedic cleanse called panchakarma many years ago the first time I ever heard of, or made, kitchari, and it is to this day one of my essential feel-good foods. Mung beans, common in Indian and Chinese medicine, are detoxifying; the mix of spices is both warming and calming; white rice is easy to digest; and well-cooked vegetables (sans alliums or nightshade) are grounding and nourishing. If you feel off, or are coming back from a cold, or have been overindulging and want to give your system a break, this is what you should eat."]','rescued-named');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('arroz-de-pato','Arroz de Pato (Portuguese Duck Rice)','Classic Portuguese baked duck rice — shredded duck and chouriço folded through rice cooked in the duck broth, then baked until the top crisps.','portuguese','medium',90,20,110,6,560,1,0,0,1,0,'duck',2,0.55,10,0,'[{"name":"Duck legs","quantity":4,"unit":"unit","unit_norm":"unit","category":"meat"},{"name":"Chouriço","quantity":1,"unit":"unit","unit_norm":"unit","category":"meat"},{"name":"Smoked bacon","quantity":100,"unit":"g","unit_norm":"g","category":"meat"},{"name":"Long-grain rice","quantity":3,"unit":"cups","unit_norm":"cup","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Bay leaf","quantity":2,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Orange","quantity":1,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Coarse salt","quantity":1,"unit":"tsp","unit_norm":"tbsp","category":"pantry"}]','["Put the duck legs, chouriço, bacon, half an onion, bay, a strip of orange peel and salt in a large pot. Cover with water and simmer 50–60 min until the duck is tender.","Lift out the meats. Strain and reserve the broth. Shred the duck (discard skin and bones); slice the chouriço and bacon.","Soften the remaining chopped onion and garlic in olive oil. Add the rice and stir 1 min.","Add 6 cups of the reserved broth (top up with water if short), bring to a boil, then simmer covered ~15 min until the rice is just done but a little wet.","Heat oven to 200°C (400°F). Fold most of the duck into the rice; spread in a baking dish.","Top with the sliced chouriço, bacon and remaining duck. Bake 15–20 min until the top is golden and crisp.","Rest 5 min and serve with orange wedges."]','Portuguese classic (added for Groceree)');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('caldo-verde','Caldo Verde (Portuguese Greens & Potato Soup)','Silky potato soup with thinly shredded collard greens and slices of chouriço — Portugal''s most-loved everyday soup. Naturally gluten-free and very easy.','portuguese','easy',30,10,40,6,260,1,0,0,1,0,'pork',2,0.8,7,1,'[{"name":"Potatoes","quantity":700,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Collard greens (couve galega) or kale","quantity":300,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Chouriço","quantity":1,"unit":"unit","unit_norm":"unit","category":"meat"},{"name":"Yellow onion","quantity":1,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Garlic","quantity":2,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Coarse salt","quantity":1,"unit":"tsp","unit_norm":"tbsp","category":"pantry"}]','["Soften the chopped onion and garlic in olive oil in a large pot.","Add peeled, chunked potatoes and ~1.5 L water with salt. Boil until potatoes are very soft, ~20 min.","Meanwhile slice the chouriço and simmer the slices in a little water 5 min (skim the fat), then set aside.","Blend the potato base smooth with a stick blender.","Shred the greens as finely as possible. Stir into the soup and simmer 5–8 min until just tender (don''t overcook).","Serve topped with the chouriço slices and a thread of olive oil."]','Portuguese classic (added for Groceree)');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('frango-piri-piri','Frango Grelhado Piri-Piri (Grilled Piri-Piri Chicken)','Butterflied chicken marinated in garlic, lemon and piri-piri, then grilled. Fast, gluten-free, dairy-free and a family favourite.','portuguese','easy',30,15,45,4,430,1,0,0,1,0,'chicken',2,0.8,7,0,'[{"name":"Whole chicken, butterflied (or thighs)","quantity":1.4,"unit":"kg","unit_norm":"g","category":"meat"},{"name":"Garlic","quantity":4,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Piri-piri / hot chilli","quantity":2,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Lemon","quantity":1,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Sweet paprika","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Coarse salt","quantity":1,"unit":"tsp","unit_norm":"tbsp","category":"pantry"}]','["Blend garlic, chilli, lemon juice, paprika, olive oil and salt into a marinade.","Coat the butterflied chicken and rest at least 30 min (overnight is better).","Grill or roast at 220°C, skin-side first, ~15 min per side, basting with the marinade, until juices run clear.","Rest 5 min, cut up and serve with lemon and a salad or rice."]','Portuguese classic (added for Groceree)');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('bacalhau-a-bras','Bacalhau à Brás (Salt Cod with Eggs & Potato)','Shredded salt cod tossed with onions, matchstick potatoes and eggs until just creamy — a Lisbon classic. Naturally gluten-free.','portuguese','medium',30,20,50,4,520,1,0,1,1,0,'fish',2,0.55,8,0,'[{"name":"Salt cod (bacalhau), soaked & flaked","quantity":500,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"Potatoes","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Eggs","quantity":6,"unit":"unit","unit_norm":"unit","category":"dairy"},{"name":"Yellow onion","quantity":2,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Garlic","quantity":3,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"Black olives","quantity":12,"unit":"unit","unit_norm":"unit","category":"pantry"},{"name":"Parsley","quantity":1,"unit":"handful","unit_norm":"unit","category":"produce"},{"name":"Olive oil","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Fry the potato matchsticks in oil until golden (or use ready straw potatoes). Drain.","Soften sliced onion and garlic in olive oil. Add the flaked, soaked cod and warm through 3–4 min.","Fold in the fried potatoes.","Beat the eggs, pour over and stir gently over low heat until just set and creamy — do not overcook.","Off the heat, scatter olives and chopped parsley. Serve immediately."]','Portuguese classic (added for Groceree)');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sardinhas-assadas','Sardinhas Assadas (Grilled Sardines)','Whole sardines simply salted and grilled — the taste of a Portuguese summer. Gluten-free, dairy-free, very easy.','portuguese','easy',12,10,22,4,310,1,0,1,1,0,'fish',2,0.8,6,0,'[{"name":"Fresh sardines","quantity":12,"unit":"unit","unit_norm":"unit","category":"seafood"},{"name":"Coarse sea salt","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Bell peppers","quantity":2,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Boiling potatoes","quantity":600,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Lemon","quantity":1,"unit":"unit","unit_norm":"unit","category":"produce"}]','["Salt the whole sardines generously and leave 30–60 min; pat off excess salt.","Boil the potatoes whole until tender; keep warm.","Grill the peppers until charred, then peel and dress with olive oil.","Grill the sardines over high heat ~3 min per side until the skin crisps.","Serve with the potatoes, peppers and lemon wedges."]','Portuguese classic (added for Groceree)');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('carne-porco-alentejana','Carne de Porco à Alentejana (Pork with Clams)','Pork marinated in garlic and red-pepper paste, seared and finished with clams and fried potato cubes. Surf-and-turf Alentejo style, naturally gluten-free.','portuguese','medium',40,30,70,4,540,1,0,0,1,0,'pork',2,0.55,10,0,'[{"name":"Pork shoulder","quantity":700,"unit":"g","unit_norm":"g","category":"meat"},{"name":"Clams, purged","quantity":600,"unit":"g","unit_norm":"g","category":"seafood"},{"name":"Massa de pimentão (red pepper paste)","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":4,"unit":"cloves","unit_norm":"clove","category":"produce"},{"name":"White wine","quantity":150,"unit":"ml","unit_norm":"ml","category":"pantry"},{"name":"Bay leaf","quantity":2,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Potatoes, cubed & fried","quantity":500,"unit":"g","unit_norm":"g","category":"produce"},{"name":"Coriander","quantity":1,"unit":"handful","unit_norm":"unit","category":"produce"},{"name":"Lemon","quantity":1,"unit":"unit","unit_norm":"unit","category":"produce"},{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Marinate the pork cubes with red-pepper paste, crushed garlic, white wine and bay for at least 2 h.","Drain (keep the marinade). Sear the pork in olive oil until browned; add the marinade and simmer until tender, ~20 min.","Add the purged clams, cover, and cook just until they open (discard any that don''t), ~5 min.","Fold in the fried potato cubes.","Finish with chopped coriander and lemon. Serve hot."]','Portuguese classic (added for Groceree)');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('creamy-coconut-curry-lentils-spinach','Creamy Coconut Curry Lentils with Spinach','Brown lentils simmered in curried coconut milk with wilted spinach, served over rice.','indian','easy',40,5,45,4,430,1,1,1,1,0,'none',2,0.8,11,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Yellow onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Curry powder","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Dry brown lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Vegetable broth","quantity":2,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Coconut milk","quantity":1,"unit":"can","unit_norm":"can","category":"dairy"},{"name":"Baby spinach","quantity":3,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Cooked rice","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Saute garlic and ginger in the oil in a deep skillet for 1 minute.","Add diced onion and cook until soft, then add curry powder and toast 1 minute.","Add lentils and broth, bring to a boil, cover and simmer 20 minutes.","Stir in coconut milk and simmer uncovered 10 minutes to thicken.","Off heat, stir in spinach to wilt and adjust salt and curry.","Serve over rice with chopped cilantro."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mujaddara-rice-lentil-pilaf','Mujaddara (Rice and Lentil Pilaf with Caramelized Onions)','Cheap, deeply savoury pilaf of rice and lentils crowned with slow caramelized onions.','middle-eastern','medium',100,10,110,6,350,1,1,1,1,0,'none',2,0.6,8,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow onions","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Allspice","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Ground cloves","quantity":0.25,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Vegetable broth","quantity":2.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Long grain white rice","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Brown lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Thinly slice the onions and cook in oil over low heat about 1 hour until deeply caramelized; remove half to top later.","Add cumin, allspice and cloves to the remaining onions and toast 1 minute.","Add the broth and scrape the pot.","Add lentils and simmer until partly tender, then add the rice.","Cover and cook until rice and lentils are tender and the liquid is absorbed.","Top with the reserved caramelized onions."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('quick-chana-masala','Quick Chana Masala','Fast chickpea curry in a spiced fire-roasted tomato sauce.','indian','easy',20,15,35,4,400,1,1,1,1,0,'none',2,0.82,14,1,'[{"name":"Brown basmati rice","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Coconut oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Serrano or jalapeno","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":5,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Garam masala","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Ground coriander","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Ground cumin","quantity":0.75,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Ground turmeric","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Fire-roasted crushed tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Chickpeas","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Cook the rice if serving.","Warm oil over medium-low and cook onion, minced serrano and salt about 5 minutes.","Add garlic and ginger 30 to 60 seconds, then add the spices and cook 1 minute.","Add the tomatoes with juices, breaking up any whole pieces.","Add the drained chickpeas and simmer 10 minutes or more, then season.","Serve over rice with lemon and cilantro."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('quick-curried-chickpeas-spinach','Quick Curried Chickpeas with Spinach','Twenty-minute pantry curry of chickpeas and spinach in tomato sauce.','indian','easy',20,5,25,4,380,1,1,1,1,0,'none',2,0.85,8,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"inch","unit_norm":"inch","category":"produce"},{"name":"Curry powder","quantity":1.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Spinach","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"Tomato sauce","quantity":15,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Chickpeas","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"}]','["Saute onion, garlic and ginger in the oil 3 to 5 minutes.","Add curry powder for 1 minute, then add a splash of water and the spinach to wilt.","Add the drained chickpeas and tomato sauce, stir and heat through 5 minutes.","Serve over rice or with bread."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chana-saag-chickpeas-spinach','Chana Saag (Creamy Chickpeas and Spinach)','Chickpeas and spinach simmered creamy with coconut milk over rice.','indian','easy',25,10,35,4,420,1,1,1,1,0,'none',2,0.8,9,1,'[{"name":"White rice","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Curry powder","quantity":1.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Spinach","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"Chickpeas","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Coconut milk","quantity":1,"unit":"can","unit_norm":"can","category":"dairy"}]','["Cook the rice.","Saute the aromatics and add curry powder.","Add spinach to wilt, then the chickpeas and coconut milk.","Simmer until creamy and serve over rice."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sri-lankan-coconut-lentils','Coconut Lentils (Sri Lankan Parippu)','Ultra-cheap red lentils cooked soft in turmeric coconut milk.','indian','easy',25,5,30,4,316,1,1,1,1,0,'none',1,0.85,5,1,'[{"name":"Red lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Turmeric","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Coconut milk","quantity":1,"unit":"can","unit_norm":"can","category":"dairy"},{"name":"Water","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Rinse the lentils 2 to 3 times.","Add garlic, salt, turmeric, coconut milk and the water, then stir.","Bring to a boil then simmer about 20 minutes until the liquid is absorbed.","Rest 5 minutes and season."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('cuban-black-beans-and-rice','Cuban Black Beans and Rice','Dried black beans simmered with sofrito, vinegar and a touch of sugar, over rice.','latin','medium',75,15,90,4,410,1,1,1,1,0,'none',2,0.62,12,0,'[{"name":"Dried black beans","quantity":0.5,"unit":"lb","unit_norm":"lb","category":"pantry"},{"name":"Green pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Bay leaf","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Oregano","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Paprika","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Vinegar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Sugar","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Rice","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Simmer the soaked beans with half the pepper, a quarter of the onion, 2 cloves garlic and the bay leaf about 45 minutes.","Make a sofrito: saute the remaining onion, pepper and garlic, then add cumin, oregano and paprika 30 seconds.","Combine the sofrito with the beans and add vinegar and sugar; simmer to thicken.","Serve over rice."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('one-pot-green-curry-lentil-dal','1-Pot Lentil Green Curry Dal','One-pot lentil dal built on green curry paste and coconut milk.','indian','easy',30,10,40,4,400,1,1,1,1,0,'none',2,0.82,9,1,'[{"name":"Coconut oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Green chili","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Shallot","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Green curry paste","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Coconut milk","quantity":1,"unit":"can","unit_norm":"can","category":"dairy"},{"name":"Rice","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Heat the pot and add coconut oil, chili, ginger, shallot and garlic.","Add the curry paste and stir.","Add lentils and coconut milk and simmer until tender (use canned lentils and warm 10 minutes to shorten).","Serve over rice."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('best-red-lentil-dahl','Red Lentil Dahl','Vegetable-loaded split red lentil dahl finished with coconut milk and citrus.','indian','easy',25,10,35,6,360,1,1,1,1,0,'none',2,0.8,15,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Carrot","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Curry powder","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garam masala","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Turmeric","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Split red lentils","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Vegetable broth","quantity":3,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Canned tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Coconut milk","quantity":1,"unit":"can","unit_norm":"can","category":"dairy"},{"name":"Lime","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Saute the onion 3 to 4 minutes, then add ginger, garlic, carrot and bell pepper.","Add the spices, lentils and broth, bring to a boil and simmer about 10 minutes.","Add coconut milk and cook 5 minutes more to your desired thickness.","Season and serve with rice or potatoes."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lentil-bolognese-vegan-gf','Lentil Bolognese (Vegan, Gluten-Free)','Quick weeknight lentil and mushroom bolognese over gluten-free pasta.','italian','easy',25,10,35,4,450,1,1,1,1,0,'none',2,0.78,10,0,'[{"name":"Gluten-free pasta","quantity":12,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Mushrooms","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"Oregano","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Red pepper flakes","quantity":0.25,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Tomato sauce","quantity":15,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Green or brown lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Cook the gluten-free pasta.","Saute onion, garlic, mushrooms and spices 3 to 5 minutes.","Add diced tomatoes with liquid, tomato sauce, lentils and water; cover, boil then simmer 18 to 25 minutes.","Serve over the pasta."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('red-lentil-walnut-bolognese','Red Lentil and Walnut Bolognese','Ten-ingredient red lentil bolognese with walnuts for a meaty base.','italian','easy',45,10,55,5,470,1,1,1,1,0,'none',2,0.72,13,0,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrot","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Celery","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Mushrooms","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"Red lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Walnuts","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Tomato paste","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Canned tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Vegetable broth","quantity":2,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Fresh basil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Gluten-free pasta","quantity":12,"unit":"oz","unit_norm":"oz","category":"pantry"}]','["Saute the onion, carrot, celery, garlic and mushrooms into a soffritto.","Add lentils, chopped walnuts, tomato paste, tomatoes and broth.","Simmer until thick and the lentils are tender.","Serve over gluten-free pasta with basil."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('lentil-bolognese-pappardelle','Vegetarian Lentil Bolognese with Pappardelle','Creamy red lentil bolognese brightened with balsamic, over GF pappardelle.','italian','medium',50,10,60,5,460,1,1,1,1,0,'none',2,0.68,12,0,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrot","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Celery","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Mushrooms","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"},{"name":"Red lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Vegetable broth","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Balsamic vinegar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Gluten-free pappardelle","quantity":12,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Bay leaf","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"Fresh parsley","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Saute the aromatics.","Add lentils and broth and simmer until creamy.","Remove the bay leaf and stir in the balsamic.","Cook the gluten-free pasta separately, then combine and garnish."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sheet-pan-greek-chicken-vegetables','Sheet Pan Greek Chicken and Vegetables','Lemon-oregano chicken roasted with peppers, tomatoes and onion on one tray.','mediterranean','easy',40,10,50,4,480,1,0,0,1,0,'chicken',2,0.8,11,1,'[{"name":"Olive oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Dried oregano","quantity":0.5,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Grape tomatoes","quantity":1,"unit":"pint","unit_norm":"pint","category":"produce"},{"name":"Bell peppers","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Red onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Boneless skinless chicken breast","quantity":1.5,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Kalamata olives","quantity":15,"unit":"","unit_norm":"","category":"pantry"},{"name":"Parsley","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Cooked rice","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Heat the oven to 400F and make the lemon, garlic, oregano and oil marinade.","Chop the vegetables into 1 to 1.5 inch pieces, toss with half the marinade and roast 10 minutes.","Pound the chicken even, cut each breast in two and coat with the remaining marinade.","Add the chicken to the sheet and roast 20 to 25 minutes to 165F.","Top with olives, lemon zest and parsley and serve over rice."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sheet-pan-honey-mustard-chicken','Sheet Pan Honey Mustard Chicken and Veggies','Chicken thighs and baby potatoes roasted in a tangy honey mustard glaze.','american','easy',40,10,50,4,592,1,0,0,1,0,'chicken',1,0.82,10,1,'[{"name":"Chicken thighs","quantity":2,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Baby potatoes","quantity":1.5,"unit":"lb","unit_norm":"lb","category":"produce"},{"name":"Mixed vegetables","quantity":3,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Mayonnaise","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Dijon mustard","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow mustard","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Honey","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Apple cider vinegar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic powder","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Paprika","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Heat the oven to 400F.","Whisk the honey mustard sauce.","Toss the chicken and vegetables with the sauce on a sheet pan.","Roast 30 to 40 minutes until the chicken reaches 165F and the potatoes are tender."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('roasted-chicken-and-vegetables','Roasted Chicken and Vegetables','Bone-in thighs roasted over herbed potatoes, carrots and onion.','american','easy',45,10,55,4,781,1,0,0,1,0,'chicken',1,0.8,10,1,'[{"name":"Bone-in chicken thighs","quantity":2,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Baby potatoes","quantity":1.5,"unit":"lb","unit_norm":"lb","category":"produce"},{"name":"Carrots","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Red onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":6,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Dried basil","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Dried rosemary","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Dried thyme","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Paprika","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Heat the oven to 425F.","Mix the oil with the herbs and spices.","Toss the vegetables with half and spread in a 9x13 dish.","Coat the chicken with the rest, place on top and roast until the chicken is 165F and the vegetables are tender."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('italian-sausage-white-bean-skillet','Italian Sausage and White Bean Skillet','Crispy Italian sausage with cannellini beans and wilted spinach in one pan.','italian','easy',20,5,25,4,520,1,0,0,1,0,'pork',3,0.85,4,1,'[{"name":"Italian sausage","quantity":1,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cannellini beans","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Spinach","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"}]','["Brown the sausage in the oil until crispy-edged, about 10 minutes.","Add the drained beans and pepper and coat in the fat to heat through.","Stir in the spinach in batches until wilted."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-sausage-white-bean-skillet','Chicken Sausage White Bean Skillet','Fully-cooked chicken sausage with white beans in a light pan sauce and greens.','american','easy',20,10,30,4,470,1,0,0,1,0,'chicken',2,0.85,8,1,'[{"name":"Chicken sausage links","quantity":5,"unit":"","unit_norm":"","category":"meat"},{"name":"Olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"White beans","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Dried oregano","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Smoked paprika","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Spinach","quantity":8,"unit":"oz","unit_norm":"oz","category":"produce"}]','["Slice and brown the sausage, then set aside.","Saute onion and garlic in the remaining oil about 3 minutes.","Add the beans (do not rinse, the starchy liquid makes a light sauce) and seasonings.","Add spinach to wilt and return the sausage."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sun-dried-tomato-kale-white-bean-skillet','Sun-Dried Tomato, Kale and White Bean Skillet','Garlicky kale and white beans dressed with sun-dried tomatoes.','mediterranean','easy',15,10,25,4,340,1,1,1,1,0,'none',4,0.82,8,1,'[{"name":"White beans","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Sun-dried tomatoes","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Apple cider vinegar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Dried basil","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Red pepper flakes","quantity":0.25,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Kale","quantity":1,"unit":"bunch","unit_norm":"bunch","category":"produce"}]','["Make a dressing from the jar oil, vinegar, basil and seasonings.","Saute garlic in olive oil 1 minute, then add the kale with 2 tablespoons water to wilt.","Add the beans and sun-dried tomatoes to heat through.","Drizzle the dressing and season."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('easy-chicken-stir-fry','Easy Chicken Stir Fry','Chicken and crisp vegetables in a glossy tamari-ginger sauce over rice.','asian','easy',15,15,30,4,450,1,0,0,1,0,'chicken',2,0.8,13,1,'[{"name":"Chicken breast","quantity":1,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Cooking oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Tamari","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Brown sugar","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Toasted sesame oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Cornstarch","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Broccoli","quantity":3,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Red bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrots","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Green onions","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"Rice","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Mix the tamari sauce ingredients.","Chop the vegetables and chicken.","Brown the chicken in hot oil, then remove.","Stir-fry the vegetables tender-crisp.","Return the chicken, add the sauce and toss until glossy; serve over rice."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('one-pot-teriyaki-chicken-rice','One Pot Teriyaki Chicken and Rice','Chicken, jasmine rice and vegetables cooked together with GF teriyaki.','asian','easy',25,10,35,4,499,1,0,0,1,0,'chicken',2,0.82,9,1,'[{"name":"Chicken breast","quantity":0.66,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Cooking oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Jasmine rice","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Water","quantity":2.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Gluten-free teriyaki sauce","quantity":0.33,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Mixed vegetables","quantity":2,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Green onions","quantity":2,"unit":"","unit_norm":"","category":"produce"}]','["Saute garlic, ginger and chicken in the oil.","Add the rice and toast 1 minute, then add water, boil and simmer covered about 15 minutes.","Add the vegetables, drizzle the teriyaki and fold gently.","Rest 5 minutes and top with green onion."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('chicken-fried-rice','Chicken Fried Rice','Day-old rice stir-fried with chicken, egg and vegetables in tamari.','asian','easy',15,15,30,4,500,1,0,0,1,0,'chicken',1,0.8,12,1,'[{"name":"Chicken breast","quantity":0.66,"unit":"lb","unit_norm":"lb","category":"meat"},{"name":"Toasted sesame oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cooking oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Tamari","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":2,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fresh ginger","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"produce"},{"name":"Green onions","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrot","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Red bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Frozen peas","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Eggs","quantity":2,"unit":"","unit_norm":"","category":"dairy"},{"name":"Cooked and cooled rice","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Scramble the eggs and set aside.","Stir-fry the carrots, then the bell pepper and white green-onion ends, and add the chicken.","Add the cold rice and return the eggs.","Season with tamari and sesame oil and top with green onion."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('best-lentil-soup','Best Lentil Soup','Hearty curried lentil soup with greens, part-blended for body.','mediterranean','easy',45,10,55,4,380,1,1,1,1,0,'none',2,0.78,13,1,'[{"name":"Olive oil","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrots","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Ground cumin","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Curry powder","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Dried thyme","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Brown or green lentils","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Vegetable broth","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Water","quantity":2,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Kale or collard greens","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Saute the onion and carrot 5 minutes.","Add garlic, cumin, curry and thyme 30 seconds, then the tomatoes and cook a few minutes.","Add lentils, broth, water, salt and pepper, boil then simmer partially covered 25 to 30 minutes.","Blend 2 cups and return to the pot.","Add the greens 5 minutes, stir in lemon juice and season."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('smoky-black-bean-soup','Smoky Black Bean Soup','Smoky paprika black bean soup, partly pureed and finished with lime.','mexican','easy',25,10,35,4,351,1,1,1,1,0,'none',1,0.82,8,1,'[{"name":"Black beans","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Smoked paprika","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Jalapeno","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Vegetable broth","quantity":2,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Lime","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Saute the aromatics and spices.","Add the beans (puree some for thickness) and the broth.","Simmer until thick and finish with lime.","Top as desired."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('slow-cooker-black-bean-soup','Slow Cooker Black Bean Soup','Set-and-forget dried black bean soup with peppers and salsa.','mexican','easy',480,10,490,6,294,1,1,1,1,0,'none',1,0.85,9,1,'[{"name":"Dried black beans","quantity":1,"unit":"lb","unit_norm":"lb","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrots","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Chili powder","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Vegetable broth","quantity":6,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Salsa","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Add everything to the slow cooker.","Cook on low about 8 hours until the beans are very soft.","Immersion-blend until thick and season."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('vegetarian-15-bean-soup','Vegetarian 15 Bean Soup','Big-batch mixed bean soup seasoned from scratch, finished with cider vinegar.','american','easy',110,10,120,6,320,1,1,1,1,0,'none',1,0.7,10,1,'[{"name":"15-bean mix","quantity":1,"unit":"","unit_norm":"","category":"pantry"},{"name":"Coconut oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Carrots","quantity":3,"unit":"","unit_norm":"","category":"produce"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Oregano","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Smoked paprika","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Apple cider vinegar","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Saute the aromatics.","Add the beans and water and simmer about 90 minutes until soft (discard the seasoning packet).","Add the tomatoes and spices and simmer 20 minutes.","Salt to taste and finish with apple cider vinegar."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('classic-minestrone-soup-gf','Classic Minestrone Soup (Gluten-Free)','Vegetable, bean and GF-pasta minestrone in a herby tomato broth.','italian','easy',45,15,60,6,360,1,1,1,1,0,'none',2,0.76,16,1,'[{"name":"Olive oil","quantity":4,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Carrots","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Celery","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Tomato paste","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Seasonal vegetables","quantity":2,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Dried oregano","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Dried thyme","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Vegetable broth","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Water","quantity":2,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Small gluten-free pasta","quantity":1,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Cannellini beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Greens","quantity":2,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"}]','["Saute onion, carrot, celery and tomato paste 7 to 10 minutes.","Add the seasonal vegetables, garlic and herbs 2 minutes.","Add tomatoes, broth, water, salt, bay and pepper, boil then simmer 15 minutes.","Add the gluten-free pasta, beans and greens and cook until the pasta is done.","Remove the bay and stir in lemon and a final tablespoon of oil."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('vegan-sweet-potato-peanut-stew','Vegan Sweet Potato Peanut Stew','West-African-inspired sweet potato and peanut butter stew with collards.','african','easy',30,10,40,5,468,1,1,1,1,0,'none',2,0.8,10,1,'[{"name":"Fresh ginger","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"produce"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Sweet potatoes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Crushed tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Vegetable broth","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Natural peanut butter","quantity":0.5,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Collard greens","quantity":4,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Brown rice","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Chopped peanuts","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"dairy"}]','["Saute ginger, onion and garlic.","Add sweet potatoes, tomatoes, broth and peanut butter and simmer 15 to 20 minutes until soft.","Stir in the collards 5 minutes and smash some sweet potato to thicken; season.","Serve over rice with peanuts."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('slow-cooker-vegetarian-lentil-chili','Slow Cooker Vegetarian Lentil Chili','Dump-and-go brown lentil chili with a silky mouthfeel.','american','easy',240,10,250,6,369,1,1,1,1,0,'none',1,0.85,9,1,'[{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Brown lentils","quantity":1.5,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Kidney beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Chili powder","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Coconut oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Vegetable broth","quantity":4,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Dice the onion and mince the garlic.","Add all the ingredients to the slow cooker and stir.","Cook on high 4 hours or low 8 hours until the lentils are tender.","Salt to taste and add toppings."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('homemade-vegetarian-three-bean-chili','Homemade Vegetarian Three-Bean Chili','Smoky three-bean and corn chili sweetened with a touch of molasses.','mexican','easy',30,10,40,6,400,1,1,1,1,0,'none',1,0.8,14,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Green bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Tomato paste","quantity":6,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Fire-roasted green chiles","quantity":4,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Molasses","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Kidney beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Black beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Pinto beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Corn","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Chili powder","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cumin","quantity":2,"unit":"tsp","unit_norm":"tsp","category":"pantry"}]','["Dice the onion and pepper and mince the garlic.","Toast the spices in a dry pot 2 to 4 minutes.","Add oil, onion, garlic, pepper and salt and cook 4 to 6 minutes.","Add tomato paste, tomatoes, chiles, molasses and water and simmer 5 minutes.","Add the beans and corn and simmer covered 20 to 25 minutes."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('simple-shakshuka','Simple Shakshuka','Eggs poached in a smoky spiced tomato and pepper sauce.','middle-eastern','easy',35,5,40,4,300,1,1,1,1,0,'none',2,0.78,14,1,'[{"name":"Olive oil","quantity":3,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Yellow onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Red bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Jalapenos","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Celery","quantity":5,"unit":"","unit_norm":"","category":"produce"},{"name":"Smoked paprika","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Cardamom","quantity":1.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Garlic","quantity":4,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Fire-roasted diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Tomato paste","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Eggs","quantity":3,"unit":"","unit_norm":"","category":"dairy"},{"name":"Parsley","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"}]','["Heat the oven to 350F.","In an oven-safe skillet saute onion, bell pepper, jalapeno, celery and all the spices 10 to 12 minutes.","Add garlic, tomatoes, tomato paste, lemon and sugar and cook 10 minutes, thinning with water.","Make wells and crack in the eggs.","Bake 8 to 12 minutes until the whites set and top with parsley."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('smoky-white-bean-shakshuka','Smoky White Bean Shakshuka','Eggs and white beans baked into a smoky tomato sauce.','middle-eastern','easy',25,10,35,4,360,1,1,1,1,0,'none',2,0.8,10,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Canned tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Smoked paprika","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Oregano","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Cannellini beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Eggs","quantity":4,"unit":"","unit_norm":"","category":"dairy"},{"name":"Parsley","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"produce"}]','["Saute the garlic and onion.","Add the tomatoes and spices and simmer 5 to 7 minutes to thicken, then salt.","Stir in the drained beans.","Make wells, add the eggs, cover and cook until set.","Top with parsley."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('ratatouille-frittata','Ratatouille Frittata','Roasted eggplant, zucchini and tomato folded into a dairy-free baked frittata.','mediterranean','medium',80,15,95,8,162,1,1,1,1,0,'none',2,0.6,9,0,'[{"name":"Eggplant","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Zucchini","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Grape tomatoes","quantity":1,"unit":"pint","unit_norm":"pint","category":"produce"},{"name":"Dried basil","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Dried oregano","quantity":0.5,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Eggs","quantity":8,"unit":"","unit_norm":"","category":"dairy"},{"name":"Dairy-free milk","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"}]','["Heat the oven to 400F and roast the diced eggplant, zucchini, onion and whole tomatoes with the herbs and oil about 50 minutes, stirring.","Whisk the eggs with the dairy-free milk and salt and pepper and pour over the vegetables in an oven-safe skillet.","Bake about 30 minutes until set."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('dairy-free-vegetable-frittata','Dairy-Free Vegetable Frittata','Quick baked frittata with spinach, peppers and broccoli, made with non-dairy milk.','american','easy',20,10,30,6,220,1,1,1,1,0,'none',2,0.8,7,1,'[{"name":"Eggs","quantity":9,"unit":"","unit_norm":"","category":"dairy"},{"name":"Dairy-free milk","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"pantry"},{"name":"Spinach","quantity":2,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Red bell pepper","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Red onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Broccoli","quantity":1,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"}]','["Saute the vegetables in an oven-safe skillet.","Whisk the eggs with the non-dairy milk and seasoning and pour over.","Bake until set, about 13 to 20 minutes."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('sweet-potato-black-bean-enchiladas','Sweet Potato Black Bean Enchiladas','Corn tortillas rolled around spiced sweet potato and black beans under a salsa sauce.','mexican','medium',35,20,55,4,430,1,1,1,1,0,'none',1,0.62,9,0,'[{"name":"Olive oil","quantity":1,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Onion","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Garlic","quantity":3,"unit":"clove","unit_norm":"clove","category":"produce"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Sweet potatoes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Black beans","quantity":2,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Canned diced tomatoes","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Corn tortillas","quantity":10,"unit":"","unit_norm":"","category":"pantry"},{"name":"Salsa","quantity":1,"unit":"jar","unit_norm":"jar","category":"pantry"}]','["Saute onion, garlic and cumin.","Add sweet potato, beans and tomatoes and simmer covered 15 to 20 minutes until mashable, then mash slightly.","Blend salsa with reserved beans and cumin for the sauce and spread in a dish.","Warm the tortillas, fill and roll seam-down.","Top with the sauce and bake until hot."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('southwest-stuffed-sweet-potatoes','Southwest Stuffed Sweet Potatoes','Baked sweet potatoes stuffed with black beans and drizzled with cashew-nacho sauce.','mexican','medium',60,15,75,4,420,1,1,1,1,0,'none',3,0.6,9,0,'[{"name":"Sweet potatoes","quantity":4,"unit":"","unit_norm":"","category":"produce"},{"name":"Black beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Mixed vegetables","quantity":2,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Cashews","quantity":0.75,"unit":"cup","unit_norm":"cup","category":"dairy"},{"name":"Green chiles","quantity":4,"unit":"oz","unit_norm":"oz","category":"pantry"},{"name":"Lemon","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Jalapenos","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Cilantro","quantity":0.25,"unit":"cup","unit_norm":"cup","category":"produce"}]','["Bake the sweet potatoes at 425F about 45 to 60 minutes.","Make the black bean and vegetable filling.","Blend the cashews, water, green chiles, lemon juice and jalapenos into a sauce.","Split the potatoes, fluff, fill, drizzle the sauce and garnish with cilantro."]','curated-budget-gfdf');
INSERT INTO recipes (id,name,description,cuisine,difficulty,cook_time,prep_time,total_time,servings,calories_per_serving,is_gluten_free,is_vegetarian,is_pescatarian,is_dairy_free,contains_dairy,primary_protein,cost_tier,ease_score,ingredient_count,is_one_pot,ingredients,instructions,source) VALUES ('mexican-sweet-potato-hash','Mexican Sweet Potato Hash with Black Beans and Spinach','Quick skillet hash of sweet potato, black beans and spinach, great with a fried egg.','mexican','easy',20,10,30,3,330,1,1,1,1,0,'none',2,0.82,9,1,'[{"name":"Olive oil","quantity":2,"unit":"tbsp","unit_norm":"tbsp","category":"pantry"},{"name":"Sweet potatoes","quantity":2,"unit":"","unit_norm":"","category":"produce"},{"name":"Shallot","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Black beans","quantity":1,"unit":"can","unit_norm":"can","category":"pantry"},{"name":"Cumin","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Chili powder","quantity":1,"unit":"tsp","unit_norm":"tsp","category":"pantry"},{"name":"Spinach","quantity":3,"unit":"cup","unit_norm":"cup","category":"produce"},{"name":"Lime","quantity":1,"unit":"","unit_norm":"","category":"produce"},{"name":"Eggs","quantity":3,"unit":"","unit_norm":"","category":"dairy"}]','["Cook the diced sweet potatoes in the oil over medium-high about 15 minutes until tender.","Add the shallot, beans, salt, cumin and chili powder and saute 3 minutes.","Fold in the spinach to wilt and finish with lime.","Top with a fried egg if you like."]','curated-budget-gfdf');